
function getDfmeaStructIdForCause(causeId) {
  const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : null;
  if (!ctx || !ctx.isPFMEA) return null;

  let structId = null;
  const allCauses = [...(fmeaData.libraries?.causes || []), ...(ctx.libraries?.causes || [])];
  const cause = allCauses.find(c => String(c.id) === String(causeId));
  if (cause && cause.structId) structId = cause.structId;

  if (!structId && ctx.functionLines) {
    for (const fl of ctx.functionLines) {
      const flCauses = (ctx.failureModeCauses || {})[fl.id] || [];
      const hasCause = (fl.failureModes || []).some(fm => {
        const fmCauses = (ctx.failureModeCauses || {})[fm.id] || [];
        return fmCauses.includes(causeId) || (fm.causes || []).some(c => String(c.id) === String(causeId));
      });
      if (hasCause || flCauses.includes(causeId)) {
        structId = fl.structId;
        break;
      }
    }
  }

  if (!structId) {
    structId = (typeof selectedStructureId !== 'undefined' ? selectedStructureId : null);
  }

  let pstep = (ctx.processSteps || []).find(ps => String(ps.id) === String(structId));
  if (!pstep && ctx.structure && typeof getParentStructureNode === 'function') {
    const parent = getParentStructureNode(ctx.structure, structId);
    if (parent) pstep = (ctx.processSteps || []).find(ps => String(ps.id) === String(parent.id)) || parent;
  }

  return (pstep && pstep.dfmeaStructId) || ctx.dfmeaStructId || null;
}
window.getDfmeaStructIdForCause = getDfmeaStructIdForCause;

let activeDashboardMode = 'AIAG';

const AIAG_VDA_AP_TABLE = [
  // sIdx 0: Severity 1
  [
    ['L', 'L', 'L', 'L', 'L'], // dIdx 0: D 1
    ['L', 'L', 'L', 'L', 'L'], // dIdx 1: D 2-4
    ['L', 'L', 'L', 'L', 'L'], // dIdx 2: D 5-6
    ['L', 'L', 'L', 'L', 'L']  // dIdx 3: D 7-10
  ],
  // sIdx 1: Severity 2-3
  [
    ['L', 'L', 'L', 'L', 'L'], // D 1
    ['L', 'L', 'L', 'L', 'L'], // D 2-4
    ['L', 'L', 'L', 'L', 'M'], // D 5-6
    ['L', 'L', 'L', 'L', 'M']  // D 7-10
  ],
  // sIdx 2: Severity 4-6
  [
    ['L', 'L', 'L', 'L', 'L'], // D 1
    ['L', 'L', 'L', 'M', 'M'], // D 2-4
    ['L', 'L', 'M', 'M', 'H'], // D 5-6
    ['L', 'L', 'M', 'H', 'H']  // D 7-10
  ],
  // sIdx 3: Severity 7-8
  [
    ['L', 'L', 'L', 'L', 'L'], // D 1
    ['L', 'L', 'M', 'H', 'H'], // D 2-4
    ['L', 'M', 'M', 'H', 'H'], // D 5-6
    ['L', 'M', 'H', 'H', 'H']  // D 7-10
  ],
  // sIdx 4: Severity 9-10
  [
    ['L', 'L', 'M', 'H', 'H'], // D 1
    ['L', 'L', 'H', 'H', 'H'], // D 2-4
    ['L', 'M', 'H', 'H', 'H'], // D 5-6
    ['L', 'H', 'H', 'H', 'H']  // D 7-10
  ]
];
window.AIAG_VDA_AP_TABLE = AIAG_VDA_AP_TABLE;

function getApMatrixIndices(s, d, o) {
  let sIdx = 0;
  if (s === 1) sIdx = 0;
  else if (s <= 3) sIdx = 1;
  else if (s <= 6) sIdx = 2;
  else if (s <= 8) sIdx = 3;
  else sIdx = 4;

  let dIdx = 0;
  if (d === 1) dIdx = 0;
  else if (d <= 4) dIdx = 1;
  else if (d <= 6) dIdx = 2;
  else dIdx = 3;

  let oIdx = 0;
  if (o === 1) oIdx = 0;
  else if (o <= 3) oIdx = 1;
  else if (o <= 5) oIdx = 2;
  else if (o <= 7) oIdx = 3;
  else oIdx = 4;

  return { sIdx, dIdx, oIdx };
}
window.getApMatrixIndices = getApMatrixIndices;

function calculateAIAGVDA_AP(s, o, d, classSymbol = '') {
  let numS = parseInt(s) || 1;
  if (classSymbol && typeof getClassWeight === 'function') {
    const w = getClassWeight(classSymbol);
    if (w > numS) numS = w;
  }
  const numO = parseInt(o) || 1;
  const numD = parseInt(d) || 1;

  const { sIdx, dIdx, oIdx } = getApMatrixIndices(numS, numD, numO);
  return AIAG_VDA_AP_TABLE[sIdx][dIdx][oIdx];
}
window.calculateAIAGVDA_AP = calculateAIAGVDA_AP;

function computeAP(s, o, d, classSymbol = '') {
  return calculateAIAGVDA_AP(s, o, d, classSymbol);
}
window.computeAP = computeAP;
window.calculatedAIAGVDA_AP = computeAP;

function getRpnBinIndex(rpn) {
  if (rpn <= 100) return 0;
  if (rpn <= 200) return 1;
  if (rpn <= 300) return 2;
  if (rpn <= 400) return 3;
  if (rpn <= 500) return 4;
  if (rpn <= 600) return 5;
  if (rpn <= 700) return 6;
  if (rpn <= 800) return 7;
  if (rpn <= 900) return 8;
  return 9;
}
window.getRpnBinIndex = getRpnBinIndex;

function generateApMatrixHtml(gridData, title, badgeText, badgeBg) {
  const apMatrixConfig = [
    {
      sLabel: '1', rowSpan: 4, dRows: [
        { dLabel: '1', apList: AIAG_VDA_AP_TABLE[0][0], dIdx: 0 },
        { dLabel: '2-4', apList: AIAG_VDA_AP_TABLE[0][1], dIdx: 1 },
        { dLabel: '5-6', apList: AIAG_VDA_AP_TABLE[0][2], dIdx: 2 },
        { dLabel: '7-10', apList: AIAG_VDA_AP_TABLE[0][3], dIdx: 3 }
      ]
    },
    {
      sLabel: '2-3', rowSpan: 4, dRows: [
        { dLabel: '1', apList: AIAG_VDA_AP_TABLE[1][0], dIdx: 0 },
        { dLabel: '2-4', apList: AIAG_VDA_AP_TABLE[1][1], dIdx: 1 },
        { dLabel: '5-6', apList: AIAG_VDA_AP_TABLE[1][2], dIdx: 2 },
        { dLabel: '7-10', apList: AIAG_VDA_AP_TABLE[1][3], dIdx: 3 }
      ]
    },
    {
      sLabel: '4-6', rowSpan: 4, dRows: [
        { dLabel: '1', apList: AIAG_VDA_AP_TABLE[2][0], dIdx: 0 },
        { dLabel: '2-4', apList: AIAG_VDA_AP_TABLE[2][1], dIdx: 1 },
        { dLabel: '5-6', apList: AIAG_VDA_AP_TABLE[2][2], dIdx: 2 },
        { dLabel: '7-10', apList: AIAG_VDA_AP_TABLE[2][3], dIdx: 3 }
      ]
    },
    {
      sLabel: '7-8', rowSpan: 4, dRows: [
        { dLabel: '1', apList: AIAG_VDA_AP_TABLE[3][0], dIdx: 0 },
        { dLabel: '2-4', apList: AIAG_VDA_AP_TABLE[3][1], dIdx: 1 },
        { dLabel: '5-6', apList: AIAG_VDA_AP_TABLE[3][2], dIdx: 2 },
        { dLabel: '7-10', apList: AIAG_VDA_AP_TABLE[3][3], dIdx: 3 }
      ]
    },
    {
      sLabel: '9-10', rowSpan: 4, dRows: [
        { dLabel: '1', apList: AIAG_VDA_AP_TABLE[4][0], dIdx: 0 },
        { dLabel: '2-4', apList: AIAG_VDA_AP_TABLE[4][1], dIdx: 1 },
        { dLabel: '5-6', apList: AIAG_VDA_AP_TABLE[4][2], dIdx: 2 },
        { dLabel: '7-10', apList: AIAG_VDA_AP_TABLE[4][3], dIdx: 3 }
      ]
    }
  ];

  let html = `
    <div style="background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px; padding:12px; color:var(--text-primary); flex:1; min-width:0;">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
        <h4 style="font-size:12px; margin:0; color:#38bdf8; font-weight:bold;">${title}</h4>
        <span class="badge" style="background:${badgeBg}; color:#ffffff; font-size:10px; padding:2px 6px; border-radius:4px;">${badgeText}</span>
      </div>

      <div style="overflow-x:auto;">
        <table style="width:100%; border-collapse:collapse; text-align:center; font-size:10px;">
          <thead>
            <tr>
              <th rowspan="2" style="background:var(--table-header-bg); border:1px solid var(--border-color); width:35px; padding:4px; color:var(--table-header-text);">S</th>
              <th rowspan="2" style="background:var(--table-header-bg); border:1px solid var(--border-color); width:40px; padding:4px; color:var(--table-header-text);">D</th>
              <th colspan="5" style="background:var(--table-header-bg); border:1px solid var(--border-color); padding:4px; color:var(--table-header-text); font-size:11px;">O (Occurrence)</th>
            </tr>
            <tr>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">1</th>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">2-3</th>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">4-5</th>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">6-7</th>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">8-10</th>
            </tr>
          </thead>
          <tbody>
  `;

  apMatrixConfig.forEach((sGroup, sIdx) => {
    sGroup.dRows.forEach((dRow, dSubIdx) => {
      html += `<tr>`;
      if (dSubIdx === 0) {
        html += `<td rowspan="${sGroup.rowSpan}" style="background:var(--bg-card); border:1px solid var(--border-color); font-weight:bold; color:#38bdf8; font-size:11px;">S ${sGroup.sLabel}</td>`;
      }
      html += `<td style="background:var(--bg-card); border:1px solid var(--border-color); color:var(--text-muted); font-weight:bold;">${dRow.dLabel}</td>`;

      dRow.apList.forEach((apVal, oIdx) => {
        const bg = apVal === 'H' ? '#ef4444' : (apVal === 'M' ? '#f59e0b' : '#10b981');
        const count = gridData[sIdx][dRow.dIdx][oIdx];

        let cellContent = '';
        if (count > 0) {
          cellContent = `<span style="background:rgba(15,23,42,0.95); color:#ffffff; border-radius:3px; padding:1px 4px; font-weight:bold; font-size:10px; border:1px solid #ffffff;">${count}</span>`;
        }

        html += `
          <td style="background:${bg}; border:1px solid var(--border-color); padding:3px 2px; height:24px; vertical-align:middle;" title="S:${sGroup.sLabel} D:${dRow.dLabel} O-bin:${oIdx + 1} | AP=${apVal} | Count: ${count}">
            ${cellContent}
          </td>
        `;
      });

      html += `</tr>`;
    });
  });

  html += `
          </tbody>
        </table>
      </div>
    </div>
  `;

  return html;
}
window.generateApMatrixHtml = generateApMatrixHtml;

