// ----------------------------------------------------
// MULTI-THEME ENGINE (BRIGHT, BLACK ICE, NIGHT SKY)
// ----------------------------------------------------
function initTheme() {
  const savedTheme = localStorage.getItem('app_theme') || 'bright';
  setTheme(savedTheme);
}

function setTheme(themeName) {
  // Normalize themeName
  const normalized = (themeName === 'black' || themeName === 'dark')
    ? 'dark'
    : (themeName === 'night-sky' || themeName === 'nightSky')
      ? 'night-sky'
      : 'bright';

  // Remove all previous theme classes
  document.body.classList.remove('dark-theme', 'black-theme', 'night-sky-theme', 'bright-mode');

  const btn = document.getElementById('themeToggleBtn');
  const icon = document.getElementById('themeToggleIcon');
  const text = document.getElementById('themeToggleText');

  if (normalized === 'night-sky') {
    document.documentElement.setAttribute('data-theme', 'night-sky');
    document.body.setAttribute('data-theme', 'night-sky');
    document.body.classList.add('night-sky-theme');
    localStorage.setItem('app_theme', 'night-sky');

    if (icon) icon.innerText = '🌌';
    if (text) text.innerText = 'Night Sky';
    if (btn) {
      btn.style.background = 'linear-gradient(135deg, #1C1F3B 0%, #282C4D 60%, #4D4D80 100%)';
      btn.style.borderColor = '#4D4D80';
      btn.style.color = '#ffffff';
      btn.title = 'Current: Night Sky Theme (Click to switch to Bright)';
    }
  } else if (normalized === 'dark') {
    document.documentElement.setAttribute('data-theme', 'dark');
    document.body.setAttribute('data-theme', 'dark');
    document.body.classList.add('dark-theme', 'black-theme');
    localStorage.setItem('app_theme', 'dark');

    if (icon) icon.innerText = '🌙';
    if (text) text.innerText = 'Black Ice';
    if (btn) {
      btn.style.background = 'linear-gradient(135deg, #000000 0%, #1A1A1A 60%, #333333 100%)';
      btn.style.borderColor = '#4D4D4D';
      btn.style.color = '#ffffff';
      btn.title = 'Current: Black Ice Theme (Click to switch to Night Sky)';
    }
  } else {
    document.documentElement.setAttribute('data-theme', 'bright');
    document.body.setAttribute('data-theme', 'bright');
    document.body.classList.add('bright-mode');
    localStorage.setItem('app_theme', 'bright');

    if (icon) icon.innerText = '☀️';
    if (text) text.innerText = 'Bright';
    if (btn) {
      btn.style.background = 'linear-gradient(135deg, #0284c7 0%, #2563eb 100%)';
      btn.style.borderColor = '#38bdf8';
      btn.style.color = '#ffffff';
      btn.title = 'Current: Bright Theme (Click to switch to Black Ice)';
    }
  }
}

function toggleTheme() {
  const currentTheme = localStorage.getItem('app_theme') || 'bright';
  if (currentTheme === 'bright') {
    setTheme('dark'); // Bright -> Black Ice
  } else if (currentTheme === 'dark' || currentTheme === 'black') {
    setTheme('night-sky'); // Black Ice -> Night Sky
  } else {
    setTheme('bright'); // Night Sky -> Bright
  }
}
window.toggleTheme = toggleTheme;
window.setTheme = setTheme;
window.initTheme = initTheme;

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initTheme);
} else {
  initTheme();
}

