// ----------------------------------------------------
// Security & SHA-256 Password Encryption Helper
// ----------------------------------------------------
function sha256Pure(ascii) {
  function rightRotate(value, amount) {
    return (value >>> amount) | (value << (32 - amount));
  }
  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  const lengthProperty = 'length';
  let i, j;
  let result = '';
  const words = [];
  const asciiLength = ascii[lengthProperty];
  const hash = [];
  const k = [];
  let primeCounter = 0;
  const isComposite = {};
  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) {
        isComposite[i] = 1;
      }
      if (primeCounter < 8) {
        hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      }
      k[primeCounter] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
      primeCounter++;
    }
  }
  ascii += '\x80';
  while (ascii[lengthProperty] % 64 - 56) ascii += '\x00';
  for (i = 0; i < ascii[lengthProperty]; i++) {
    j = ascii.charCodeAt(i);
    if (j >> 8) return '';
    words[i >> 2] |= j << ((3 - i % 4) * 8);
  }
  words[words[lengthProperty]] = ((asciiLength * 8) / maxWord) | 0;
  words[words[lengthProperty]] = (asciiLength * 8);
  for (j = 0; j < words[lengthProperty]; j += 16) {
    const w = words.slice(j, j + 16);
    const oldHash = hash.slice(0);
    for (i = 0; i < 64; i++) {
      let wItem = w[i];
      if (i >= 16) {
        const s0 = rightRotate(w[i - 15], 7) ^ rightRotate(w[i - 15], 18) ^ (w[i - 15] >>> 3);
        const s1 = rightRotate(w[i - 2], 17) ^ rightRotate(w[i - 2], 19) ^ (w[i - 2] >>> 10);
        wItem = w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
      }
      const ch = (hash[4] & hash[5]) ^ (~hash[4] & hash[6]);
      const maj = (hash[0] & hash[1]) ^ (hash[0] & hash[2]) ^ (hash[1] & hash[2]);
      const sigma0 = rightRotate(hash[0], 2) ^ rightRotate(hash[0], 13) ^ rightRotate(hash[0], 22);
      const sigma1 = rightRotate(hash[4], 6) ^ rightRotate(hash[4], 11) ^ rightRotate(hash[4], 25);
      const temp1 = hash[7] + sigma1 + ch + k[i] + wItem;
      const temp2 = sigma0 + maj;
      hash.unshift((temp1 + temp2) | 0);
      hash[4] = (hash[4] + temp1) | 0;
      hash.pop();
    }
    for (i = 0; i < 8; i++) {
      hash[i] = (hash[i] + oldHash[i]) | 0;
    }
  }
  for (i = 0; i < 8; i++) {
    let word = hash[i];
    if (word < 0) word += maxWord;
    result += word.toString(16).padStart(8, '0');
  }
  return result;
}

async function hashPasswordSHA256(password) {
  if (typeof crypto !== 'undefined' && crypto.subtle) {
    try {
      const msgUint8 = new TextEncoder().encode(password);
      const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
      const hashArray = Array.from(new Uint8Array(hashBuffer));
      return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    } catch (e) {
      console.warn("subtle crypto failed, falling back to JS SHA-256:", e);
    }
  }
  return sha256Pure(password);
}

let currentUser = null;

function isCurrentUserAdmin() {
  if (!currentUser) return false;
  return currentUser.role === 'Admin' ||
    currentUser.role === 'SuperAdmin' ||
    Boolean(currentUser.permissions && currentUser.permissions.canManageUsers);
}


// ----------------------------------------------------
// ----------------------------------------------------
// Core Encryption Engine for Admin Settings & System Libraries
// ----------------------------------------------------
const SETTINGS_MAGIC_HEADER = 'JOST_ENC_CFG_v1:';
const LIB_MAGIC_HEADER = 'JOST_ENC_LIB_v1:';
const ENCRYPTION_SECRET_KEY = 'JostFMEA$AdminSecretKey2026';

function encryptDataPayload(payloadObj, magicHeader = SETTINGS_MAGIC_HEADER) {
  try {
    const jsonStr = JSON.stringify(payloadObj);
    const utf8Bytes = (typeof TextEncoder !== 'undefined')
      ? new TextEncoder().encode(jsonStr)
      : Buffer.from(jsonStr, 'utf8');
    const encryptedBytes = new Uint8Array(utf8Bytes.length);
    for (let i = 0; i < utf8Bytes.length; i++) {
      encryptedBytes[i] = utf8Bytes[i] ^ ENCRYPTION_SECRET_KEY.charCodeAt(i % ENCRYPTION_SECRET_KEY.length);
    }
    let binary = '';
    for (let i = 0; i < encryptedBytes.length; i++) {
      binary += String.fromCharCode(encryptedBytes[i]);
    }
    const b64 = (typeof btoa !== 'undefined') ? btoa(binary) : Buffer.from(binary, 'binary').toString('base64');
    return magicHeader + b64;
  } catch (e) {
    console.error("Encryption error:", e);
    return null;
  }
}

function decryptDataPayload(encryptedStr) {
  try {
    if (!encryptedStr || typeof encryptedStr !== 'string') return null;
    let payload = encryptedStr.trim();
    if (payload.startsWith(SETTINGS_MAGIC_HEADER)) {
      payload = payload.slice(SETTINGS_MAGIC_HEADER.length);
    } else if (payload.startsWith(LIB_MAGIC_HEADER)) {
      payload = payload.slice(LIB_MAGIC_HEADER.length);
    }
    const binary = (typeof atob !== 'undefined') ? atob(payload) : Buffer.from(payload, 'base64').toString('binary');
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i) ^ ENCRYPTION_SECRET_KEY.charCodeAt(i % ENCRYPTION_SECRET_KEY.length);
    }
    const decodedStr = (typeof TextDecoder !== 'undefined')
      ? new TextDecoder('utf-8').decode(bytes)
      : Buffer.from(bytes).toString('utf8');
    return JSON.parse(decodedStr);
  } catch (e) {
    // If unencrypted or raw JSON, fallback to JSON.parse
    try {
      return JSON.parse(encryptedStr.trim());
    } catch (parseErr) {
      console.error("Decryption error:", e);
      return null;
    }
  }
}

function encryptAdminSettings(settingsObj) {
  return encryptDataPayload(settingsObj, SETTINGS_MAGIC_HEADER);
}

function decryptAdminSettings(encryptedStr) {
  return decryptDataPayload(encryptedStr);
}

