let systemUsers = [...DEFAULT_USER_LIBRARY];
let loginAuditLogs = [];

function getUserLibraryFilePath() {
  const baseDir = getEffectiveSharePointPath();
  const sep = (baseDir.includes('/') && !baseDir.includes('\\')) ? '/' : '\\';
  return (baseDir.endsWith('\\') || baseDir.endsWith('/'))
    ? `${baseDir}${USER_LIBRARY_FILE_NAME}`
    : `${baseDir}${sep}${USER_LIBRARY_FILE_NAME}`;
}

async function checkAndInitUserLibrary() {
  const isElectron = window.electronAPI && window.electronAPI.isElectron;
  const filePath = getUserLibraryFilePath();

  if (isElectron && window.electronAPI.readFileContent) {
    try {
      let readRes = await window.electronAPI.readFileContent(filePath);
      // Auto-migrate from fmea_user_library.json if .enc not yet created
      if ((!readRes || !readRes.success || !readRes.content) && USER_LIBRARY_FALLBACK_NAME) {
        const baseDir = getEffectiveSharePointPath();
        const sep = (baseDir.includes('/') && !baseDir.includes('\\')) ? '/' : '\\';
        const fallbackPath = (baseDir.endsWith('\\') || baseDir.endsWith('/'))
          ? `${baseDir}${USER_LIBRARY_FALLBACK_NAME}`
          : `${baseDir}${sep}${USER_LIBRARY_FALLBACK_NAME}`;
        const fallbackRes = await window.electronAPI.readFileContent(fallbackPath);
        if (fallbackRes && fallbackRes.success && fallbackRes.content) {
          readRes = fallbackRes;
        }
      }

      if (readRes && readRes.success && readRes.content && readRes.content.trim()) {
        try {
          const parsed = decryptDataPayload(readRes.content);
          if (Array.isArray(parsed) && parsed.length > 0) {
            let merged = [...parsed];
            if (!merged.some(u => u.username && u.username.toLowerCase() === 'admin')) {
              merged.unshift(DEFAULT_USER_LIBRARY[0]);
            }
            if (!merged.some(u => u.username && u.username.toLowerCase() === 'readonly')) {
              merged.push(DEFAULT_USER_LIBRARY[1]);
            }
            systemUsers = merged;
            try { localStorage.setItem('jost_system_users', JSON.stringify(systemUsers)); } catch (e) { }
            // Ensure persisted in encrypted format
            await saveUserLibraryToDisk();
            return systemUsers;
          }
        } catch (parseErr) {
          console.warn("Could not parse user library, re-initializing default:", parseErr);
        }
      }

      // Default init
      systemUsers = [...DEFAULT_USER_LIBRARY];
      await saveUserLibraryToDisk();
      try { localStorage.setItem('jost_system_users', JSON.stringify(systemUsers)); } catch (e) { }
      return systemUsers;
    } catch (err) {
      console.warn("Error checking user library on disk:", err);
    }
  }

  // Fallback to local storage or defaults
  try {
    const localStored = localStorage.getItem('jost_system_users');
    if (localStored) {
      const parsed = JSON.parse(localStored);
      if (Array.isArray(parsed) && parsed.length > 0) {
        systemUsers = parsed;
        return systemUsers;
      }
    }
  } catch (e) { }

  systemUsers = [...DEFAULT_USER_LIBRARY];
  return systemUsers;
}

async function saveUserLibraryToDisk() {
  const isElectron = window.electronAPI && window.electronAPI.isElectron;
  const filePath = getUserLibraryFilePath();
  const encryptedContent = encryptDataPayload(systemUsers, LIB_MAGIC_HEADER);

  try {
    localStorage.setItem('jost_system_users', JSON.stringify(systemUsers));
  } catch (e) { }

  if (isElectron && window.electronAPI.writeFile && encryptedContent) {
    try {
      const res = await window.electronAPI.writeFile(filePath, encryptedContent);
      // Also mirror to local app directory if distinct from repository path
      const localAppPath = `d:\\Jost\\${USER_LIBRARY_FILE_NAME}`;
      if (localAppPath.toLowerCase() !== filePath.toLowerCase()) {
        try { await window.electronAPI.writeFile(localAppPath, encryptedContent); } catch (e) { }
      }
      return res && res.success;
    } catch (err) {
      console.warn("Failed to write fmea_user_library.enc to disk:", err);
    }
  }
  return false;
}

// ----------------------------------------------------
// Authentication Logic
// ----------------------------------------------------
async function handleLoginSubmit(e) {
  if (e) e.preventDefault();
  try {
    // Refresh user library from disk first
    await checkAndInitUserLibrary();

    const usernameInput = document.getElementById('loginUsername').value.trim();
    const passwordInput = document.getElementById('loginPassword').value.trim();
    const errDiv = document.getElementById('loginErrorMsg');

    const isReadOnlyLogin = usernameInput.toLowerCase() === 'readonly';

    let foundUser = null;
    if (isReadOnlyLogin) {
      foundUser = systemUsers.find(u => u.username && u.username.toLowerCase() === 'readonly');
      if (!foundUser) {
        foundUser = DEFAULT_USER_LIBRARY[1];
        systemUsers.push(foundUser);
        await saveUserLibraryToDisk();
      }
    } else {
      const hashedInput = await hashPasswordSHA256(passwordInput);
      foundUser = systemUsers.find(u =>
        u.username && u.username.toLowerCase() === usernameInput.toLowerCase() &&
        (u.noPasswordRequired === true || u.passwordHash === hashedInput)
      );
    }

    if (foundUser) {
      currentUser = foundUser;
      if (typeof populateAutoSaveAdminSettingsForm === 'function') {
        populateAutoSaveAdminSettingsForm();
      } else if (typeof toggleFileAccessModeFields === 'function') {
        toggleFileAccessModeFields();
      }
      loginAuditLogs.unshift({ username: foundUser.username, timestamp: new Date().toLocaleString(), status: 'Success' });
      if (errDiv) errDiv.style.display = 'none';
      document.getElementById('loginScreenOverlay').style.display = 'none';

      // Ensure all files are closed and workspace is reset on login
      if (typeof closeActiveFileAndResetWorkspace === 'function') {
        closeActiveFileAndResetWorkspace();
      }

      // Sync user to storage & Quality Suite session
      try {
        sessionStorage.setItem('jost_session_active', 'true');
        sessionStorage.setItem('jost_current_user', JSON.stringify(foundUser));
        localStorage.setItem('jost_current_user', JSON.stringify(foundUser));
        localStorage.setItem('fmea_user', JSON.stringify(foundUser));
        if (window.QualityStorageSync && typeof window.QualityStorageSync.setCurrentUser === 'function') {
          window.QualityStorageSync.setCurrentUser(foundUser);
        }
      } catch (e) { }

      // Determine user access capabilities
      const role = (foundUser.role || '').toLowerCase();
      const isPlantUserOnly = role === 'plant user';

      if (isPlantUserOnly) {
        // Quality Suite only: launch directly into Failure Register without opening FMEA file
        window.location.href = 'FailureRegister.html?view=log';
        return false;
      }

      // Dual access (FMEA + Quality): Load catalog and present Destination choice modal
      sharePointFileListCache = null;
      await loadSharePointCatalogFromDisk();

      if (typeof window.openWorkspaceSelectorModal === 'function') {
        window.openWorkspaceSelectorModal(foundUser);
      } else {
        await openSharePointFileBrowserModal();
      }

      // Update menu bar avatar
      const label = document.getElementById('currentUserLabel');
      if (label) label.textContent = `${foundUser.name} (${foundUser.role})`;
      const infoDiv = document.getElementById('userMenuInfo');
      if (infoDiv) infoDiv.innerHTML = `<strong>${escapeHtml(foundUser.name)}</strong><br>${escapeHtml(foundUser.username)} · <span style="color:#60a5fa;">${escapeHtml(foundUser.role)}</span>`;

      // Show Admin menu for system admins and file creators
      updateAdminMenuVisibility();

      // Update Revision Approval notification bell & pending count for newly logged-in user
      if (typeof updateNavbarNotificationBellUI === 'function') {
        updateNavbarNotificationBellUI();
      }

      // Check if user logged in after clicking deep-link
      try {
        const pendingIntentRaw = sessionStorage.getItem('pendingApprovalReviewIntent');
        if (pendingIntentRaw) {
          sessionStorage.removeItem('pendingApprovalReviewIntent');
          const pendingIntent = JSON.parse(pendingIntentRaw);
          if (pendingIntent && pendingIntent.logId) {
            setTimeout(async () => {
              if (typeof openApprovalReviewFromLog === 'function') {
                await openApprovalReviewFromLog(pendingIntent.logId);
              }
            }, 300);
          }
        }
      } catch (e) {
        console.warn('Error handling post-login approval intent:', e);
      }
    } else {
      loginAuditLogs.unshift({ username: usernameInput, timestamp: new Date().toLocaleString(), status: 'Failed (Invalid Credentials)' });
      if (errDiv) errDiv.style.display = 'block';
    }
  } catch (err) {
    console.error("Error during login submit:", err);
    if (window.showCustomAlert) {
      await window.showCustomAlert('Login Error', err.message, 'error');
    } else {
      alert("Login Error: " + err.message);
    }
  }
  return false;
}

async function loginAsReadOnly() {
  const userInput = document.getElementById('loginUsername');
  const passInput = document.getElementById('loginPassword');
  if (userInput) userInput.value = 'readonly';
  if (passInput) passInput.value = '';
  await handleLoginSubmit(null);
}

async function logout() {
  const currentName = activeSharePointFileName || (fmeaData && fmeaData.projectInfo && fmeaData.projectInfo.name ? fmeaData.projectInfo.name : 'Active FMEA Project');
  const hasActiveData = !!(activeSharePointFileName || (fmeaData && fmeaData.structureTree && fmeaData.structureTree.length > 0) || (fmeaData && fmeaData.revisions && fmeaData.revisions.length > 0));

  if (hasActiveData || (typeof hasUnsavedChanges !== 'undefined' && hasUnsavedChanges)) {
    const unsavedText = (typeof hasUnsavedChanges !== 'undefined' && hasUnsavedChanges) ? ' (Contains UNSAVED changes!)' : '';
    const shouldSave = await showCustomConfirm(
      `You have an active project open: "${currentName}"${unsavedText}.\n\nDo you want to SAVE your data before logging out?`,
      "Logout Warning",
      "warning"
    );

    if (shouldSave) {
      if (typeof performAutoSave === 'function') {
        await performAutoSave(`Logout Auto-Save for "${currentName}"`);
      }
    } else {
      const confirmDiscard = await showCustomConfirm(
        `Are you sure you want to LOGOUT WITHOUT SAVING?\n\nClick Confirm to discard changes, close the project, and log out.`,
        "Discard Changes & Logout",
        "danger"
      );
      if (!confirmDiscard) {
        return; // Abort logout process
      }
    }

    // Close existing file & reset workspace
    closeActiveFileAndResetWorkspace();
  }

  currentUser = null;
  try {
    sessionStorage.removeItem('jost_session_active');
    sessionStorage.removeItem('jost_current_user');
    localStorage.removeItem('jost_current_user');
    localStorage.removeItem('fmea_user');
  } catch (e) { }
  if (typeof toggleFileAccessModeFields === 'function') {
    toggleFileAccessModeFields();
  }

  if (typeof updateNavbarNotificationBellUI === 'function') {
    updateNavbarNotificationBellUI();
  }

  const loginOverlay = document.getElementById('loginScreenOverlay');
  if (loginOverlay) loginOverlay.style.display = 'flex';

  const label = document.getElementById('currentUserLabel');
  if (label) label.textContent = 'Not Logged In';
  const infoDiv = document.getElementById('userMenuInfo');
  if (infoDiv) infoDiv.textContent = 'Not logged in';
  const adminItem = document.getElementById('menuAdminItem');
  if (adminItem) adminItem.style.display = 'none';

  if (typeof checkAndInitSharePointAdminSettings === 'function') {
    checkAndInitSharePointAdminSettings();
  }
  if (typeof renderFMEATable === 'function') {
    renderFMEATable();
  }
  if (typeof showToast === 'function') {
    showToast("Logged out successfully. Active file closed.");
  }
}

