function cleanupLegacyLocalStorageFileStores() {
  cleanupNonSettingLocalStorage();
}

function cleanupNonSettingLocalStorage() {
  try {
    if (typeof localStorage === 'undefined') return;
    const keysToRemove = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && !PERSISTED_SETTING_KEYS.has(key)) {
        keysToRemove.push(key);
      }
    }
    keysToRemove.forEach(k => {
      try { localStorage.removeItem(k); } catch (e) { }
    });
  } catch (e) {
    console.warn('[Storage Cleanup Notice]', e);
  }
}

// Window beforeunload: purge non-setting temporary storage & clear in-memory WB3 state
