function closeActiveFileAndResetWorkspace() {
  if (typeof releaseCurrentFileLock === 'function') {
    releaseCurrentFileLock();
  }
  cleanupLegacyLocalStorageFileStores();
  activeSharePointFileName = null;
  if (typeof hasUnsavedChanges !== 'undefined') {
    hasUnsavedChanges = false;
  }

  // Preserve the current effective repository path before global state reset
  const currentPath = typeof getEffectiveSharePointPath === 'function' ? getEffectiveSharePointPath() : activeResolvedSharePointLocalPath;

  // Clear global FMEA data model
  resetGlobalState();
  viewCompleteFmeaMode = false;
  const chkViewCompleteEl = document.getElementById('chkViewCompleteFmea');
  if (chkViewCompleteEl) {
    chkViewCompleteEl.checked = false;
  }

  // Restore the effective path to prevent resetting back to default 'd:\Jost'
  if (currentPath) {
    activeResolvedSharePointLocalPath = currentPath;
    if (typeof fmeaData !== 'undefined' && fmeaData) {
      fmeaData.adminSettings = fmeaData.adminSettings || {};
      fmeaData.adminSettings.sharepointSiteUrl = currentPath;
      fmeaData.adminSettings.adminConfigSharePointUrl = currentPath;
    }
  }

  const focusedNodeLabel = document.getElementById('focusedNodeName');
  if (focusedNodeLabel) {
    focusedNodeLabel.textContent = 'None Selected (No File Open)';
  }

  if (typeof updateHeaderRevisionBadge === 'function') updateHeaderRevisionBadge();
  if (typeof renderTreeSidebar === 'function') renderTreeSidebar();
  if (typeof renderFmeaContextDropdown === 'function') renderFmeaContextDropdown();
  if (typeof renderFMEATable === 'function') renderFMEATable();
  if (typeof updateWorkspaceVisibility === 'function') updateWorkspaceVisibility();
  if (typeof updateSaveStatusBadgeUI === 'function') updateSaveStatusBadgeUI('saved', '✓ Saved');
}

