    const isAdminTarget = u.role === 'Admin' || u.role === 'SuperAdmin' || u.username.toLowerCase() === 'admin';
    const isCurrentAdmin = currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin');

