function convertFlatTreeToNested(nodes) {
  if (!nodes) return null;
  if (!Array.isArray(nodes) && typeof nodes === 'object') return nodes;
  if (!Array.isArray(nodes) || nodes.length === 0) return null;

  const map = {};
  const normalizedNodes = nodes.map((n, idx) => {
    const nodeId = String(n.id || n.structId || ('struct-' + idx));
    const parentId = n.parentId ? String(n.parentId) : null;
    const typeStr = n.isAssembly ? (idx === 0 ? 'System' : 'Sub-System') : (n.type || 'Component');

    const nodeObj = {
      id: nodeId,
      parentId: parentId,
      name: String(n.name || n.componentName || 'Component ' + (idx + 1)),
      partNo: String(n.partNo || n.partNumber || n.partCode || 'PART-001'),
      partNumber: String(n.partNumber || n.partNo || n.partCode || 'PART-001'),
      type: typeStr,
      description: String(n.description || n.desc || ''),
      children: []
    };
    map[nodeId] = nodeObj;
    return nodeObj;
  });

  let currentSubAssemblyId = null;
  const topRootId = normalizedNodes[0].id;

  normalizedNodes.forEach((node, idx) => {
    if (idx === 0) return;
    if (!node.parentId) {
      if (node.type === 'Component' && currentSubAssemblyId) {
        node.parentId = currentSubAssemblyId;
      } else {
        node.parentId = topRootId;
      }
    }
    if (node.type === 'Sub-System' || node.type === 'Assembly' || node.type === 'System') {
      currentSubAssemblyId = node.id;
    }
  });

  const roots = [];
  normalizedNodes.forEach(node => {
    if (node.parentId && map[node.parentId] && node.parentId !== node.id) {
      map[node.parentId].children.push(node);
    } else {
      roots.push(node);
    }
  });

  if (roots.length === 1) {
    return roots[0];
  } else if (roots.length > 1) {
    return {
      id: 'root-system-assembly',
      name: (roots[0].name || 'System') + ' Assembly',
      partNo: roots[0].partNo || 'SYS-MASTER',
      type: 'System',
      children: roots
    };
  }
  return null;
}

function normalizeFmeaDataset(parsed) {
  if (!parsed || typeof parsed !== 'object') return parsed;

  if (parsed.structure && typeof deduplicateStructureTree === 'function') {
    deduplicateStructureTree(parsed.structure);
  }
  if (Array.isArray(parsed.pfmeas)) {
    parsed.pfmeas.forEach(p => {
      if (p && p.structure && typeof deduplicateStructureTree === 'function') {
        deduplicateStructureTree(p.structure);
      }
    });
  }

  parsed.functions = parsed.functions || [];
  parsed.requirements = parsed.requirements || [];
  parsed.functionLines = parsed.functionLines || [];
  parsed.functionRequirements = parsed.functionRequirements || {};

  parsed.libraries = parsed.libraries || {};
  parsed.libraries.effects = parsed.libraries.effects || [];
  parsed.libraries.causes = parsed.libraries.causes || [];
  parsed.libraries.controls = parsed.libraries.controls || [];
  parsed.libraries.actions = parsed.libraries.actions || [];

  parsed.failureModeEffects = parsed.failureModeEffects || {};
  parsed.failureModeCauses = parsed.failureModeCauses || {};
  parsed.causeControls = parsed.causeControls || {};
  parsed.causeActions = parsed.causeActions || {};

  // 1. Deduplicate & standardize functions (alias duplicate function IDs by structId + name)
  const funcIdAliasMap = new Map();
  const uniqueFunctions = [];
  const funcNameKeyMap = new Map();

  parsed.functions.forEach((f, idx) => {
    f.structId = f.structId || f.structureId;
    f.funcNo = f.funcNo || `FUNC-${String(idx + 1).padStart(2, '0')}`;
    f.name = f.name || f.desc || f.text || 'Function';
    const key = (f.structId || '') + ':::' + f.name.trim().toLowerCase();
    if (!funcNameKeyMap.has(key)) {
      funcNameKeyMap.set(key, f.id);
      uniqueFunctions.push(f);
    } else {
      const primaryId = funcNameKeyMap.get(key);
      if (f.id && f.id !== primaryId) {
        funcIdAliasMap.set(f.id, primaryId);
      }
    }
  });
  parsed.functions = uniqueFunctions;

  // 2. Deduplicate & standardize requirements (alias duplicate requirement IDs by structId + text)
  const reqIdAliasMap = new Map();
  const uniqueRequirements = [];
  const reqTextKeyMap = new Map();

  parsed.requirements.forEach((r, idx) => {
    r.structId = r.structId || r.structureId;
    r.reqNo = r.reqNo || `REQ-${String(idx + 1).padStart(2, '0')}`;
    r.text = r.text || r.desc || r.name || 'Requirement';
    const key = (r.structId || '') + ':::' + r.text.trim().toLowerCase();
    if (!reqTextKeyMap.has(key)) {
      reqTextKeyMap.set(key, r.id);
      uniqueRequirements.push(r);
    } else {
      const primaryId = reqTextKeyMap.get(key);
      if (r.id && r.id !== primaryId) {
        reqIdAliasMap.set(r.id, primaryId);
      }
    }
  });
  parsed.requirements = uniqueRequirements;

  // 3. Consolidate & Merge functionLines sharing the same structId and funcId
  const consolidatedLines = [];
  const lineMap = new Map(); // key: structId + ':::' + funcId

  parsed.functionLines.forEach(fl => {
    // Alias funcId <-> functionId
    let fId = fl.funcId || fl.functionId;
    if (funcIdAliasMap.has(fId)) fId = funcIdAliasMap.get(fId);
    fl.funcId = fId;
    fl.functionId = fId;

    // Alias reqId <-> requirementId
    let rId = fl.reqId || fl.requirementId;
    if (reqIdAliasMap.has(rId)) rId = reqIdAliasMap.get(rId);
    fl.reqId = rId;
    fl.requirementId = rId;

    fl.failureModes = fl.failureModes || [];

    // Auto-create failureMode object from failureModeId/failureModeName if failureModes array is empty
    if (fl.failureModes.length === 0 && (fl.failureModeId || fl.failureModeName)) {
      const fmId = fl.failureModeId || ('fm-' + fl.id);
      const fmName = fl.failureModeName || 'Failure Mode';
      fl.failureModes.push({
        id: fmId,
        name: fmName,
        severity: fl.severity || 5,
        occurrence: fl.occurrence || 3,
        detection: fl.detection || 2,
        rpn: fl.rpn || 30,
        ap: fl.ap || 'M'
      });
    }

    const key = (fl.structId || '') + ':::' + (fl.funcId || '');
    let targetFl = null;

    if (!lineMap.has(key)) {
      lineMap.set(key, fl);
      consolidatedLines.push(fl);
      targetFl = fl;
    } else {
      const primaryFl = lineMap.get(key);
      targetFl = primaryFl;

      // Merge failureModes into primaryFl (avoiding duplicate fm.id)
      (fl.failureModes || []).forEach(fm => {
        if (!primaryFl.failureModes.some(existingFm => existingFm.id === fm.id)) {
          primaryFl.failureModes.push(fm);
        }
      });
      // Redirect requirements to primaryFl
      parsed.functionRequirements[primaryFl.id] = parsed.functionRequirements[primaryFl.id] || [];
      if (parsed.functionRequirements[fl.id]) {
        parsed.functionRequirements[fl.id].forEach(reqId => {
          const finalReqId = reqIdAliasMap.get(reqId) || reqId;
          if (!parsed.functionRequirements[primaryFl.id].includes(finalReqId)) {
            parsed.functionRequirements[primaryFl.id].push(finalReqId);
          }
        });
      }
    }

    // Auto-link requirementId into parsed.functionRequirements map
    parsed.functionRequirements[targetFl.id] = parsed.functionRequirements[targetFl.id] || [];
    if (fl.requirementId) {
      const finalReqId = reqIdAliasMap.get(fl.requirementId) || fl.requirementId;
      if (!parsed.functionRequirements[targetFl.id].includes(finalReqId)) {
        parsed.functionRequirements[targetFl.id].push(finalReqId);
      }
    }

    // Auto-link requirement by functionId/structId if functionRequirements map is currently empty for this line
    if (parsed.functionRequirements[targetFl.id].length === 0) {
      parsed.requirements.forEach(req => {
        if (req.structId === fl.structId && (req.functionId === fl.funcId || req.funcId === fl.funcId)) {
          if (!parsed.functionRequirements[targetFl.id].includes(req.id)) {
            parsed.functionRequirements[targetFl.id].push(req.id);
          }
        }
      });
    }

    // Ensure failureModeEffects and failureModeCauses map entries match fm.id
    (targetFl.failureModes || []).forEach(fm => {
      if (!parsed.failureModeEffects[fm.id] && parsed.failureModeEffects[fl.id]) {
        parsed.failureModeEffects[fm.id] = parsed.failureModeEffects[fl.id];
      }
      if (!parsed.failureModeCauses[fm.id] && parsed.failureModeCauses[fl.id]) {
        parsed.failureModeCauses[fm.id] = parsed.failureModeCauses[fl.id];
      }
    });

    // Remove untouched auto-created placeholder default failure modes
    targetFl.failureModes = (targetFl.failureModes || []).filter(fm => {
      const n = (fm && fm.name || '').trim();
      const isPlaceholder = n === 'Default Failure Mode (Click to Edit)' || n === 'Process Failure Mode (Click to Edit)';
      if (!isPlaceholder) return true;
      const effs = parsed.failureModeEffects[fm.id] || [];
      const causes = parsed.failureModeCauses[fm.id] || [];
      return effs.length > 0 || causes.length > 0;
    });
  });

  if (Array.isArray(parsed.pfmeas)) {
    parsed.pfmeas.forEach(pf => {
      if (!pf || !Array.isArray(pf.functionLines)) return;
      pf.functionLines.forEach(pfl => {
        pfl.failureModes = (pfl.failureModes || []).filter(fm => {
          const n = (fm && fm.name || '').trim();
          const isPlaceholder = n === 'Default Failure Mode (Click to Edit)' || n === 'Process Failure Mode (Click to Edit)';
          if (!isPlaceholder) return true;
          const effs = (pf.failureModeEffects && pf.failureModeEffects[fm.id]) || [];
          const causes = (pf.failureModeCauses && pf.failureModeCauses[fm.id]) || [];
          return effs.length > 0 || causes.length > 0;
        });
      });
    });
  }

  parsed.functionLines = consolidatedLines;
  return parsed;
}

function loadParsedFMEAData(parsed) {
  if (parsed && isValidFmeaDataPayload(parsed)) {
    // Complete state erase & purge of previous file memory
    resetGlobalState();

    // Auto-normalize structure representation if flat array or structureTree was provided
    if (Array.isArray(parsed.structure)) {
      parsed.structureTree = parsed.structure;
      parsed.structure = convertFlatTreeToNested(parsed.structure);
    } else if (!parsed.structure && parsed.structureTree && Array.isArray(parsed.structureTree)) {
      parsed.structure = convertFlatTreeToNested(parsed.structureTree);
    } else if (parsed.structure && typeof parsed.structure === 'object' && !parsed.structureTree) {
      if (typeof getFlatStructureNodes === 'function') {
        parsed.structureTree = getFlatStructureNodes(parsed.structure);
      }
    }

    if (parsed.structure && typeof deduplicateStructureTree === 'function') {
      deduplicateStructureTree(parsed.structure);
      if (typeof getFlatStructureNodes === 'function') {
        parsed.structureTree = getFlatStructureNodes(parsed.structure);
      }
    }

    // Auto-normalize projectInfo and revisions for seamless compatibility
    if (!parsed.projectInfo || !parsed.projectInfo.name) {
      const defaultName = (parsed.structure && parsed.structure.name) ? parsed.structure.name : "Imported FMEA Project";
      parsed.projectInfo = {
        name: defaultName,
        fmeaCode: `DFMEA-${Date.now().toString().slice(-6)}`,
        subject: "Automotive Systems Reliability & DFMEA Analysis",
        creatorName: "JOST AI FMEA Generator",
        author: "JOST AI FMEA Generator",
        date: new Date().toISOString().slice(0, 10),
        ...(parsed.projectInfo || {})
      };
    }

    if (!parsed.revisions) {
      parsed.revisions = [];
    }

    // Normalize functions, requirements, failureModes, effects, causes, and controls
    parsed = normalizeFmeaDataset(parsed);

    fmeaData = parsed;
    fmeaData.activeFmeaType = fmeaData.activeFmeaType || 'DFMEA';
    fmeaData.accessMode = fmeaData.accessMode || 'READ_WRITE';
    fmeaData.status = fmeaData.status || 'In Progress';
    fmeaData.revisions = fmeaData.revisions || [];
    fmeaData.currentRevision = (fmeaData.revisions.length > 0) ? fmeaData.revisions[0] : null;
    fmeaData.meetings = fmeaData.meetings || [];
    fmeaData.libraries = fmeaData.libraries || { mainEffectFunctions: [], effects: [], causes: [], controls: [], actions: [] };
    ensureMasterLibraryData();
    fmeaData.libraries.mainEffectFunctions = fmeaData.libraries.mainEffectFunctions || [];
    fmeaData.failureModeEffects = fmeaData.failureModeEffects || {};
    fmeaData.failureModeCauses = fmeaData.failureModeCauses || {};
    fmeaData.causeControls = fmeaData.causeControls || {};
    fmeaData.causeActions = fmeaData.causeActions || {};
    fmeaData.characteristicLinkages = parsed.characteristicLinkages || {};
    fmeaData.characteristicInControlPlan = parsed.characteristicInControlPlan || {};

    // Restore external state arrays from saved data
    if (parsed.requirementGroups) requirementGroups = parsed.requirementGroups;
    if (parsed.systemUsers) systemUsers = parsed.systemUsers;
    if (parsed.loginAuditLogs) loginAuditLogs = parsed.loginAuditLogs;

    // Ensure default user rights baseline
    fmeaData.userRights = fmeaData.userRights || {};
    if (!fmeaData.userRights['admin']) fmeaData.userRights['admin'] = 'Owner';
    if (!fmeaData.userRights['readonly']) fmeaData.userRights['readonly'] = 'Viewer';
    if (!fmeaData.userRights['*']) fmeaData.userRights['*'] = 'Viewer';
    const fileCreator = fmeaData.createdBy || fmeaData.projectInfo?.creatorName || fmeaData.projectInfo?.author;
    if (fileCreator && !fmeaData.userRights[fileCreator]) {
      fmeaData.userRights[fileCreator] = 'Owner';
    }

    // Restore saved AI Workbench progress so user can stop and resume after closing file
    if (typeof restoreWorkbenchStateFromProjectData === 'function') {
      restoreWorkbenchStateFromProjectData(fmeaData);
    }

    renderVariantDropdowns();
    renderFmeaContextDropdown();
    renderTreeSidebar();

    // Auto-select structure node and render DFMEA table part by part
    const allStructNodes = getStructureNodesArray(fmeaData.structure);
    if (allStructNodes.length > 0) {
      if (!selectedStructureId || !allStructNodes.some(n => n.id === selectedStructureId)) {
        selectedStructureId = allStructNodes[0].id;
      }
    }

    const firstNode = selectedStructureId ? getStructureNodeById(fmeaData.structure, selectedStructureId) : (allStructNodes[0] || null);
    const firstNodeLabel = firstNode ? `${firstNode.partNo ? firstNode.partNo + ' - ' : ''}${firstNode.name}` : 'Root Element';
    if (typeof renderFMEATableAsync === 'function') {
      renderFMEATableAsync(firstNodeLabel);
    } else {
      renderFMEATable();
    }

    closeModal('startupModal');
    processPostLoadRevisionCheck();
    showToast("✨ Successfully loaded project dataset!");
  } else {
    closeActiveFileAndResetWorkspace();
    if (typeof showCustomAlert === 'function') {
      showCustomAlert("⚠️ Cannot Open File\n\nThe selected file is corrupted or not a valid FMEA project dataset.\n\nReturning to File Browser...", "Corrupted File Error", "error");
    } else {
      alert("Invalid or Corrupted FMEA JSON format.");
    }
    if (typeof openSharePointFileBrowserModal === 'function') {
      openSharePointFileBrowserModal();
    }
  }
}

function loadJSON(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = async function (e) {
    try {
      const parsed = await decryptFmeaFilePayload(e.target.result);
      if (!isValidFmeaDataPayload(parsed)) {
        throw new Error("File content does not match valid FMEA JSON schema.");
      }
      activeSharePointFileName = file.name;
      loadParsedFMEAData(parsed);
    } catch (err) {
      closeActiveFileAndResetWorkspace();
      if (typeof showCustomAlert === 'function') {
        await showCustomAlert(`⚠️ Cannot Open File "${file.name}"\n\n${err.message}\n\nReturning to file browser...`, "JSON Validation Error", "error");
      } else {
        alert("Error opening project file: " + err.message);
      }
      if (typeof openSharePointFileBrowserModal === 'function') {
        openSharePointFileBrowserModal();
      }
    }
  };
  reader.readAsText(file);
}

async function saveJSON() {
  if (typeof getActiveFmeaData === 'function') {
    getActiveFmeaData();
  }
  if (fmeaData && fmeaData.structure && typeof deduplicateStructureTree === 'function') {
    deduplicateStructureTree(fmeaData.structure);
  }
  fmeaData.pfmeas = fmeaData.pfmeas || [];
  fmeaData.pfmeaInstances = fmeaData.pfmeas;

  const exportData = {
    ...fmeaData,
    requirementGroups: requirementGroups,
    systemUsers: systemUsers,
    loginAuditLogs: loginAuditLogs
  };

  const encryptedPayload = encryptFmeaFilePayload(exportData);

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const defaultName = `FMEA_Export_${fmeaData.projectInfo ? fmeaData.projectInfo.name.replace(/\s+/g, '_') : 'Project'}.json`;
      const result = await window.electronAPI.saveDialog(defaultName);
      if (result && !result.canceled && result.filePath) {
        const saveRes = await window.electronAPI.writeFile(result.filePath, encryptedPayload);
        if (saveRes.success) {
          showToast(`✨ Saved successfully to: ${result.filePath}`);
        } else {
          alert(`Error saving file: ${saveRes.error}`);
        }
      }
    } catch (err) {
      alert("Error saving file: " + err.message);
    }
    return;
  }

  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(encryptedPayload);
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute("href", dataStr);
  downloadAnchor.setAttribute("download", `FMEA_Export_${fmeaData.projectInfo ? fmeaData.projectInfo.name.replace(/\s+/g, '_') : 'Project'}.json`);
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();
}

function updateWorkspaceVisibility() {
  const wrapper = document.getElementById('appWorkspaceWrapper');
  const tableContainer = document.getElementById('fmeaTableContainer');
  const placeholder = document.getElementById('noProjectPlaceholder');
  const closeFileBtn = document.getElementById('btnCloseActiveFile');
  const toolbar = document.querySelector('.workspace-toolbar');
  const treeSidebar = document.getElementById('treeSidebarAside');
  const treeReopenTab = document.getElementById('treeSidebarReopenTab');
  const procSidebar = document.getElementById('sidebarProcessContainer');
  const procReopenTab = document.getElementById('procSidebarReopenTab');

  const hasFile = hasValidActiveProject();
  // Workspace is only usable once the file has at least one revision
  const hasRevision = hasFile && Array.isArray(fmeaData.revisions) && fmeaData.revisions.length > 0;
  const hasActive = hasFile && hasRevision;

  if (wrapper) {
    wrapper.style.display = 'flex';
  }

  // Switch placeholder content between "no file" and "no revision" states
  const phIcon = document.getElementById('noProjectPlaceholderIcon');
  const phTitle = document.getElementById('noProjectPlaceholderTitle');
  const phText = document.getElementById('noProjectPlaceholderText');
  const phBtnRepo = document.getElementById('noProjectBtnOpenRepo');
  const phBtnRev = document.getElementById('noProjectBtnCreateRev');
  if (hasFile && !hasRevision) {
    if (phIcon) phIcon.textContent = '📝';
    if (phTitle) phTitle.textContent = 'No Revision Created';
    if (phText) phText.textContent = `File "${activeSharePointFileName}" is open, but it has no revision yet. Create the initial revision to start working on the FMEA.`;
    if (phBtnRepo) phBtnRepo.style.display = 'none';
    if (phBtnRev) phBtnRev.style.display = '';
  } else {
    if (phIcon) phIcon.textContent = '📑';
    if (phTitle) phTitle.textContent = 'No Active FMEA Project Loaded';
    if (phText) phText.textContent = 'Please open your SharePoint repository to select an existing FMEA project JSON file or create a new project in the repository.';
    if (phBtnRepo) phBtnRepo.style.display = '';
    if (phBtnRev) phBtnRev.style.display = 'none';
  }

  // Close File menu item: only enabled when a file is open
  const menuClose = document.getElementById('menuItemCloseFile');
  if (menuClose) {
    menuClose.classList.toggle('disabled', !hasFile);
    menuClose.style.pointerEvents = hasFile ? '' : 'none';
    menuClose.style.opacity = hasFile ? '' : '0.4';
    menuClose.setAttribute('aria-disabled', hasFile ? 'false' : 'true');
    menuClose.title = hasFile ? '' : 'No file is open';
  }

  // Secondary Variant & Revision context bar: hidden when no file is open (or file has no revision)
  const navContextBar = document.getElementById('navContextBar') || document.querySelector('.nav-context-bar');
  if (navContextBar) {
    navContextBar.style.display = (hasFile && hasRevision) ? 'flex' : 'none';
  }

  if (treeSidebar) {
    if (!hasActive) {
      treeSidebar.style.display = 'none';
    } else {
      treeSidebar.style.display = window._treeSidebarCollapsed ? 'none' : 'flex';
    }
  }

  if (treeReopenTab) {
    if (!hasActive) {
      treeReopenTab.style.display = 'none';
      treeReopenTab.classList.remove('visible');
    } else {
      treeReopenTab.style.display = '';
      treeReopenTab.classList.toggle('visible', !!window._treeSidebarCollapsed);
    }
  }

  if (procSidebar) {
    const isPFMEA = fmeaData && fmeaData.activeFmeaType === 'PFMEA';
    if (!hasActive || !isPFMEA) {
      procSidebar.style.display = 'none';
    } else {
      procSidebar.style.display = window._procSidebarCollapsed ? 'none' : 'flex';
    }
  }

  if (procReopenTab) {
    const isPFMEA = fmeaData && fmeaData.activeFmeaType === 'PFMEA';
    if (!hasActive || !isPFMEA) {
      procReopenTab.style.display = 'none';
      procReopenTab.classList.remove('visible');
    } else {
      procReopenTab.style.display = '';
      procReopenTab.classList.toggle('visible', !!window._procSidebarCollapsed);
    }
  }

  if (tableContainer) {
    tableContainer.style.display = hasActive ? '' : 'none';
  }

  if (placeholder) {
    placeholder.style.display = hasActive ? 'none' : 'flex';
  }

  if (toolbar) {
    toolbar.style.display = hasActive ? 'flex' : 'none';
  }

  if (closeFileBtn) {
    closeFileBtn.style.display = hasFile ? 'inline-flex' : 'none';
  }

  if (typeof updateNavigationTabsState === 'function') {
    updateNavigationTabsState();
  }
}

function processPostLoadRevisionCheck() {
  const revs = fmeaData.revisions || [];

  // Default starting view to DFMEA Master
  fmeaData.activeFmeaType = 'DFMEA';
  fmeaData.activePfmeaId = null;

  if (revs.length === 0) {
    // No revisions available -> Prompt user to create first revision directly
    fmeaData.currentRevision = null;
    updateWorkspaceVisibility();
    updateHeaderRevisionBadge();
    if (typeof renderFmeaContextDropdown === 'function') renderFmeaContextDropdown();
    renderFMEATable();
    showToast("📂 File opened. Please create the initial revision to begin editing.", "info");
    openRevisionModal();
    return;
  }

  // Find in-progress DFMEA revision first, or fallback to latest DFMEA revision
  const dfmeaRevs = revs.filter(r => !r.fmeaType || r.fmeaType === 'DFMEA');
  const inProgRev = dfmeaRevs.find(r => r && r.status !== 'Frozen') || revs.find(r => r && r.status !== 'Frozen');
  const latestRev = inProgRev || (dfmeaRevs.length > 0 ? dfmeaRevs[dfmeaRevs.length - 1] : revs[revs.length - 1]);

  if (latestRev) {
    if (latestRev.status === 'Draft') {
      latestRev.status = 'In Progress';
    }
    fmeaData.currentRevision = latestRev;
  }

  updateWorkspaceVisibility();
  updateHeaderRevisionBadge();
  if (typeof renderFmeaContextDropdown === 'function') renderFmeaContextDropdown();
  renderFMEATable();

  if (latestRev) {
    showToast(`📂 Opened file. Defaulted to latest DFMEA Revision ${latestRev.revNumber || ''} (${latestRev.status || 'Active'})`);
  }
}

function renderVariantCheckboxList(containerId, prefix, selectedVariants = null) {
  const container = document.getElementById(containerId);
  if (!container) return;

  ensureDefaultVariant(fmeaData);
  const activeVariants = (fmeaData.variants || []).filter(v => v.active !== false);
  const allActiveIds = activeVariants.map(v => v.id);

  let currentSelected = [];
  if (selectedVariants === null || selectedVariants === undefined || selectedVariants === 'ALL' || (Array.isArray(selectedVariants) && selectedVariants.includes('ALL'))) {
    if (typeof selectedVariantFilter !== 'undefined' && selectedVariantFilter && selectedVariantFilter !== 'ALL') {
      currentSelected = [selectedVariantFilter];
    } else {
      currentSelected = [...allActiveIds];
    }
  } else {
    currentSelected = Array.isArray(selectedVariants) ? selectedVariants : [selectedVariants];
  }

  const isAllChecked = allActiveIds.length > 0 && allActiveIds.every(id => currentSelected.includes(id));

  let html = `
    <label style="display:flex; align-items:center; gap:6px; font-weight:bold; margin-bottom:4px; cursor:pointer;">
      <input type="checkbox" id="${prefix}_var_ALL" value="ALL" ${isAllChecked ? 'checked' : ''} onchange="handleAllVariantCheckboxToggle('${prefix}', this.checked)">
      🌟 All Variants
    </label>
  `;

  (fmeaData.variants || []).forEach(v => {
    const isChecked = currentSelected.includes(v.id);
    html += `
      <label style="display:flex; align-items:center; gap:6px; font-size:12px; margin-bottom:3px; cursor:pointer;">
        <input type="checkbox" class="${prefix}_var_item" value="${v.id}" ${isChecked ? 'checked' : ''} ${!v.active ? 'disabled' : ''} onchange="handleIndividualVariantCheckboxToggle('${prefix}')">
        ${escapeHtml(v.name)} (${v.active ? 'Active' : 'Inactive'})
      </label>
    `;
  });

  container.innerHTML = html;
}

function handleAllVariantCheckboxToggle(prefix, isChecked) {
  const items = document.querySelectorAll(`.${prefix}_var_item:not(:disabled)`);
  items.forEach(chk => {
    chk.checked = isChecked;
  });
}

function handleIndividualVariantCheckboxToggle(prefix) {
  const allChk = document.getElementById(`${prefix}_var_ALL`);
  const items = Array.from(document.querySelectorAll(`.${prefix}_var_item:not(:disabled)`));
  const allItemsChecked = items.length > 0 && items.every(c => c.checked);
  if (allChk) {
    allChk.checked = allItemsChecked;
  }
}

function getSelectedVariantsFromCheckboxes(prefix) {
  const items = Array.from(document.querySelectorAll(`.${prefix}_var_item:checked`));
  const selected = items.map(c => c.value);
  if (selected.length > 0) {
    return selected;
  }
  if (typeof selectedVariantFilter !== 'undefined' && selectedVariantFilter && selectedVariantFilter !== 'ALL') {
    return [selectedVariantFilter];
  }
  return (fmeaData.variants || []).filter(v => v.active !== false).map(v => v.id);
}

function getSelectedCheckboxValues(itemClass, allId) {
  const items = document.querySelectorAll(`.${itemClass}:checked`);
  const selected = Array.from(items).map(c => c.value);
  if (selected.length > 0) return selected;
  if (typeof selectedVariantFilter !== 'undefined' && selectedVariantFilter && selectedVariantFilter !== 'ALL') {
    return [selectedVariantFilter];
  }
  return (fmeaData.variants || []).filter(v => v.active !== false).map(v => v.id);
}

function renderVariantDropdowns() {
  const select = document.getElementById('variantSelect');
  const ctrlVar = document.getElementById('ctrlVariant');
  const actVar = document.getElementById('actVariant');

  let opts = `<option value="ALL">All Variants</option>`;
  (fmeaData.variants || []).forEach(v => {
    opts += `<option value="${v.id}" ${!v.active ? 'disabled' : ''}>${v.name} (${v.active ? 'Active' : 'Inactive'})</option>`;
  });

  if (select) {
    select.innerHTML = opts;
    select.value = selectedVariantFilter;
  }
  if (ctrlVar) ctrlVar.innerHTML = opts;
  if (actVar) actVar.innerHTML = opts;

  renderVariantCheckboxList('structVariantCheckboxList', 'struct');
  renderVariantCheckboxList('reqVariantCheckboxList', 'req');
  renderVariantCheckboxList('causeVariantCheckboxList', 'cause');
  renderVariantCheckboxList('funcVariantCheckboxList', 'func');
  renderVariantCheckboxList('fmVariantCheckboxList', 'fm');
}

function getVariantNamesDisplay(variantVal) {
  if (!variantVal) return 'ALL';
  const valArray = Array.isArray(variantVal) ? variantVal : [variantVal];
  if (valArray.length === 0) return '-';

  if (valArray.includes('ALL')) {
    const activeVars = (fmeaData.variants || []).filter(v => v.active !== false);
    if (activeVars.length === 0) return 'ALL';
    return activeVars.map(v => v.name).join(', ');
  }

  const names = valArray.map(id => {
    const v = (fmeaData.variants || []).find(item => item.id === id);
    return v ? v.name : id;
  });
  return names.join(', ');
}

function handleVariantChange() {
  selectedVariantFilter = document.getElementById('variantSelect').value;
  renderFMEATable();
}

function renderBaseVariantOptions(editingId = '') {
  const select = document.getElementById('varBaseVariant');
  if (!select) return;
  let opts = '<option value="">-- None (Standalone / Empty Variant) --</option>';
  (fmeaData.variants || []).forEach(v => {
    if (v.id !== editingId && v.active !== false) {
      opts += `<option value="${v.id}">${escapeHtml(v.name)}</option>`;
    }
  });
  select.innerHTML = opts;
}

function copyVariantDataBinding(item, baseVariantId, newVariantId) {
  if (!item || !baseVariantId || !newVariantId) return;

  if (item.variants) {
    if (Array.isArray(item.variants)) {
      if (item.variants.includes(baseVariantId) && !item.variants.includes(newVariantId)) {
        item.variants.push(newVariantId);
      }
    } else if (typeof item.variants === 'string') {
      if (item.variants === baseVariantId) {
        item.variants = [baseVariantId, newVariantId];
      }
    }
  }

  if (item.variantId) {
    if (Array.isArray(item.variantId)) {
      if (item.variantId.includes(baseVariantId) && !item.variantId.includes(newVariantId)) {
        item.variantId.push(newVariantId);
      }
    } else if (typeof item.variantId === 'string') {
      if (item.variantId === baseVariantId) {
        item.variantId = [baseVariantId, newVariantId];
      }
    }
  }
}

function migrateLegacyAllVariants(variantIds) {
  if (!fmeaData) return;
  const fallbackIds = (variantIds && variantIds.length > 0)
    ? variantIds
    : (fmeaData.variants || []).map(v => v.id);
  if (fallbackIds.length === 0) return;

  function fixBinding(item) {
    if (!item) return;
    if (item.variants !== undefined) {
      if (item.variants === 'ALL' || (Array.isArray(item.variants) && (item.variants.includes('ALL') || item.variants.length === 0))) {
        item.variants = [...fallbackIds];
      }
    }
    if (item.variantId !== undefined) {
      if (item.variantId === 'ALL' || (Array.isArray(item.variantId) && (item.variantId.includes('ALL') || item.variantId.length === 0))) {
        item.variantId = [...fallbackIds];
      }
    }
  }

  // 1. DFMEA Structure Tree
  function traverseTree(node) {
    if (!node) return;
    fixBinding(node);
    if (node.children) node.children.forEach(traverseTree);
  }
  if (fmeaData.structure) traverseTree(fmeaData.structure);

  // 2. DFMEA Reqs, Function Lines, Functions
  (fmeaData.requirements || []).forEach(fixBinding);
  (fmeaData.functionLines || []).forEach(fixBinding);
  (fmeaData.functions || []).forEach(fixBinding);

  // 3. Libraries
  if (fmeaData.libraries) {
    (fmeaData.libraries.causes || []).forEach(fixBinding);
    (fmeaData.libraries.controls || []).forEach(fixBinding);
    (fmeaData.libraries.actions || []).forEach(fixBinding);
    (fmeaData.libraries.masterCharacteristics || []).forEach(fixBinding);
    (fmeaData.libraries.characteristics || []).forEach(fixBinding);
    (fmeaData.libraries.failureModes || []).forEach(fixBinding);
  }

  // 4. PFMEA Instances
  const pfmeas = fmeaData.pfmeaInstances ? fmeaData.pfmeaInstances : (fmeaData.pfmea ? [fmeaData.pfmea] : (fmeaData.pfmeas || []));
  pfmeas.forEach(pfmea => {
    if (pfmea.structure) traverseTree(pfmea.structure);
    (pfmea.requirements || []).forEach(fixBinding);
    (pfmea.processSteps || []).forEach(fixBinding);
    (pfmea.functions || []).forEach(fixBinding);
    (pfmea.functionLines || []).forEach(fixBinding);
  });
}

function inheritBaseVariantDataLinks(baseVariantId, newVariantId) {
  if (!baseVariantId || !newVariantId) return;

  // 1. Traverse DFMEA Structure Tree
  function traverseTree(node) {
    if (!node) return;
    copyVariantDataBinding(node, baseVariantId, newVariantId);
    if (node.children) node.children.forEach(traverseTree);
  }
  if (fmeaData.structure) traverseTree(fmeaData.structure);

  // 2. Traverse DFMEA Reqs, Function Lines, Functions
  (fmeaData.requirements || []).forEach(r => copyVariantDataBinding(r, baseVariantId, newVariantId));
  (fmeaData.functionLines || []).forEach(fl => copyVariantDataBinding(fl, baseVariantId, newVariantId));
  (fmeaData.functions || []).forEach(f => copyVariantDataBinding(f, baseVariantId, newVariantId));

  // 3. Traverse Libraries (Causes, Controls, Actions, Master Characteristics, Failure Modes)
  if (fmeaData.libraries) {
    (fmeaData.libraries.causes || []).forEach(c => copyVariantDataBinding(c, baseVariantId, newVariantId));
    (fmeaData.libraries.controls || []).forEach(ctrl => copyVariantDataBinding(ctrl, baseVariantId, newVariantId));
    (fmeaData.libraries.actions || []).forEach(act => copyVariantDataBinding(act, baseVariantId, newVariantId));
    (fmeaData.libraries.masterCharacteristics || []).forEach(mc => copyVariantDataBinding(mc, baseVariantId, newVariantId));
    (fmeaData.libraries.characteristics || []).forEach(ch => copyVariantDataBinding(ch, baseVariantId, newVariantId));
    (fmeaData.libraries.failureModes || []).forEach(fm => copyVariantDataBinding(fm, baseVariantId, newVariantId));
  }

  // 4. Traverse PFMEA Instances
  const pfmeas = fmeaData.pfmeaInstances ? fmeaData.pfmeaInstances : (fmeaData.pfmea ? [fmeaData.pfmea] : (fmeaData.pfmeas || []));
  pfmeas.forEach(pfmea => {
    if (pfmea.structure) traverseTree(pfmea.structure);
    (pfmea.requirements || []).forEach(r => copyVariantDataBinding(r, baseVariantId, newVariantId));
    (pfmea.processSteps || []).forEach(ps => copyVariantDataBinding(ps, baseVariantId, newVariantId));
    (pfmea.functions || []).forEach(f => copyVariantDataBinding(f, baseVariantId, newVariantId));
    (pfmea.functionLines || []).forEach(fl => copyVariantDataBinding(fl, baseVariantId, newVariantId));
  });
}

function ensureDefaultVariant(data) {
  if (!data) return;
  if (!Array.isArray(data.variants)) {
    data.variants = [];
  }
  if (data.variants.length === 0) {
    data.variants.push({
      id: "var-default",
      name: "Variant A",
      customer: "Global Motors",
      model: "2026 SUV Platform",
      vehicle: "EV / ICE Dual",
      comments: "Default Variant A",
      active: true
    });
  }

  // Ensure functions have variants
  const allFuncs = [
    ...(data.functions || []),
    ...(data.pfmea && data.pfmea.functions ? data.pfmea.functions : [])
  ];
  allFuncs.forEach(f => {
    if (!f.variants && !f.variantId) {
      f.variants = ['ALL'];
    }
  });

  // Ensure functionLines & failureModes have variants
  const allLines = [
    ...(data.functionLines || []),
    ...(data.pfmea && data.pfmea.functionLines ? data.pfmea.functionLines : [])
  ];
  allLines.forEach(fl => {
    (fl.failureModes || []).forEach(fm => {
      if (!fm.variants && !fm.variantId) {
        fm.variants = ['ALL'];
      }
    });
  });
}

function openVariantModal() {
  ensureDefaultVariant(fmeaData);
  renderBaseVariantOptions('');
  renderVariantListTable();
  const countBadge = document.getElementById('variantCountBadge');
  if (countBadge) {
    countBadge.textContent = (fmeaData.variants || []).length;
  }
  openModal('variantModal');
}

function openVariantCreationForm() {
  resetVariantForm();
  const modalTitle = document.getElementById('variantEditModalTitle');
  if (modalTitle) {
    modalTitle.innerHTML = '➕ Add New Variant &amp; Header Configurations';
  }
  openModal('variantEditModal');
  setTimeout(() => {
    const nameInput = document.getElementById('varName');
    if (nameInput) nameInput.focus();
  }, 80);
}

function resetVariantForm() {
  const form = document.getElementById('variantForm');
  if (form) form.reset();
  const editIdInput = document.getElementById('variantEditId');
  if (editIdInput) editIdInput.value = '';
  renderBaseVariantOptions('');
}

function renderVariantListTable() {
  const tbody = document.getElementById('variantListTable');
  if (!tbody) return;

  if (!fmeaData.variants || fmeaData.variants.length === 0) {
    tbody.innerHTML = '<tr><td colspan="9" style="text-align:center; color:var(--text-muted); padding:16px;">No variants defined. Click "Add New Variant" above.</td></tr>';
    return;
  }

  tbody.innerHTML = fmeaData.variants.map((v, idx) => {
    const baseVar = v.baseVariantId ? fmeaData.variants.find(item => item.id === v.baseVariantId) : null;
    const baseVarText = baseVar ? escapeHtml(baseVar.name) : '<span style="color:var(--text-muted); font-style:italic;">None (Standalone)</span>';

    const getPhaseBadges = (phases) => {
      const raw = phases || ['Prototype', 'Pre-Launch', 'Production'];
      return raw.map(p => {
        if (p.toLowerCase().includes('proto')) return '<span style="background:#fef3c7; color:#92400e; border:1px solid #f59e0b; padding:1px 3px; border-radius:2px; font-weight:bold; font-size:7.5px; display:inline-block; margin:1px;">🧪 Proto</span>';
        if (p.toLowerCase().includes('pre') || p.toLowerCase().includes('safe')) return '<span style="background:#e0f2fe; color:#0369a1; border:1px solid #0284c7; padding:1px 3px; border-radius:2px; font-weight:bold; font-size:7.5px; display:inline-block; margin:1px;">🚀 Pre-L</span>';
        return '<span style="background:#dcfce7; color:#166534; border:1px solid #16a34a; padding:1px 3px; border-radius:2px; font-weight:bold; font-size:7.5px; display:inline-block; margin:1px;">🏭 Prod</span>';
      }).join(' ');
    };

    const dfPhases = v.dfmeaHeader?.phases || v.phases || ['Prototype', 'Pre-Launch', 'Production'];
    const pfPhases = v.pfmeaHeader?.phases || v.phases || ['Prototype', 'Pre-Launch', 'Production'];
    const cpPhases = v.cpHeader?.phases || v.phases || ['Prototype', 'Pre-Launch', 'Production'];

    let phaseDisplayHtml = '';
    const areAllSame = JSON.stringify(dfPhases) === JSON.stringify(pfPhases) && JSON.stringify(pfPhases) === JSON.stringify(cpPhases);
    if (areAllSame) {
      phaseDisplayHtml = getPhaseBadges(dfPhases);
    } else {
      phaseDisplayHtml = `
        <div style="font-size:8.5px; text-align:left; display:flex; flex-direction:column; gap:2px;">
          <div><strong style="color:#0284c7;">DF:</strong> ${getPhaseBadges(dfPhases)}</div>
          <div><strong style="color:#059669;">PF:</strong> ${getPhaseBadges(pfPhases)}</div>
          <div><strong style="color:#7c3aed;">CP:</strong> ${getPhaseBadges(cpPhases)}</div>
        </div>
      `;
    }

    const has5T = v.fiveT && (v.fiveT.task || v.fiveT.team || (v.fiveT.teamMembers && v.fiveT.teamMembers.length > 0));
    const modelApp = [v.model, v.vehicle].filter(Boolean).join(' / ') || '-';

    return `
      <tr>
        <td style="text-align:center; font-weight:bold; color:#0284c7;">${idx + 1}</td>
        <td>
          <div style="font-weight:700; color:var(--text-primary);">${escapeHtml(v.name)}</div>
          ${v.comments ? `<div style="font-size:10px; color:var(--text-muted);">${escapeHtml(v.comments)}</div>` : ''}
        </td>
        <td style="font-family:monospace; font-size:11px;">${escapeHtml(v.partNumber || '-')}</td>
        <td>${escapeHtml(v.customer || '-')}</td>
        <td style="font-size:11px;">${escapeHtml(modelApp)}</td>
        <td style="text-align:center;">${phaseDisplayHtml}</td>
        <td style="text-align:center;">
          <button class="btn btn-sm ${has5T ? 'btn-success' : 'btn-outline-primary'}" style="display:inline-flex; align-items:center; gap:4px; font-size:11px; font-weight:600; padding:3px 10px; white-space:nowrap;" onclick="openFiveTModal('${v.id}')">
            📋 5T Plan ${has5T ? '✓' : ''}
          </button>
        </td>
        <td style="text-align:center;">
          <span class="badge ${v.active !== false ? 'badge-success' : 'badge-secondary'}">${v.active !== false ? 'Active' : 'Archived'}</span>
        </td>
        <td style="text-align:center;">
          <div style="display:inline-flex; gap:4px; align-items:center;">
            <button class="btn btn-sm btn-outline-primary" style="display:inline-flex; align-items:center; justify-content:center; width:26px; height:26px; padding:0; font-size:12px;" onclick="editVariant('${v.id}')" title="Edit Variant &amp; Header">✏️</button>
            <button class="btn btn-sm ${v.active !== false ? 'btn-outline-warning' : 'btn-outline-success'}" style="display:inline-flex; align-items:center; justify-content:center; width:26px; height:26px; padding:0; font-size:12px;" onclick="toggleVariantActive('${v.id}')" title="${v.active !== false ? 'Archive' : 'Activate'}">${v.active !== false ? '📦' : '♻️'}</button>
            ${fmeaData.variants.length > 1 ? `<button class="btn btn-sm btn-outline-danger" style="display:inline-flex; align-items:center; justify-content:center; width:26px; height:26px; padding:0; font-size:12px;" onclick="deleteVariant('${v.id}')" title="Delete Variant">🗑️</button>` : ''}
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

function switchVariantHeaderTab(tabName) {
  const tabs = ['dfmea', 'pfmea', 'cp'];
  const targetTab = tabs.includes(tabName) ? tabName : 'dfmea';

  tabs.forEach(t => {
    const btn = document.getElementById(`btnVarTab_${t}`);
    const panel = document.getElementById(`varHeaderTabContent_${t}`);
    if (t === targetTab) {
      if (panel) panel.style.display = 'block';
      if (btn) btn.classList.add('active');
    } else {
      if (panel) panel.style.display = 'none';
      if (btn) btn.classList.remove('active');
    }
  });
}

function resetVariantForm() {
  const editId = document.getElementById('variantEditId');
  if (editId) editId.value = '';
  const form = document.getElementById('variantForm');
  if (form) form.reset();

  ['varDfmea_phaseProto', 'varDfmea_phasePrelaunch', 'varDfmea_phaseProd',
    'varPfmea_phaseProto', 'varPfmea_phasePrelaunch', 'varPfmea_phaseProd',
    'varCp_phaseProto', 'varCp_phasePrelaunch', 'varCp_phaseProd'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.checked = true;
    });

  if (document.getElementById('varDfmea_engLoc')) document.getElementById('varDfmea_engLoc').value = '';
  if (document.getElementById('varPfmea_plantLoc')) document.getElementById('varPfmea_plantLoc').value = '';
  if (document.getElementById('varCp_plantLoc')) document.getElementById('varCp_plantLoc').value = '';

  const defaultTab = typeof isPFMEAMode === 'function' && isPFMEAMode() ? 'pfmea' : 'dfmea';
  switchVariantHeaderTab(defaultTab);

  renderBaseVariantOptions();
}

function saveVariant(e) {
  e.preventDefault();
  const editId = document.getElementById('variantEditId').value;
  const name = document.getElementById('varName').value.trim();
  const partNumber = document.getElementById('varPartNumber') ? document.getElementById('varPartNumber').value.trim() : '';
  const baseVariantSelect = document.getElementById('varBaseVariant');
  const baseVariantId = baseVariantSelect ? baseVariantSelect.value : '';
  const customer = document.getElementById('varCustomer').value.trim();
  const model = document.getElementById('varModel').value.trim();
  const vehicle = document.getElementById('varVehicle').value.trim();
  const comments = document.getElementById('varComments') ? document.getElementById('varComments').value.trim() : '';

  // DFMEA Header Info
  const dfmeaPhases = [];
  if (document.getElementById('varDfmea_phaseProto')?.checked) dfmeaPhases.push('Prototype');
  if (document.getElementById('varDfmea_phasePrelaunch')?.checked) dfmeaPhases.push('Pre-Launch');
  if (document.getElementById('varDfmea_phaseProd')?.checked) dfmeaPhases.push('Production');
  const finalDfmeaPhases = dfmeaPhases.length > 0 ? dfmeaPhases : ['Prototype', 'Pre-Launch', 'Production'];
  const dfmeaDocNo = document.getElementById('varDfmea_docNo') ? document.getElementById('varDfmea_docNo').value.trim() : '';
  const dfmeaConfidentiality = document.getElementById('varDfmea_confidentiality') ? document.getElementById('varDfmea_confidentiality').value.trim() : '';
  const dfmeaSubject = document.getElementById('varDfmea_subject') ? document.getElementById('varDfmea_subject').value.trim() : '';
  const dfmeaEngLoc = document.getElementById('varDfmea_engLoc') ? document.getElementById('varDfmea_engLoc').value.trim() : '';
  const dfmeaDesignResp = document.getElementById('varDfmea_designResp') ? document.getElementById('varDfmea_designResp').value.trim() : '';
  const dfmeaKeyLead = document.getElementById('varDfmea_keyLead') ? document.getElementById('varDfmea_keyLead').value.trim() : '';

  // PFMEA Header Info
  const pfmeaPhases = [];
  if (document.getElementById('varPfmea_phaseProto')?.checked) pfmeaPhases.push('Prototype');
  if (document.getElementById('varPfmea_phasePrelaunch')?.checked) pfmeaPhases.push('Pre-Launch');
  if (document.getElementById('varPfmea_phaseProd')?.checked) pfmeaPhases.push('Production');
  const finalPfmeaPhases = pfmeaPhases.length > 0 ? pfmeaPhases : ['Prototype', 'Pre-Launch', 'Production'];
  const pfmeaDocNo = document.getElementById('varPfmea_docNo') ? document.getElementById('varPfmea_docNo').value.trim() : '';
  const pfmeaConfidentiality = document.getElementById('varPfmea_confidentiality') ? document.getElementById('varPfmea_confidentiality').value.trim() : '';
  const pfmeaSubject = document.getElementById('varPfmea_subject') ? document.getElementById('varPfmea_subject').value.trim() : '';
  const pfmeaPlantLoc = document.getElementById('varPfmea_plantLoc') ? document.getElementById('varPfmea_plantLoc').value.trim() : '';
  const pfmeaProcessResp = document.getElementById('varPfmea_processResp') ? document.getElementById('varPfmea_processResp').value.trim() : '';
  const pfmeaKeyLead = document.getElementById('varPfmea_keyLead') ? document.getElementById('varPfmea_keyLead').value.trim() : '';

  // Control Plan Header Info
  const cpPhases = [];
  if (document.getElementById('varCp_phaseProto')?.checked) cpPhases.push('Prototype');
  if (document.getElementById('varCp_phasePrelaunch')?.checked) cpPhases.push('Pre-Launch');
  if (document.getElementById('varCp_phaseProd')?.checked) cpPhases.push('Production');
  const finalCpPhases = cpPhases.length > 0 ? cpPhases : ['Prototype', 'Pre-Launch', 'Production'];
  const cpDocNo = document.getElementById('varCp_docNo') ? document.getElementById('varCp_docNo').value.trim() : '';
  const cpConfidentiality = document.getElementById('varCp_confidentiality') ? document.getElementById('varCp_confidentiality').value.trim() : '';
  const cpSubject = document.getElementById('varCp_subject') ? document.getElementById('varCp_subject').value.trim() : '';
  const cpPlantLoc = document.getElementById('varCp_plantLoc') ? document.getElementById('varCp_plantLoc').value.trim() : '';
  const cpResp = document.getElementById('varCp_resp') ? document.getElementById('varCp_resp').value.trim() : '';
  const cpKeyLead = document.getElementById('varCp_keyLead') ? document.getElementById('varCp_keyLead').value.trim() : '';

  const dfmeaHeader = {
    phases: finalDfmeaPhases,
    docNo: dfmeaDocNo,
    confidentiality: dfmeaConfidentiality,
    subject: dfmeaSubject,
    engLoc: dfmeaEngLoc,
    designResp: dfmeaDesignResp,
    keyLead: dfmeaKeyLead
  };

  const pfmeaHeader = {
    phases: finalPfmeaPhases,
    docNo: pfmeaDocNo,
    confidentiality: pfmeaConfidentiality,
    subject: pfmeaSubject,
    plantLoc: pfmeaPlantLoc,
    processResp: pfmeaProcessResp,
    keyLead: pfmeaKeyLead
  };

  const cpHeader = {
    phases: finalCpPhases,
    docNo: cpDocNo,
    confidentiality: cpConfidentiality,
    subject: cpSubject,
    plantLoc: cpPlantLoc,
    resp: cpResp,
    keyLead: cpKeyLead
  };

  if (editId) {
    const v = fmeaData.variants.find(item => item.id === editId);
    if (v) {
      v.name = name;
      v.partNumber = partNumber;
      v.baseVariantId = baseVariantId;
      v.customer = customer;
      v.model = model;
      v.vehicle = vehicle;
      v.dfmeaHeader = dfmeaHeader;
      v.pfmeaHeader = pfmeaHeader;
      v.cpHeader = cpHeader;
      v.phases = finalPfmeaPhases || finalDfmeaPhases;
      v.subject = pfmeaSubject || dfmeaSubject || cpSubject || v.subject;
      v.engLoc = dfmeaEngLoc || pfmeaPlantLoc || cpPlantLoc || v.engLoc;
      v.plantLoc = pfmeaPlantLoc || cpPlantLoc || dfmeaEngLoc || v.plantLoc;
      v.designResp = dfmeaDesignResp || pfmeaProcessResp || v.designResp;
      v.keyLead = dfmeaKeyLead || pfmeaKeyLead || cpKeyLead || v.keyLead;
      v.comments = comments;
      if (v.fiveT) v.fiveT.phases = finalPfmeaPhases;
    }
  } else {
    const existingVariantIds = (fmeaData.variants || []).map(v => v.id);
    migrateLegacyAllVariants(existingVariantIds);

    const newVariantId = 'var-' + Date.now();
    const newVariant = {
      id: newVariantId,
      baseVariantId: baseVariantId || '',
      name,
      partNumber,
      customer,
      model,
      vehicle,
      dfmeaHeader,
      pfmeaHeader,
      cpHeader,
      phases: finalPfmeaPhases || finalDfmeaPhases,
      subject: pfmeaSubject || dfmeaSubject || cpSubject || name,
      engLoc: dfmeaEngLoc || pfmeaPlantLoc || cpPlantLoc || '',
      plantLoc: pfmeaPlantLoc || cpPlantLoc || dfmeaEngLoc || '',
      designResp: dfmeaDesignResp || pfmeaProcessResp || '',
      keyLead: dfmeaKeyLead || pfmeaKeyLead || cpKeyLead || '',
      comments,
      active: true,
      fiveT: {
        team: '',
        teamMembers: [],
        task: dfmeaSubject || pfmeaSubject || name,
        timing: '',
        phases: finalPfmeaPhases,
        techDocs: '',
        topEvents: '',
        dfmeaChecklist: [],
        pfmeaChecklist: []
      }
    };
    fmeaData.variants.push(newVariant);

    if (baseVariantId) {
      inheritBaseVariantDataLinks(baseVariantId, newVariantId);
    }
  }

  resetVariantForm();
  closeModal('variantEditModal');
  renderVariantDropdowns();
  renderVariantListTable();
  const countBadge = document.getElementById('variantCountBadge');
  if (countBadge) {
    countBadge.textContent = (fmeaData.variants || []).length;
  }
  renderFMEATable();
  showToast(`Variant "${name}" &amp; Document-Specific Header Info saved successfully!`, 'success');
}

function editVariant(id) {
  const v = fmeaData.variants.find(item => item.id === id);
  if (!v) return;
  document.getElementById('variantEditId').value = v.id;
  const modalTitle = document.getElementById('variantEditModalTitle');
  if (modalTitle) {
    modalTitle.innerHTML = `✏️ Edit Variant — <span style="color:#ffffff;">${escapeHtml(v.name || 'Variant')}</span>`;
  }
  document.getElementById('varName').value = v.name || '';
  if (document.getElementById('varPartNumber')) document.getElementById('varPartNumber').value = v.partNumber || '';
  renderBaseVariantOptions(v.id);
  const baseSelect = document.getElementById('varBaseVariant');
  if (baseSelect) baseSelect.value = v.baseVariantId || '';
  document.getElementById('varCustomer').value = v.customer || '';
  document.getElementById('varModel').value = v.model || '';
  document.getElementById('varVehicle').value = v.vehicle || '';
  document.getElementById('varComments').value = v.comments || '';

  // DFMEA Header fields
  const dfH = v.dfmeaHeader || {};
  const dfPhases = dfH.phases || v.phases || (v.fiveT && v.fiveT.phases) || ['Prototype', 'Pre-Launch', 'Production'];
  if (document.getElementById('varDfmea_phaseProto')) document.getElementById('varDfmea_phaseProto').checked = dfPhases.includes('Prototype');
  if (document.getElementById('varDfmea_phasePrelaunch')) document.getElementById('varDfmea_phasePrelaunch').checked = dfPhases.includes('Pre-Launch');
  if (document.getElementById('varDfmea_phaseProd')) document.getElementById('varDfmea_phaseProd').checked = dfPhases.includes('Production');
  if (document.getElementById('varDfmea_docNo')) document.getElementById('varDfmea_docNo').value = dfH.docNo || '';
  if (document.getElementById('varDfmea_confidentiality')) document.getElementById('varDfmea_confidentiality').value = dfH.confidentiality || '';
  if (document.getElementById('varDfmea_subject')) document.getElementById('varDfmea_subject').value = dfH.subject || v.subject || (v.fiveT && v.fiveT.task) || '';
  if (document.getElementById('varDfmea_engLoc')) document.getElementById('varDfmea_engLoc').value = dfH.engLoc || v.engLoc || '';
  if (document.getElementById('varDfmea_designResp')) document.getElementById('varDfmea_designResp').value = dfH.designResp || v.designResp || '';
  if (document.getElementById('varDfmea_keyLead')) document.getElementById('varDfmea_keyLead').value = dfH.keyLead || v.keyLead || '';

  // PFMEA Header fields
  const pfH = v.pfmeaHeader || {};
  const pfPhases = pfH.phases || v.phases || (v.fiveT && v.fiveT.phases) || ['Prototype', 'Pre-Launch', 'Production'];
  if (document.getElementById('varPfmea_phaseProto')) document.getElementById('varPfmea_phaseProto').checked = pfPhases.includes('Prototype');
  if (document.getElementById('varPfmea_phasePrelaunch')) document.getElementById('varPfmea_phasePrelaunch').checked = pfPhases.includes('Pre-Launch');
  if (document.getElementById('varPfmea_phaseProd')) document.getElementById('varPfmea_phaseProd').checked = pfPhases.includes('Production');
  if (document.getElementById('varPfmea_docNo')) document.getElementById('varPfmea_docNo').value = pfH.docNo || '';
  if (document.getElementById('varPfmea_confidentiality')) document.getElementById('varPfmea_confidentiality').value = pfH.confidentiality || '';
  if (document.getElementById('varPfmea_subject')) document.getElementById('varPfmea_subject').value = pfH.subject || v.subject || (v.fiveT && v.fiveT.task) || '';
  if (document.getElementById('varPfmea_plantLoc')) document.getElementById('varPfmea_plantLoc').value = pfH.plantLoc || v.plantLoc || v.engLoc || '';
  if (document.getElementById('varPfmea_processResp')) document.getElementById('varPfmea_processResp').value = pfH.processResp || v.designResp || '';
  if (document.getElementById('varPfmea_keyLead')) document.getElementById('varPfmea_keyLead').value = pfH.keyLead || v.keyLead || '';

  // Control Plan Header fields
  const cpH = v.cpHeader || {};
  const cpPhases = cpH.phases || v.phases || (v.fiveT && v.fiveT.phases) || ['Prototype', 'Pre-Launch', 'Production'];
  if (document.getElementById('varCp_phaseProto')) document.getElementById('varCp_phaseProto').checked = cpPhases.includes('Prototype');
  if (document.getElementById('varCp_phasePrelaunch')) document.getElementById('varCp_phasePrelaunch').checked = cpPhases.includes('Pre-Launch');
  if (document.getElementById('varCp_phaseProd')) document.getElementById('varCp_phaseProd').checked = cpPhases.includes('Production');
  if (document.getElementById('varCp_docNo')) document.getElementById('varCp_docNo').value = cpH.docNo || '';
  if (document.getElementById('varCp_confidentiality')) document.getElementById('varCp_confidentiality').value = cpH.confidentiality || '';
  if (document.getElementById('varCp_subject')) document.getElementById('varCp_subject').value = cpH.subject || v.subject || '';
  if (document.getElementById('varCp_plantLoc')) document.getElementById('varCp_plantLoc').value = cpH.plantLoc || v.plantLoc || v.engLoc || '';
  if (document.getElementById('varCp_resp')) document.getElementById('varCp_resp').value = cpH.resp || v.designResp || '';
  if (document.getElementById('varCp_keyLead')) document.getElementById('varCp_keyLead').value = cpH.keyLead || v.keyLead || '';

  const defaultTab = typeof isPFMEAMode === 'function' && isPFMEAMode() ? 'pfmea' : 'dfmea';
  switchVariantHeaderTab(defaultTab);

  openModal('variantEditModal');
  setTimeout(() => {
    const nameInput = document.getElementById('varName');
    if (nameInput) nameInput.focus();
  }, 80);
}

function toggleVariantActive(id) {
  const v = (fmeaData.variants || []).find(item => item.id === id);
  if (v) {
    v.active = v.active === false ? true : false;
    renderVariantDropdowns();
    renderVariantListTable();
    renderFMEATable();
    if (typeof showToast === 'function') {
      showToast(`Variant "${v.name}" is now ${v.active ? 'Active' : 'Archived'}.`, 'info');
    }
  }
}

function toggleVariantStatus(id) {
  toggleVariantActive(id);
}

if (typeof window !== 'undefined') {
  window.toggleVariantActive = toggleVariantActive;
  window.toggleVariantStatus = toggleVariantStatus;
  window.openVariantModal = openVariantModal;
  window.openFiveTModal = openFiveTModal;
  window.editVariant = editVariant;
  window.deleteVariant = deleteVariant;
  window.saveVariant = saveVariant;
  window.switchVariantHeaderTab = switchVariantHeaderTab;
  window.resetVariantForm = resetVariantForm;
}

async function deleteVariant(id) {
  if (fmeaData.variants.length <= 1) {
    alert("At least one variant must remain in the project.");
    return;
  }
  const v = fmeaData.variants.find(item => item.id === id);
  if (!v) return;
  const isConfirmed = await showCustomConfirm(`Are you sure you want to delete variant "${v.name}"?`, 'Delete Variant', 'warning');
  if (isConfirmed) {
    fmeaData.variants = fmeaData.variants.filter(item => item.id !== id);
    renderVariantDropdowns();
    renderVariantListTable();
    renderFMEATable();
    if (typeof showToast === 'function') {
      showToast(`Deleted variant "${v.name}"`);
    }
  }
}

