    if (m.isDfmeaLead) {
      roleBadge = '<span style="background:rgba(56,189,248,0.2); color:#38bdf8; border:1px solid #0284c7; padding:1px 6px; border-radius:3px; font-weight:800; font-size:9.5px; margin-right:4px;">🎖️ DFMEA LEAD</span>';
    } else if (m.isPfmeaLead) {
      roleBadge = '<span style="background:rgba(52,211,153,0.2); color:#34d399; border:1px solid #059669; padding:1px 6px; border-radius:3px; font-weight:800; font-size:9.5px; margin-right:4px;">🎖️ PFMEA LEAD</span>';
    } else if (m.isCpLead) {
      roleBadge = '<span style="background:rgba(251,191,36,0.2); color:#fbbf24; border:1px solid #d97706; padding:1px 6px; border-radius:3px; font-weight:800; font-size:9.5px; margin-right:4px;">🎖️ CONTROL PLAN LEAD</span>';
    } else {
      roleBadge = '<span style="background:rgba(148,163,184,0.15); color:#cbd5e1; border:1px solid #475569; padding:1px 5px; border-radius:3px; font-weight:700; font-size:9.5px; margin-right:4px;">👥 CFT</span>';
    }

