window.renderFiveTTeamMembersTable = renderFiveTTeamMembersTable;

function renderFiveTChecklist(type) {
  const v = fmeaData.variants.find(item => item.id === activeFiveTVariantId);
  if (!v || !v.fiveT) return;

  const key = type === 'dfmea' ? 'dfmeaChecklist' : 'pfmeaChecklist';
  const container = document.getElementById(`fiveT_${type}Checklist`);
  if (!container) return;

  const list = v.fiveT[key] || [];

  if (list.length === 0) {
    container.innerHTML = `<span class="text-muted" style="font-size:12px;">No items added yet. Click "+ Add Item" below.</span>`;
    return;
  }

  container.innerHTML = list.map((item, idx) => `
    <div class="five-t-item-row">
      <input type="checkbox" ${item.checked ? 'checked' : ''} onchange="toggleFiveTChecklistItem('${type}', ${idx}, this.checked)" style="cursor:pointer; width:16px; height:16px;">
      <input type="text" value="${escapeHtml(item.text)}" onchange="updateFiveTChecklistText('${type}', ${idx}, this.value)" style="flex:1; border:1px solid #cbd5e1; border-radius:4px; padding:3px 8px; font-size:12px;">
      <button class="btn btn-xs btn-danger" onclick="deleteFiveTChecklistItem('${type}', ${idx})" style="padding:2px 6px;">✕</button>
    </div>
  `).join('');
}

