function saveFiveTData() {
  const v = fmeaData.variants.find(item => item.id === activeFiveTVariantId);
  if (!v) return;

  v.fiveT = v.fiveT || {};
  v.fiveT.team = document.getElementById('fiveT_team')?.value.trim() || '';
  v.fiveT.task = document.getElementById('fiveT_task')?.value.trim() || '';
  v.fiveT.timing = document.getElementById('fiveT_timing')?.value.trim() || '';
  v.fiveT.techDocs = document.getElementById('fiveT_techDocs')?.value.trim() || '';
  v.fiveT.topEvents = document.getElementById('fiveT_topEvents')?.value.trim() || '';

  const selectedPhases = [];
  if (document.getElementById('fiveT_phase_proto')?.checked) selectedPhases.push('Prototype');
  if (document.getElementById('fiveT_phase_prelaunch')?.checked) selectedPhases.push('Pre-Launch');
  if (document.getElementById('fiveT_phase_prod')?.checked) selectedPhases.push('Production');
  if (selectedPhases.length > 0) {
    v.fiveT.phases = selectedPhases;
    v.phases = selectedPhases;
  }

  // Synchronize 5T Task to doc subjects if not defined
  v.dfmeaHeader = v.dfmeaHeader || {};
  v.pfmeaHeader = v.pfmeaHeader || {};
  v.cpHeader = v.cpHeader || {};

  if (!v.dfmeaHeader.subject && v.fiveT.task) v.dfmeaHeader.subject = v.fiveT.task;
  if (!v.pfmeaHeader.subject && v.fiveT.task) v.pfmeaHeader.subject = v.fiveT.task;
  if (!v.cpHeader.subject && v.fiveT.task) v.cpHeader.subject = v.fiveT.task;

  // Synchronize 5T assigned leads
  const members = v.fiveT.teamMembers || [];
  const dfLead = members.find(m => m.isDfmeaLead)?.name;
  const pfLead = members.find(m => m.isPfmeaLead)?.name;
  const cpLead = members.find(m => m.isCpLead)?.name;

  if (dfLead && !v.dfmeaHeader.designResp) v.dfmeaHeader.designResp = 'Design: ' + dfLead;
  if (dfLead && !v.dfmeaHeader.keyLead) v.dfmeaHeader.keyLead = dfLead;

  if (pfLead && !v.pfmeaHeader.processResp) v.pfmeaHeader.processResp = 'Process: ' + pfLead;
  if (pfLead && !v.pfmeaHeader.keyLead) v.pfmeaHeader.keyLead = pfLead;

  if (cpLead && !v.cpHeader.resp) v.cpHeader.resp = 'Quality / Process: ' + cpLead;
  if (cpLead && !v.cpHeader.keyLead) v.cpHeader.keyLead = cpLead;

  closeModal('fiveTModal');
  renderVariantListTable();
  if (typeof markDataChanged === 'function') markDataChanged('5T Planning Data Updated');
  showToast(`5T Planning saved for ${v.name}`);
}
function getStructureNodeById(treeNode, id) {
  if (!id) return null;
  const root = treeNode || (fmeaData ? fmeaData.structure : null);

  function searchTree(node) {
    if (!node) return null;
    if (node.id === id) return node;
    if (node.children) {
      for (let child of node.children) {
        const found = searchTree(child);
        if (found) return found;
      }
    }
    return null;
  }

  const treeMatch = searchTree(root);
  if (treeMatch) return treeMatch;

  if (fmeaData && fmeaData.structure && root !== fmeaData.structure) {
    const masterMatch = searchTree(fmeaData.structure);
    if (masterMatch) return masterMatch;
  }

  if (typeof getActiveFmeaData === 'function') {
    const ctx = getActiveFmeaData();
    if (ctx && ctx.isPFMEA && ctx.pfmea && ctx.pfmea.processSteps) {
      const pstep = ctx.pfmea.processSteps.find(ps => ps.id === id);
      if (pstep) {
        return {
          id: pstep.id,
          partNo: pstep.stepNo,
          name: pstep.name,
          description: pstep.description,
          variantId: pstep.variantId,
          dfmeaStructId: pstep.dfmeaStructId
        };
      }
    }
  }

  return null;
}

function getParentStructureNode(root, targetId, parent = null) {
  if (!root) return null;
  if (root.id === targetId) return parent;
  if (root.children) {
    for (let child of root.children) {
      const found = getParentStructureNode(child, targetId, root);
      if (found) return found;
    }
  }
  return null;
}

function getNodePathName(nodeId) {
  const ctx = getActiveFmeaData();
  const node = getStructureNodeById(ctx.structure, nodeId);
  return node ? `${node.partNo} - ${node.name}` : 'Unknown';
}

function renderTreeSidebar() {
  const container = document.getElementById('sidebarTreeContainer');
  const titleEl = document.getElementById('sidebarTreeHeaderTitle');
  if (titleEl) titleEl.textContent = 'System Hierarchy';

  if (fmeaData && fmeaData.structure && typeof deduplicateStructureTree === 'function') {
    deduplicateStructureTree(fmeaData.structure);
  }

  const hasData = !!(activeSharePointFileName || (fmeaData && fmeaData.structure && fmeaData.structure.children && fmeaData.structure.children.length > 0) || (fmeaData && fmeaData.structureTree && fmeaData.structureTree.length > 0));

  if (container) {
    if (!hasData) {
      container.innerHTML = `<div style="padding:30px 14px; text-align:center; color:var(--text-muted); font-size:12px;">No active system hierarchy loaded.</div>`;
    } else {
      container.innerHTML = buildTreeHTML(fmeaData.structure, false);
    }
  }

  if (typeof renderProcessSidebar === 'function') {
    renderProcessSidebar();
  }
}

function renderProcessSidebar() {
  const container = document.getElementById('sidebarProcessContainer');
  const listEl = document.getElementById('sidebarProcessList');
  if (!container || !listEl) return;

  const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : null;
  const procReopen = document.getElementById('procSidebarReopenTab');
  if (!ctx || !ctx.isPFMEA) {
    // Not in PFMEA mode — collapse fully and hide reopen tab
    container.classList.add('collapsed');
    container.style.display = '';  // let CSS handle it
    if (procReopen) procReopen.classList.remove('visible');
    return;
  }

  // In PFMEA mode — ensure sidebar is visible as flex
  container.style.display = 'flex';
  if (window._procSidebarCollapsed) {
    container.classList.add('collapsed');
    if (procReopen) procReopen.classList.add('visible');
  } else {
    container.classList.remove('collapsed');
    if (procReopen) procReopen.classList.remove('visible');
  }

  const allPsteps = ctx.pfmea?.processSteps || [];
  const structId = selectedStructureId;
  const filteredSteps = structId
    ? allPsteps.filter(ps => String(ps.dfmeaStructId) === String(structId))
    : allPsteps;

  // Auto-select valid step if currently selected step does not belong to this element
  if (selectedProcessStepId && selectedProcessStepId !== 'ALL') {
    const existsInElement = filteredSteps.some(ps => String(ps.id) === String(selectedProcessStepId));
    if (!existsInElement) {
      selectedProcessStepId = filteredSteps[0] ? filteredSteps[0].id : null;
    }
  } else if ((!selectedProcessStepId || selectedProcessStepId === 'ALL') && filteredSteps.length > 0) {
    selectedProcessStepId = filteredSteps[0].id;
  }

  const searchInput = document.getElementById('sidebarProcessSearchInput');
  const searchVal = (searchInput?.value || '').toLowerCase().trim();

  let html = '';

  if (filteredSteps.length === 0) {
    html += `
      <div style="padding:20px 10px; text-align:center; color:#64748b; font-size:11.5px;">
        <div>⚙️ No operations under this element.</div>
        ${ctx.isReadOnly ? '' : `<button class="btn btn-sm btn-outline-success" style="font-size:10.5px; padding:3px 8px; margin-top:8px;" onclick="openAddProcessStepModal('${structId || ''}')">+ Add First Operation</button>`}
      </div>
    `;
  } else {
    filteredSteps.forEach((ps, idx) => {
      const stepNo = ps.stepNo || `Op ${(idx + 1) * 10}`;
      const name = ps.name || 'Process Step';
      if (searchVal && !stepNo.toLowerCase().includes(searchVal) && !name.toLowerCase().includes(searchVal)) {
        return;
      }

      const isActive = (String(selectedProcessStepId) === String(ps.id));
      const fls = (ctx.functionLines || []).filter(fl => String(fl.structId) === String(ps.id));
      const fmCount = fls.reduce((sum, fl) => sum + (fl.failureModes || []).length, 0);
      const isFirst = idx === 0;
      const isLast = idx === filteredSteps.length - 1;

      html += `
        <div class="char-op-nav-item ${isActive ? 'active' : ''}" data-cell-type="struct" data-pstep-id="${ps.id}" data-struct-id="${ps.id}" onclick="selectProcessStep('${ps.id}')" style="padding:7px 10px; margin-bottom:5px; border-radius:6px; cursor:pointer; background:${isActive ? 'rgba(52,211,153,0.18)' : '#070b14'}; border:1px solid ${isActive ? '#059669' : '#1e293b'}; transition:all 0.15s ease;">
          <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:3px;">
            <span style="font-size:11px; font-weight:800; color:#34d399; background:rgba(52,211,153,0.15); border:1px solid rgba(52,211,153,0.3); padding:1px 5px; border-radius:3px;">${escapeHtml(stepNo)}</span>
            <div style="display:flex; align-items:center; gap:3px;">
              <span style="font-size:10px; color:#94a3b8; margin-right:2px;" title="${fls.length} functions, ${fmCount} failure modes">⚡ ${fls.length}F | ${fmCount}FM</span>
              ${ctx.isReadOnly ? '' : `
                <button type="button" class="btn btn-xs" style="background:none; border:none; color:#38bdf8; padding:0 2px; cursor:pointer; font-size:11px;" onclick="event.stopPropagation(); moveProcessStepOrder('${ps.id}', -1)" title="Move Operation Up" ${isFirst ? 'disabled style="opacity:0.3; cursor:not-allowed; padding:0 2px; background:none; border:none; color:#38bdf8;"' : ''}>🔼</button>
                <button type="button" class="btn btn-xs" style="background:none; border:none; color:#38bdf8; padding:0 2px; cursor:pointer; font-size:11px;" onclick="event.stopPropagation(); moveProcessStepOrder('${ps.id}', 1)" title="Move Operation Down" ${isLast ? 'disabled style="opacity:0.3; cursor:not-allowed; padding:0 2px; background:none; border:none; color:#38bdf8;"' : ''}>🔽</button>
                <button type="button" class="btn btn-xs" style="background:none; border:none; color:#94a3b8; padding:0 2px; cursor:pointer;" onclick="event.stopPropagation(); openAddProcessStepModal('${ps.dfmeaStructId || ''}', '${ps.id}')" title="Edit Operation">✏️</button>
                <button type="button" class="btn btn-xs" style="background:none; border:none; color:#ef4444; padding:0 2px; cursor:pointer;" onclick="event.stopPropagation(); deleteProcessStepDirect('${ps.id}')" title="Delete Operation">🗑️</button>
              `}
            </div>
          </div>
          <div style="font-size:11.5px; font-weight:600; color:${isActive ? '#f8fafc' : '#cbd5e1'}; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(name)}</div>
        </div>
      `;
    });
  }

  listEl.innerHTML = html;
}

function selectProcessStep(pstepId) {
  selectedProcessStepId = pstepId;
  renderProcessSidebar();
  if (typeof renderFMEATableAsync === 'function') {
    renderFMEATableAsync();
  } else {
    renderFMEATable();
  }
}

function filterProcessSidebar(val) {
  renderProcessSidebar();
}

window.renderProcessSidebar = renderProcessSidebar;
window.selectProcessStep = selectProcessStep;
window.filterProcessSidebar = filterProcessSidebar;

let selectedReferenceNodeId = null;

function buildTreeHTML(node, isEditableModal = false) {
  if (!node) return '';
  const ctx = getActiveFmeaData();
  const isSelected = isEditableModal ? (selectedReferenceNodeId === node.id) : (selectedStructureId === node.id);
  const isBeingEdited = isEditableModal && (document.getElementById('structNodeId')?.value === node.id);
  const hasChildren = node.children && node.children.length > 0;

  const editBtnHtml = isEditableModal ? `
    <div class="tree-node-actions">
      <button type="button" class="tree-btn tree-btn-edit" onclick="event.stopPropagation(); editStructureNodeFromTree('${node.id}')" title="Edit element">
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>
      </button>
      <button type="button" class="tree-btn tree-btn-delete" onclick="event.stopPropagation(); deleteStructureElement('${node.id}')" title="Delete element and subtree">
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>
      </button>
    </div>
  ` : '';

  window.treeCollapsedNodeIds = window.treeCollapsedNodeIds || new Set();
  const isCollapsed = window.treeCollapsedNodeIds.has(String(node.id));
  const nodeDomId = (isEditableModal ? 'modal-tree-node-' : 'sidebar-tree-node-') + node.id;

  const togglerHtml = hasChildren
    ? `<span class="tree-toggler" onclick="toggleTreeNodeCollapse('${node.id}', ${isEditableModal}, event)" title="${isCollapsed ? 'Click to expand' : 'Click to collapse'}">${isCollapsed ? '▶' : '▼'}</span>`
    : `<span class="tree-toggler is-leaf" style="cursor:default; opacity:0.35;">•</span>`;

  // Display component characteristics tag if defined
  let charTagHtml = '';
  const nodeChars = Array.isArray(node.characteristics) ? node.characteristics : (node.characteristics ? [node.characteristics] : []);
  if (nodeChars.length > 0) {
    const charSummary = nodeChars.slice(0, 2).join(', ') + (nodeChars.length > 2 ? ` +${nodeChars.length - 2}` : '');
    charTagHtml = `<span style="background:rgba(56,189,248,0.15); border:1px solid rgba(56,189,248,0.35); color:#38bdf8; font-size:9.5px; padding:0 4px; border-radius:3px; margin-left:4px;" title="Characteristics: ${escapeHtml(nodeChars.join(', '))}">${escapeHtml(charSummary)}</span>`;
  }

  return `
    <div class="tree-node ${isCollapsed ? 'is-collapsed' : ''}" id="${nodeDomId}" data-cell-type="struct" data-struct-id="${node.id}">
      <div class="tree-item ${isSelected ? 'selected' : ''} ${isBeingEdited ? 'editing-node' : ''}" data-cell-type="struct" data-struct-id="${node.id}" onclick="selectStructureNode('${node.id}', ${isEditableModal})" ondblclick="toggleTreeNodeCollapse('${node.id}', ${isEditableModal}, event)">
        <div class="tree-item-content">
          ${togglerHtml}
          <span class="tree-icon" onclick="toggleTreeNodeCollapse('${node.id}', ${isEditableModal}, event)" title="${hasChildren ? (isCollapsed ? 'Click to expand' : 'Click to collapse') : ''}">${hasChildren ? (isCollapsed ? '📁' : '📂') : '📄'}</span>
          <span class="tree-part-tag">${escapeHtml(node.partNo)}</span>
          <span class="tree-node-name">${escapeHtml(node.name)}</span>
          ${charTagHtml}
        </div>
        ${editBtnHtml}
      </div>
      ${hasChildren ? `<div class="tree-children" style="${isCollapsed ? 'display:none;' : ''}">${node.children.map(c => buildTreeHTML(c, isEditableModal)).join('')}</div>` : ''}
    </div>
  `;
}

function selectStructureNode(id, isEditableModal) {
  const ctx = getActiveFmeaData();
  if (isEditableModal) {
    selectedReferenceNodeId = id;
    const node = getStructureNodeById(ctx.structure, id);

    // Reset form to Create mode targeting selectedReferenceNodeId
    document.getElementById('structNodeId').value = '';
    document.getElementById('structPartNo').value = '';
    document.getElementById('structName').value = '';
    document.getElementById('structDesc').value = '';
    document.getElementById('structFormTitle').innerText = `+ Add Node (Target: ${node ? node.name : 'Root'})`;

    const btnSave = document.getElementById('btnSaveStruct');
    if (btnSave) btnSave.innerText = '➕ Create Node';

    const btnCancel = document.getElementById('btnCancelStruct');
    if (btnCancel) btnCancel.style.display = 'none';
    const btnDel = document.getElementById('btnDeleteStruct');
    if (btnDel) btnDel.style.display = 'none';

    window.activeSelectedStructClassifications = [];
    if (typeof window.renderClassificationMultiSelect === 'function') {
      window.renderClassificationMultiSelect('structClassificationContainer', [], (sel) => {
        window.activeSelectedStructClassifications = sel;
      });
    }
    const targetBadge = document.getElementById('targetRefNodeBadge');
    if (targetBadge) {
      targetBadge.innerHTML = node ? `🎯 Target Reference Node: <strong>${escapeHtml(node.partNo)} - ${escapeHtml(node.name)}</strong>` : '';
    }

    renderVariantCheckboxList('structVariantCheckboxList', 'struct', ['ALL']);

    const hActions = document.getElementById('nodeHierarchyActions');
    if (hActions) hActions.style.display = 'none';

    const container = document.getElementById('modalTreeContainer');
    if (container) container.innerHTML = buildTreeHTML(ctx.structure, true);
  } else {
    selectedStructureId = id; // Focus directly on clicked element for part-by-part loading
    if (typeof renderProcessSidebar === 'function') {
      renderProcessSidebar();
    }
    // NOTE: Do NOT clear activeComparisonState here — comparison mode persists across
    // sidebar navigation. The diff highlights remain visible for whichever element is selected.
    // User exits compare mode explicitly via "Exit Comparison View" button in the banner.
    const node = getStructureNodeById(fmeaData.structure, selectedStructureId);
    const nodeLabel = node ? `${node.partNo ? node.partNo + ' - ' : ''}${node.name}` : 'Selected Element';
    const focusedEl = document.getElementById('focusedNodeName');
    if (focusedEl) focusedEl.innerText = node ? `${node.partNo} - ${node.name}` : 'None Selected (Showing All System Elements)';
    renderTreeSidebar();
    if (typeof renderFMEATableAsync === 'function') {
      renderFMEATableAsync(nodeLabel, () => {
        updateAiPackageGeneratorButtonVisibility();
      });
    } else {
      renderFMEATable();
      updateAiPackageGeneratorButtonVisibility();
    }
  }
}

function editStructureNodeFromTree(id) {
  const ctx = getActiveFmeaData();
  const node = getStructureNodeById(ctx.structure, id);
  if (!node) return;

  selectedReferenceNodeId = id;
  document.getElementById('structNodeId').value = node.id;
  document.getElementById('structPartNo').value = node.partNo;
  document.getElementById('structName').value = node.name;
  document.getElementById('structDesc').value = node.description || '';
  document.getElementById('structFormTitle').innerText = `✏️ Edit Element: ${node.partNo} - ${node.name}`;

  const btnSave = document.getElementById('btnSaveStruct');
  if (btnSave) btnSave.innerText = '💾 Update Node';

  const btnCancel = document.getElementById('btnCancelStruct');
  if (btnCancel) btnCancel.style.display = 'inline-block';
  const btnDel = document.getElementById('btnDeleteStruct');
  if (btnDel) btnDel.style.display = 'none';

  const targetBadge = document.getElementById('targetRefNodeBadge');
  if (targetBadge) {
    targetBadge.innerHTML = `✏️ Editing Element: <strong>${escapeHtml(node.partNo)} - ${escapeHtml(node.name)}</strong>`;
  }

  renderVariantCheckboxList('structVariantCheckboxList', 'struct', node.variantId || ['ALL']);

  if (typeof initStructCharacteristicsUI === 'function') {
    initStructCharacteristicsUI(node.characteristics || []);
  }
  window.activeSelectedStructClassifications = Array.isArray(node.classificationIds) ? [...node.classificationIds] : [];
  if (typeof window.renderClassificationMultiSelect === 'function') {
    window.renderClassificationMultiSelect('structClassificationContainer', window.activeSelectedStructClassifications, (sel) => {
      window.activeSelectedStructClassifications = sel;
    });
  }
  const customSpecInput = document.getElementById('structCustomCharSpecInput');
  if (customSpecInput) {
    customSpecInput.value = node.characteristicsSpec || '';
  }

  const hActions = document.getElementById('nodeHierarchyActions');
  if (hActions) {
    hActions.style.display = (node.id === ctx.structure.id) ? 'none' : 'block';
  }

  const container = document.getElementById('modalTreeContainer');
  if (container) container.innerHTML = buildTreeHTML(ctx.structure, true);
}

