// ----------------------------------------------------
window.showAllControlsVariants = false;
window.showAllActionsVariants = false;

function toggleShowAllControlsVariants(checked) {
  window.showAllControlsVariants = checked;
  renderControlsLibraryList();
}
window.toggleShowAllControlsVariants = toggleShowAllControlsVariants;

function getVariantsForCause(causeId) {
  if (!causeId) return null;
  const ctx = getActiveFmeaData();

  // 1. Search in master cause library
  fmeaData.libraries = fmeaData.libraries || {};
  fmeaData.libraries.causes = fmeaData.libraries.causes || [];
  let c = fmeaData.libraries.causes.find(item => item.id === causeId);

  // 2. Search in current FMEA context failureModeCauses / causes
  if (!c && ctx.causes) {
    if (Array.isArray(ctx.causes)) {
      c = ctx.causes.find(item => item.id === causeId);
    } else if (typeof ctx.causes === 'object') {
      c = Object.values(ctx.causes).find(item => item.id === causeId);
    }
  }

  // 3. Search in DFMEA master causes if in PFMEA
  if (!c && fmeaData.causes) {
    if (Array.isArray(fmeaData.causes)) {
      c = fmeaData.causes.find(item => item.id === causeId);
    } else if (typeof fmeaData.causes === 'object') {
      c = Object.values(fmeaData.causes).find(item => item.id === causeId);
    }
  }

  if (c) {
    const v = c.variants || c.variantId;
    if (v) {
      if (Array.isArray(v) && v.length > 0) return v;
      if (typeof v === 'string' && v.trim() !== '') return [v];
    }
  }

  // 4. If no specific cause variants found, fall back to global selectedVariantFilter if active
  if (selectedVariantFilter && selectedVariantFilter !== 'ALL') {
    return [selectedVariantFilter];
  }

  return null;
}

function resetControlForm() {
  const form = document.getElementById('controlForm');
  if (form) form.reset();
  let hidden = document.getElementById('ctrlEditId');
  if (hidden) hidden.value = '';
  if (document.getElementById('ctrlInControlPlan')) document.getElementById('ctrlInControlPlan').checked = true;
  if (document.getElementById('ctrlIsPokaYoke')) document.getElementById('ctrlIsPokaYoke').checked = false;

  const causeVar = getVariantsForCause(activeCauseId);
  const defaultVar = causeVar || (selectedVariantFilter && selectedVariantFilter !== 'ALL' ? [selectedVariantFilter] : ['ALL']);
  renderVariantCheckboxList('ctrlVariantCheckboxList', 'ctrl', defaultVar);
  const submitBtn = document.querySelector('#controlForm button[type="submit"]');
  if (submitBtn) submitBtn.textContent = '+ Add to Library';
}

function openControlModal(causeId, type, charId = null) {
  if (!checkCanEditFMEA()) return;
  const ctx = getActiveFmeaData();
  const isPFMEA = (ctx && ctx.isPFMEA) || (fmeaData && fmeaData.activeFmeaType === 'PFMEA');
  activeCauseId = causeId;
  const effectiveCharId = isPFMEA ? (charId || null) : null;
  window.activeControlCharId = effectiveCharId;
  window.activeControlType = type || null;
  let linked = [];
  if (effectiveCharId) {
    linked = getControlsForCharacteristicOrCause(effectiveCharId, causeId);
  } else {
    linked = (ctx.causeControls || {})[causeId] || (fmeaData.causeControls || {})[causeId] || [];
    if (linked.length === 0 && Array.isArray(fmeaData.pfmeas)) {
      for (const p of fmeaData.pfmeas) {
        if (p.causeControls && Array.isArray(p.causeControls[causeId]) && p.causeControls[causeId].length > 0) {
          linked = p.causeControls[causeId];
          break;
        }
      }
    }
  }
  window.activePendingControlIds = [...linked];
  window.showAllControlsVariants = false;
  const searchInput = document.getElementById('ctrlSearchInput');
  if (searchInput) searchInput.value = '';

  const modalTitle = document.querySelector('#controlModal .modal-header h3');
  if (modalTitle) {
    if (effectiveCharId) {
      const allChars = [...(fmeaData.libraries?.characteristics || []), ...(ctx?.libraries?.characteristics || [])];
      const chObj = allChars.find(c => String(c.id) === String(effectiveCharId));
      const chName = chObj ? (chObj.name || chObj.details || 'Characteristic') : 'Characteristic';
      modalTitle.textContent = `Link ${type || 'Prevention/Detection'} Controls — [${chName}]`;
    } else {
      modalTitle.textContent = `Link ${type || 'Prevention/Detection'} Controls`;
    }
  }

  resetControlForm();
  renderControlsLibraryList();
  openModal('controlModal');
}

function toggleControlSelection(id, checked) {
  if (!window.activePendingControlIds) window.activePendingControlIds = [];
  if (checked) {
    if (!window.activePendingControlIds.includes(id)) window.activePendingControlIds.push(id);
  } else {
    window.activePendingControlIds = window.activePendingControlIds.filter(x => x !== id);
  }
}
window.toggleControlSelection = toggleControlSelection;

function renderControlsLibraryList() {
  const container = document.getElementById('controlsLibraryContainer');
  const ctx = getActiveFmeaData();
  const linkedIds = window.activePendingControlIds || (ctx.causeControls || {})[activeCauseId] || (fmeaData.causeControls || {})[activeCauseId] || [];

  fmeaData.libraries = fmeaData.libraries || {};
  fmeaData.libraries.controls = fmeaData.libraries.controls || [];

  const isPFMEAControl = (ctrl) => {
    return ctrl.module === 'PFMEA' || ctrl.origin === 'PFMEA' || (ctrl.id && String(ctrl.id).toLowerCase().includes('pfmea'));
  };

  let controls = fmeaData.libraries.controls;
  if (!ctx.isPFMEA) {
    controls = controls.filter(ctrl => !isPFMEAControl(ctrl) || linkedIds.includes(ctrl.id));
  } else {
    // In PFMEA mode, show PFMEA controls OR any controls already linked to this cause
    controls = controls.filter(ctrl => isPFMEAControl(ctrl) || linkedIds.includes(ctrl.id));
  }

  // Filter by cause's variants or global variant filter (unless override unchecked)
  const causeVar = getVariantsForCause(activeCauseId);
  const targetVarFilter = causeVar || (selectedVariantFilter !== 'ALL' ? selectedVariantFilter : null);
  if (targetVarFilter && !window.showAllControlsVariants) {
    controls = controls.filter(ctrl => matchesVariantFilter(ctrl.variants || ctrl.variantId, targetVarFilter));
  }

  const searchQuery = (document.getElementById('ctrlSearchInput')?.value || '').toLowerCase().trim();
  if (searchQuery) {
    controls = controls.filter(ctrl =>
      (ctrl.desc && ctrl.desc.toLowerCase().includes(searchQuery)) ||
      (ctrl.type && ctrl.type.toLowerCase().includes(searchQuery))
    );
  }

  const checkFilter = document.getElementById('ctrlCheckFilter')?.value || 'ALL';
  if (checkFilter === 'CHECKED') {
    controls = controls.filter(ctrl => linkedIds.includes(ctrl.id));
  } else if (checkFilter === 'UNCHECKED') {
    controls = controls.filter(ctrl => !linkedIds.includes(ctrl.id));
  }

  const varText = causeVar
    ? `Cause Variant: ${getVariantNamesDisplay(causeVar)}`
    : (selectedVariantFilter !== 'ALL' ? `Global Variant Filter` : 'All Variants');

  const filterHeaderHtml = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; padding:4px 8px;  border:1px solid #334155; border-radius:4px;">
      <span style="font-size:10.5px; font-weight:700; color:#38bdf8;">🎯 Active Filter: ${escapeHtml(varText)}</span>
      <label style="font-size:10.5px; font-weight:600; color:#cbd5e1; cursor:pointer; margin:0; display:flex; align-items:center; gap:4px;">
        <input type="checkbox" id="chkShowAllControlVariants" onchange="toggleShowAllControlsVariants(this.checked)" ${window.showAllControlsVariants ? 'checked' : ''}>
        View All Controls (Ignore Variant Filter)
      </label>
    </div>
  `;

  const listHtml = controls.map(ctrl => {
    const isChecked = linkedIds.includes(ctrl.id);
    const typeBadge = ctrl.type === 'Prevention'
      ? `<span style="background:rgba(16,185,129,0.15); color:#34d399; border:1px solid #059669; font-size:9.5px; padding:1px 5px; border-radius:3px; font-weight:700; margin-right:4px;">[Prevention]</span>`
      : `<span style="background:rgba(245,158,11,0.15); color:#fbbf24; border:1px solid #d97706; font-size:9.5px; padding:1px 5px; border-radius:3px; font-weight:700; margin-right:4px;">[Detection]</span>`;

    return `
    <div class="checkbox-card" style="display:flex; justify-content:space-between; align-items:center; background:${isChecked ? 'rgba(2, 132, 199, 0.12)' : '#1e293b'}; border:1px solid ${isChecked ? '#0284c7' : '#334155'}; padding:6px 10px; border-radius:6px; margin-bottom:4px;">
      <label style="flex:1; cursor:pointer; margin:0; font-size:11.5px; color:#f8fafc;">
        <input type="checkbox" id="chk_ctrl_${ctrl.id}" ${isChecked ? 'checked' : ''} onchange="toggleControlSelection('${ctrl.id}', this.checked)">
        ${typeBadge}${ctrl.inControlPlan === false ? '<span style="background:rgba(239,68,68,0.15); color:#f87171; border:1px solid #dc2626; font-size:9px; padding:1px 4px; border-radius:3px; margin-right:3px;">[No CP]</span>' : '<span style="background:rgba(2,132,199,0.15); color:#38bdf8; border:1px solid #0284c7; font-size:9px; padding:1px 4px; border-radius:3px; margin-right:3px;">[📋 CP]</span>'}${ctrl.isPokaYoke ? '<span style="background:rgba(16,185,129,0.2); color:#34d399; border:1px solid #059669; font-size:9px; padding:1px 4px; border-radius:3px; margin-right:3px;">[🛡️ POKA-YOKE]</span>' : ''}<strong style="">${escapeHtml(ctrl.desc)}</strong> <small style="color:#94a3b8; font-size:10px;">(${getVariantNamesDisplay(ctrl.variants || ctrl.variantId)})</small>
      </label>
      <div class="card-actions" style="display:flex; gap:4px;">
        <button class="btn btn-sm btn-secondary" style="font-size:10px; padding:2px 6px;" onclick="editLibraryControl('${ctrl.id}')">Edit</button>
        <button class="btn btn-sm btn-danger" style="font-size:10px; padding:2px 6px;" onclick="deleteLibraryControl('${ctrl.id}')">Del</button>
      </div>
    </div>
    `;
  }).join('');

  container.innerHTML = filterHeaderHtml + (listHtml || '<p class="text-muted" style="padding:12px; color:#94a3b8;">No controls in library matching active filter. Check "View All Controls" or create one on the left.</p>');
}

function addControlToLibrary(e) {
  e.preventDefault();
  if (!checkCanEditFMEA()) return;
  const ctx = getActiveFmeaData();
  const editId = document.getElementById('ctrlEditId') ? document.getElementById('ctrlEditId').value : null;
  const desc = document.getElementById('ctrlDesc').value.trim();
  const type = document.getElementById('ctrlType').value;
  const inControlPlan = document.getElementById('ctrlInControlPlan') ? document.getElementById('ctrlInControlPlan').checked : true;
  const isPokaYoke = document.getElementById('ctrlIsPokaYoke') ? document.getElementById('ctrlIsPokaYoke').checked : false;
  const variants = getSelectedVariantsFromCheckboxes('ctrl');

  if (editId) {
    const item = fmeaData.libraries.controls.find(i => i.id === editId);
    if (item) {
      item.desc = desc;
      item.type = type;
      item.inControlPlan = inControlPlan;
      item.isPokaYoke = isPokaYoke;
      item.variants = variants;
      item.variantId = variants;
    }
  } else {
    const newCtrl = {
      id: (ctx.isPFMEA ? 'lib-ctrl-pfmea-' : 'lib-ctrl-dfmea-') + Date.now(),
      desc,
      type,
      inControlPlan,
      isPokaYoke,
      variants,
      variantId: variants,
      origin: ctx.isPFMEA ? 'PFMEA' : 'DFMEA',
      module: ctx.isPFMEA ? 'PFMEA' : 'DFMEA'
    };
    fmeaData.libraries.controls.push(newCtrl);
    if (!window.activePendingControlIds) window.activePendingControlIds = [];
    if (!window.activePendingControlIds.includes(newCtrl.id)) window.activePendingControlIds.push(newCtrl.id);
  }

  resetControlForm();
  renderControlsLibraryList();
  renderFMEATable();
}

function editLibraryControl(id) {
  const item = fmeaData.libraries.controls.find(i => i.id === id);
  if (!item) return;
  document.getElementById('ctrlDesc').value = item.desc;
  document.getElementById('ctrlType').value = item.type;
  if (document.getElementById('ctrlInControlPlan')) {
    document.getElementById('ctrlInControlPlan').checked = item.inControlPlan !== false;
  }
  if (document.getElementById('ctrlIsPokaYoke')) {
    document.getElementById('ctrlIsPokaYoke').checked = !!item.isPokaYoke;
  }
  renderVariantCheckboxList('ctrlVariantCheckboxList', 'ctrl', item.variants || item.variantId || ['ALL']);

  let hidden = document.getElementById('ctrlEditId');
  if (!hidden) {
    hidden = document.createElement('input');
    hidden.type = 'hidden';
    hidden.id = 'ctrlEditId';
    document.getElementById('controlForm').appendChild(hidden);
  }
  hidden.value = item.id;

  const submitBtn = document.querySelector('#controlForm button[type="submit"]');
  if (submitBtn) submitBtn.textContent = 'Update Control';
}

async function deleteLibraryControl(id) {
  const isConfirmed = await showCustomConfirm("Delete this control from the master library?", "Delete Control", "warning");
  if (!isConfirmed) return;
  const ctx = getActiveFmeaData();
  fmeaData.libraries.controls = fmeaData.libraries.controls.filter(i => i.id !== id);
  if (window.activePendingControlIds) {
    window.activePendingControlIds = window.activePendingControlIds.filter(cId => cId !== id);
  }
  if (ctx.causeControls) {
    Object.keys(ctx.causeControls).forEach(k => {
      ctx.causeControls[k] = ctx.causeControls[k].filter(cId => cId !== id);
    });
  }
  renderControlsLibraryList();
  renderFMEATable();
}

function applySelectedControls() {
  if (!checkCanEditFMEA()) return;
  const ctx = getActiveFmeaData();
  const pendingIds = [...(window.activePendingControlIds || [])];
  const charId = window.activeControlCharId;

  if (charId) {
    const key = String(activeCauseId) + '_' + String(charId);
    ctx.causeCharControls = ctx.causeCharControls || {};
    ctx.causeCharControls[key] = pendingIds;
    ctx.charControls = ctx.charControls || {};
    ctx.charControls[charId] = pendingIds;
    fmeaData.causeCharControls = fmeaData.causeCharControls || {};
    fmeaData.causeCharControls[key] = pendingIds;
    fmeaData.charControls = fmeaData.charControls || {};
    fmeaData.charControls[charId] = pendingIds;
    if (ctx.isPFMEA && ctx.pfmea) {
      ctx.pfmea.causeCharControls = ctx.pfmea.causeCharControls || {};
      ctx.pfmea.causeCharControls[key] = pendingIds;
      ctx.pfmea.charControls = ctx.pfmea.charControls || {};
      ctx.pfmea.charControls[charId] = pendingIds;
    }
  } else {
    ctx.causeControls = ctx.causeControls || {};
    ctx.causeControls[activeCauseId] = pendingIds;
    if (ctx.isPFMEA && ctx.pfmea) {
      ctx.pfmea.causeControls = ctx.pfmea.causeControls || {};
      ctx.pfmea.causeControls[activeCauseId] = pendingIds;
    }
    fmeaData.causeControls = fmeaData.causeControls || {};
    fmeaData.causeControls[activeCauseId] = pendingIds;
  }

  closeModal('controlModal');
  if (typeof markDataChanged === 'function') markDataChanged('Controls Linkage Updated');
  renderFMEATable();
  if (typeof refreshFailureNetworkAfterEdit === 'function') {
    refreshFailureNetworkAfterEdit(activeCauseId);
  }
}

