/* ========================================================================================= */
/* 🔗 MULTI-TIER REVISION PINNING & BASELINE LINEAGE ENGINE (DFMEA -> PFMEA -> CONTROL PLAN)  */
/* ========================================================================================= */

function resolveDfmeaSourceData(pfmeaInstance = null) {
  if (!fmeaData) return { mode: 'LIVE', isFrozen: false, revNumber: 'Live Draft', freezeDate: null, lineageLabel: 'DFMEA Live Draft', sourceData: {} };

  const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : null;
  const targetPf = pfmeaInstance || (ctx && ctx.isPFMEA ? ctx.pfmea : null);
  const cfg = (targetPf && targetPf.dfmeaSourceConfig) || fmeaData.dfmeaSourceConfig || { mode: 'LIVE' };
  const dfmeaRevs = (fmeaData.revisions || []).filter(r => r.fmeaType !== 'PFMEA');
  const frozenRevs = dfmeaRevs.filter(r => r.status === 'Frozen').sort((a, b) => new Date(b.createdDate || 0) - new Date(a.createdDate || 0));

  if (cfg.mode === 'SPECIFIC' && cfg.selectedRevisionId) {
    const matched = dfmeaRevs.find(r => r.id === cfg.selectedRevisionId);
    if (matched && matched.snapshotData) {
      const snap = (matched.snapshotData && matched.snapshotData.dfmea) ? matched.snapshotData.dfmea : matched.snapshotData;
      return {
        mode: 'SPECIFIC',
        isFrozen: matched.status === 'Frozen',
        revId: matched.id,
        revNumber: matched.revNumber || 'Rev',
        freezeDate: matched.freezeDate || null,
        author: matched.creator || matched.author || '',
        lineageLabel: `DFMEA Rev ${matched.revNumber} (Frozen ${matched.freezeDate || ''})`,
        sourceData: snap
      };
    }
  }

  if (cfg.mode === 'LATEST_FROZEN' && frozenRevs.length > 0) {
    const latest = frozenRevs[0];
    const snap = (latest.snapshotData && latest.snapshotData.dfmea) ? latest.snapshotData.dfmea : latest.snapshotData;
    return {
      mode: 'LATEST_FROZEN',
      isFrozen: true,
      revId: latest.id,
      revNumber: latest.revNumber || 'Rev',
      freezeDate: latest.freezeDate || null,
      author: latest.creator || latest.author || '',
      lineageLabel: `DFMEA Rev ${latest.revNumber} (Frozen ${latest.freezeDate || ''})`,
      sourceData: snap || fmeaData
    };
  }

  // Default: LIVE Working Draft
  const currentDfRev = (fmeaData.revisions || []).find(r => r.id === fmeaData.currentRevision) || (fmeaData.revisions && fmeaData.revisions[0]);
  const liveLabel = currentDfRev ? `DFMEA Rev ${currentDfRev.revNumber} (Live Draft)` : 'DFMEA Live Draft';
  return {
    mode: 'LIVE',
    isFrozen: false,
    revId: currentDfRev ? currentDfRev.id : null,
    revNumber: currentDfRev ? currentDfRev.revNumber : 'Live Draft',
    freezeDate: null,
    author: (fmeaData.headerInfo && fmeaData.headerInfo.preparedBy) || '',
    lineageLabel: liveLabel,
    sourceData: {
      structure: fmeaData.structure,
      functions: fmeaData.functions,
      requirements: fmeaData.requirements,
      functionLines: fmeaData.functionLines,
      libraries: fmeaData.libraries,
      failureModeEffects: fmeaData.failureModeEffects,
      failureModeCauses: fmeaData.failureModeCauses,
      causeControls: fmeaData.causeControls,
      causeActions: fmeaData.causeActions
    }
  };
}
window.resolveDfmeaSourceData = resolveDfmeaSourceData;

function resolvePfmeaSourceData(targetPfmeaId = null, cpRevision = null) {
  if (!fmeaData) return { mode: 'LIVE', isFrozen: false, revNumber: 'Live Draft', pfmea: null, dfmeaSource: null, lineageLabel: 'PFMEA Live Draft' };

  const activePfmeas = (fmeaData.pfmeas && fmeaData.pfmeas.length > 0) ? fmeaData.pfmeas : (fmeaData.pfmea ? [fmeaData.pfmea] : []);
  let targetPfmea = null;
  if (targetPfmeaId) {
    targetPfmea = activePfmeas.find(p => String(p.id) === String(targetPfmeaId));
  }
  if (!targetPfmea && fmeaData.activePfmeaId) {
    targetPfmea = activePfmeas.find(p => String(p.id) === String(fmeaData.activePfmeaId));
  }
  if (!targetPfmea && activePfmeas.length > 0) {
    targetPfmea = activePfmeas[0];
  }

  const cpCfg = (cpRevision && cpRevision.sourceConfig) || fmeaData.controlPlanSourceConfig || { mode: 'LIVE' };
  const pfRevs = (targetPfmea && targetPfmea.revisions) || [];
  const frozenPfRevs = pfRevs.filter(r => r.status === 'Frozen').sort((a, b) => new Date(b.createdDate || 0) - new Date(a.createdDate || 0));

  let resolvedPfmea = targetPfmea;
  let isFrozen = false;
  let revNumber = 'Live Draft';
  let freezeDate = null;
  let revId = null;

  if (cpCfg.mode === 'SPECIFIC' && cpCfg.selectedPfmeaRevisionId) {
    const matched = pfRevs.find(r => r.id === cpCfg.selectedPfmeaRevisionId);
    if (matched && matched.snapshotData && matched.snapshotData.pfmea) {
      resolvedPfmea = matched.snapshotData.pfmea;
      isFrozen = matched.status === 'Frozen';
      revNumber = matched.revNumber;
      freezeDate = matched.freezeDate;
      revId = matched.id;
    }
  } else if (cpCfg.mode === 'LATEST_FROZEN' && frozenPfRevs.length > 0) {
    const latest = frozenPfRevs[0];
    if (latest && latest.snapshotData && latest.snapshotData.pfmea) {
      resolvedPfmea = latest.snapshotData.pfmea;
      isFrozen = true;
      revNumber = latest.revNumber;
      freezeDate = latest.freezeDate;
      revId = latest.id;
    }
  } else {
    // LIVE
    const curPfRev = targetPfmea && targetPfmea.revisions && targetPfmea.revisions.find(r => r.id === targetPfmea.currentRevision);
    revNumber = curPfRev ? `${curPfRev.revNumber} (Live Draft)` : 'Live Draft';
  }

  const dfmeaSource = resolveDfmeaSourceData(resolvedPfmea);

  return {
    mode: cpCfg.mode || 'LIVE',
    isFrozen,
    revId,
    revNumber,
    freezeDate,
    pfmea: resolvedPfmea,
    rawPfmeaInstance: targetPfmea,
    dfmeaSource,
    lineageLabel: isFrozen
      ? `PFMEA Rev ${revNumber} (Frozen ${freezeDate || ''})`
      : `PFMEA Live Draft (as of ${new Date().toLocaleDateString()})`
  };
}
window.resolvePfmeaSourceData = resolvePfmeaSourceData;

function checkUpstreamRevisionDrift(contextType = 'PFMEA', targetId = null) {
  if (!fmeaData) return null;

  if (contextType === 'PFMEA') {
    const activePfmeas = (fmeaData.pfmeas && fmeaData.pfmeas.length > 0) ? fmeaData.pfmeas : (fmeaData.pfmea ? [fmeaData.pfmea] : []);
    const pf = targetId ? activePfmeas.find(p => p.id === targetId) : (activePfmeas[0] || null);
    const cfg = (pf && pf.dfmeaSourceConfig) || fmeaData.dfmeaSourceConfig || { mode: 'LIVE' };
    const dfmeaRevs = (fmeaData.revisions || []).filter(r => r.fmeaType !== 'PFMEA');
    const frozenRevs = dfmeaRevs.filter(r => r.status === 'Frozen').sort((a, b) => new Date(b.createdDate || 0) - new Date(a.createdDate || 0));

    if (frozenRevs.length === 0) return { hasDrift: false, isLiveWithoutFrozen: true };

    const latestFrozen = frozenRevs[0];

    if (cfg.mode === 'SPECIFIC') {
      if (cfg.selectedRevisionId !== latestFrozen.id) {
        const currentMatched = dfmeaRevs.find(r => r.id === cfg.selectedRevisionId);
        return {
          hasDrift: true,
          type: 'NEWER_FROZEN_AVAILABLE',
          currentPinnedRevNo: currentMatched ? currentMatched.revNumber : 'Previous',
          latestFrozenRevNo: latestFrozen.revNumber,
          latestFrozenRevId: latestFrozen.id,
          latestFrozenDate: latestFrozen.freezeDate
        };
      }
    } else if (cfg.mode === 'LIVE') {
      return {
        hasDrift: false,
        canPinToFrozen: true,
        latestFrozenRevNo: latestFrozen.revNumber,
        latestFrozenRevId: latestFrozen.id,
        latestFrozenDate: latestFrozen.freezeDate
      };
    }
  } else if (contextType === 'CONTROL_PLAN') {
    const pfSource = resolvePfmeaSourceData();
    const pf = pfSource.rawPfmeaInstance;
    const pfRevs = (pf && pf.revisions) || [];
    const frozenPfRevs = pfRevs.filter(r => r.status === 'Frozen').sort((a, b) => new Date(b.createdDate || 0) - new Date(a.createdDate || 0));

    if (frozenPfRevs.length === 0) return { hasDrift: false, isLiveWithoutFrozen: true };

    const latestFrozen = frozenPfRevs[0];
    const cpCfg = fmeaData.controlPlanSourceConfig || { mode: 'LIVE' };

    if (cpCfg.mode === 'SPECIFIC' && cpCfg.selectedPfmeaRevisionId !== latestFrozen.id) {
      const currentMatched = pfRevs.find(r => r.id === cpCfg.selectedPfmeaRevisionId);
      return {
        hasDrift: true,
        type: 'NEWER_PFMEA_FROZEN_AVAILABLE',
        currentPinnedRevNo: currentMatched ? currentMatched.revNumber : 'Previous',
        latestFrozenRevNo: latestFrozen.revNumber,
        latestFrozenRevId: latestFrozen.id,
        latestFrozenDate: latestFrozen.freezeDate
      };
    } else if (cpCfg.mode === 'LIVE') {
      return {
        hasDrift: false,
        canPinToFrozen: true,
        latestFrozenRevNo: latestFrozen.revNumber,
        latestFrozenRevId: latestFrozen.id,
        latestFrozenDate: latestFrozen.freezeDate
      };
    }
  }

  return { hasDrift: false };
}
window.checkUpstreamRevisionDrift = checkUpstreamRevisionDrift;

function generateUpstreamBaselineDiff(oldSnapshotData, newSnapshotData) {
  const oldReqs = (oldSnapshotData && oldSnapshotData.requirements) || [];
  const newReqs = (newSnapshotData && newSnapshotData.requirements) || [];
  const oldLines = (oldSnapshotData && oldSnapshotData.functionLines) || [];
  const newLines = (newSnapshotData && newSnapshotData.functionLines) || [];

  const addedReqs = [];
  const modifiedReqs = [];
  const removedReqs = [];

  const oldReqMap = new Map();
  oldReqs.forEach(r => oldReqMap.set(r.id || r.reqNo, r));

  const newReqMap = new Map();
  newReqs.forEach(r => newReqMap.set(r.id || r.reqNo, r));

  newReqs.forEach(nr => {
    const key = nr.id || nr.reqNo;
    if (!oldReqMap.has(key)) {
      addedReqs.push(nr);
    } else {
      const or = oldReqMap.get(key);
      if (or.text !== nr.text || or.spec !== nr.spec || or.classSymbol !== nr.classSymbol) {
        modifiedReqs.push({ old: or, new: nr });
      }
    }
  });

  oldReqs.forEach(or => {
    const key = or.id || or.reqNo;
    if (!newReqMap.has(key)) {
      removedReqs.push(or);
    }
  });

  // Failure Modes Diff
  const oldFms = [];
  oldLines.forEach(l => (l.failureModes || []).forEach(fm => oldFms.push({ ...fm, funcId: l.funcId, structId: l.structId })));
  const newFms = [];
  newLines.forEach(l => (l.failureModes || []).forEach(fm => newFms.push({ ...fm, funcId: l.funcId, structId: l.structId })));

  const oldFmMap = new Map();
  oldFms.forEach(f => oldFmMap.set(f.id || f.name, f));
  const newFmMap = new Map();
  newFms.forEach(f => newFmMap.set(f.id || f.name, f));

  const addedFms = [];
  const modifiedFms = [];
  const removedFms = [];

  newFms.forEach(nf => {
    const key = nf.id || nf.name;
    if (!oldFmMap.has(key)) {
      addedFms.push(nf);
    } else {
      const ofm = oldFmMap.get(key);
      if (ofm.name !== nf.name) {
        modifiedFms.push({ old: ofm, new: nf });
      }
    }
  });

  oldFms.forEach(ofm => {
    const key = ofm.id || ofm.name;
    if (!newFmMap.has(key)) {
      removedFms.push(ofm);
    }
  });

  return {
    addedReqs,
    modifiedReqs,
    removedReqs,
    addedFms,
    modifiedFms,
    removedFms
  };
}
window.generateUpstreamBaselineDiff = generateUpstreamBaselineDiff;

function openBaselineSettingsModal(contextType = 'PFMEA', targetId = null) {
  const modal = document.getElementById('baselineSettingsModal');
  if (!modal) return;

  const ctxInput = document.getElementById('baselineSettingsContextType');
  const targetInput = document.getElementById('baselineSettingsTargetId');
  if (ctxInput) ctxInput.value = contextType;
  if (targetInput) targetInput.value = targetId || '';

  const titleEl = document.getElementById('baselineSettingsModalTitle');
  const subEl = document.getElementById('baselineSettingsModalSubtitle');
  const statusBox = document.getElementById('baselineCurrentStatusBox');
  const specSelect = document.getElementById('baselineSpecificRevisionSelect');

  if (contextType === 'PFMEA') {
    const activePfmeas = (fmeaData.pfmeas && fmeaData.pfmeas.length > 0) ? fmeaData.pfmeas : (fmeaData.pfmea ? [fmeaData.pfmea] : []);
    const pf = targetId ? activePfmeas.find(p => p.id === targetId) : (activePfmeas[0] || null);
    const pfName = pf ? (pf.name || pf.id) : 'Active PFMEA';
    const cfg = (pf && pf.dfmeaSourceConfig) || fmeaData.dfmeaSourceConfig || { mode: 'LIVE' };
    const dfmeaSource = resolveDfmeaSourceData(pf);
    const drift = checkUpstreamRevisionDrift('PFMEA', pf ? pf.id : null);

    if (titleEl) titleEl.innerText = `⚙️ Configure DFMEA Baseline for ${pfName}`;
    if (subEl) subEl.innerText = `Select whether ${pfName} auto-syncs with the live DFMEA working draft or pins to an approved frozen DFMEA revision.`;

    let statusHtml = `
      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
        <div>
          <span style="font-size:11px; color:#94a3b8; font-weight:600;">Current Sourcing Status:</span>
          <div style="font-size:13px; font-weight:700; color:${dfmeaSource.isFrozen ? '#38bdf8' : '#34d399'}; margin-top:2px;">
            ${dfmeaSource.isFrozen ? '🔒 ' : '🟢 '}${escapeHtml(dfmeaSource.lineageLabel)}
          </div>
        </div>
        <div>
          ${drift && drift.hasDrift ? `
            <button type="button" class="btn btn-xs" onclick="closeModal('baselineSettingsModal'); openRebaselineWizardModal('PFMEA', '${pf ? pf.id : ''}', '${drift.latestFrozenRevId}')" style="background:#4f46e5; color:#fff; border:none; padding:4px 10px; font-size:11px; font-weight:700; border-radius:4px; cursor:pointer;">
              ⚡ Review & Upgrade to Rev ${escapeHtml(drift.latestFrozenRevNo)}
            </button>
          ` : ''}
        </div>
      </div>
    `;
    if (statusBox) statusBox.innerHTML = statusHtml;

    // Populate DFMEA frozen revisions
    const dfmeaRevs = (fmeaData.revisions || []).filter(r => r.fmeaType !== 'PFMEA');
    const frozenRevs = dfmeaRevs.filter(r => r.status === 'Frozen');

    if (specSelect) {
      if (frozenRevs.length === 0) {
        specSelect.innerHTML = `<option value="">(No Frozen DFMEA Revisions Available - Create & Freeze DFMEA Rev First)</option>`;
      } else {
        specSelect.innerHTML = frozenRevs.map(r => `
          <option value="${r.id}" ${cfg.selectedRevisionId === r.id ? 'selected' : ''}>
            DFMEA Rev ${escapeHtml(r.revNumber)} — Frozen on ${escapeHtml(r.freezeDate || r.createdDate)} by ${escapeHtml(r.creator || 'Lead')}
          </option>
        `).join('');
      }
    }

    // Set radio selection
    const mode = cfg.mode || 'LIVE';
    if (mode === 'LIVE' && document.getElementById('baselineModeLive')) document.getElementById('baselineModeLive').checked = true;
    else if (mode === 'LATEST_FROZEN' && document.getElementById('baselineModeLatestFrozen')) document.getElementById('baselineModeLatestFrozen').checked = true;
    else if (mode === 'SPECIFIC' && document.getElementById('baselineModeSpecific')) document.getElementById('baselineModeSpecific').checked = true;

  } else if (contextType === 'CONTROL_PLAN') {
    const pfSource = resolvePfmeaSourceData();
    const pf = pfSource.rawPfmeaInstance;
    const cpCfg = fmeaData.controlPlanSourceConfig || { mode: 'LIVE' };
    const drift = checkUpstreamRevisionDrift('CONTROL_PLAN');

    if (titleEl) titleEl.innerText = `⚙️ Configure PFMEA Baseline for Process Control Plan`;
    if (subEl) subEl.innerText = `Select whether the Process Control Plan auto-syncs with live PFMEA draft or locks to an approved frozen PFMEA revision.`;

    let statusHtml = `
      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
        <div>
          <span style="font-size:11px; color:#94a3b8; font-weight:600;">Current Sourcing Status:</span>
          <div style="font-size:13px; font-weight:700; color:${pfSource.isFrozen ? '#38bdf8' : '#34d399'}; margin-top:2px;">
            ${pfSource.isFrozen ? '🔒 ' : '🟢 '}${escapeHtml(pfSource.lineageLabel)}
          </div>
        </div>
        <div>
          ${drift && drift.hasDrift ? `
            <button type="button" class="btn btn-xs" onclick="closeModal('baselineSettingsModal'); openRebaselineWizardModal('CONTROL_PLAN', null, '${drift.latestFrozenRevId}')" style="background:#4f46e5; color:#fff; border:none; padding:4px 10px; font-size:11px; font-weight:700; border-radius:4px; cursor:pointer;">
              ⚡ Review & Upgrade to PFMEA Rev ${escapeHtml(drift.latestFrozenRevNo)}
            </button>
          ` : ''}
        </div>
      </div>
    `;
    if (statusBox) statusBox.innerHTML = statusHtml;

    const pfRevs = (pf && pf.revisions) || [];
    const frozenPfRevs = pfRevs.filter(r => r.status === 'Frozen');

    if (specSelect) {
      if (frozenPfRevs.length === 0) {
        specSelect.innerHTML = `<option value="">(No Frozen PFMEA Revisions Available - Freeze PFMEA First)</option>`;
      } else {
        specSelect.innerHTML = frozenPfRevs.map(r => `
          <option value="${r.id}" ${cpCfg.selectedPfmeaRevisionId === r.id ? 'selected' : ''}>
            PFMEA Rev ${escapeHtml(r.revNumber)} — Frozen on ${escapeHtml(r.freezeDate || r.createdDate)} by ${escapeHtml(r.creator || 'Lead')}
          </option>
        `).join('');
      }
    }

    const mode = cpCfg.mode || 'LIVE';
    if (mode === 'LIVE' && document.getElementById('baselineModeLive')) document.getElementById('baselineModeLive').checked = true;
    else if (mode === 'LATEST_FROZEN' && document.getElementById('baselineModeLatestFrozen')) document.getElementById('baselineModeLatestFrozen').checked = true;
    else if (mode === 'SPECIFIC' && document.getElementById('baselineModeSpecific')) document.getElementById('baselineModeSpecific').checked = true;
  }

  onBaselineModeRadioChange();
  modal.style.display = 'flex';
}
