function saveBaselineSettings() {
  const contextType = document.getElementById('baselineSettingsContextType')?.value || 'PFMEA';
  const targetId = document.getElementById('baselineSettingsTargetId')?.value || '';
  const selectedMode = document.querySelector('input[name="baselineSourceModeRadio"]:checked')?.value || 'LIVE';
  const selectedRevId = document.getElementById('baselineSpecificRevisionSelect')?.value || null;

  if (contextType === 'PFMEA') {
    const activePfmeas = (fmeaData.pfmeas && fmeaData.pfmeas.length > 0) ? fmeaData.pfmeas : (fmeaData.pfmea ? [fmeaData.pfmea] : []);
    const pf = targetId ? activePfmeas.find(p => p.id === targetId) : (activePfmeas[0] || null);

    const newCfg = {
      mode: selectedMode,
      selectedRevisionId: selectedMode === 'SPECIFIC' ? selectedRevId : null,
      updatedAt: new Date().toISOString()
    };

    if (pf) {
      pf.dfmeaSourceConfig = newCfg;
    }
    fmeaData.dfmeaSourceConfig = newCfg;

    syncLiveDfmeaDataToPfmeas();
    if (typeof renderFMEATable === 'function') renderFMEATable();
    if (typeof renderFmeaContextDropdown === 'function') renderFmeaContextDropdown();
    if (typeof saveProjectToLocalStorage === 'function') saveProjectToLocalStorage();

    if (typeof showToast === 'function') {
      showToast(`✅ PFMEA Baseline updated to: ${selectedMode === 'LIVE' ? '🟢 Live Working Draft' : selectedMode === 'LATEST_FROZEN' ? '🔒 Auto-Track Latest Frozen' : '📌 Specific Frozen Revision'}`);
    }
  } else if (contextType === 'CONTROL_PLAN') {
    const newCfg = {
      mode: selectedMode,
      selectedPfmeaRevisionId: selectedMode === 'SPECIFIC' ? selectedRevId : null,
      updatedAt: new Date().toISOString()
    };
    fmeaData.controlPlanSourceConfig = newCfg;

    const curCpRev = getActiveControlPlanRevision();
    if (curCpRev) {
      curCpRev.sourceConfig = newCfg;
    }

    updateControlPlanHeaderBadges();
    renderControlPlanTable();
    renderControlPlanRevisionUI();
    if (typeof saveProjectToLocalStorage === 'function') saveProjectToLocalStorage();

    if (typeof showToast === 'function') {
      showToast(`✅ Control Plan Baseline updated to: ${selectedMode === 'LIVE' ? '🟢 Live PFMEA Draft' : selectedMode === 'LATEST_FROZEN' ? '🔒 Auto-Track Latest Frozen' : '📌 Specific Frozen Revision'}`);
    }
  }

  const modal = document.getElementById('baselineSettingsModal');
  if (modal) modal.style.display = 'none';
}
window.saveBaselineSettings = saveBaselineSettings;

function openRebaselineWizardModal(contextType = 'PFMEA', targetId = null, targetNewRevId = null) {
  const modal = document.getElementById('rebaselineWizardModal');
  if (!modal) return;

  const titleEl = document.getElementById('rebaselineWizardTitle');
  const subEl = document.getElementById('rebaselineWizardSubtitle');
  const sumBox = document.getElementById('rebaselineImpactSummaryBox');
  const diffCont = document.getElementById('rebaselineDiffContainer');
  const confirmBtn = document.getElementById('btnConfirmRebaselineUpgrade');

  if (contextType === 'PFMEA') {
    const activePfmeas = (fmeaData.pfmeas && fmeaData.pfmeas.length > 0) ? fmeaData.pfmeas : (fmeaData.pfmea ? [fmeaData.pfmea] : []);
    const pf = targetId ? activePfmeas.find(p => p.id === targetId) : (activePfmeas[0] || null);
    const oldSource = resolveDfmeaSourceData(pf);

    const dfmeaRevs = (fmeaData.revisions || []).filter(r => r.fmeaType !== 'PFMEA');
    const targetRev = targetNewRevId ? dfmeaRevs.find(r => r.id === targetNewRevId) : dfmeaRevs.filter(r => r.status === 'Frozen')[0];

    if (!targetRev) {
      alert("Target DFMEA revision not found.");
      return;
    }

    const newSnapshot = (targetRev.snapshotData && targetRev.snapshotData.dfmea) ? targetRev.snapshotData.dfmea : targetRev.snapshotData;
    const oldSnapshot = oldSource.sourceData;

    const diff = generateUpstreamBaselineDiff(oldSnapshot, newSnapshot);

    if (titleEl) titleEl.innerText = `🛡️ Re-baseline PFMEA to DFMEA Rev ${escapeHtml(targetRev.revNumber)}`;
    if (subEl) subEl.innerText = `Upgrading from ${escapeHtml(oldSource.lineageLabel)} ➔ DFMEA Rev ${escapeHtml(targetRev.revNumber)} (Frozen ${escapeHtml(targetRev.freezeDate || '')})`;

    let sumHtml = `
      <div style="display:flex; justify-content:space-around; align-items:center; text-align:center; padding:6px 0;">
        <div>
          <span style="font-size:18px; font-weight:800; color:#34d399;">+${diff.addedReqs.length + diff.addedFms.length}</span>
          <div style="font-size:11px; color:#94a3b8;">New Items to Add</div>
        </div>
        <div>
          <span style="font-size:18px; font-weight:800; color:#fbbf24;">${diff.modifiedReqs.length + diff.modifiedFms.length}</span>
          <div style="font-size:11px; color:#94a3b8;">Specs / Severity Deltas</div>
        </div>
        <div>
          <span style="font-size:18px; font-weight:800; color:#f87171;">-${diff.removedReqs.length + diff.removedFms.length}</span>
          <div style="font-size:11px; color:#94a3b8;">Obsolete / Removed</div>
        </div>
      </div>
    `;
    if (sumBox) sumBox.innerHTML = sumHtml;

    let diffHtml = '';
    // Section 1: Modified Characteristics
    if (diff.modifiedReqs.length > 0) {
      diffHtml += `
        <div style="background:#141e33; border:1px solid #243456; border-radius:6px; padding:10px;">
          <strong style="color:#fbbf24; font-size:12px;">⚡ Modified Characteristics & Tolerances:</strong>
          <table style="width:100%; border-collapse:collapse; font-size:11px; margin-top:6px;">
            <thead><tr style="color:#94a3b8; border-bottom:1px solid #334155; text-align:left;"><th style="padding:4px;">Req #</th><th style="padding:4px;">Description</th><th style="padding:4px;">Before ➔ After</th></tr></thead>
            <tbody>
              ${diff.modifiedReqs.map(m => `
                <tr style="border-bottom:1px solid #1e293b;">
                  <td style="padding:4px; font-weight:700; color:#38bdf8;">${escapeHtml(m.new.reqNo || '')}</td>
                  <td style="padding:4px;">${escapeHtml(m.new.text || '')}</td>
                  <td style="padding:4px;">
                    <span style="text-decoration:line-through; color:#f87171;">${escapeHtml(m.old.spec || m.old.classSymbol || '-')}</span>
                    ➔ <strong style="color:#34d399;">${escapeHtml(m.new.spec || m.new.classSymbol || '-')}</strong>
                  </td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `;
    }

    // Section 2: Added Requirements
    if (diff.addedReqs.length > 0) {
      diffHtml += `
        <div style="background:#141e33; border:1px solid #243456; border-radius:6px; padding:10px;">
          <strong style="color:#34d399; font-size:12px;">+ New Characteristics in Rev ${escapeHtml(targetRev.revNumber)}:</strong>
          <ul style="margin:6px 0 0 16px; padding:0; font-size:11.5px; color:#cbd5e1;">
            ${diff.addedReqs.map(r => `<li><strong>[${escapeHtml(r.reqNo || 'CHAR')}]</strong> ${escapeHtml(r.text || '')} ${r.spec ? `<em style="color:#38bdf8;">(${escapeHtml(r.spec)})</em>` : ''}</li>`).join('')}
          </ul>
        </div>
      `;
    }

    if (diffCont) diffCont.innerHTML = diffHtml || `<div style="padding:16px; text-align:center; color:#94a3b8; font-size:12px;">No structural conflicts detected. Ready to upgrade baseline!</div>`;

    if (confirmBtn) {
      confirmBtn.onclick = () => executeRebaselineUpgrade('PFMEA', pf ? pf.id : null, targetRev.id);
    }
  } else if (contextType === 'CONTROL_PLAN') {
    const pfSource = resolvePfmeaSourceData();
    const pf = pfSource.rawPfmeaInstance;
    const pfRevs = (pf && pf.revisions) || [];
    const targetRev = targetNewRevId ? pfRevs.find(r => r.id === targetNewRevId) : pfRevs.filter(r => r.status === 'Frozen')[0];

    if (!targetRev) {
      alert("Target PFMEA revision not found.");
      return;
    }

    const newSnapshot = (targetRev.snapshotData && targetRev.snapshotData.pfmea) ? targetRev.snapshotData.pfmea : targetRev.snapshotData;
    const oldSnapshot = pfSource.pfmea;

    const oldReqs = (oldSnapshot && (oldSnapshot.requirements || oldSnapshot.characteristics)) || [];
    const newReqs = (newSnapshot && (newSnapshot.requirements || newSnapshot.characteristics)) || [];
    const diff = generateUpstreamBaselineDiff({ requirements: oldReqs }, { requirements: newReqs });

    if (titleEl) titleEl.innerText = `🛡️ Re-baseline Control Plan to PFMEA Rev ${escapeHtml(targetRev.revNumber)}`;
    if (subEl) subEl.innerText = `Upgrading from ${escapeHtml(pfSource.lineageLabel)} ➔ PFMEA Rev ${escapeHtml(targetRev.revNumber)} (Frozen ${escapeHtml(targetRev.freezeDate || '')})`;

    let sumHtml = `
      <div style="display:flex; justify-content:space-around; align-items:center; text-align:center; padding:6px 0;">
        <div>
          <span style="font-size:18px; font-weight:800; color:#34d399;">+${diff.addedReqs.length}</span>
          <div style="font-size:11px; color:#94a3b8;">New Items to Add</div>
        </div>
        <div>
          <span style="font-size:18px; font-weight:800; color:#fbbf24;">${diff.modifiedReqs.length}</span>
          <div style="font-size:11px; color:#94a3b8;">Specs / Tolerances Deltas</div>
        </div>
        <div>
          <span style="font-size:18px; font-weight:800; color:#f87171;">-${diff.removedReqs.length}</span>
          <div style="font-size:11px; color:#94a3b8;">Obsolete / Removed</div>
        </div>
      </div>
    `;
    if (sumBox) sumBox.innerHTML = sumHtml;

    let diffHtml = '';
    if (diff.modifiedReqs.length > 0) {
      diffHtml += `
        <div style="background:#141e33; border:1px solid #243456; border-radius:6px; padding:10px;">
          <strong style="color:#fbbf24; font-size:12px;">⚡ Modified Characteristics & Tolerances:</strong>
          <table style="width:100%; border-collapse:collapse; font-size:11px; margin-top:6px;">
            <thead><tr style="color:#94a3b8; border-bottom:1px solid #334155; text-align:left;"><th style="padding:4px;">Req #</th><th style="padding:4px;">Description</th><th style="padding:4px;">Before ➔ After</th></tr></thead>
            <tbody>
              ${diff.modifiedReqs.map(m => `
                <tr style="border-bottom:1px solid #1e293b;">
                  <td style="padding:4px; font-weight:700; color:#38bdf8;">${escapeHtml(m.new.reqNo || m.new.id || '')}</td>
                  <td style="padding:4px;">${escapeHtml(m.new.text || m.new.name || '')}</td>
                  <td style="padding:4px;">
                    <span style="text-decoration:line-through; color:#f87171;">${escapeHtml(m.old.spec || m.old.classSymbol || '-')}</span>
                    ➔ <strong style="color:#34d399;">${escapeHtml(m.new.spec || m.new.classSymbol || '-')}</strong>
                  </td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `;
    }

    if (diff.addedReqs.length > 0) {
      diffHtml += `
        <div style="background:#141e33; border:1px solid #243456; border-radius:6px; padding:10px;">
          <strong style="color:#34d399; font-size:12px;">+ New Characteristics in Rev ${escapeHtml(targetRev.revNumber)}:</strong>
          <ul style="margin:6px 0 0 16px; padding:0; font-size:11.5px; color:#cbd5e1;">
            ${diff.addedReqs.map(r => `<li><strong>[${escapeHtml(r.reqNo || r.id || 'CHAR')}]</strong> ${escapeHtml(r.text || r.name || '')} ${r.spec ? `<em style="color:#38bdf8;">(${escapeHtml(r.spec)})</em>` : ''}</li>`).join('')}
          </ul>
        </div>
      `;
    }

    if (diffCont) diffCont.innerHTML = diffHtml || `<div style="padding:16px; text-align:center; color:#94a3b8; font-size:12px;">No structural conflicts detected. Ready to upgrade baseline!</div>`;

    if (confirmBtn) {
      confirmBtn.onclick = () => executeRebaselineUpgrade('CONTROL_PLAN', null, targetRev.id);
    }
  }

  modal.style.display = 'flex';
}
window.openRebaselineWizardModal = openRebaselineWizardModal;

function executeRebaselineUpgrade(contextType = 'PFMEA', targetId = null, targetNewRevId = null) {
  if (contextType === 'PFMEA') {
    const activePfmeas = (fmeaData.pfmeas && fmeaData.pfmeas.length > 0) ? fmeaData.pfmeas : (fmeaData.pfmea ? [fmeaData.pfmea] : []);
    const pf = targetId ? activePfmeas.find(p => p.id === targetId) : (activePfmeas[0] || null);

    if (pf) {
      pf.dfmeaSourceConfig = {
        mode: 'SPECIFIC',
        selectedRevisionId: targetNewRevId,
        updatedAt: new Date().toISOString()
      };
    }
    fmeaData.dfmeaSourceConfig = {
      mode: 'SPECIFIC',
      selectedRevisionId: targetNewRevId,
      updatedAt: new Date().toISOString()
    };

    syncLiveDfmeaDataToPfmeas();
    if (typeof renderFMEATable === 'function') renderFMEATable();
    if (typeof renderFmeaContextDropdown === 'function') renderFmeaContextDropdown();
    if (typeof saveProjectToLocalStorage === 'function') saveProjectToLocalStorage();

    if (typeof showToast === 'function') {
      showToast(`🎉 PFMEA has been successfully re-baselined to DFMEA Rev!`);
    }
  } else if (contextType === 'CONTROL_PLAN') {
    const newCfg = {
      mode: 'SPECIFIC',
      selectedPfmeaRevisionId: targetNewRevId,
      updatedAt: new Date().toISOString()
    };
    fmeaData.controlPlanSourceConfig = newCfg;

    const curCpRev = getActiveControlPlanRevision();
    if (curCpRev) {
      curCpRev.sourceConfig = newCfg;
    }

    updateControlPlanHeaderBadges();
    renderControlPlanTable();
    renderControlPlanRevisionUI();
    if (typeof saveProjectToLocalStorage === 'function') saveProjectToLocalStorage();

    if (typeof showToast === 'function') {
      showToast(`🎉 Process Control Plan has been successfully re-baselined to PFMEA Rev!`);
    }
  }

  const modal = document.getElementById('rebaselineWizardModal');
  if (modal) modal.style.display = 'none';
}
window.executeRebaselineUpgrade = executeRebaselineUpgrade;

function onDfmeaSyncSourceSelectChange(selectedVal) {
  const syncNotice = document.getElementById('syncDfmeaSourceNotice');
  if (selectedVal === 'LIVE') {
    if (syncNotice) syncNotice.innerText = 'Using real-time live DFMEA draft';
  } else {
    if (syncNotice) syncNotice.innerText = `Sourcing from frozen DFMEA snapshot`;
  }
}
window.onDfmeaSyncSourceSelectChange = onDfmeaSyncSourceSelectChange;

function syncLiveDfmeaDataToPfmeas() {
  if (!fmeaData) return;

  // Sync across all PFMEA instances respecting each PFMEA's source binding
  const pfmeasToSync = fmeaData.pfmeas ? fmeaData.pfmeas : (fmeaData.pfmea ? [fmeaData.pfmea] : []);

  pfmeasToSync.forEach(pfmea => {
    const dfmeaSource = resolveDfmeaSourceData(pfmea);
    const sourceData = dfmeaSource.sourceData || fmeaData;
    const dfmeaReqs = sourceData.requirements || [];
    const dfmeaLines = sourceData.functionLines || [];

    // Build lookup maps for this DFMEA source's failure modes and severities
    const dfFmMap = {};
    dfmeaLines.forEach(fl => {
      const structNode = typeof getStructureNodeById === 'function' ? getStructureNodeById(sourceData.structure || fmeaData.structure, fl.structId) : null;
      const structName = structNode ? (structNode.partNo ? `${structNode.partNo} - ${structNode.name}` : structNode.name) : 'DFMEA System';
      const funcObj = (sourceData.functions || fmeaData.functions || []).find(f => f.id === fl.funcId);
      const funcName = funcObj ? funcObj.name : 'DFMEA Function';

      // Get requirement text if linked
      const reqMap = sourceData.functionRequirements || fmeaData.functionRequirements || {};
      const reqIds = reqMap[fl.id] || [];
      const assignedReqs = (sourceData.requirements || []).filter(r => reqIds.includes(r.id));
      const reqText = assignedReqs.map(r => r.reqNo ? `${r.reqNo}: ${r.text}` : r.text).join('; ');

      (fl.failureModes || []).forEach(fm => {
        const effMap = sourceData.failureModeEffects || fmeaData.failureModeEffects || {};
        const linkedEffIds = effMap[fm.id] || [];
        const linkedEffects = ((sourceData.libraries && sourceData.libraries.effects) || (fmeaData.libraries && fmeaData.libraries.effects) || []).filter(e => linkedEffIds.includes(e.id));
        const fmDirectSev = parseInt(fm.sev || fm.severity, 10) || 0;
        const fmChainSev = (typeof getEffectiveSeverityForFailureMode === 'function') ? getEffectiveSeverityForFailureMode(fm.id) : 0;
        const effsMaxSev = linkedEffects.reduce((max, e) => Math.max(max, parseInt(e.severity) || 0), 0);
        const maxSev = Math.max(fmChainSev, effsMaxSev, fmDirectSev, 7);
        dfFmMap[fm.id] = {
          fmName: fm.name,
          funcName: funcName,
          structName: structName,
          requirement: reqText,
          severity: maxSev
        };
      });
    });

    // 1. Sync Requirements / Product Characteristics
    (pfmea.requirements || []).forEach(pReq => {
      if (pReq.dfmeaReqId) {
        const sourceReq = dfmeaReqs.find(r => r.id === pReq.dfmeaReqId);
        if (sourceReq) {
          pReq.reqNo = sourceReq.reqNo;
          pReq.text = sourceReq.text;
          pReq.spec = sourceReq.spec;
          if (sourceReq.classSymbol) pReq.classSymbol = sourceReq.classSymbol;
        }
      }
    });

    // 2. Sync Process Failure Modes
    (pfmea.functionLines || []).forEach(fl => {
      (fl.failureModes || []).forEach(pfm => {
        if (pfm.dfmeaFmId && dfFmMap[pfm.dfmeaFmId]) {
          const source = dfFmMap[pfm.dfmeaFmId];
          pfm.name = 'Process non-conformance leading to: ' + source.fmName;
        }
      });
    });
  });

  // 3. Also sync transferred effects in active effect library using global or active DFMEA source
  const globalDfSource = resolveDfmeaSourceData(null);
  const gLines = (globalDfSource.sourceData && globalDfSource.sourceData.functionLines) || fmeaData.functionLines || [];
  const gFmMap = {};
  gLines.forEach(fl => {
    const structNode = typeof getStructureNodeById === 'function' ? getStructureNodeById((globalDfSource.sourceData && globalDfSource.sourceData.structure) || fmeaData.structure, fl.structId) : null;
    const structName = structNode ? (structNode.partNo ? `${structNode.partNo} - ${structNode.name}` : structNode.name) : 'DFMEA System';
    const funcObj = ((globalDfSource.sourceData && globalDfSource.sourceData.functions) || fmeaData.functions || []).find(f => f.id === fl.funcId);
    const funcName = funcObj ? funcObj.name : 'DFMEA Function';

    (fl.failureModes || []).forEach(fm => {
      const effMap = (globalDfSource.sourceData && globalDfSource.sourceData.failureModeEffects) || fmeaData.failureModeEffects || {};
      const linkedEffIds = effMap[fm.id] || [];
      const linkedEffects = (fmeaData.libraries && fmeaData.libraries.effects || []).filter(e => linkedEffIds.includes(e.id));
      const fmDirectSev = parseInt(fm.sev || fm.severity, 10) || 0;
      const fmChainSev = (typeof getEffectiveSeverityForFailureMode === 'function') ? getEffectiveSeverityForFailureMode(fm.id) : 0;
      const effsMaxSev = linkedEffects.reduce((max, e) => Math.max(max, parseInt(e.severity) || 0), 0);
      const maxSev = Math.max(fmChainSev, effsMaxSev, fmDirectSev, 7);
      gFmMap[fm.id] = {
        fmName: fm.name,
        funcName: funcName,
        structName: structName,
        severity: maxSev
      };
    });
  });

  (fmeaData.libraries && fmeaData.libraries.effects || []).forEach(eff => {
    if (eff.dfmeaFmId && gFmMap[eff.dfmeaFmId]) {
      const source = gFmMap[eff.dfmeaFmId];
      if (source.structName) eff.systemName = source.structName;
      eff.functionName = source.funcName;
      eff.desc = source.fmName + ' (DFMEA Failure Mode)';
      eff.severity = source.severity;
    }
  });
}

// ----------------------------------------------------
// FMEA Column Header Filtering Module
// ----------------------------------------------------
var headerColumnFilters = {}; // { colKey: Set of selected string values } for FMEA Table
var dvpColumnFilters = {}; // { colKey: Set of selected string values } for DVP Table
var charSpecColumnFilters = {}; // { colKey: Set of selected string values } for Characteristics Table
var charLinkageColumnFilters = {}; // { colKey: Set of selected string values } for Characteristics Linkage Matrix
var activeFilterContext = 'fmea'; // 'fmea' | 'dvp' | 'charspec' | 'charlinkage'
var currentFilterMenuKey = null;
var tempHeaderFilterSelection = null;

function toggleViewCompleteFmea(checked) {
  viewCompleteFmeaMode = !!checked;
  const focusedNodeName = document.getElementById('focusedNodeName');
  if (focusedNodeName) {
    if (viewCompleteFmeaMode) {
      focusedNodeName.textContent = 'Showing Complete FMEA (Full Tree View)';
    } else {
      const activeNode = selectedStructureId ? getStructureNodeById(fmeaData.structure, selectedStructureId) : null;
      focusedNodeName.textContent = activeNode ? `${activeNode.partNo ? activeNode.partNo + ' - ' : ''}${activeNode.name}` : 'None Selected (Showing Full Tree)';
    }
  }
  if (typeof renderFMEATableAsync === 'function') {
    renderFMEATableAsync(viewCompleteFmeaMode ? 'Complete FMEA (All System Elements)' : 'Active Component');
  } else {
    renderFMEATable();
  }
}

function getColumnTitle(colKey) {
  const labelSpan = document.querySelector(`#fmeaTable thead th[data-colkey="${colKey}"] .hdr-text`);
  if (labelSpan) return labelSpan.textContent.trim();
  return colKey;
}

function buildRowContextsForContext(ctx, targetStructureId = null, applyVariantFilter = false) {
  const isPFMEA = ctx.isPFMEA;
  const isVDA = (fmeaData.methodologyMode === 'AIAG-VDA');
  const rows = [];

  function getFlatStructureNodes(root) {
    if (!root) return [];
    let list = [root];
    if (root.children && root.children.length > 0) {
      root.children.forEach(c => { list = list.concat(getFlatStructureNodes(c)); });
    }
    return list;
  }

  let allNodes = [];
  if (isPFMEA && ctx.pfmea && ctx.pfmea.processSteps) {
    ctx.pfmea.processSteps.forEach(pstep => {
      allNodes.push({
        id: pstep.id,
        partNo: pstep.stepNo,
        name: pstep.name,
        variantId: pstep.variantId,
        dfmeaStructId: pstep.dfmeaStructId
      });
    });
  } else {
    allNodes = getFlatStructureNodes(fmeaData.structure);
  }

  if (targetStructureId) {
    if (isPFMEA) {
      if (viewCompleteFmeaMode) {
        const rootNode = getStructureNodeById(fmeaData.structure, targetStructureId);
        const subTreeIds = new Set(getFlatStructureNodes(rootNode).map(n => n.id));
        allNodes = allNodes.filter(n => n.id === targetStructureId || subTreeIds.has(n.dfmeaStructId));
      } else {
        allNodes = allNodes.filter(n => n.id === targetStructureId || String(n.dfmeaStructId) === String(targetStructureId));
      }
    } else {
      if (viewCompleteFmeaMode) {
        const rootNode = getStructureNodeById(fmeaData.structure, targetStructureId);
        const subTreeIds = new Set(getFlatStructureNodes(rootNode).map(n => n.id));
        allNodes = allNodes.filter(n => subTreeIds.has(n.id));
      } else {
        allNodes = allNodes.filter(n => n.id === targetStructureId);
      }
    }
  }

  if (applyVariantFilter) {
    allNodes = allNodes.filter(n => matchesVariantFilter(n.variantId));
  }

  allNodes.forEach(structNode => {
    let nodeLines = (ctx.functionLines || []).filter(fl => fl.structId === structNode.id);
    let structName = 'System Element';
    if (structNode) {
      if (structNode.dfmeaStructId) {
        const parentNode = getStructureNodeById(fmeaData.structure, structNode.dfmeaStructId);
        if (parentNode) {
          const parentName = `${parentNode.partNo ? parentNode.partNo + ' - ' : ''}${parentNode.name}`.trim();
          structName = `[${parentName}] ${structNode.partNo || ''} ${structNode.name || ''}`.trim();
        } else {
          structName = `${structNode.partNo || ''} ${structNode.name || ''}`.trim();
        }
      } else {
        structName = `${structNode.partNo ? structNode.partNo + ' - ' : ''}${structNode.name || ''}`.trim();
      }
    }

    if (nodeLines.length === 0) return;

    nodeLines.forEach(fl => {
      const funcObj = (ctx.functions || []).find(f => f.id === fl.funcId);
      if (!funcObj || fl.isConsidered === false) return;
      if (applyVariantFilter && !matchesVariantFilter(funcObj.variants || funcObj.variantId, undefined, structNode.variantId)) return;

      const reqMap = ctx.functionRequirements || {};
      const reqIds = reqMap[fl.id] || [];
      const allReqsList = getActiveRequirementsList(ctx);
      const assignedReqs = allReqsList.filter(r => reqIds.includes(r.id) && (!applyVariantFilter || matchesVariantFilter(r.variants || r.variantId, undefined, funcObj.variants || structNode.variantId)));
      const reqTextPlain = assignedReqs.length > 0 ? assignedReqs.map(r => `${r.reqNo}: ${r.text}`).join('; ') : '-';

      const failureModes = fl.failureModes || [];
      if (failureModes.length === 0) return;

      failureModes.forEach(fm => {
        if (applyVariantFilter && !matchesVariantFilter(fm.variants || fm.variantId, undefined, funcObj.variants || structNode.variantId)) return;

        const effMap = ctx.failureModeEffects || {};
        const linkedEffIds = effMap[fm.id] || [];
        const linkedEffects = (fmeaData.libraries && fmeaData.libraries.effects || []).filter(e => linkedEffIds.includes(e.id));
        const maxSeverity = linkedEffects.reduce((max, e) => Math.max(max, parseInt(e.severity) || 1), 1);
        const effectsTextPlain = linkedEffects.length > 0 ? linkedEffects.map(e => `${e.desc} (S:${e.severity})`).join('; ') : '-';

        const causeMap = ctx.failureModeCauses || {};
        const linkedCauseIds = causeMap[fm.id] || [];
        const linkedCauses = (fmeaData.libraries && fmeaData.libraries.causes || []).filter(c => linkedCauseIds.includes(c.id) && (!applyVariantFilter || matchesVariantFilter(c.variants || c.variantId, undefined, fm.variants || funcObj.variants || structNode.variantId)));

        if (linkedCauses.length === 0) {
          rows.push({
            struct: structName,
            func: funcObj.name,
            req: reqTextPlain,
            fm: fm.name,
            fe: effectsTextPlain,
            s: String(maxSeverity),
            fc: '-',
            char: '-',
            class: '-',
            var: 'ALL',
            prev: '-',
            o: '1',
            detctrl: '-',
            d: '1',
            rpn: isVDA ? 'Low (L)' : String(maxSeverity),
            act: '-',
            pd: '-',
            resp: '-',
            date: '-',
            status: '-',
            taken: '-',
            s2: '-',
            o2: '-',
            d2: '-',
            rpn2: '-',
            comments: fm.comments || '-'
          });
          return;
        }

        linkedCauses.forEach(cause => {
          const causeVarNames = getVariantNamesDisplay(cause.variants);
          const ctrlIds = (fmeaData.causeControls || {})[cause.id] || [];
          const linkedCtrls = (fmeaData.libraries && fmeaData.libraries.controls || []).filter(c => ctrlIds.includes(c.id));
          const prevCtrls = linkedCtrls.filter(c => c.type === 'Prevention');
          const detCtrls = linkedCtrls.filter(c => c.type === 'Detection');

          const prevCtrlStrPlain = prevCtrls.map(c => c.desc).join('; ') || '-';
          const detCtrlStrPlain = detCtrls.map(c => c.desc).join('; ') || '-';

          const causeClassSym = cause.classSymbol || cause.class || (typeof getHighestClassSymbolForCause === 'function' ? getHighestClassSymbolForCause(cause) : '');
          const classW = typeof getClassWeight === 'function' ? getClassWeight(causeClassSym) : 0;
          const effSev = Math.max(maxSeverity, classW);
          const occ = parseInt(cause.occurrence) || 1;
          const det = parseInt(cause.detection) || 1;
          const rpn = effSev * occ * det;
          const ap = calculateAIAGVDA_AP(effSev, occ, det, causeClassSym);
          const evalDisp = isVDA ? (ap === 'H' ? 'High (H)' : (ap === 'M' ? 'Med (M)' : 'Low (L)')) : String(rpn);

          const actIds = (ctx.causeActions || {})[cause.id] || [];
          const linkedActions = (fmeaData.libraries && fmeaData.libraries.actions || []).filter(a => actIds.includes(a.id));

          if (linkedActions.length === 0) {
            rows.push({
              struct: structName,
              func: funcObj.name,
              req: reqTextPlain,
              fm: fm.name,
              fe: effectsTextPlain,
              s: String(maxSeverity),
              fc: cause.details,
              char: cause.characteristics || '-',
              class: cause.classSymbol || '-',
              var: causeVarNames,
              prev: prevCtrlStrPlain,
              o: String(occ),
              detctrl: detCtrlStrPlain,
              d: String(det),
              rpn: evalDisp,
              act: '-',
              pd: '-',
              resp: '-',
              date: '-',
              status: '-',
              taken: '-',
              s2: '-',
              o2: '-',
              d2: '-',
              rpn2: '-',
              comments: cause.comments || fm.comments || '-'
            });
          } else {
            linkedActions.forEach(act => {
              const s2 = parseInt(cause.s2) || maxSeverity;
              const o2 = parseInt(cause.o2) || occ;
              const d2 = parseInt(cause.d2) || det;
              const rpn2 = act.detail ? (s2 * o2 * d2) : '-';
              const ap2 = act.detail ? calculateAIAGVDA_AP(s2, o2, d2) : '-';
              const evalDisp2 = act.detail ? (isVDA ? (ap2 === 'H' ? 'High (H)' : (ap2 === 'M' ? 'Med (M)' : 'Low (L)')) : String(rpn2)) : '-';

              rows.push({
                struct: structName,
                func: funcObj.name,
                req: reqTextPlain,
                fm: fm.name,
                fe: effectsTextPlain,
                s: String(maxSeverity),
                fc: cause.details,
                char: cause.characteristics || '-',
                class: cause.classSymbol || '-',
                var: causeVarNames,
                prev: prevCtrlStrPlain,
                o: String(occ),
                detctrl: detCtrlStrPlain,
                d: String(det),
                rpn: evalDisp,
                act: act.detail || '-',
                pd: act.pd || '-',
                resp: act.responsible || '-',
                date: act.targetDate || '-',
                status: act.status || (act.completionDate ? 'Completed' : (act.targetDate ? 'In Progress' : 'Planned')),
                taken: (act.actionTaken || '-') + (act.completionDate ? ` (${act.completionDate})` : ''),
                s2: act.detail ? String(s2) : '-',
                o2: act.detail ? String(o2) : '-',
                d2: act.detail ? String(d2) : '-',
                rpn2: evalDisp2,
                comments: cause.comments || fm.comments || '-'
              });
            });
          }
        });
      });
    });
  });

  return rows;
}

let _cachedFmeaRowContexts = null;
let _cachedFmeaUniqueColValues = new Map();

/**
 * Invalidates the cached row contexts and unique column filter values.
 * Called whenever FMEA data or active structure selection changes.
 */
function invalidateFmeaFilterCache() {
  _cachedFmeaRowContexts = null;
  _cachedFmeaUniqueColValues.clear();
}
window.invalidateFmeaFilterCache = invalidateFmeaFilterCache;

function getOpenTableFmeaRowContexts(forceRefresh = false) {
  if (!forceRefresh && _cachedFmeaRowContexts) {
    return _cachedFmeaRowContexts;
  }
  const ctx = getActiveFmeaData();
  const targetStructId = viewCompleteFmeaMode ? null : (selectedStructureId || null);
  _cachedFmeaRowContexts = buildRowContextsForContext(ctx, targetStructId, true);
  _cachedFmeaUniqueColValues.clear();
  return _cachedFmeaRowContexts;
}

function getAllFmeaRowContexts(forceRefresh = false) {
  return getOpenTableFmeaRowContexts(forceRefresh);
}

function getUniqueValuesForColumn(colKey, forceRefresh = false) {
  if (!forceRefresh && _cachedFmeaUniqueColValues.has(colKey)) {
    return _cachedFmeaUniqueColValues.get(colKey);
  }
  const rows = getAllFmeaRowContexts(forceRefresh);
  const set = new Set();
  rows.forEach(r => {
    const val = String(r[colKey] !== undefined && r[colKey] !== null ? r[colKey] : '-').trim();
    if (val) set.add(val);
  });
  const arr = Array.from(set);
  arr.sort((a, b) => {
    const numA = Number(a), numB = Number(b);
    if (!isNaN(numA) && !isNaN(numB)) return numA - numB;
    return a.localeCompare(b);
  });
  _cachedFmeaUniqueColValues.set(colKey, arr);
  return arr;
}

function isRowMatchingHeaderFilters(rowCtx) {
  if (!headerColumnFilters) return true;
  for (const [colKey, set] of Object.entries(headerColumnFilters)) {
    if (!set) continue;
    const val = String(rowCtx[colKey] !== undefined && rowCtx[colKey] !== null ? rowCtx[colKey] : '-').trim();
    if (!set.has(val)) {
      return false;
    }
  }
  return true;
}

function getFilterMapForContext(context) {
  if (context === 'dvp') return dvpColumnFilters;
  if (context === 'charspec') return charSpecColumnFilters;
  if (context === 'charlinkage') return charLinkageColumnFilters;
  return headerColumnFilters;
}

function getColumnTitleForContext(context, colKey) {
  if (context === 'dvp') {
    const titles = {
      itemType: 'Item Type',
      pd: 'P&D',
      desc: 'Control / Action Description',
      responsible: 'Responsible Person',
      targetDate: 'Target Date',
      completionDate: 'Completion Date',
      status: 'Status',
      remark: 'Action Taken / Remarks'
    };
    return titles[colKey] || colKey;
  }
  if (context === 'charspec') {
    const titles = {
      sysCharNo: 'System No. (Auto)',
      charNo: 'Char No. (Unique)',
      text: 'Characteristic Description & Linked Cause',
      spec: 'Engineering Specification / Criteria',
      element: 'Linked System Element / Process Step',
      variants: 'Assigned Variants',
      module: 'Module'
    };
    return titles[colKey] || colKey;
  }
  if (context === 'charlinkage') {
    const titles = {
      partNo: 'Part No',
      type: 'Item Type (Char / Req)',
      charNo: 'Char No (Unique)',
      desc: 'Product / Transient Characteristic',
      spec: 'Engineering Specification',
      classification: 'Special Class',
      drawingNo: 'Drawing No',
      inCp: 'In Control Plan?',
      opNo: 'Process Op No',
      processName: 'Process Name',
      procCharNo: 'Process Char No',
      procDesc: 'Process Control / Parameter',
      procSpec: 'Process Specification',
      procClass: 'Process Class',
      status: 'Linkage Status'
    };
    return titles[colKey] || colKey;
  }
  return getColumnTitle(colKey);
}

function getUniqueValuesForContext(context, colKey) {
  if (context === 'dvp') {
    return getUniqueValuesForDvpColumn(colKey);
  }
  if (context === 'charspec') {
    return getUniqueValuesForCharSpecColumn(colKey);
  }
  if (context === 'charlinkage') {
    return getUniqueValuesForCharLinkageColumn(colKey);
  }
  return getUniqueValuesForColumn(colKey);
}

function getUniqueValuesForDvpColumn(colKey) {
  const selectedScopeVals = getSelectedScopeValues('dvpScopeMultiSelectContainer');
  const targetScopes = resolveSelectedScopes(selectedScopeVals);
  const variantFilter = document.getElementById('dvpFilterVariant')?.value || 'ALL';
  const searchText = (document.getElementById('dvpSearchInput')?.value || '').toLowerCase().trim();

  let items = getDvpItemsList(targetScopes);
  if (variantFilter !== 'ALL') {
    items = items.filter(item => {
      const vars = Array.isArray(item.variants) ? item.variants : [item.variants];
      return vars.includes('ALL') || vars.includes(variantFilter);
    });
  }
  if (searchText) {
    items = items.filter(i =>
      (i.desc && i.desc.toLowerCase().includes(searchText)) ||
      (i.responsible && i.responsible.toLowerCase().includes(searchText)) ||
      (i.context && i.context.toLowerCase().includes(searchText)) ||
      (i.remark && i.remark.toLowerCase().includes(searchText))
    );
  }

  const values = new Set();
  items.forEach(item => {
    let val = '';
    if (colKey === 'itemType') val = item.itemType || item.category || '-';
    else if (colKey === 'pd') val = item.pd || '-';
    else if (colKey === 'desc') val = item.desc || '-';
    else if (colKey === 'responsible') val = item.responsible || '-';
    else if (colKey === 'targetDate') val = item.targetDate || '-';
    else if (colKey === 'completionDate') val = item.completionDate || '-';
    else if (colKey === 'status') val = item.status || '-';
    else if (colKey === 'remark') val = item.remark || '-';

    if (val !== undefined && val !== null && String(val).trim() !== '') {
      values.add(String(val).trim());
    }
  });

  return Array.from(values).sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));
}

function getUniqueValuesForCharSpecColumn(colKey) {
  const items = (typeof getExtractedCharacteristicsData === 'function') ? getExtractedCharacteristicsData({ ignoreColumnFilters: true }) : [];
  const values = new Set();
  items.forEach(item => {
    let val = '';
    if (colKey === 'sysCharNo') val = item.sysCharNo || '-';
    else if (colKey === 'charNo') val = item.charNo || item.num || '-';
    else if (colKey === 'text') val = item.text || '-';
    else if (colKey === 'spec') val = item.spec || '-';
    else if (colKey === 'element') val = item.element || '-';
    else if (colKey === 'variants') val = item.variants || 'ALL';
    else if (colKey === 'module') val = item.module || '-';

    if (val !== undefined && val !== null && String(val).trim() !== '') {
      values.add(String(val).trim());
    }
  });

  return Array.from(values).sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));
}

function getUniqueValuesForCharLinkageColumn(colKey) {
  const elementId = window.selectedCharLinkageElementId;
  if (!elementId || !fmeaData) return [];
  const activeOpId = window.selectedCharLinkageOpId || 'ALL';
  const sourceMode = window.activeCharLinkageSource || 'characteristics';
  const items = typeof getLinkageSourceItemsForElement === 'function' ? getLinkageSourceItemsForElement(elementId, activeOpId, sourceMode) : [];

  const values = new Set();

  items.forEach(ch => {
    let links = (fmeaData.characteristicLinkages && fmeaData.characteristicLinkages[ch.id]) || [];
    if (activeOpId !== 'ALL') {
      links = links.filter(l => l.opId === activeOpId);
    }
    const isLinked = links.length > 0;
    const isCp = (typeof ch.inControlPlan === 'boolean' && ch.inControlPlan) || (fmeaData.characteristicInControlPlan && fmeaData.characteristicInControlPlan[ch.id]) || links.some(l => l.inControlPlan);

    if (colKey === 'partNo') {
      if (ch.partNo) values.add(String(ch.partNo).trim());
    } else if (colKey === 'type') {
      const t = ch.sourceType === 'CHARACTERISTIC' ? 'Char' : (ch.sourceType === 'REQUIREMENT' ? 'Req' : (ch.sourceType || 'Char'));
      values.add(t);
    } else if (colKey === 'charNo') {
      if (ch.charNo) values.add(String(ch.charNo).trim());
    } else if (colKey === 'desc') {
      if (ch.desc) values.add(String(ch.desc).trim());
    } else if (colKey === 'spec') {
      if (ch.spec) values.add(String(ch.spec).trim());
    } else if (colKey === 'classification') {
      values.add(ch.classification || 'None');
    } else if (colKey === 'drawingNo') {
      if (ch.drawingNo) values.add(String(ch.drawingNo).trim());
    } else if (colKey === 'inCp') {
      values.add(isCp ? 'Yes' : 'No');
    } else if (colKey === 'opNo') {
      if (isLinked) {
        links.forEach(l => { if (l.opNo) values.add(String(l.opNo).trim()); });
      }
    } else if (colKey === 'processName') {
      if (isLinked) {
        links.forEach(l => { if (l.processName) values.add(String(l.processName).trim()); });
      }
    } else if (colKey === 'procCharNo') {
      if (isLinked) {
        links.forEach(l => {
          const num = l.procCharNo || l.procCharId;
          if (num) values.add(String(num).trim());
        });
      }
    } else if (colKey === 'procDesc') {
      if (isLinked) {
        links.forEach(l => { if (l.procDesc) values.add(String(l.procDesc).trim()); });
      }
    } else if (colKey === 'procSpec') {
      if (isLinked) {
        links.forEach(l => { if (l.procSpec) values.add(String(l.procSpec).trim()); });
      }
    } else if (colKey === 'procClass') {
      if (isLinked) {
        links.forEach(l => {
          const eff = typeof getEffectiveProcessCharClass === 'function' ? getEffectiveProcessCharClass(l.procCharId || l.id, l.opId || activeOpId) : { effectiveClass: l.procClass };
          const pClass = eff.effectiveClass || l.procClass || 'None';
          values.add(pClass);
        });
      }
    } else if (colKey === 'status') {
      if (!isLinked) {
        values.add('⚠️ Gaps');
      } else {
        values.add('✅ Linked');
      }
      if (ch.nature === 'PFMEA_TRANSIENT' || links.some(l => l.nature === 'PFMEA_TRANSIENT')) {
        values.add('⚡ Transient');
      }
    }
  });

  return Array.from(values).sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));
}

function openGenericHeaderFilterMenu(event, context, colKey) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }

  activeFilterContext = context || 'fmea';
  currentFilterMenuKey = colKey;
  const uniqueVals = getUniqueValuesForContext(activeFilterContext, colKey);
  const activeMap = getFilterMapForContext(activeFilterContext);

  if (activeMap[colKey]) {
    tempHeaderFilterSelection = new Set(activeMap[colKey]);
  } else {
    tempHeaderFilterSelection = new Set(uniqueVals);
  }

  let menu = document.getElementById('fmeaHeaderFilterPopup');
  if (!menu) {
    menu = document.createElement('div');
    menu.id = 'fmeaHeaderFilterPopup';
    menu.className = 'fmea-header-filter-popup';
    document.body.appendChild(menu);
  }

  const rect = event.currentTarget.getBoundingClientRect();
  menu.style.top = (rect.bottom + window.scrollY + 4) + 'px';
  menu.style.left = Math.max(10, Math.min(rect.left + window.scrollX, window.innerWidth - 305)) + 'px';
  menu.style.display = 'block';

  renderHeaderFilterMenuContent(colKey, uniqueVals, '');
}

function openHeaderFilterMenu(event, colKey) {
  openGenericHeaderFilterMenu(event, 'fmea', colKey);
}

function openDvpHeaderFilterMenu(event, colKey) {
  openGenericHeaderFilterMenu(event, 'dvp', colKey);
}

function openCharSpecHeaderFilterMenu(event, colKey) {
  openGenericHeaderFilterMenu(event, 'charspec', colKey);
}

function openCharLinkageHeaderFilterMenu(event, colKey) {
  openGenericHeaderFilterMenu(event, 'charlinkage', colKey);
}

function renderHeaderFilterMenuContent(colKey, uniqueVals, searchQuery = '') {
  const menu = document.getElementById('fmeaHeaderFilterPopup');
  if (!menu) return;

  const currentSelection = tempHeaderFilterSelection || new Set(uniqueVals);
  const q = (searchQuery || '').toLowerCase().trim();

  const visibleVals = uniqueVals.filter(v => !q || String(v).toLowerCase().includes(q));
  const totalSelectedCount = currentSelection.size;
  const totalValsCount = uniqueVals.length;
  const titleStr = getColumnTitleForContext(activeFilterContext, colKey);

  let html = `
    <div style="padding:12px; background:var(--bg-card, #1e293b); border:1px solid var(--border-color, #334155); border-radius:8px; box-shadow:0 10px 25px rgba(0,0,0,0.5); width:290px; font-family:sans-serif; z-index:99999; color:var(--text-primary, #f8fafc);">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; border-bottom:1px solid var(--border-color, #334155); padding-bottom:6px;">
        <div style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:240px;">
          <strong style="font-size:12px; color:var(--text-primary, #f8fafc);" title="${escapeHtml(titleStr)}">Filter: ${escapeHtml(titleStr)}</strong>
        </div>
        <span style="cursor:pointer; font-weight:bold; font-size:14px; color:var(--text-muted, #94a3b8); line-height:1;" onclick="closeHeaderFilterMenu()">&times;</span>
      </div>

      <div style="margin-bottom:8px; position:relative;">
        <input type="text" id="colFilterSearchInput" placeholder="🔍 Search values..." value="${escapeHtml(searchQuery)}" oninput="handleColFilterSearch(this.value, event)" style="width:100%; padding:6px 24px 6px 10px; font-size:11px; background:var(--bg-card, #0f172a); color:var(--text-primary, #f8fafc); border:1px solid var(--border-color, #334155); border-radius:4px; box-sizing:border-box;">
        ${searchQuery ? `<span style="position:absolute; right:8px; top:6px; cursor:pointer; color:var(--text-muted, #94a3b8); font-weight:bold; font-size:12px;" onclick="handleColFilterSearch('', event)" title="Clear search">&times;</span>` : ''}
      </div>

      <div style="display:flex; gap:4px; margin-bottom:8px;">
        <button type="button" class="btn btn-xs" style="flex:1; font-size:10px; font-weight:600; padding:5px 4px; background:var(--bg-card, #0f172a); color:var(--text-primary, #f8fafc); border:1px solid var(--border-color, #334155); border-radius:4px; cursor:pointer;" onclick="colFilterSelectAll(event)" title="Check all visible values and remember">All</button>
        <button type="button" class="btn btn-xs" style="flex:1; font-size:10px; font-weight:600; padding:5px 4px; background:var(--bg-card, #0f172a); color:var(--text-primary, #f8fafc); border:1px solid var(--border-color, #334155); border-radius:4px; cursor:pointer;" onclick="colFilterSelectChecked(event)" title="Keep checked values">Checked</button>
        <button type="button" class="btn btn-xs" style="flex:1; font-size:10px; font-weight:600; padding:5px 4px; background:var(--bg-card, #0f172a); color:var(--text-primary, #f8fafc); border:1px solid var(--border-color, #334155); border-radius:4px; cursor:pointer;" onclick="colFilterSelectNonChecked(event)" title="Invert visible selection">Non-Checked</button>
        <button type="button" class="btn btn-xs" style="flex:1; font-size:10px; font-weight:600; padding:5px 4px; background:var(--bg-card, #0f172a); color:var(--text-primary, #f8fafc); border:1px solid var(--border-color, #334155); border-radius:4px; cursor:pointer;" onclick="colFilterClear(event)" title="Uncheck visible values">Clear</button>
      </div>

      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px; font-size:10px; color:var(--text-muted, #94a3b8);">
        <span>Showing: ${visibleVals.length} of ${totalValsCount}</span>
        <span>Selected: ${totalSelectedCount}</span>
      </div>

      <div style="max-height:180px; overflow-y:auto; border:1px solid var(--border-color, #334155); border-radius:4px; padding:4px; margin-bottom:10px; background:var(--bg-card, #0f172a);">
  `;

  if (visibleVals.length === 0) {
    html += `<div style="font-size:11px; color:var(--text-muted, #94a3b8); text-align:center; padding:12px;">No matching values found</div>`;
  } else {
    visibleVals.forEach(val => {
      const checked = currentSelection.has(val) ? 'checked' : '';
      html += `
        <label style="display:flex; align-items:center; gap:6px; font-size:11px; color:var(--text-primary, #f8fafc); padding:4px 6px; border-radius:3px; cursor:pointer; user-select:none; word-break:break-word;" onmouseover="this.style.background='rgba(56, 189, 248, 0.15)'" onmouseout="this.style.background='transparent'">
          <input type="checkbox" class="col-filter-chk" value="${escapeHtml(val)}" ${checked} onchange="toggleColFilterValue('${escapeHtml(val)}', this.checked)">
          <span>${escapeHtml(val)}</span>
        </label>
      `;
    });
  }

  html += `
      </div>

      <div style="display:flex; justify-content:space-between; align-items:center; gap:6px;">
        <button type="button" class="btn btn-xs" onclick="resetSingleHeaderFilter('${colKey}')" style="font-size:10px; font-weight:600; padding:5px 10px; background:var(--bg-card, #0f172a); color:var(--text-primary, #f8fafc); border:1px solid var(--border-color, #334155); border-radius:4px; cursor:pointer;">Reset Column</button>
        <div style="display:flex; gap:4px;">
          <button type="button" class="btn btn-xs" onclick="applyHeaderFilter()" style="font-size:10px; font-weight:700; padding:5px 14px; background:#0284c7; color:#ffffff; border:none; border-radius:4px; cursor:pointer;">Apply</button>
        </div>
      </div>
    </div>
  `;

  menu.innerHTML = html;

  const searchEl = document.getElementById('colFilterSearchInput');
  if (searchEl && document.activeElement !== searchEl) {
    searchEl.focus();
    searchEl.setSelectionRange(searchEl.value.length, searchEl.value.length);
  }
}

function toggleFilterIncludeAllTree(checked) {
  filterIncludeAllTreeElements = checked;
  if (!currentFilterMenuKey) return;
  const uniqueVals = getUniqueValuesForContext(activeFilterContext, currentFilterMenuKey);
  const activeMap = getFilterMapForContext(activeFilterContext);
  if (!activeMap[currentFilterMenuKey]) {
    tempHeaderFilterSelection = new Set(uniqueVals);
  }
  const searchEl = document.getElementById('colFilterSearchInput');
  renderHeaderFilterMenuContent(currentFilterMenuKey, uniqueVals, searchEl ? searchEl.value : '');
}

function handleColFilterSearch(query, event) {
  if (event) {
    event.stopPropagation();
  }
  if (!currentFilterMenuKey) return;
  const uniqueVals = getUniqueValuesForContext(activeFilterContext, currentFilterMenuKey);
  renderHeaderFilterMenuContent(currentFilterMenuKey, uniqueVals, query);
}

function toggleColFilterValue(val, isChecked) {
  if (!currentFilterMenuKey) return;
  if (!tempHeaderFilterSelection) {
    const all = getUniqueValuesForContext(activeFilterContext, currentFilterMenuKey);
    tempHeaderFilterSelection = new Set(all);
  }
  if (isChecked) {
    tempHeaderFilterSelection.add(val);
  } else {
    tempHeaderFilterSelection.delete(val);
  }
}

function colFilterSelectAll(event) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  if (!currentFilterMenuKey) return;
  const uniqueVals = getUniqueValuesForContext(activeFilterContext, currentFilterMenuKey);
  const searchEl = document.getElementById('colFilterSearchInput');
  const q = (searchEl ? searchEl.value : '').toLowerCase().trim();

  if (!tempHeaderFilterSelection) {
    tempHeaderFilterSelection = new Set();
  }

  uniqueVals.forEach(v => {
    if (!q || String(v).toLowerCase().includes(q)) {
      tempHeaderFilterSelection.add(v);
    }
  });

  renderHeaderFilterMenuContent(currentFilterMenuKey, uniqueVals, searchEl ? searchEl.value : '');
}

function colFilterSelectChecked(event) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  if (!currentFilterMenuKey) return;
  const uniqueVals = getUniqueValuesForContext(activeFilterContext, currentFilterMenuKey);
  const searchEl = document.getElementById('colFilterSearchInput');
  if (!tempHeaderFilterSelection || tempHeaderFilterSelection.size === 0) {
    tempHeaderFilterSelection = new Set(uniqueVals);
  }
  renderHeaderFilterMenuContent(currentFilterMenuKey, uniqueVals, searchEl ? searchEl.value : '');
}

function colFilterSelectNonChecked(event) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  if (!currentFilterMenuKey) return;
  const uniqueVals = getUniqueValuesForContext(activeFilterContext, currentFilterMenuKey);
  const searchEl = document.getElementById('colFilterSearchInput');
  const q = (searchEl ? searchEl.value : '').toLowerCase().trim();

  if (!tempHeaderFilterSelection) {
    tempHeaderFilterSelection = new Set(uniqueVals);
  }

  uniqueVals.forEach(v => {
    if (!q || String(v).toLowerCase().includes(q)) {
      if (tempHeaderFilterSelection.has(v)) {
        tempHeaderFilterSelection.delete(v);
      } else {
        tempHeaderFilterSelection.add(v);
      }
    }
  });

  renderHeaderFilterMenuContent(currentFilterMenuKey, uniqueVals, searchEl ? searchEl.value : '');
}

function colFilterInvert(event) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  colFilterSelectNonChecked(event);
}

function colFilterClear(event) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  if (!currentFilterMenuKey) return;
  const uniqueVals = getUniqueValuesForContext(activeFilterContext, currentFilterMenuKey);
  const searchEl = document.getElementById('colFilterSearchInput');
  const q = (searchEl ? searchEl.value : '').toLowerCase().trim();

  if (!tempHeaderFilterSelection) {
    tempHeaderFilterSelection = new Set(uniqueVals);
  }

  if (q) {
    uniqueVals.forEach(v => {
      if (String(v).toLowerCase().includes(q)) {
        tempHeaderFilterSelection.delete(v);
      }
    });
  } else {
    tempHeaderFilterSelection.clear();
  }

  renderHeaderFilterMenuContent(currentFilterMenuKey, uniqueVals, searchEl ? searchEl.value : '');
}

function applyHeaderFilter() {
  if (currentFilterMenuKey && tempHeaderFilterSelection) {
    const allVals = getUniqueValuesForContext(activeFilterContext, currentFilterMenuKey);
    const activeMap = getFilterMapForContext(activeFilterContext);
    if (tempHeaderFilterSelection.size >= allVals.length) {
      delete activeMap[currentFilterMenuKey];
    } else {
      activeMap[currentFilterMenuKey] = new Set(tempHeaderFilterSelection);
    }
  }
  const ctx = activeFilterContext;
  closeHeaderFilterMenu();

  if (ctx === 'dvp') {
    renderDvpTable();
  } else if (ctx === 'charspec') {
    renderCharacteristicsSpecsTable();
  } else if (ctx === 'charlinkage') {
    renderCharacteristicsLinkageMatrix();
  } else {
    renderFMEATable();
    const chkModal = document.getElementById('outputChecklistVerificationModal');
    if (chkModal && chkModal.style.display !== 'none' && typeof refreshChecklistReportPreview === 'function') {
      refreshChecklistReportPreview();
    }
  }
}

function closeHeaderFilterMenu() {
  const menu = document.getElementById('fmeaHeaderFilterPopup');
  if (menu) menu.style.display = 'none';
  currentFilterMenuKey = null;
  tempHeaderFilterSelection = null;
}

function resetSingleHeaderFilter(colKey) {
  const activeMap = getFilterMapForContext(activeFilterContext);
  delete activeMap[colKey];
  const ctx = activeFilterContext;
  closeHeaderFilterMenu();

  if (ctx === 'dvp') {
    renderDvpTable();
  } else if (ctx === 'charspec') {
    renderCharacteristicsSpecsTable();
  } else if (ctx === 'charlinkage') {
    renderCharacteristicsLinkageMatrix();
  } else {
    renderFMEATable();
    const chkModal = document.getElementById('outputChecklistVerificationModal');
    if (chkModal && chkModal.style.display !== 'none' && typeof refreshChecklistReportPreview === 'function') {
      refreshChecklistReportPreview();
    }
  }
}

function clearAllHeaderFilters() {
  headerColumnFilters = {};
  closeHeaderFilterMenu();
  renderFMEATable();
  const chkModal = document.getElementById('outputChecklistVerificationModal');
  if (chkModal && chkModal.style.display !== 'none' && typeof refreshChecklistReportPreview === 'function') {
    refreshChecklistReportPreview();
  }
  showToast('All column header filters cleared.');
}

function resetDvpHeaderFilters() {
  dvpColumnFilters = {};
  closeHeaderFilterMenu();
  const searchInput = document.getElementById('dvpSearchInput');
  if (searchInput) searchInput.value = '';
  const variantSelect = document.getElementById('dvpFilterVariant');
  if (variantSelect) variantSelect.value = 'ALL';
  renderDvpTable();
  showToast('All DVP column filters reset.');
}

function resetCharacteristicsSpecsFilters() {
  charSpecColumnFilters = {};
  closeHeaderFilterMenu();
  const searchInput = document.getElementById('charSpecSearchInput');
  if (searchInput) searchInput.value = '';
  const scopeFilter = document.getElementById('charSpecScopeFilter');
  if (scopeFilter) scopeFilter.value = 'ALL';
  const variantFilter = document.getElementById('charSpecVariantFilter');
  if (variantFilter) variantFilter.value = 'ALL';
  const classFilter = document.getElementById('charSpecClassFilter');
  if (classFilter) classFilter.value = 'ALL';
  renderCharacteristicsSpecsTable();
  showToast('Characteristics filters reset.');
}

function resetCharacteristicsLinkageFilters() {
  charLinkageColumnFilters = {};
  closeHeaderFilterMenu();
  renderCharacteristicsLinkageMatrix();
  showToast('All Characteristics Linkage filters reset.');
}
window.resetCharacteristicsLinkageFilters = resetCharacteristicsLinkageFilters;
window.resetCharMatrixFilters = resetCharacteristicsLinkageFilters;
window.openCharLinkageHeaderFilterMenu = openCharLinkageHeaderFilterMenu;

function updateHeaderFilterButtonsUI() {
  const allBtns = document.querySelectorAll('#fmeaTable thead .col-filter-btn, #modalPreviewFmeaTable thead .col-filter-btn');
  let activeCount = 0;

  allBtns.forEach(btn => {
    const colKey = btn.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];
    if (!colKey) return;

    const set = headerColumnFilters[colKey];
    const allVals = getUniqueValuesForColumn(colKey);
    const isFiltered = set && set.size < allVals.length;

    if (isFiltered) {
      btn.classList.add('filter-active');
      btn.textContent = '🔵';
      btn.title = `Active Filter (${set.size}/${allVals.length} items selected)`;
      activeCount++;
    } else {
      btn.classList.remove('filter-active');
      btn.textContent = '🔻';
      btn.title = 'Filter Column';
    }
  });

  const clearBtn = document.getElementById('btnClearHeaderFilters');
  if (clearBtn) {
    if (activeCount > 0) {
      clearBtn.style.display = 'inline-flex';
      const countSpan = document.getElementById('activeFilterCount');
      if (countSpan) countSpan.textContent = activeCount;
    } else {
      clearBtn.style.display = 'none';
    }
  }
}

