document.addEventListener('click', function (e) {
  const popup = document.getElementById('fmeaHeaderFilterPopup');
  if (popup && popup.style.display !== 'none') {
    const path = e.composedPath ? e.composedPath() : [];
    const isInsidePopup = path.includes(popup) || popup.contains(e.target) || (e.target && popup.contains(e.target.parentElement));
    if (!isInsidePopup && (!e.target || !e.target.classList || !e.target.classList.contains('col-filter-btn'))) {
      closeHeaderFilterMenu();
    }
  }
});

function formatEffectDetailsFullString(e, currFmId = null) {
  if (!e) return '';
  const parts = [];
  if (e.systemName) parts.push(e.systemName);
  if (e.functionName) parts.push(e.functionName);
  if (e.requirement) parts.push(e.requirement);
  const effSevInfo = (typeof getEffectiveSeverityForEffect === 'function')
    ? getEffectiveSeverityForEffect(e, currFmId)
    : { displayText: String(e.severity || 1) };
  parts.push(`${e.desc || ''} (S:${effSevInfo.displayText})`);
  return parts.join('\n');
}

function formatCauseDetailsFullString(cause) {
  if (!cause) return '';
  const parts = [];
  if (cause.systemElement) parts.push(cause.systemElement);
  if (cause.function) parts.push(cause.function);
  if (cause.requirement) parts.push(cause.requirement);
  parts.push(cause.details || '');
  return parts.join('\n');
}

function buildColoredHierarchyTag(system, func, req) {
  const lines = [];
  if (system && system.trim() && system.trim() !== '-- Optional / None --' && !system.includes('Optional / None') && system.trim() !== 'Main Effect Node') {
    lines.push(`<div style="color:#0284c7 !important; font-weight:700; font-size:11.5px; margin-bottom:2px; text-align:left; -webkit-print-color-adjust:exact;" title="System Element">${escapeHtml(system)}</div>`);
  }
  if (func && func.trim() && !func.trim().startsWith('--') && !func.includes('Optional / None')) {
    lines.push(`<div style="color:#7c3aed !important; font-weight:700; font-size:11.5px; margin-bottom:2px; text-align:left; -webkit-print-color-adjust:exact;" title="Function">${escapeHtml(func)}</div>`);
  }
  if (req && req.trim()) {
    lines.push(`<div style="color:#d97706 !important; font-weight:700; font-size:11.5px; margin-bottom:2px; text-align:left; -webkit-print-color-adjust:exact;" title="Requirement">${escapeHtml(req)}</div>`);
  }
  if (lines.length === 0) return '';
  return lines.join('');
}

function formatRPNBadgeHTML(s, occ, det, isVDA) {
  const sNum = parseInt(s) || 1;
  const oNum = parseInt(occ) || 1;
  const dNum = parseInt(det) || 1;
  const rpnVal = sNum * oNum * dNum;

  if (isVDA) {
    const rawAp = typeof evalRiskCategory === 'function' ? evalRiskCategory(sNum, rpnVal, 100, 50, 40) : (sNum >= 9 || rpnVal >= 100 ? 'H' : (sNum >= 7 || rpnVal >= 50 ? 'M' : 'L'));
    const apVal = (rawAp === 'H' ? 'High (H)' : (rawAp === 'M' ? 'Medium (M)' : (rawAp === 'L' ? 'Low (L)' : String(rawAp))));
    let bg = '#dcfce7', color = '#166534', border = '#86efac';
    if (apVal.startsWith('High') || apVal.includes('(H)') || rawAp === 'H') {
      bg = '#fee2e2'; color = '#991b1b'; border = '#f87171';
    } else if (apVal.startsWith('Medium') || apVal.includes('(M)') || rawAp === 'M') {
      bg = '#fef3c7'; color = '#92400e'; border = '#fbbf24';
    }
    return `<span style="background:${bg} !important; color:${color} !important; border:1px solid ${border} !important; font-weight:bold; padding:2px 5px; border-radius:4px; font-size:10px; display:inline-block; -webkit-print-color-adjust:exact;">${apVal}</span>`;
  } else {
    const risk = typeof getAIAGRiskClassification === 'function' ? getAIAGRiskClassification(sNum, rpnVal) : { bg: '#dcfce7', text: '#166534', border: '#86efac' };
    return `<span style="background:${risk.bg} !important; color:${risk.text} !important; border:1px solid ${risk.border} !important; font-weight:bold; padding:2px 5px; border-radius:4px; font-size:10px; display:inline-block; -webkit-print-color-adjust:exact;">${rpnVal}</span>`;
  }
}

function renderCauseFormattedCell(cause, idx) {
  if (!cause) return '-';
  const sysTag = buildColoredHierarchyTag(cause.systemElement, cause.function, cause.requirement);
  const numLabel = (typeof idx === 'number') ? `${idx + 1}.` : '1.';
  const descText = cause.details || cause.desc || cause.name || cause.text || '';
  return `<div class="fmea-cause-item" data-cause-id="${cause.id || ''}" data-cause-text="${escapeHtml(descText)}" style="text-align:left; margin-bottom:4px; display:flex;">
    <div style="font-weight:bold; color:var(--text-secondary); font-size:11.5px; margin-bottom:2px;">${numLabel}</div>
    <div style="padding-left:4px;">
      ${sysTag}
      <div style="font-weight:600; color:var(--text-primary); margin-top:2px;">${escapeHtml(descText)}</div>
    </div>
  </div>`;
}

function renderRiskTdHTML(isVDA, maxSeverity, occ, det, rpn, ap, rowspan = 1, extraAttrs = '') {
  if (isVDA) {
    let riskClass = 'rpn-risk-low';
    let text = 'Low (L)';
    if (ap === 'H') { riskClass = 'rpn-risk-high'; text = 'High (H)'; }
    else if (ap === 'M') { riskClass = 'rpn-risk-med'; text = 'Med (M)'; }
    return `<td ${extraAttrs} rowspan="${rowspan}" class="rpn-cell-full ${riskClass}">${text}</td>`;
  } else {
    let riskClass = 'rpn-risk-low';
    const sNum = parseInt(maxSeverity) || 1;
    const numRpn = parseInt(rpn) || (sNum * (parseInt(occ || 1)) * (parseInt(det || 1)));

    if (sNum === 9 || sNum === 10) {
      if (numRpn > 40) riskClass = 'rpn-risk-high';
      else riskClass = 'rpn-risk-low';
    } else {
      if (numRpn > 100) riskClass = 'rpn-risk-high';
      else if (numRpn > 80) riskClass = 'rpn-risk-med';
      else riskClass = 'rpn-risk-low';
    }
    return `<td ${extraAttrs} rowspan="${rowspan}" class="rpn-cell-full ${riskClass}">${numRpn}</td>`;
  }
}

function getRiskRatingStyle(sev, occ, det, isVDA) {
  const s = parseInt(sev) || 1;
  const o = parseInt(occ) || 1;
  const d = parseInt(det) || 1;
  if (isVDA) {
    const ap = typeof calculateAIAGVDA_AP === 'function' ? calculateAIAGVDA_AP(s, o, d) : 'L';
    if (ap === 'H') return 'background-color:#ef4444 !important; color:#ffffff !important; font-weight:800 !important;';
    if (ap === 'M') return 'background-color:#f59e0b !important; color:#0f172a !important; font-weight:800 !important;';
    return 'background-color:#22c55e !important; color:#ffffff !important; font-weight:800 !important;';
  }
  const rpn = s * o * d;
  if (rpn >= 200) return 'background-color:#ef4444 !important; color:#ffffff !important; font-weight:800 !important;';
  if (rpn >= 80) return 'background-color:#f59e0b !important; color:#0f172a !important; font-weight:800 !important;';
  return 'background-color:#22c55e !important; color:#ffffff !important; font-weight:800 !important;';
}

function getSeverityColorStyle(sev) {
  const num = parseInt(sev, 10);
  if (isNaN(num)) return '';
  if (num >= 9) return 'background-color:#ef4444 !important; color:#ffffff !important; font-weight:800 !important;';
  if (num === 7 || num === 8) return 'background-color:#f59e0b !important; color:#0f172a !important; font-weight:800 !important;';
  if (num >= 1 && num <= 6) return 'background-color:#10b981 !important; color:#ffffff !important; font-weight:800 !important;';
  return '';
}

function getOccurrenceColorStyle(occ) {
  return '';
}

function getDetectionColorStyle(det) {
  return '';
}

function getSeverityBadgeHtml(sev) {
  if (sev === null || sev === undefined || sev === '' || sev === '-' || sev === 'null' || sev === '0') return '';
  const num = parseInt(sev, 10);
  if ((isNaN(num) || num <= 0) && !(typeof sev === 'string' && sev.includes('('))) return '';
  let colorStyle = getSeverityColorStyle(sev);
  if (!colorStyle) {
    colorStyle = 'background-color:#10b981 !important; color:#ffffff !important; font-weight:800 !important;';
  }
  const displayText = (typeof sev === 'string' && sev.includes('(')) ? sev : num;
  return `<span class="rating-badge sev-badge-${num}" style="${colorStyle} padding:2px 8px; border-radius:4px; font-weight:800; display:inline-block; font-size:11px; vertical-align:middle; margin-left:4px; box-shadow:0 1px 2px rgba(0,0,0,0.2);">${escapeHtml(String(displayText))}</span>`;
}

window.getRiskRatingStyle = getRiskRatingStyle;
window.getSeverityColorStyle = getSeverityColorStyle;
window.getOccurrenceColorStyle = getOccurrenceColorStyle;
window.getDetectionColorStyle = getDetectionColorStyle;
window.getSeverityBadgeHtml = getSeverityBadgeHtml;


