function openQuickStructureModal(mode, targetId) {
  if (!checkCanEditFMEA()) return;
  const ctx = getActiveFmeaData();
  if (!ctx || !ctx.structure) return;

  const targetNode = getStructureNodeById(ctx.structure, targetId) || (ctx.structure.id === targetId ? ctx.structure : null);
  if (!targetNode && mode !== 'NEXT_LEVEL') {
    showToast("Target element not found.", "warning");
    return;
  }

  const modal = document.getElementById('quickStructureElementModal');
  if (!modal) return;

  const titleEl = document.getElementById('quickStructModalTitle');
  const subtitleEl = document.getElementById('quickStructModalSubtitle');
  const iconEl = document.getElementById('quickStructModalIcon');
  const modeInput = document.getElementById('quickStructMode');
  const targetInput = document.getElementById('quickStructTargetId');
  const partNoInput = document.getElementById('quickStructPartNo');
  const nameInput = document.getElementById('quickStructName');
  const descInput = document.getElementById('quickStructDesc');
  const specsInput = document.getElementById('quickStructSpecs');
  const variantsSelect = document.getElementById('quickStructVariants');
  const classSelect = document.getElementById('quickStructClass');

  if (modeInput) modeInput.value = mode;
  if (targetInput) targetInput.value = targetId || '';

  // Populate variants dropdown
  if (variantsSelect) {
    let variantsList = [{ id: 'ALL', name: 'All Variants' }];
    if (Array.isArray(ctx.variants) && ctx.variants.length > 0) {
      variantsList = [{ id: 'ALL', name: 'All Variants' }, ...ctx.variants];
    } else if (Array.isArray(fmeaData.variants) && fmeaData.variants.length > 0) {
      variantsList = [{ id: 'ALL', name: 'All Variants' }, ...fmeaData.variants];
    }
    variantsSelect.innerHTML = variantsList.map(v => `<option value="${escapeHtml(v.id || v.name)}">${escapeHtml(v.name || v.id)}</option>`).join('');
  }

  if (mode === 'EDIT') {
    if (!targetNode) return;
    if (iconEl) iconEl.textContent = '✏️';
    if (titleEl) titleEl.textContent = 'Edit Element Details';
    if (subtitleEl) subtitleEl.textContent = `Target: ${targetNode.partNo || ''} - ${targetNode.name || ''}`;
    if (partNoInput) partNoInput.value = targetNode.partNo || '';
    if (nameInput) nameInput.value = targetNode.name || '';
    if (descInput) descInput.value = targetNode.description || '';
    if (specsInput) specsInput.value = Array.isArray(targetNode.characteristics) ? targetNode.characteristics.join(', ') : (targetNode.characteristics || targetNode.characteristicsSpec || '');
    if (classSelect) classSelect.value = (Array.isArray(targetNode.classificationIds) && targetNode.classificationIds[0]) || '';
    if (variantsSelect) variantsSelect.value = Array.isArray(targetNode.variantId) ? (targetNode.variantId[0] || 'ALL') : (targetNode.variantId || 'ALL');
  } else if (mode === 'SAME_LEVEL') {
    const parentNode = getParentStructureNode(ctx.structure, targetId);
    if (!parentNode && targetNode && targetNode.id === ctx.structure.id) {
      showToast("Cannot add sibling to the root element. Adding as next level instead.", "info");
      openQuickStructureModal('NEXT_LEVEL', targetId);
      return;
    }
    if (iconEl) iconEl.textContent = '➕';
    if (titleEl) titleEl.textContent = 'Add Element at Same Level';
    if (subtitleEl) subtitleEl.textContent = `Sibling of: ${targetNode ? targetNode.name : 'Selected Element'}`;
    if (partNoInput) partNoInput.value = '';
    if (nameInput) nameInput.value = '';
    if (descInput) descInput.value = '';
    if (specsInput) specsInput.value = '';
    if (classSelect) classSelect.value = '';
    if (variantsSelect) variantsSelect.value = 'ALL';
  } else {
    // NEXT_LEVEL
    if (iconEl) iconEl.textContent = '➕';
    if (titleEl) titleEl.textContent = 'Add Element at Next Level';
    const parentName = targetNode ? `${targetNode.partNo ? targetNode.partNo + ' - ' : ''}${targetNode.name}` : 'Root Element';
    if (subtitleEl) subtitleEl.textContent = `Parent: ${parentName}`;
    if (partNoInput) partNoInput.value = '';
    if (nameInput) nameInput.value = '';
    if (descInput) descInput.value = '';
    if (specsInput) specsInput.value = '';
    if (classSelect) classSelect.value = '';
    if (variantsSelect) variantsSelect.value = 'ALL';
  }

  openModal('quickStructureElementModal');
  setTimeout(() => {
    if (partNoInput) partNoInput.focus();
  }, 100);
}

function saveQuickStructureElement(event) {
  if (event) event.preventDefault();
  if (!checkCanEditFMEA()) return;

  const ctx = getActiveFmeaData();
  if (!ctx || !ctx.structure) return;

  const mode = document.getElementById('quickStructMode')?.value || 'NEXT_LEVEL';
  const targetId = document.getElementById('quickStructTargetId')?.value || ctx.structure.id;
  const partNo = document.getElementById('quickStructPartNo')?.value.trim() || '';
  const name = document.getElementById('quickStructName')?.value.trim() || '';
  const desc = document.getElementById('quickStructDesc')?.value.trim() || '';
  const specsRaw = document.getElementById('quickStructSpecs')?.value.trim() || '';
  const variantVal = document.getElementById('quickStructVariants')?.value || 'ALL';
  const classVal = document.getElementById('quickStructClass')?.value || '';

  if (!partNo || !name) {
    showToast("Please enter both Part No and Element Name.", "warning");
    return;
  }

  const characteristics = specsRaw ? specsRaw.split(',').map(s => s.trim()).filter(Boolean) : [];
  const classificationIds = classVal ? [classVal] : [];

  if (mode === 'EDIT') {
    const node = getStructureNodeById(ctx.structure, targetId) || (ctx.structure.id === targetId ? ctx.structure : null);
    if (!node) {
      showToast("Element to edit not found.", "warning");
      return;
    }
    node.partNo = partNo;
    node.name = name;
    node.description = desc;
    node.characteristics = characteristics;
    node.characteristicsSpec = specsRaw;
    node.classificationIds = classificationIds;
    node.variantId = variantVal;

    // Sync master fmeaData
    if (fmeaData.structure) {
      const masterNode = getStructureNodeById(fmeaData.structure, targetId) || (fmeaData.structure.id === targetId ? fmeaData.structure : null);
      if (masterNode) {
        masterNode.partNo = partNo;
        masterNode.name = name;
        masterNode.description = desc;
        masterNode.characteristics = characteristics;
        masterNode.characteristicsSpec = specsRaw;
        masterNode.classificationIds = classificationIds;
        masterNode.variantId = variantVal;
      }
    }

    markDataChanged('Updated Structure Element Details');
    showToast(`✨ Updated element: ${name}`, 'success');
  } else {
    const newNode = {
      id: (ctx.isPFMEA ? 'pstruct-' : 'struct-') + Date.now(),
      partNo,
      name,
      description: desc,
      variantId: variantVal,
      characteristics,
      characteristicsSpec: specsRaw,
      classificationIds,
      children: []
    };

    if (mode === 'SAME_LEVEL') {
      const parentNode = getParentStructureNode(ctx.structure, targetId);
      if (parentNode) {
        parentNode.children = parentNode.children || [];
        parentNode.children.push(newNode);
      } else {
        ctx.structure.children = ctx.structure.children || [];
        ctx.structure.children.push(newNode);
      }
    } else {
      // NEXT_LEVEL
      let targetParent = getStructureNodeById(ctx.structure, targetId);
      if (!targetParent && ctx.structure.id === targetId) targetParent = ctx.structure;
      if (!targetParent) targetParent = ctx.structure;
      targetParent.children = targetParent.children || [];
      targetParent.children.push(newNode);
    }

    // Also sync fmeaData.structure if different
    if (fmeaData.structure && fmeaData.structure !== ctx.structure) {
      if (mode === 'SAME_LEVEL') {
        const mParent = getParentStructureNode(fmeaData.structure, targetId);
        if (mParent) {
          mParent.children = mParent.children || [];
          mParent.children.push(JSON.parse(JSON.stringify(newNode)));
        }
      } else {
        const mParent = getStructureNodeById(fmeaData.structure, targetId) || fmeaData.structure;
        if (mParent) {
          mParent.children = mParent.children || [];
          mParent.children.push(JSON.parse(JSON.stringify(newNode)));
        }
      }
    }

    markDataChanged('Added Structure Element');
    showToast(`✨ Created element: ${name}`, 'success');
  }

  closeModal('quickStructureElementModal');
  saveProjectToLocalStorage();
  renderTreeSidebar();
  renderFMEATable();
}

window.openQuickStructureModal = openQuickStructureModal;
window.saveQuickStructureElement = saveQuickStructureElement;
window.onContextAddSameLevelClick = onContextAddSameLevelClick;
window.onContextAddNextLevelClick = onContextAddNextLevelClick;
