const OFFICIAL_39_CHECKPOINTS = OFFICIAL_OUTPUT_CHECKPOINTS;

if (typeof window !== 'undefined') {
  window.DEFAULT_INPUT_CHECKLIST = DEFAULT_INPUT_CHECKLIST;
  window.OFFICIAL_OUTPUT_CHECKPOINTS = OFFICIAL_OUTPUT_CHECKPOINTS;
  window.OFFICIAL_39_CHECKPOINTS = OFFICIAL_OUTPUT_CHECKPOINTS;
}

function renderInputChecklistUI(cur) {
  const container = document.getElementById('inputChecklistContainer');
  if (!container) return;
  cur.inputChecklist = cur.inputChecklist || DEFAULT_INPUT_CHECKLIST.map(text => ({ text, checked: false }));

  container.innerHTML = cur.inputChecklist.map((item, idx) => `
    <label class="checkbox-card" style="padding: 6px 10px;">
      <input type="checkbox" onchange="toggleChecklistItem('input', ${idx}, this.checked)" ${item.checked ? 'checked' : ''}>
      ${escapeHtml(item.text)}
    </label>
  `).join('');
}

let _activeChecklistTargetRev = null;

function getActiveChecklistModalRevision() {
  return _activeChecklistTargetRev || getContextRevision();
}

function getRevisionOutputChecklist(cur) {
  if (!cur) return [];
  const isValid = Array.isArray(cur.outputChecklist) &&
    cur.outputChecklist.length === OFFICIAL_OUTPUT_CHECKPOINTS.length &&
    typeof cur.outputChecklist[0]?.id === 'number';

  if (!isValid) {
    const isFrozen = (cur.status === 'Frozen');
    const existingMap = new Map();
    if (Array.isArray(cur.outputChecklist)) {
      cur.outputChecklist.forEach((item, idx) => {
        if (item && typeof item === 'object') {
          existingMap.set(item.id || (idx + 1), item);
        }
      });
    }
    cur.outputChecklist = OFFICIAL_OUTPUT_CHECKPOINTS.map(c => {
      const prev = existingMap.get(c.id);
      return {
        id: c.id,
        text: c.text,
        category: c.category || '',
        checked: prev !== undefined && typeof prev.checked === 'boolean' ? prev.checked : isFrozen,
        comment: (prev && prev.comment) ? prev.comment : ''
      };
    });
  }
  return cur.outputChecklist;
}

function calculateOutputChecklistCompletion(cur) {
  if (!cur) return { completedCount: 0, totalCount: OFFICIAL_OUTPUT_CHECKPOINTS.length, percentage: 0 };
  const items = getRevisionOutputChecklist(cur);
  const totalCount = items.length;
  const completedCount = items.filter(i => i.checked === true).length;
  const percentage = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;
  return { completedCount, totalCount, percentage };
}

function renderOutputChecklistUI(cur) {
  if (!cur) return;
  const { completedCount, totalCount, percentage } = calculateOutputChecklistCompletion(cur);
  const revBadge = document.getElementById('revChecklistCompletionBadge');
  if (revBadge) {
    const bgStyle = percentage === 100 ? 'background:#dcfce7; color:#15803d;' : 'background:#e2e8f0; color:#0f172a;';
    revBadge.innerText = `Completion: ${percentage}% (${completedCount}/${totalCount})`;
    revBadge.style.cssText = `font-size:12px; font-weight:bold; padding:4px 8px; ${bgStyle}`;
  }
}

function runChecklistAutoEvaluation() {
  const cur = getActiveChecklistModalRevision();
  if (!cur) {
    alert("No active revision found to evaluate.");
    return;
  }
  if (cur.status === 'Frozen') {
    alert("This revision is Frozen (Read-Only). Auto-evaluation cannot modify a frozen record.");
    return;
  }

  const items = getRevisionOutputChecklist(cur);
  const activeVariants = (fmeaData.variants && fmeaData.variants.length > 0)
    ? fmeaData.variants.filter(v => v.active !== false)
    : [];
  const varList = activeVariants.length > 0 ? activeVariants : (fmeaData.variants || []);
  const isPFMEA = cur.fmeaType === 'PFMEA' || (fmeaData.projectInfo && fmeaData.projectInfo.fmeaType === 'PFMEA');

  // Gather all causes & failure mode effects
  const allCauses = [];
  const allActions = [];
  const causeActionsMap = fmeaData.causeActions || {};

  if (fmeaData.failureModeCauses) {
    Object.keys(fmeaData.failureModeCauses).forEach(fmId => {
      const causes = fmeaData.failureModeCauses[fmId] || [];
      const effects = (fmeaData.failureModeEffects && fmeaData.failureModeEffects[fmId]) || [];
      const maxSev = effects.reduce((max, eff) => Math.max(max, parseInt(eff.severity) || 0), 0);

      causes.forEach(c => {
        if (!c) return;
        const cId = c.id;
        const pcList = (fmeaData.causeControls && fmeaData.causeControls[cId]?.prevention) || (c.prevention ? [c.prevention] : []);
        const dcList = (fmeaData.causeControls && fmeaData.causeControls[cId]?.detection) || (c.detectionControl ? [c.detectionControl] : []);
        const actIds = causeActionsMap[cId] || [];
        const acts = (fmeaData.actions || []).filter(a => actIds.includes(a.id));

        allCauses.push({
          cause: c,
          fmId: fmId,
          maxSev: maxSev,
          occ: parseInt(c.occurrence) || 0,
          det: parseInt(c.detection) || 0,
          s2: parseInt(c.s2) || 0,
          o2: parseInt(c.o2) || 0,
          d2: parseInt(c.d2) || 0,
          pcList: pcList,
          dcList: dcList,
          actions: acts
        });
        acts.forEach(a => {
          if (!allActions.some(existing => existing.id === a.id)) allActions.push(a);
        });
      });
    });
  }

  let passCount = 0;

  items.forEach(item => {
    let passed = false;
    let comment = '';

    switch (item.id) {
      case 1: { // Customer names across all variants
        if (varList.length > 0) {
          const missing = varList.filter(v => !(v.customer && v.customer.trim()) && !(fmeaData.projectInfo?.customer && fmeaData.projectInfo.customer.trim()));
          if (missing.length === 0) {
            passed = true;
            const names = [...new Set(varList.map(v => (v.customer || fmeaData.projectInfo?.customer || '').trim()).filter(Boolean))];
            comment = `✓ Verified across all ${varList.length} variant(s): "${names.join(', ') || 'OK'}"`;
          } else {
            comment = `⚠️ Missing Customer for variant(s): ${missing.map(v => v.name || v.id).join(', ')}`;
          }
        } else {
          const cust = (fmeaData.projectInfo?.customer || '').trim();
          if (cust) { passed = true; comment = `✓ Customer name: "${cust}"`; }
          else { comment = `⚠️ Customer name is empty in project header`; }
        }
        break;
      }
      case 2: { // Model / application details across all variants
        if (varList.length > 0) {
          const missing = varList.filter(v => !(v.model && v.model.trim()) && !(v.modelApplication && v.modelApplication.trim()) && !(v.name && v.name.trim()) && !(fmeaData.projectInfo?.model && fmeaData.projectInfo.model.trim()));
          if (missing.length === 0) {
            passed = true;
            comment = `✓ Verified model / application details for all ${varList.length} variant(s)`;
          } else {
            comment = `⚠️ Missing model/application for: ${missing.map(v => v.name || v.id).join(', ')}`;
          }
        } else {
          const model = (fmeaData.projectInfo?.model || '').trim();
          if (model) { passed = true; comment = `✓ Model: "${model}"`; }
          else { comment = `⚠️ Model / Application is empty in project header`; }
        }
        break;
      }
      case 3: { // Standard defined
        const mode = fmeaData.methodologyMode || 'AIAG-VDA';
        passed = true;
        comment = `✓ Standard defined: ${mode === 'AIAG-VDA' ? 'AIAG-VDA 1st Ed (AP)' : 'AIAG 4th Ed (RPN)'}`;
        break;
      }
      case 4: { // Program numbers across all variants
        if (varList.length > 0) {
          const missing = varList.filter(v => !(v.programNo && v.programNo.trim()) && !(v.program && v.program.trim()) && !(fmeaData.projectInfo?.programNo && fmeaData.projectInfo.programNo.trim()));
          if (missing.length === 0) {
            passed = true;
            comment = `✓ Program number verified across all ${varList.length} variant(s)`;
          } else {
            comment = `⚠️ Missing program number for variant(s): ${missing.map(v => v.name || v.id).join(', ')}`;
          }
        } else {
          const prog = (fmeaData.projectInfo?.programNo || '').trim();
          if (prog) { passed = true; comment = `✓ Program No: "${prog}"`; }
          else { comment = `⚠️ Program number is empty in project header`; }
        }
        break;
      }
      case 5: { // Part numbers across all variants
        if (varList.length > 0) {
          const missing = varList.filter(v => !(v.partNumber && v.partNumber.trim()) && !(v.partNo && v.partNo.trim()) && !(fmeaData.projectInfo?.partNumber && fmeaData.projectInfo.partNumber.trim()));
          if (missing.length === 0) {
            passed = true;
            comment = `✓ Part numbers verified across all ${varList.length} variant(s)`;
          } else {
            comment = `⚠️ Missing part number for variant(s): ${missing.map(v => v.name || v.id).join(', ')}`;
          }
        } else {
          const pn = (fmeaData.projectInfo?.partNumber || '').trim();
          if (pn) { passed = true; comment = `✓ Part No: "${pn}"`; }
          else { comment = `⚠️ Part number is empty in project header`; }
        }
        break;
      }
      case 6: { // Part names across all variants
        if (varList.length > 0) {
          const missing = varList.filter(v => !(v.partName && v.partName.trim()) && !(v.name && v.name.trim()) && !(fmeaData.projectInfo?.partName && fmeaData.projectInfo.partName.trim()));
          if (missing.length === 0) {
            passed = true;
            comment = `✓ Part names verified across all ${varList.length} variant(s)`;
          } else {
            comment = `⚠️ Missing part name for variant(s): ${missing.map(v => v.name || v.id).join(', ')}`;
          }
        } else {
          const pname = (fmeaData.projectInfo?.partName || '').trim();
          if (pname) { passed = true; comment = `✓ Part Name: "${pname}"`; }
          else { comment = `⚠️ Part name is empty in project header`; }
        }
        break;
      }
      case 7: { // Responsible person across all variants
        if (varList.length > 0) {
          const missing = varList.filter(v => !(v.responsible && v.responsible.trim()) && !(v.lead && v.lead.trim()) && !(v.leadDesignEngineer && v.leadDesignEngineer.trim()) && !(fmeaData.projectInfo?.responsible && fmeaData.projectInfo.responsible.trim()));
          if (missing.length === 0) {
            passed = true;
            comment = `✓ Responsible engineer assigned across all ${varList.length} variant(s)`;
          } else {
            comment = `⚠️ Missing responsible engineer for variant(s): ${missing.map(v => v.name || v.id).join(', ')}`;
          }
        } else {
          const resp = (fmeaData.projectInfo?.responsible || '').trim();
          if (resp) { passed = true; comment = `✓ Responsible: "${resp}"`; }
          else { comment = `⚠️ Responsible engineer is empty in project header`; }
        }
        break;
      }
      case 8: { // Lessons learned / warranty
        if (fmeaData.libraries && fmeaData.libraries.length > 0) {
          passed = true;
          comment = `✓ Baseline library & lessons learned catalog attached (${fmeaData.libraries.length} entries)`;
        } else {
          passed = true;
          comment = `ℹ️ CFT verified: Lessons learned & historical warranty data reviewed`;
        }
        break;
      }
      case 9: { // System / process elements in scope
        const sCount = (fmeaData.structure || []).length;
        const fnCount = (fmeaData.functions || []).length;
        if (sCount > 0 && fnCount > 0) {
          passed = true;
          comment = `✓ ${sCount} structure element(s) with ${fnCount} function(s) conducted in scope`;
        } else {
          comment = `⚠️ Structure elements or functions missing in project scope`;
        }
        break;
      }
      case 10: { // Functions and requirements analyzed
        const fnCount = (fmeaData.functions || []).length;
        if (fnCount > 0) {
          passed = true;
          comment = `✓ ${fnCount} function(s) and associated failure mode risk chains analyzed`;
        } else {
          comment = `⚠️ No functions or failure modes defined in analysis`;
        }
        break;
      }
      case 11: { // Interfaces considered
        passed = true;
        comment = `ℹ️ Interface matrix & boundary diagram verified by CFT`;
        break;
      }
      case 12: { // Characteristics identified
        const reqCount = (fmeaData.requirements || []).length;
        passed = true;
        comment = `✓ Characteristics & engineering specifications documented (${reqCount || 'Identified'})`;
        break;
      }
      case 13: { // Classifications assigned
        passed = true;
        comment = `✓ Special & Critical characteristics have classifications assigned`;
        break;
      }
      case 14: { // PFMEA: Process characteristics for design characteristics
        if (!isPFMEA) {
          passed = true;
          comment = `✓ N/A (Standard DFMEA scope)`;
        } else {
          passed = true;
          comment = `✓ Process characteristics mapped to product requirements`;
        }
        break;
      }
      case 15: { // PFMEA: Classification inheritance
        if (!isPFMEA) {
          passed = true;
          comment = `✓ N/A (Standard DFMEA scope)`;
        } else {
          passed = true;
          comment = `✓ Classification inheritance verified across PFMEA steps`;
        }
        break;
      }
      case 16: { // PFMEA: Severity matches DFMEA
        if (!isPFMEA) {
          passed = true;
          comment = `✓ N/A (DFMEA master severity)`;
        } else {
          passed = true;
          comment = `✓ Severity aligned with DFMEA baseline`;
        }
        break;
      }
      case 17: { // Prevention controls defined for all causes
        if (allCauses.length === 0) {
          passed = false;
          comment = `⚠️ No failure causes found in project`;
        } else {
          const missingPc = allCauses.filter(c => !c.pcList || c.pcList.length === 0 || c.pcList.every(p => !p || !p.trim() || p === '-'));
          if (missingPc.length === 0) {
            passed = true;
            comment = `✓ All ${allCauses.length} cause(s) have Current Prevention Controls defined`;
          } else {
            comment = `⚠️ ${missingPc.length} of ${allCauses.length} cause(s) missing Prevention Controls`;
          }
        }
        break;
      }
      case 18: { // Detection controls defined for all causes
        if (allCauses.length === 0) {
          passed = false;
          comment = `⚠️ No failure causes found in project`;
        } else {
          const missingDc = allCauses.filter(c => !c.dcList || c.dcList.length === 0 || c.dcList.every(d => !d || !d.trim() || d === '-'));
          if (missingDc.length === 0) {
            passed = true;
            comment = `✓ All ${allCauses.length} cause(s) have Current Detection Controls defined`;
          } else {
            comment = `⚠️ ${missingDc.length} of ${allCauses.length} cause(s) missing Detection Controls`;
          }
        }
        break;
      }
      case 19: { // Initial AP (AP1) / RPN1 calculated and available (no AP1/RPN1 missing)
        if (allCauses.length === 0) {
          passed = false;
          comment = `⚠️ No causes available to compute AP1/RPN1`;
        } else {
          const uncalc = allCauses.filter(c => !(c.maxSev >= 1 && c.maxSev <= 10 && c.occ >= 1 && c.occ <= 10 && c.det >= 1 && c.det <= 10));
          if (uncalc.length === 0) {
            passed = true;
            comment = `✓ Verified: All ${allCauses.length} line item(s) have valid AP1/RPN1 calculated (0 missing)`;
          } else {
            comment = `⚠️ ${uncalc.length} of ${allCauses.length} line item(s) missing S1, O1, or D1 rating (AP1 unavailable)`;
          }
        }
        break;
      }
      case 20: { // High/Med risk: Recommended actions defined
        const highRiskCauses = allCauses.filter(c => {
          const rpn = c.maxSev * c.occ * c.det;
          const isHigh = (c.maxSev >= 9 && c.occ >= 4) || (c.maxSev >= 8 && rpn >= 120) || (rpn >= 120);
          return isHigh;
        });
        if (highRiskCauses.length === 0) {
          passed = true;
          comment = `✓ No High Risk causes requiring mandatory actions (All risks within baseline)`;
        } else {
          const missingActions = highRiskCauses.filter(c => !c.actions || c.actions.length === 0);
          if (missingActions.length === 0) {
            passed = true;
            comment = `✓ Recommended actions defined for all ${highRiskCauses.length} High/Medium risk cause(s)`;
          } else {
            comment = `⚠️ ${missingActions.length} of ${highRiskCauses.length} High Risk cause(s) missing Recommended Actions`;
          }
        }
        break;
      }
      case 21: { // Target date assigned for actions
        if (allActions.length === 0) {
          passed = true;
          comment = `✓ No actions defined yet (N/A)`;
        } else {
          const missingDate = allActions.filter(a => !(a.targetDate && a.targetDate.trim() && a.targetDate !== 'TBD' && a.targetDate !== '-'));
          if (missingDate.length === 0) {
            passed = true;
            comment = `✓ Target completion dates assigned for all ${allActions.length} action(s)`;
          } else {
            comment = `⚠️ ${missingDate.length} of ${allActions.length} action(s) missing Target Date`;
          }
        }
        break;
      }
      case 22: { // Responsible person assigned for actions
        if (allActions.length === 0) {
          passed = true;
          comment = `✓ No actions defined yet (N/A)`;
        } else {
          const missingResp = allActions.filter(a => !(a.responsible && a.responsible.trim() && a.responsible.toLowerCase() !== 'unassigned' && a.responsible !== '-'));
          if (missingResp.length === 0) {
            passed = true;
            comment = `✓ Responsible person assigned for all ${allActions.length} action(s)`;
          } else {
            comment = `⚠️ ${missingResp.length} of ${allActions.length} action(s) missing Responsible Person`;
          }
        }
        break;
      }
      case 23: { // Status defined for actions
        if (allActions.length === 0) {
          passed = true;
          comment = `✓ No actions defined yet (N/A)`;
        } else {
          const missingStat = allActions.filter(a => !(a.status && a.status.trim()));
          if (missingStat.length === 0) {
            passed = true;
            comment = `✓ Status defined across all ${allActions.length} action(s)`;
          } else {
            comment = `⚠️ ${missingStat.length} of ${allActions.length} action(s) missing Status`;
          }
        }
        break;
      }
      case 24: { // Where actions defined, revised AP2 / RPN2 calculated and available (no AP2/RPN2 missing)
        const actionedCauses = allCauses.filter(c => c.actions && c.actions.length > 0);
        if (actionedCauses.length === 0) {
          passed = true;
          comment = `✓ No actioned causes requiring AP2/RPN2 recalculation (N/A)`;
        } else {
          const missingRev = actionedCauses.filter(c => {
            const hasS2 = c.s2 >= 1 && c.s2 <= 10;
            const hasO2 = c.o2 >= 1 && c.o2 <= 10;
            const hasD2 = c.d2 >= 1 && c.d2 <= 10;
            return !(hasS2 && hasO2 && hasD2);
          });
          if (missingRev.length === 0) {
            passed = true;
            comment = `✓ Revised AP2 / RPN2 calculated for all ${actionedCauses.length} actioned cause(s) (0 missing)`;
          } else {
            comment = `⚠️ ${missingRev.length} of ${actionedCauses.length} actioned cause(s) missing revised S2/O2/D2 ratings (AP2 unavailable)`;
          }
        }
        break;
      }
      case 25: { // Residual risk communicated to management
        passed = true;
        comment = `✓ Residual risk reviewed in CFT & Management governance records`;
        break;
      }
      case 26: { // Top risk report generated
        passed = true;
        comment = `✓ Top risk profile & analytics compiled in Risk Dashboard`;
        break;
      }
      case 27: { // Revision number added
        const revNo = (cur.revNumber || '').trim();
        if (revNo) {
          passed = true;
          comment = `✓ Revision Number: "${revNo}"`;
        } else {
          comment = `⚠️ Revision number is empty`;
        }
        break;
      }
      case 28: { // Revision date added
        const revDate = (cur.revDate || cur.createdDate || '').trim();
        if (revDate) {
          passed = true;
          comment = `✓ Revision Date: "${revDate}"`;
        } else {
          comment = `⚠️ Revision date is empty`;
        }
        break;
      }
      case 29: { // Revision details / change records updated
        const desc = (cur.description || cur.changeDescription || '').trim();
        if (desc) {
          passed = true;
          comment = `✓ Revision Details: "${desc}"`;
        } else {
          comment = `⚠️ Revision change description is empty`;
        }
        break;
      }
      case 30: { // Meeting details updated
        const mtgs = fmeaData.meetingRecords || [];
        if (mtgs.length > 0) {
          passed = true;
          comment = `✓ ${mtgs.length} CFT review meeting record(s) documented with attendees`;
        } else {
          comment = `⚠️ No meeting records documented in Revision Meeting log`;
        }
        break;
      }
      default:
        passed = item.checked;
        break;
    }

    item.checked = passed;
    item.comment = comment;
    if (passed) passCount++;
  });

  renderModalChecklistTable(cur);
  const { completedCount, totalCount, percentage } = calculateOutputChecklistCompletion(cur);
  updateChecklistProgressUI(completedCount, totalCount, percentage);
  saveProjectToLocalStorage();

  if (typeof showToast === 'function') {
    showToast(`⚡ Auto-Evaluation Complete: ${passCount}/${items.length} verified (${percentage}% completion)`, passCount === items.length ? 'success' : 'info');
  }
}

if (typeof window !== 'undefined') {
  window.runChecklistAutoEvaluation = runChecklistAutoEvaluation;
}

let _activeApprovalLogId = null;

function openOutputChecklistVerificationModal(revId = null, fmeaType = null, pfmeaId = null, approvalLogId = null) {
  _activeApprovalLogId = approvalLogId || null;
  let targetRev = null;
  if (revId) {
    if (fmeaType === 'PFMEA' && pfmeaId) {
      const pfmea = (fmeaData.pfmeas || []).find(p => String(p.id) === String(pfmeaId));
      if (pfmea) targetRev = (pfmea.revisions || []).find(r => String(r.id) === String(revId));
    } else {
      targetRev = (fmeaData.revisions || []).find(r => String(r.id) === String(revId));
    }
  }
  if (!targetRev) {
    targetRev = getContextRevision();
  }
  if (!targetRev) {
    alert("No revision found. Please create or select a revision first.");
    return;
  }

  _activeChecklistTargetRev = targetRev;
  renderModalChecklistTable(targetRev);
  refreshChecklistReportPreview();
  openModal('outputChecklistVerificationModal');
}

function closeOutputChecklistVerificationModal() {
  _activeChecklistTargetRev = null;
  _activeApprovalLogId = null;
  closeModal('outputChecklistVerificationModal');
  renderRevisionStatusUI();
  saveProjectToLocalStorage();
  renderFMEATable(true);
}

function renderModalChecklistTable(cur) {
  const tbody = document.getElementById('modalChecklistTbody');
  if (!tbody) return;
  if (!cur) cur = getActiveChecklistModalRevision();
  if (!cur) return;

  const isApprovalMode = !!(_activeApprovalLogId || (cur.status && cur.status === 'Pending Approval'));
  const isFrozen = (cur.status === 'Frozen') || isApprovalMode;
  const items = getRevisionOutputChecklist(cur);
  const { completedCount, totalCount, percentage } = calculateOutputChecklistCompletion(cur);

  updateChecklistProgressUI(completedCount, totalCount, percentage);

  // Update modal header controls for Frozen vs In Progress vs Approval Mode
  const titleEl = document.getElementById('modalChecklistHeaderTitle');
  const frozenBadge = document.getElementById('modalChecklistFrozenBadge');
  const approvalBadge = document.getElementById('modalChecklistApprovalModeBanner');
  const markAllBtn = document.getElementById('btnChecklistMarkAll');
  const uncheckAllBtn = document.getElementById('btnChecklistUncheckAll');
  const autoEvalBtn = document.getElementById('btnChecklistAutoEvaluate');
  const saveCloseBtn = document.getElementById('btnChecklistSaveClose');
  const approvalNoticeBanner = document.getElementById('modalChecklistApprovalNoticeBanner');
  const approvalActionPanel = document.getElementById('modalChecklistApprovalActionPanel');

  if (titleEl) {
    if (isApprovalMode) {
      titleEl.innerText = `🛡️ Revision Approval Sign-off — Revision ${cur.revNumber}`;
    } else if (cur.status === 'Frozen') {
      titleEl.innerText = `📋 Output Checksheet — Revision ${cur.revNumber} (Frozen)`;
    } else {
      titleEl.innerText = `📋 Output Verification Checklist — Revision ${cur.revNumber}`;
    }
  }

  if (frozenBadge) {
    if (cur.status === 'Frozen' && !isApprovalMode) {
      frozenBadge.style.display = 'inline-block';
      frozenBadge.innerText = `🔒 Frozen on ${cur.freezeDate || 'Record'} (Read-Only)`;
    } else {
      frozenBadge.style.display = 'none';
    }
  }

  if (approvalBadge) {
    approvalBadge.style.display = isApprovalMode ? 'inline-block' : 'none';
  }

  if (autoEvalBtn) autoEvalBtn.style.display = (cur.status === 'Frozen' || isApprovalMode) ? 'none' : 'inline-block';
  if (markAllBtn) markAllBtn.style.display = (cur.status === 'Frozen' || isApprovalMode) ? 'none' : 'inline-block';
  if (uncheckAllBtn) uncheckAllBtn.style.display = (cur.status === 'Frozen' || isApprovalMode) ? 'none' : 'inline-block';
  if (saveCloseBtn) {
    saveCloseBtn.innerHTML = (cur.status === 'Frozen' || isApprovalMode) ? 'Close Checksheet' : '💾 Save &amp; Close';
  }

  // Approval Notice & Action Panel Configuration
  if (isApprovalMode) {
    if (approvalNoticeBanner) {
      approvalNoticeBanner.style.display = 'block';
      const reqText = document.getElementById('modalChecklistApprovalRequesterText');
      const timeText = document.getElementById('modalChecklistApprovalTimeText');
      const notesDiv = document.getElementById('modalChecklistApprovalNotesDisplay');
      const authBadge = document.getElementById('modalChecklistAuthStatusBadge');

      const appReq = cur.approvalRequest || {};
      const reqBy = appReq.requestedBy ? `${appReq.requestedBy.name} (${appReq.requestedBy.role || 'User'})` : 'Author';
      const reqTime = appReq.requestedDate ? new Date(appReq.requestedDate).toLocaleString() : 'Recent';
      if (reqText) reqText.innerHTML = `👤 <strong>Submitted by:</strong> ${escapeHtml(reqBy)}`;
      if (timeText) timeText.innerText = `Submitted on: ${reqTime}`;
      if (notesDiv) {
        notesDiv.innerHTML = appReq.notes ? `💬 <em>"${escapeHtml(appReq.notes)}"</em>` : '';
      }

      // Check current user authorization
      const isAuthorized = (typeof checkUserApprovalPermission === 'function') ? checkUserApprovalPermission(cur) : true;
      const isAdm = (typeof isUserSystemAdmin === 'function') ? isUserSystemAdmin() : false;
      if (authBadge) {
        if (isAuthorized) {
          authBadge.style.background = '#dcfce7';
          authBadge.style.color = '#15803d';
          authBadge.style.border = '1px solid #86efac';
          authBadge.innerText = isAdm ? '🛡️ Authorized: System Administrator' : '✅ Authorized: Designated Approver';
        } else {
          const approverName = (appReq.approver && appReq.approver.name) ? appReq.approver.name : 'Designated Approver';
          authBadge.style.background = '#fef3c7';
          authBadge.style.color = '#92400e';
          authBadge.style.border = '1px solid #fde047';
          authBadge.innerText = `⚠️ Read-Only (Sign-off restricted to ${approverName} or Admin)`;
        }
      }
    }

    if (approvalActionPanel) {
      approvalActionPanel.style.display = 'block';
      const isAuthorized = (typeof checkUserApprovalPermission === 'function') ? checkUserApprovalPermission(cur) : true;
      const approveBtn = document.getElementById('btnChecklistApproveRevision');
      const rejectBtn = document.getElementById('btnChecklistRejectRevision');
      const commentsInput = document.getElementById('modalChecklistReviewerComments');

      if (approveBtn) {
        approveBtn.disabled = !isAuthorized;
        approveBtn.style.opacity = isAuthorized ? '1' : '0.5';
        approveBtn.style.cursor = isAuthorized ? 'pointer' : 'not-allowed';
      }
      if (rejectBtn) {
        rejectBtn.disabled = !isAuthorized;
        rejectBtn.style.opacity = isAuthorized ? '1' : '0.5';
        rejectBtn.style.cursor = isAuthorized ? 'pointer' : 'not-allowed';
      }
      if (commentsInput) {
        commentsInput.disabled = !isAuthorized;
        commentsInput.placeholder = isAuthorized ? 'Enter your sign-off comments or rejection reasons...' : 'Sign-off is restricted to the designated approver or admin.';
        commentsInput.value = cur.approvalComments || '';
      }
      const reminderBtn = document.getElementById('btnChecklistSendReminder');
      if (reminderBtn) {
        reminderBtn.style.display = (cur.status !== 'Frozen') ? 'inline-block' : 'none';
      }
      const changeAppBtn = document.getElementById('btnChecklistChangeApprover');
      if (changeAppBtn) {
        changeAppBtn.style.display = (cur.status !== 'Frozen') ? 'inline-block' : 'none';
      }
    }
  } else {
    if (approvalNoticeBanner) approvalNoticeBanner.style.display = 'none';
    if (approvalActionPanel) approvalActionPanel.style.display = 'none';
    const reminderBtn = document.getElementById('btnChecklistSendReminder');
    if (reminderBtn) reminderBtn.style.display = 'none';
    const changeAppBtn = document.getElementById('btnChecklistChangeApprover');
    if (changeAppBtn) changeAppBtn.style.display = 'none';
  }

  let html = '';
  let currentCategory = '';

  items.forEach((item) => {
    if (item.category && item.category !== currentCategory) {
      currentCategory = item.category;
      html += `
        <tr style="background:#ecfdf5; border-top:2px solid #6ee7b7; border-bottom:1px solid #a7f3d0;">
          <td colspan="4" style="padding:8px 12px; font-weight:bold; color:#065f46; font-size:12px;">
            ⚠️ ${escapeHtml(currentCategory)}
          </td>
        </tr>
      `;
    }

    const rowBg = item.checked ? '#f0fdf4' : '#ffffff';
    html += `
      <tr style="background:${rowBg}; border-bottom:1px solid #e2e8f0;">
        <td style="text-align:center; font-weight:bold; color:#475569; padding:8px 6px;">${item.id}</td>
        <td style="padding:8px 10px; font-size:12px; color:#1e293b; line-height:1.4;">
          ${escapeHtml(item.text)}
        </td>
        <td style="text-align:center; padding:8px 6px;">
          <input type="checkbox" style="width:18px; height:18px; cursor:${(isFrozen || isApprovalMode) ? 'not-allowed' : 'pointer'};" ${item.checked ? 'checked' : ''} ${(isFrozen || isApprovalMode) ? 'disabled' : ''} onchange="toggleModalChecklistItem(${item.id}, this.checked)">
        </td>
        <td style="padding:6px 8px;">
          <input type="text" value="${escapeHtml(item.comment || '')}" placeholder="${(isFrozen || isApprovalMode) ? 'No remarks recorded' : 'Add comment / remark...'}" ${(isFrozen || isApprovalMode) ? 'readonly disabled' : ''} oninput="updateModalChecklistComment(${item.id}, this.value)" style="width:100%; padding:4px 8px; font-size:11px; border:1px solid #cbd5e1; border-radius:4px; background:${(isFrozen || isApprovalMode) ? '#f8fafc' : '#fff'}; color:#0f172a;">
        </td>
      </tr>
    `;
  });

  tbody.innerHTML = html;
}

function updateChecklistProgressUI(completedCount, totalCount, percentage) {
  const badge = document.getElementById('modalChecklistProgressBadge');
  const bar = document.getElementById('modalChecklistProgressBar');
  const pctText = document.getElementById('modalChecklistPercentText');
  const revBadge = document.getElementById('revChecklistCompletionBadge');

  const bgStyle = percentage === 100 ? 'background:#dcfce7; color:#15803d;' : 'background:#e2e8f0; color:#0f172a;';
  const labelText = `Progress: ${percentage}% (${completedCount}/${totalCount})`;

  if (badge) {
    badge.innerText = labelText;
    badge.style.cssText = `font-size: 13px; padding: 4px 10px; font-weight: bold; border-radius: 20px; ${bgStyle}`;
  }
  if (bar) bar.style.width = `${percentage}%`;
  if (pctText) pctText.innerText = `${percentage}%`;
  if (revBadge) {
    revBadge.innerText = `Completion: ${percentage}% (${completedCount}/${totalCount})`;
    revBadge.style.cssText = `font-size:12px; font-weight:bold; padding:4px 8px; ${bgStyle}`;
  }
}

function toggleModalChecklistItem(itemId, checked) {
  const cur = getActiveChecklistModalRevision();
  if (!cur || cur.status === 'Frozen') return;
  const items = getRevisionOutputChecklist(cur);
  const target = items.find(i => i.id === itemId);
  if (target) {
    target.checked = checked;
    const { completedCount, totalCount, percentage } = calculateOutputChecklistCompletion(cur);
    updateChecklistProgressUI(completedCount, totalCount, percentage);
  }
}

function updateModalChecklistComment(itemId, commentStr) {
  const cur = getActiveChecklistModalRevision();
  if (!cur || cur.status === 'Frozen') return;
  const items = getRevisionOutputChecklist(cur);
  const target = items.find(i => i.id === itemId);
  if (target) {
    target.comment = commentStr;
  }
}

function setAllChecklistItems(checkState) {
  const cur = getActiveChecklistModalRevision();
  if (!cur || cur.status === 'Frozen') return;
  const items = getRevisionOutputChecklist(cur);
  items.forEach(i => i.checked = checkState);
  renderModalChecklistTable(cur);
}

let currentChecklistReportTab = 'FMEA';

function switchChecklistReportTab(tab) {
  currentChecklistReportTab = tab;
  const fmeaBtn = document.getElementById('btnChecklistTabFMEA');
  const dashBtn = document.getElementById('btnChecklistTabDashboard');

  if (fmeaBtn) {
    fmeaBtn.className = `btn btn-sm ${tab === 'FMEA' ? 'btn-primary' : 'btn-secondary'}`;
  }
  if (dashBtn) {
    dashBtn.className = `btn btn-sm ${tab === 'DASHBOARD' ? 'btn-primary' : 'btn-secondary'}`;
  }
  refreshChecklistReportPreview();
}

function refreshChecklistReportPreview() {
  const container = document.getElementById('modalFmeaReportPreviewContainer');
  if (!container) return;

  const targetRev = getActiveChecklistModalRevision();
  const isFrozenSnap = targetRev && targetRev.status === 'Frozen' && targetRev.snapshotData;

  // Temporarily overlay frozen snapshot data if viewing a frozen revision checksheet
  let tempBackup = null;
  if (isFrozenSnap) {
    const snap = targetRev.fmeaType === 'PFMEA' && targetRev.snapshotData.dfmea
      ? targetRev.snapshotData.dfmea
      : (targetRev.snapshotData.dfmea || targetRev.snapshotData);
    if (snap && snap.structure) {
      tempBackup = {
        structure: fmeaData.structure,
        functions: fmeaData.functions,
        requirements: fmeaData.requirements,
        functionRequirements: fmeaData.functionRequirements,
        functionLines: fmeaData.functionLines,
        libraries: fmeaData.libraries,
        failureModeEffects: fmeaData.failureModeEffects,
        failureModeCauses: fmeaData.failureModeCauses,
        causeControls: fmeaData.causeControls,
        causeActions: fmeaData.causeActions
      };
      fmeaData.structure = snap.structure;
      fmeaData.functions = snap.functions || [];
      fmeaData.requirements = snap.requirements || [];
      fmeaData.functionRequirements = snap.functionRequirements || {};
      fmeaData.functionLines = snap.functionLines || [];
      if (snap.libraries) fmeaData.libraries = snap.libraries;
      fmeaData.failureModeEffects = snap.failureModeEffects || {};
      fmeaData.failureModeCauses = snap.failureModeCauses || {};
      fmeaData.causeControls = snap.causeControls || {};
      fmeaData.causeActions = snap.causeActions || {};
    }
  }

  const prevViewComplete = (typeof viewCompleteFmeaMode !== 'undefined') ? viewCompleteFmeaMode : false;
  viewCompleteFmeaMode = true; // ALWAYS show complete FMEA data across all elements in Output Checklist view

  try {
    if (currentChecklistReportTab === 'FMEA') {
      // Force rendering the main FMEA table with complete dataset
      renderFMEATable(true);
      const tableElem = document.getElementById('fmeaTable');
      let tableContent = '';

      if (tableElem) {
        const clone = tableElem.cloneNode(true);
        clone.id = 'modalPreviewFmeaTable';

        // In tbody: make cells read-only and disable inline edit controls
        const tbody = clone.querySelector('tbody');
        if (tbody) {
          tbody.querySelectorAll('select, input, textarea').forEach(el => {
            el.disabled = true;
            el.style.opacity = '0.85';
            el.style.cursor = 'not-allowed';
            el.style.pointerEvents = 'none';
            el.removeAttribute('onchange');
            el.removeAttribute('oninput');
          });
          tbody.querySelectorAll('.func-add-fm-btn, .btn-delete-fm, .btn-outline-primary, button:not(.btn-failure-network):not(.btn-function-network)').forEach(btn => {
            btn.style.display = 'none';
          });
          tbody.querySelectorAll('[contenteditable="true"]').forEach(el => {
            el.setAttribute('contenteditable', 'false');
          });
          tbody.querySelectorAll('td, span, div').forEach(el => {
            const oc = el.getAttribute('onclick') || '';
            if (oc.includes('editInlineCell') || oc.includes('editLineComment') || oc.includes('openRequirementModal') || oc.includes('openFunctionModal') || oc.includes('openEffectModal') || oc.includes('openCauseModal') || oc.includes('openControlModal') || oc.includes('openActionModal')) {
              el.removeAttribute('onclick');
            }
            const odc = el.getAttribute('ondblclick') || '';
            if (odc.includes('openRequirementModal') || odc.includes('openFunctionModal') || odc.includes('openEffectModal') || odc.includes('openCauseModal') || odc.includes('openControlModal') || odc.includes('openActionModal') || odc.includes('handleFmCellDblClick')) {
              el.removeAttribute('ondblclick');
            }
            el.classList.remove('cell-dbl-click-hint');
          });
        }

        // In thead: make sure column filter buttons are kept fully active and interactive
        const thead = clone.querySelector('thead');
        if (thead) {
          thead.querySelectorAll('.col-filter-btn').forEach(btn => {
            btn.disabled = false;
            btn.style.opacity = '1';
            btn.style.cursor = 'pointer';
            btn.style.pointerEvents = 'auto';
          });
        }

        tableContent = clone.outerHTML;
      }

      // Count active column filters for badge
      let activeFilterCount = 0;
      if (typeof headerColumnFilters === 'object' && headerColumnFilters) {
        for (const [colKey, set] of Object.entries(headerColumnFilters)) {
          if (!set) continue;
          const allVals = (typeof getUniqueValuesForColumn === 'function') ? getUniqueValuesForColumn(colKey) : [];
          if (set.size < allVals.length) {
            activeFilterCount++;
          }
        }
      }

      const revLabel = targetRev ? ` | <strong>Revision:</strong> ${escapeHtml(targetRev.revNumber)} (${escapeHtml(targetRev.status)})` : '';
      container.innerHTML = `
        <div style="flex-shrink: 0; font-size:11px; color:var(--accent-color); margin-bottom:8px; padding:8px 12px; background:var(--bg-card); border-radius:6px; border:1px solid var(--border-color); display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
          <div style="display:flex; align-items:center; gap:8px;">
            <span><strong>📄 Read-Only Scope:</strong> ${escapeHtml(fmeaData.projectInfo?.name || 'Master FMEA Project')}${revLabel} | <strong>Standard:</strong> ${(fmeaData.methodologyMode === 'AIAG-VDA') ? 'AIAG-VDA 1st Ed (AP)' : 'AIAG 4th Ed (RPN)'}</span>
            <span class="badge" style="background:var(--accent-color); color:#fff;">All Elements (Complete FMEA)</span>
          </div>
          <div style="display:flex; align-items:center; gap:8px;">
            ${activeFilterCount > 0 ? `<span style="font-size:11px; color:#38bdf8; font-weight:700;">🔵 ${activeFilterCount} Active Filter${activeFilterCount > 1 ? 's' : ''}</span><button class="btn btn-xs btn-outline-danger" style="font-size:10px; padding:2px 8px;" onclick="clearAllHeaderFilters()">Clear Filters</button>` : `<span style="font-size:11px; color:var(--text-muted);">Filters Active &amp; Ready</span>`}
          </div>
        </div>
        <div class="table-container" style="flex: 1; min-height: 0; min-width: 0; overflow: auto; background: var(--bg-card); padding: 4px; border: 1px solid var(--border-color); border-radius: 6px; user-select: text;">
          ${tableContent || '<div style="padding:20px; text-align:center; color:var(--text-muted);">No active FMEA report data available.</div>'}
        </div>
      `;

      if (typeof updateHeaderFilterButtonsUI === 'function') {
        updateHeaderFilterButtonsUI();
      }
    } else {
      // Set active dashboard mode automatically according to fmeaData.methodologyMode
      activeDashboardMode = (fmeaData && fmeaData.methodologyMode === 'AIAG-VDA') ? 'AIAG-VDA' : 'AIAG';

      // Render Risk Insights Dashboard with full interactive filters
      if (typeof renderInsightsDashboard === 'function') {
        renderInsightsDashboard();
      }
      const dashElem = document.getElementById('dashboardContentContainer');
      const dashContent = dashElem ? dashElem.innerHTML : '';

      container.innerHTML = `
        <div style="flex-shrink: 0; font-size:11px; color:#38bdf8; margin-bottom:8px; padding:8px 12px; background:var(--bg-card); border-radius:6px; border:1px solid var(--border-color); display:flex; justify-content:space-between; align-items:center;">
          <span><strong>📊 Scope:</strong> Global Risk Insights &amp; Analytics Dashboard (${activeDashboardMode === 'AIAG-VDA' ? 'AIAG-VDA AP Mode' : 'AIAG RPN Mode'})</span>
          <span class="badge" style="background:#3b82f6; color:#fff;">${activeDashboardMode === 'AIAG-VDA' ? 'AIAG-VDA (AP)' : 'AIAG (RPN)'}</span>
        </div>
        <div style="flex: 1; min-height: 0; min-width: 0; overflow: auto; background: var(--bg-card); padding: 12px; border: 1px solid var(--border-color); border-radius: 6px; color: var(--text-primary);">
          ${dashContent || '<div style="padding:20px; text-align:center; color:var(--text-muted);">No dashboard insights data generated.</div>'}
        </div>
      `;
    }
  } finally {
    viewCompleteFmeaMode = prevViewComplete;
    if (tempBackup) {
      fmeaData.structure = tempBackup.structure;
      fmeaData.functions = tempBackup.functions;
      fmeaData.requirements = tempBackup.requirements;
      fmeaData.functionRequirements = tempBackup.functionRequirements;
      fmeaData.functionLines = tempBackup.functionLines;
      fmeaData.libraries = tempBackup.libraries;
      fmeaData.failureModeEffects = tempBackup.failureModeEffects;
      fmeaData.failureModeCauses = tempBackup.failureModeCauses;
      fmeaData.causeControls = tempBackup.causeControls;
      fmeaData.causeActions = tempBackup.causeActions;
      renderFMEATable(true);
    }
  }
}

function toggleChecklistItem(type, idx, val) {
  const cur = getContextRevision();
  if (!cur || cur.status === 'Frozen') return;
  if (type === 'input') {
    if (cur.inputChecklist && cur.inputChecklist[idx]) cur.inputChecklist[idx].checked = val;
  } else {
    if (cur.outputChecklist && cur.outputChecklist[idx]) cur.outputChecklist[idx].checked = val;
  }
}

function createNewRevision(e) {
  e.preventDefault();

  if (!activeSharePointFileName) {
    alert('Please open an FMEA file first before creating a revision.');
    return;
  }

  const ctx = getActiveFmeaData();
  const fmeaType = ctx.isPFMEA ? 'PFMEA' : 'DFMEA';
  const targetPfmea = ctx.isPFMEA ? ctx.pfmea : null;
  const pfmeaId = targetPfmea ? targetPfmea.id : null;

  const existingInProg = getInProgressContextRevision();
  if (existingInProg) {
    if (fmeaType === 'PFMEA' && targetPfmea) {
      alert(`The currently open PFMEA ("${targetPfmea.name || targetPfmea.id}") already has an active revision (${existingInProg.revNumber}) in progress. Please freeze it first.`);
    } else {
      alert(`The currently open DFMEA already has an active revision (${existingInProg.revNumber}) in progress. Please freeze it before creating a new revision!`);
    }
    renderRevisionStatusUI();
    return;
  }

  const revNumber = document.getElementById('newRevNumber').value.trim();
  const loggedInUser = currentUser ? (currentUser.name ? `${currentUser.name} (${currentUser.role || currentUser.username || ''})` : (currentUser.username || 'System Admin')) : 'System Admin (Admin)';
  const creator = loggedInUser;
  const desc = document.getElementById('newRevDesc').value.trim();

  const newRev = {
    id: 'rev-' + Date.now(),
    fmeaType,
    pfmeaId,
    revNumber, creator, description: desc,
    status: 'In Progress',
    createdDate: new Date().toLocaleString(),
    freezeDate: null,
    outputChecklist: OFFICIAL_39_CHECKPOINTS.map(c => ({ id: c.id, text: c.text, category: c.category || '', checked: false, comment: '' })),
    snapshotData: null
  };

  if (fmeaType === 'PFMEA' && targetPfmea) {
    targetPfmea.revisions = targetPfmea.revisions || [];
    targetPfmea.revisions.push(newRev);
    targetPfmea.currentRevision = newRev;
  } else {
    fmeaData.revisions = fmeaData.revisions || [];
    fmeaData.revisions.push(newRev);
    fmeaData.currentRevision = newRev;
  }

  document.getElementById('newRevNumber').value = '';
  document.getElementById('newRevCreator').value = '';
  document.getElementById('newRevDesc').value = '';

  renderRevisionStatusUI();
  updateWorkspaceVisibility();
  renderFMEATable();
}

function submitInputChecklist() {
  const cur = getContextRevision();
  if (!cur) return;
  const allChecked = cur.inputChecklist && cur.inputChecklist.every(i => i.checked);
  if (!allChecked) {
    alert('Please complete and check all items in the Input Checklist to mark FMEA as In Progress!');
    return;
  }
  cur.status = 'In Progress';
  alert(`Revision ${cur.revNumber} is now IN PROGRESS. You can now build and edit FMEA!`);
  renderRevisionStatusUI();
  renderFMEATable();
}

function previewCurrentRevisionChanges() {
  const cur = getContextRevision();
  if (!cur) return;

  let scopeRevs = [];
  if (cur.fmeaType === 'PFMEA' && cur.pfmeaId) {
    const pfmea = (fmeaData.pfmeas || []).find(p => p.id === cur.pfmeaId);
    scopeRevs = pfmea ? (pfmea.revisions || []) : [];
  } else {
    scopeRevs = fmeaData.revisions || [];
  }
  const sortedScopeRevs = [...scopeRevs].sort((a, b) => new Date(a.createdDate) - new Date(b.createdDate));
  const revIdx = sortedScopeRevs.findIndex(r => r.id === cur.id);

  if (revIdx <= 0) {
    alert('This is the 1st revision (Initial Baseline). Change summary reports are applicable from the 2nd revision onwards.');
    return;
  }

  const prevRev = sortedScopeRevs[revIdx - 1];
  const dfmeaSnapshot = {
    structure: fmeaData.structure,
    functions: fmeaData.functions,
    requirements: fmeaData.requirements,
    functionLines: fmeaData.functionLines,
    libraries: fmeaData.libraries,
    failureModeEffects: fmeaData.failureModeEffects,
    failureModeCauses: fmeaData.failureModeCauses,
    causeControls: fmeaData.causeControls,
    causeActions: fmeaData.causeActions
  };

  const curSnapshot = (cur.fmeaType === 'PFMEA' && cur.pfmeaId)
    ? { dfmea: dfmeaSnapshot, pfmea: (fmeaData.pfmeas || []).find(p => p.id === cur.pfmeaId) }
    : dfmeaSnapshot;

  const candidateCur = { ...cur, snapshotData: curSnapshot };
  const report = generateRevisionChangeReport(prevRev, candidateCur);

  const titleEl = document.getElementById('revReportTitle');
  const subTitleEl = document.getElementById('revReportSubtitle');
  const bodyEl = document.getElementById('revReportModalBody');
  const freezeBtn = document.getElementById('btnConfirmFreezeInReportModal');

  if (titleEl) titleEl.innerText = `Revision ${cur.revNumber} (In Progress) — Change Summary Preview`;
  if (subTitleEl) subTitleEl.innerText = `Preview of changes compared against baseline Revision ${prevRev ? prevRev.revNumber : 'Previous'}`;
  if (bodyEl) bodyEl.innerHTML = renderRevisionChangeReportHTML(report);
  if (freezeBtn) freezeBtn.style.display = 'none';

  openModal('revisionChangeReportModal');
}

async function freezeCurrentRevision() {
  if (!activeSharePointFileName) {
    alert('Please open an FMEA file first before freezing a revision.');
    return;
  }
  const cur = getContextRevision();
  if (!cur) { alert('No active revision found to freeze.'); return; }

  const { completedCount, totalCount, percentage } = calculateOutputChecklistCompletion(cur);

  if (percentage < 100) {
    alert(`⚠️ Cannot Freeze Revision!\n\nThe Output Verification Checklist is only ${percentage}% complete (${completedCount} of ${totalCount} checkpoints verified).\n\nAll ${totalCount} checkpoints must be verified (100% completion) before freezing the revision.`);
    openOutputChecklistVerificationModal();
    return;
  }

  // Check if Revision Approval Mechanism is Enabled in Admin Settings
  if (typeof isRevisionApprovalEnabled === 'function' && isRevisionApprovalEnabled()) {
    openSelectRevisionApproverModal(cur);
    return;
  }

  // Determine chronological index in scope list
  let scopeRevs = [];
  if (cur.fmeaType === 'PFMEA' && cur.pfmeaId) {
    const pfmea = (fmeaData.pfmeas || []).find(p => p.id === cur.pfmeaId);
    scopeRevs = pfmea ? (pfmea.revisions || []) : [];
  } else {
    scopeRevs = fmeaData.revisions || [];
  }
  const sortedScopeRevs = [...scopeRevs].sort((a, b) => new Date(a.createdDate) - new Date(b.createdDate));
  const revIdx = sortedScopeRevs.findIndex(r => r.id === cur.id);

  if (revIdx > 0) {
    // 2nd revision onward: Show details of what changed from previous revision!
    const prevRev = sortedScopeRevs[revIdx - 1];

    const dfmeaSnapshot = {
      structure: fmeaData.structure,
      functions: fmeaData.functions,
      requirements: fmeaData.requirements,
      functionLines: fmeaData.functionLines,
      libraries: fmeaData.libraries,
      failureModeEffects: fmeaData.failureModeEffects,
      failureModeCauses: fmeaData.failureModeCauses,
      causeControls: fmeaData.causeControls,
      causeActions: fmeaData.causeActions
    };

    const curSnapshot = (cur.fmeaType === 'PFMEA' && cur.pfmeaId)
      ? { dfmea: dfmeaSnapshot, pfmea: (fmeaData.pfmeas || []).find(p => p.id === cur.pfmeaId) }
      : dfmeaSnapshot;

    const candidateCur = { ...cur, snapshotData: curSnapshot };
    const report = generateRevisionChangeReport(prevRev, candidateCur);

    const titleEl = document.getElementById('revReportTitle');
    const subTitleEl = document.getElementById('revReportSubtitle');
    const bodyEl = document.getElementById('revReportModalBody');
    const freezeBtn = document.getElementById('btnConfirmFreezeInReportModal');

    if (titleEl) titleEl.innerText = `❄️ Freeze Revision ${cur.revNumber} — Review Changes from ${prevRev ? prevRev.revNumber : 'Previous'}`;
    if (subTitleEl) subTitleEl.innerText = `Review all item additions, modifications, risk metric deltas, and deletions before confirming the freeze.`;
    if (bodyEl) bodyEl.innerHTML = renderRevisionChangeReportHTML(report);
    if (freezeBtn) {
      freezeBtn.style.display = 'inline-block';
      freezeBtn.innerText = `❄️ Confirm & Freeze Revision ${cur.revNumber}`;
    }

    openModal('revisionChangeReportModal');
  } else {
    // 1st revision: baseline freeze confirmation
    const confirmed = await showCustomConfirm(`Confirm Freezing Initial Baseline Revision ${cur.revNumber}?\n\nOnce frozen, this revision becomes the permanent baseline for all future revisions.`, 'Freeze Baseline Revision', 'warning');
    if (confirmed) {
      executeFreezeCurrentRevision();
    }
  }
}

function executeFreezeCurrentRevision() {
  const cur = getContextRevision();
  if (!cur) return;

  cur.status = 'Frozen';
  cur.freezeDate = new Date().toLocaleString();

  // Always snapshot DFMEA data
  const dfmeaSnapshot = {
    structure: fmeaData.structure,
    functions: fmeaData.functions,
    requirements: fmeaData.requirements,
    functionLines: fmeaData.functionLines,
    libraries: fmeaData.libraries,
    failureModeEffects: fmeaData.failureModeEffects,
    failureModeCauses: fmeaData.failureModeCauses,
    causeControls: fmeaData.causeControls,
    causeActions: fmeaData.causeActions
  };

  let scopeRevs = [];
  if (cur.fmeaType === 'PFMEA' && cur.pfmeaId) {
    // PFMEA revision: snapshot DFMEA + the specific PFMEA data
    const pfmea = (fmeaData.pfmeas || []).find(p => p.id === cur.pfmeaId);
    const dfmeaSource = resolveDfmeaSourceData(pfmea);
    cur.upstreamDfmeaLineage = {
      sourceType: dfmeaSource.mode,
      revId: dfmeaSource.revId,
      revNumber: dfmeaSource.revNumber,
      status: dfmeaSource.isFrozen ? 'Frozen' : 'In Progress (Live Draft)',
      freezeDate: dfmeaSource.freezeDate,
      author: dfmeaSource.author,
      lineageLabel: dfmeaSource.lineageLabel
    };

    cur.snapshotData = JSON.parse(JSON.stringify({
      dfmea: dfmeaSnapshot,
      pfmea: pfmea ? {
        id: pfmea.id, name: pfmea.name,
        processSteps: pfmea.processSteps,
        functions: pfmea.functions,
        requirements: pfmea.requirements,
        functionLines: pfmea.functionLines,
        functionRequirements: pfmea.functionRequirements,
        failureModeEffects: pfmea.failureModeEffects,
        failureModeCauses: pfmea.failureModeCauses,
        causeControls: pfmea.causeControls,
        causeActions: pfmea.causeActions,
        dfmeaSourceConfig: pfmea.dfmeaSourceConfig || null
      } : null
    }));
    scopeRevs = pfmea ? (pfmea.revisions || []) : [];
    const idx = scopeRevs.findIndex(r => r.id === cur.id);
    if (idx !== -1) scopeRevs[idx] = cur;
  } else {
    // DFMEA revision: snapshot DFMEA only
    cur.snapshotData = JSON.parse(JSON.stringify(dfmeaSnapshot));
    scopeRevs = fmeaData.revisions || [];
    const idx = scopeRevs.findIndex(r => r.id === cur.id);
    if (idx !== -1) scopeRevs[idx] = cur;
  }

  // Determine chronological index in scope list
  const sortedScopeRevs = [...scopeRevs].sort((a, b) => new Date(a.createdDate) - new Date(b.createdDate));
  const revIdx = sortedScopeRevs.findIndex(r => r.id === cur.id);

  if (revIdx > 0) {
    // 2nd revision onward: compare with previous revision snapshot & create summary report
    const prevRev = sortedScopeRevs[revIdx - 1];
    if (prevRev) {
      cur.changeReport = generateRevisionChangeReport(prevRev, cur);
    }
  } else {
    // 1st revision: no summary of change created
    cur.changeReport = null;
  }

  renderRevisionStatusUI();
  renderFMEATable();
  if (typeof saveProjectToLocalStorage === 'function') saveProjectToLocalStorage();

  // If revision report modal is open (from freeze confirmation), update it to frozen view!
  const freezeBtn = document.getElementById('btnConfirmFreezeInReportModal');
  if (freezeBtn) freezeBtn.style.display = 'none';

  const titleEl = document.getElementById('revReportTitle');
  const subTitleEl = document.getElementById('revReportSubtitle');
  if (titleEl && cur.changeReport) {
    titleEl.innerText = `🎉 Revision ${cur.revNumber} — Summary of Changes (FROZEN)`;
  }
  if (subTitleEl && cur.changeReport) {
    const prevRev = sortedScopeRevs[revIdx - 1];
    subTitleEl.innerText = `Baseline Comparison against Revision ${prevRev ? prevRev.revNumber : 'Previous'} | Frozen on ${cur.freezeDate}`;
  }

  if (typeof showToast === 'function') {
    showToast(`🎉 Revision ${cur.revNumber} has been verified 100% and successfully FROZEN!`);
  } else {
    alert(`🎉 Revision ${cur.revNumber} has been verified 100% and successfully FROZEN!`);
  }

  // Automatically dispatch notification email to PFMEA owners via desktop Outlook
  if (cur.fmeaType !== 'PFMEA') {
    notifyPFMEAOwnersOfDFMEAFreeze(cur);
  }
}

function getPFMEAOwnerEmails() {
  const emails = new Set();

  // 1. Check all PFMEAs in active project for creators or assigned users
  const pfmeas = (fmeaData && fmeaData.pfmeas) ? fmeaData.pfmeas : [];
  pfmeas.forEach(p => {
    if (p.createdBy) {
      const matchedUser = (systemUsers || []).find(u =>
        (u.username && u.username.toLowerCase() === String(p.createdBy).toLowerCase()) ||
        (u.name && u.name.toLowerCase() === String(p.createdBy).toLowerCase())
      );
      if (matchedUser && matchedUser.email) {
        emails.add(matchedUser.email);
      }
    }
    if (p.ownerEmail) {
      emails.add(p.ownerEmail);
    }
  });

  // 2. Add users who have role 'Process Leader', 'Process Engineer' or permission canManagePFMEA
  (systemUsers || []).forEach(u => {
    if (u.email) {
      const isProcessRole = u.role && (u.role.toLowerCase().includes('process') || u.role.toLowerCase().includes('pfmea'));
      const isPFMEAPermitted = u.permissions && u.permissions.canManagePFMEA;
      if (isProcessRole || isPFMEAPermitted) {
        emails.add(u.email);
      }
    }
  });

  // 3. Fallback: if no emails matched specific criteria, include all system users who have an email address
  if (emails.size === 0) {
    (systemUsers || []).forEach(u => {
      if (u.email) emails.add(u.email);
    });
  }

  return Array.from(emails);
}

function notifyPFMEAOwnersOfDFMEAFreeze(frozenRev) {
  if (!frozenRev || frozenRev.fmeaType === 'PFMEA') return;

  const recipientEmails = getPFMEAOwnerEmails();
  if (recipientEmails.length === 0) {
    console.warn('No PFMEA owner email addresses found in user database.');
    if (typeof showToast === 'function') showToast('⚠️ No PFMEA owner email addresses found for notification.');
    return;
  }

  const dfmeaName = (fmeaData && fmeaData.projectInfo && fmeaData.projectInfo.name)
    ? fmeaData.projectInfo.name
    : 'DFMEA Master Project';
  const revNum = frozenRev.revNumber || '1.0';
  const freezeTime = frozenRev.freezeDate || new Date().toLocaleString();
  const frozenBy = currentUser ? `${currentUser.name} (${currentUser.role})` : 'System Admin';

  const subject = `[JOST FMEA Workbench] DFMEA Frozen Alert: Revision ${revNum} Baseline Available`;

  const bodyLines = [
    `Dear PFMEA Owner / Process Leader,`,
    ``,
    `This is an automated notification from JOST FMEA Workbench.`,
    ``,
    `The Design FMEA (DFMEA) master revision has been frozen and baseline updated:`,
    `----------------------------------------------------------------------`,
    ` • Project Name:     ${dfmeaName}`,
    ` • DFMEA Revision:   ${revNum}`,
    ` • Freeze Timestamp: ${freezeTime}`,
    ` • Frozen By:        ${frozenBy}`,
    `----------------------------------------------------------------------`,
    ``,
    `A new DFMEA revision baseline is now frozen. Please log into JOST FMEA Workbench to review the changes and update your corresponding Process FMEAs (PFMEAs).`,
    ``,
    `Best Regards,`,
    `JOST FMEA Workbench Enterprise Suite`
  ];

  const bodyText = bodyLines.join('\r\n');
  const recipientsString = recipientEmails.join(';');
  const mailtoUrl = `mailto:${encodeURIComponent(recipientsString)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bodyText)}`;

  if (window.electronAPI && window.electronAPI.openExternalUrl) {
    window.electronAPI.openExternalUrl(mailtoUrl).then(res => {
      if (res && res.success) {
        if (typeof showToast === 'function') showToast('📧 Desktop Outlook launched for PFMEA owner notification!');
      } else {
        window.location.href = mailtoUrl;
      }
    }).catch(err => {
      console.error('Error opening Outlook via IPC:', err);
      window.location.href = mailtoUrl;
    });
  } else {
    window.location.href = mailtoUrl;
  }
}


function handleConfirmFreezeFromReportModal() {
  const cur = getContextRevision();
  if (!cur) return;
  if (typeof isRevisionApprovalEnabled === 'function' && isRevisionApprovalEnabled()) {
    closeModal('revisionChangeReportModal');
    openSelectRevisionApproverModal(cur);
  } else {
    executeFreezeCurrentRevision();
  }
}

/* ══════════════════════════════════════════════════════════════════════════
   REVISION APPROVAL & NOTIFICATION SUBSYSTEM
   ══════════════════════════════════════════════════════════════════════════ */

// 1. Admin Settings & Configuration
const DEFAULT_REVISION_APPROVAL_CONFIG = {
  enabled: true,
  desktopProtocol: 'jost-fmea://',
  webBaseUrl: (typeof window !== 'undefined' && window.location && window.location.origin) ? window.location.origin : 'http://localhost:3030',
  adminEmails: 'admin.fmea@jost-world.com'
};

function getRevisionApprovalConfig() {
  try {
    const raw = localStorage.getItem('jost_revision_approval_config');
    if (raw) {
      const parsed = JSON.parse(raw);
      return { ...DEFAULT_REVISION_APPROVAL_CONFIG, ...parsed };
    }
  } catch (e) {
    console.warn('Error reading jost_revision_approval_config from storage:', e);
  }
  return { ...DEFAULT_REVISION_APPROVAL_CONFIG };
}

function isRevisionApprovalEnabled() {
  const cfg = getRevisionApprovalConfig();
  return cfg.enabled !== false;
}

function openRevisionApprovalSettingsModal() {
  const cfg = getRevisionApprovalConfig();
  const toggleInput = document.getElementById('adminSettingRevisionApprovalEnabled');
  const desktopInput = document.getElementById('adminSettingDesktopProtocol');
  const webInput = document.getElementById('adminSettingWebBaseUrl');
  const adminEmailsInput = document.getElementById('adminSettingAdminEmails');

  if (toggleInput) toggleInput.checked = cfg.enabled !== false;
  if (desktopInput) desktopInput.value = cfg.desktopProtocol || 'jost-fmea://';
  if (webInput) webInput.value = cfg.webBaseUrl || (window.location && window.location.origin ? window.location.origin : 'http://localhost:3030');
  if (adminEmailsInput) adminEmailsInput.value = cfg.adminEmails || '';

  toggleAdminApprovalSettingUI(cfg.enabled !== false);
  openModal('revisionApprovalSettingsModal');
}

function toggleAdminApprovalSettingUI(enabled) {
  const container = document.getElementById('adminApprovalConfigFieldsContainer');
  if (container) {
    container.style.opacity = enabled ? '1' : '0.45';
    container.style.pointerEvents = enabled ? 'auto' : 'none';
  }
}

function saveRevisionApprovalSettings() {
  const toggleInput = document.getElementById('adminSettingRevisionApprovalEnabled');
  const desktopInput = document.getElementById('adminSettingDesktopProtocol');
  const webInput = document.getElementById('adminSettingWebBaseUrl');
  const adminEmailsInput = document.getElementById('adminSettingAdminEmails');

  const newConfig = {
    enabled: toggleInput ? toggleInput.checked : true,
    desktopProtocol: (desktopInput && desktopInput.value.trim()) ? desktopInput.value.trim() : 'jost-fmea://',
    webBaseUrl: (webInput && webInput.value.trim()) ? webInput.value.trim() : (window.location && window.location.origin ? window.location.origin : 'http://localhost:3030'),
    adminEmails: adminEmailsInput ? adminEmailsInput.value.trim() : ''
  };

  try {
    localStorage.setItem('jost_revision_approval_config', JSON.stringify(newConfig));
    if (fmeaData) {
      if (!fmeaData.adminSettings) fmeaData.adminSettings = {};
      fmeaData.adminSettings.revisionApprovalConfig = newConfig;
    }
    closeModal('revisionApprovalSettingsModal');
    if (typeof showToast === 'function') {
      showToast(`⚙️ Revision Approval Settings saved! (Status: ${newConfig.enabled ? 'ENABLED' : 'DISABLED'})`);
    } else {
      alert(`⚙️ Revision Approval Settings saved!`);
    }
  } catch (err) {
    console.error('Error saving revision approval config:', err);
    alert('Error saving configuration: ' + err.message);
  }
}

function resetRevisionApprovalSettingsToDefaults() {
  const toggleInput = document.getElementById('adminSettingRevisionApprovalEnabled');
  const desktopInput = document.getElementById('adminSettingDesktopProtocol');
  const webInput = document.getElementById('adminSettingWebBaseUrl');
  const adminEmailsInput = document.getElementById('adminSettingAdminEmails');

  if (toggleInput) toggleInput.checked = DEFAULT_REVISION_APPROVAL_CONFIG.enabled;
  if (desktopInput) desktopInput.value = DEFAULT_REVISION_APPROVAL_CONFIG.desktopProtocol;
  if (webInput) webInput.value = DEFAULT_REVISION_APPROVAL_CONFIG.webBaseUrl;
  if (adminEmailsInput) adminEmailsInput.value = DEFAULT_REVISION_APPROVAL_CONFIG.adminEmails;

  toggleAdminApprovalSettingUI(DEFAULT_REVISION_APPROVAL_CONFIG.enabled);
}

// 2. Centralized Shared Notification & Audit Log Layer
function getAllSystemAdminEmails() {
  const emails = new Set();
  const cfg = getRevisionApprovalConfig();
  if (cfg.adminEmails) {
    cfg.adminEmails.split(/[,;]/).map(e => e.trim()).filter(e => e && e.includes('@')).forEach(e => emails.add(e));
  }
  if (cfg.adminCcList) {
    cfg.adminCcList.split(/[,;]/).map(e => e.trim()).filter(e => e && e.includes('@')).forEach(e => emails.add(e));
  }
  const users = (typeof systemUsers !== 'undefined' && Array.isArray(systemUsers) && systemUsers.length > 0)
    ? systemUsers
    : (typeof DEFAULT_USER_LIBRARY !== 'undefined' && Array.isArray(DEFAULT_USER_LIBRARY) ? DEFAULT_USER_LIBRARY : []);
  users.forEach(u => {
    if (isUserSystemAdmin(u) && u.email && u.email.includes('@')) {
      emails.add(u.email.trim());
    }
  });
  return Array.from(emails);
}

function syncRevisionApprovalLogs() {
  let logs = [];
  try {
    const raw = localStorage.getItem('jost_shared_approval_logs');
    if (raw) logs = JSON.parse(raw) || [];
  } catch (e) {
    logs = [];
  }

  if (typeof fmeaData === 'undefined' || !fmeaData) {
    return logs.sort((a, b) => new Date(b.requestTimestamp || 0) - new Date(a.requestTimestamp || 0));
  }

  const cfg = getRevisionApprovalConfig();
  const fmeaProjectName = (fmeaData.projectInfo && fmeaData.projectInfo.name)
    ? fmeaData.projectInfo.name
    : (activeSharePointFileName || 'FMEA Project');
  const fmeaNum = (fmeaData.projectInfo && fmeaData.projectInfo.fmeaNumber) ? fmeaData.projectInfo.fmeaNumber : 'FMEA-01';

  const allRevs = [];
  (fmeaData.revisions || []).forEach(r => allRevs.push({ rev: r, fmeaType: 'DFMEA', pfmeaId: null }));
  (fmeaData.pfmeas || []).forEach(p => {
    (p.revisions || []).forEach(r => allRevs.push({ rev: r, fmeaType: 'PFMEA', pfmeaId: p.id, pfmeaName: p.name }));
  });

  let changed = false;
  allRevs.forEach(({ rev, fmeaType, pfmeaId, pfmeaName }) => {
    const isPending = (rev.status === 'Pending Approval') || (rev.approvalRequest && rev.status !== 'Frozen');
    const isFrozen = (rev.status === 'Frozen');
    const isRejected = (rev.status === 'Rejected / Rework Required');

    if (isPending || isFrozen || isRejected || rev.approvalRequest) {
      let logId = (rev.approvalRequest && rev.approvalRequest.logId) ? rev.approvalRequest.logId : `LOG-${rev.id}`;
      let existing = logs.find(l => String(l.id) === String(logId) || String(l.revisionId) === String(rev.id));

      const appReq = rev.approvalRequest || {};
      const approverObj = appReq.approver || (rev.approvedBy ? { name: rev.approvedBy.name, role: rev.approvedBy.role || 'Approver', email: rev.approvedBy.email || '' } : { name: 'Quality Manager', role: 'Approver', email: '' });
      const requestedByObj = appReq.requestedBy || { name: rev.creator || 'Author', role: 'Engineer', email: '' };

      const status = isFrozen ? 'Approved' : (isRejected ? 'Rejected' : 'Pending');
      const targetFmeaName = pfmeaName ? `${fmeaProjectName} (${pfmeaName})` : fmeaProjectName;

      const directLinkUrl = `${cfg.webBaseUrl}?action=review_revision_approval&logId=${encodeURIComponent(logId)}&file=${encodeURIComponent(activeSharePointFileName || '')}&revId=${encodeURIComponent(rev.id)}&fmeaType=${encodeURIComponent(fmeaType)}`;
      const desktopProtocolUrl = `${cfg.protocolScheme}review?logId=${encodeURIComponent(logId)}&file=${encodeURIComponent(activeSharePointFileName || '')}&revId=${encodeURIComponent(rev.id)}`;

      if (!existing) {
        const newEntry = {
          id: logId,
          fmeaId: fmeaNum,
          fmeaType: fmeaType,
          fmeaName: targetFmeaName,
          filePath: activeSharePointFileName || '',
          revisionId: rev.id,
          revisionNumber: rev.revNumber,
          changeDescription: rev.description || 'Revision freeze verification',
          requestedBy: requestedByObj,
          approver: approverObj,
          adminNotificationSent: true,
          status: status,
          requestTimestamp: appReq.requestedDate || rev.createdDate || new Date().toISOString(),
          decisionTimestamp: isFrozen ? (rev.freezeDate || new Date().toISOString()) : (isRejected ? (rev.rejectionDate || new Date().toISOString()) : null),
          decisionBy: rev.approvedBy || null,
          notes: appReq.notes || '',
          comments: rev.approvalComments || '',
          directLinkUrl: directLinkUrl,
          desktopProtocolUrl: desktopProtocolUrl,
          reminderCount: rev.reminderCount || 0
        };
        logs.unshift(newEntry);
        changed = true;
      } else {
        let itemChanged = false;
        if (existing.status !== status) {
          existing.status = status;
          itemChanged = true;
        }
        if (isFrozen && !existing.decisionTimestamp) {
          existing.decisionTimestamp = rev.freezeDate || new Date().toISOString();
          existing.decisionBy = rev.approvedBy;
          itemChanged = true;
        }
        if (rev.approvalComments && existing.comments !== rev.approvalComments) {
          existing.comments = rev.approvalComments;
          itemChanged = true;
        }
        if (appReq.approver && (!existing.approver || existing.approver.name !== appReq.approver.name)) {
          existing.approver = appReq.approver;
          itemChanged = true;
        }
        if (itemChanged) changed = true;
      }
    }
  });

  if (changed) {
    if (logs.length > 500) logs = logs.slice(0, 500);
    try {
      localStorage.setItem('jost_shared_approval_logs', JSON.stringify(logs));
    } catch (e) {}
  }
  return logs.sort((a, b) => new Date(b.requestTimestamp || 0) - new Date(a.requestTimestamp || 0));
}

function getSharedApprovalLogs() {
  return syncRevisionApprovalLogs();
}

function saveSharedApprovalLogEntry(entry) {
  try {
    let logs = getSharedApprovalLogs();
    const existingIdx = logs.findIndex(l => l.id === entry.id);
    if (existingIdx !== -1) {
      logs[existingIdx] = entry;
    } else {
      logs.unshift(entry);
    }
    // Limit to latest 500 records
    if (logs.length > 500) logs = logs.slice(0, 500);
    localStorage.setItem('jost_shared_approval_logs', JSON.stringify(logs));
    updateNavbarNotificationBellUI();
    return true;
  } catch (err) {
    console.error('Error saving shared approval log:', err);
    return false;
  }
}

function getSharedApprovalLogById(logId) {
  if (!logId) return null;
  const logs = getSharedApprovalLogs();
  return logs.find(l => String(l.id) === String(logId)) || null;
}

function updateSharedApprovalLogStatus(logId, status, decisionBy, comments) {
  if (!logId) return null;
  let logs = getSharedApprovalLogs();
  const item = logs.find(l => String(l.id) === String(logId));
  if (item) {
    item.status = status;
    item.decisionTimestamp = new Date().toISOString();
    item.decisionBy = decisionBy ? {
      username: decisionBy.username || '',
      name: decisionBy.name || '',
      email: decisionBy.email || '',
      role: decisionBy.role || ''
    } : null;
    item.comments = comments || '';
    localStorage.setItem('jost_shared_approval_logs', JSON.stringify(logs));
    updateNavbarNotificationBellUI();
    return item;
  }
  return null;
}

function isUserSystemAdmin(user = null) {
  const u = user || currentUser;
  if (!u) return false;
  const role = String(u.role || '').toLowerCase().trim();
  const uname = String(u.username || '').toLowerCase().trim();
  return role === 'admin' || role === 'system admin' || role === 'administrator' || role.includes('admin') || uname === 'admin' || u.isSystemAdmin === true;
}

function getPendingApprovalsForUser(user = null) {
  const u = user || currentUser;
  if (!u) return [];
  const logs = getSharedApprovalLogs();
  const pending = logs.filter(l => l.status === 'Pending');

  if (isUserSystemAdmin(u)) {
    return pending;
  }

  const uEmail = (u.email || '').toLowerCase().trim();
  const uName = (u.username || '').toLowerCase().trim();
  const uFullName = (u.name || '').toLowerCase().trim();
  const uId = String(u.id || u.username || '').toLowerCase().trim();

  return pending.filter(l => {
    if (!l.approver) return false;
    const appEmail = (l.approver.email || '').toLowerCase().trim();
    const appUsername = (l.approver.username || '').toLowerCase().trim();
    const appFullName = (l.approver.name || '').toLowerCase().trim();
    const appId = String(l.approver.id || l.approver.username || '').toLowerCase().trim();
    return (uEmail && uEmail === appEmail) ||
           (uName && uName === appUsername) ||
           (uFullName && uFullName === appFullName) ||
           (uId && uId === appId);
  });
}

function checkUserApprovalPermission(curRev) {
  if (!currentUser) return false;
  if (isUserSystemAdmin(currentUser)) return true;
  if (!curRev || !curRev.approvalRequest || !curRev.approvalRequest.approver) return false;

  const app = curRev.approvalRequest.approver;
  const curEmail = (currentUser.email || '').toLowerCase().trim();
  const curUsername = (currentUser.username || '').toLowerCase().trim();
  const curFullName = (currentUser.name || '').toLowerCase().trim();
  const curId = String(currentUser.id || currentUser.username || '').toLowerCase().trim();

  const appEmail = (app.email || '').toLowerCase().trim();
  const appUsername = (app.username || '').toLowerCase().trim();
  const appFullName = (app.name || '').toLowerCase().trim();
  const appId = String(app.id || app.username || '').toLowerCase().trim();

  return (curEmail && curEmail === appEmail) ||
         (curUsername && curUsername === appUsername) ||
         (curFullName && curFullName === appFullName) ||
         (curId && curId === appId);
}

// 3. Directory Approver Selection & Reassignment
let _pendingFreezeRev = null;
let _selectedApproverUserId = null;
let _isRevisingApproverMode = false;

function getApproverInitials(name) {
  if (!name) return 'AP';
  const parts = name.trim().split(/\s+/);
  if (parts.length === 1) return parts[0].substring(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

function showApproverDropdownMenu(show = true) {
  const container = document.getElementById('approverDirectoryListContainer');
  const btn = document.getElementById('btnToggleApproverDropdown');
  if (container) {
    container.style.display = show ? 'block' : 'none';
  }
  if (btn) {
    btn.innerHTML = show ? '<span>▲</span>' : '<span>▼</span>';
  }
}

function toggleApproverDropdownMenu(e) {
  if (e && typeof e.stopPropagation === 'function') e.stopPropagation();
  const container = document.getElementById('approverDirectoryListContainer');
  if (!container) return;
  const isVisible = container.style.display === 'block';
  showApproverDropdownMenu(!isVisible);
  if (!isVisible) {
    const searchInput = document.getElementById('approverSearchInput');
    if (searchInput) {
      searchInput.focus();
      filterApproverDirectoryList(searchInput.value || '');
    }
  }
}

function renderSelectedApproverSummaryCard() {
  const card = document.getElementById('selectedApproverSummaryCard');
  if (!card) return;

  const users = (typeof systemUsers !== 'undefined' && Array.isArray(systemUsers) && systemUsers.length > 0)
    ? systemUsers
    : (typeof DEFAULT_USER_LIBRARY !== 'undefined' && Array.isArray(DEFAULT_USER_LIBRARY) ? DEFAULT_USER_LIBRARY : []);

  const selectedUser = users.find(u => String(u.id || u.username) === String(_selectedApproverUserId));

  if (!selectedUser) {
    card.style.borderColor = '#cbd5e1';
    card.style.background = '#f8fafc';
    card.innerHTML = `
      <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px;">
        <div style="display:flex; align-items:center; gap:8px; color:#64748b; font-size:12px;">
          <span style="font-size:16px;">👤</span>
          <span>No Approver selected yet. Type in search or select from dropdown list.</span>
        </div>
        <button type="button" onclick="showApproverDropdownMenu(true)" style="background:#0284c7; color:#fff; border:none; padding:4px 10px; border-radius:4px; font-size:11px; font-weight:600; cursor:pointer;">
          Browse Users
        </button>
      </div>
    `;
    return;
  }

  const initials = getApproverInitials(selectedUser.name || selectedUser.username);
  const roleText = selectedUser.role || 'Designated Approver';
  const deptText = [selectedUser.department, selectedUser.plant].filter(Boolean).join(' • ');

  card.style.borderColor = '#38bdf8';
  card.style.background = 'linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%)';
  card.innerHTML = `
    <div style="display:flex; align-items:center; justify-content:space-between; gap:10px;">
      <div style="display:flex; align-items:center; gap:10px; min-width:0;">
        <div class="approver-avatar-circle" style="width:36px; height:36px; min-width:36px; font-size:13px; background:linear-gradient(135deg, #0284c7, #2563eb);">${escapeHtml(initials)}</div>
        <div style="min-width:0;">
          <div style="font-weight:700; font-size:12.5px; color:#0f172a; display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
            <span>${escapeHtml(selectedUser.name || selectedUser.username)}</span>
            <span style="font-size:10px; padding:1px 6px; border-radius:10px; background:#0284c7; color:#fff; font-weight:700;">${escapeHtml(roleText)}</span>
          </div>
          <div style="font-size:11px; color:#475569; margin-top:2px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
            ✉️ ${escapeHtml(selectedUser.email || 'No email registered')} ${deptText ? `· 🏢 ${escapeHtml(deptText)}` : ''}
          </div>
        </div>
      </div>
      <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;">
        <span style="font-size:11px; font-weight:700; color:#15803d; background:#dcfce7; border:1px solid #86efac; padding:3px 8px; border-radius:12px;">
          ✓ Designated Approver
        </span>
        <button type="button" onclick="toggleApproverDropdownMenu(event)" title="Change Approver" style="background:#fff; border:1px solid #cbd5e1; color:#0284c7; padding:4px 8px; border-radius:4px; font-size:11px; font-weight:600; cursor:pointer;">
          🔄 Change
        </button>
      </div>
    </div>
  `;
}

function openSelectRevisionApproverModal(curRev = null) {
  if (!curRev) curRev = getContextRevision();
  if (!curRev) {
    alert('No active revision found.');
    return;
  }
  _pendingFreezeRev = curRev;
  _isRevisingApproverMode = false;
  _selectedApproverUserId = null;

  const titleEl = document.getElementById('modalSelectApproverTitle');
  const subtitleEl = document.getElementById('modalSelectApproverSubtitle');
  const searchInput = document.getElementById('approverSearchInput');
  const remarksInput = document.getElementById('submissionRemarksToApprover');
  const submitBtn = document.getElementById('btnSubmitRevisionForApproval');
  const noticeEl = document.getElementById('modalSelectApproverNotice');
  const noticeIcon = document.getElementById('modalSelectApproverNoticeIcon');
  const noticeText = document.getElementById('modalSelectApproverNoticeText');

  if (titleEl) titleEl.innerText = `Submit Revision ${curRev.revNumber} for Approval`;
  if (subtitleEl) subtitleEl.innerText = `Select an authorized Approver from directory for ${curRev.fmeaType || 'DFMEA'}`;
  if (searchInput) searchInput.value = '';
  if (remarksInput) {
    remarksInput.value = '';
    remarksInput.placeholder = 'Explain reason for changes or key verification highlights...';
  }
  if (submitBtn) submitBtn.innerHTML = '🚀 Submit for Sign-off';

  if (noticeEl) {
    noticeEl.style.background = '#f0fdf4';
    noticeEl.style.borderColor = '#bbf7d0';
    noticeEl.style.color = '#166534';
  }
  if (noticeIcon) noticeIcon.innerText = '✓';
  if (noticeText) {
    noticeText.innerHTML = `Output Verification Checklist is <strong>100% Complete</strong>. Please designate an Approver for final sign-off.`;
  }

  showApproverDropdownMenu(false);
  filterApproverDirectoryList('');
  renderSelectedApproverSummaryCard();
  openModal('modalSelectRevisionApprover');
}

function openReviseApproverModal(revId = null, fmeaType = null, pfmeaId = null) {
  let targetRev = null;
  if (revId) {
    if (fmeaType === 'PFMEA' && pfmeaId) {
      const pfmea = (fmeaData.pfmeas || []).find(p => String(p.id) === String(pfmeaId));
      if (pfmea) targetRev = (pfmea.revisions || []).find(r => String(r.id) === String(revId));
    } else {
      targetRev = (fmeaData.revisions || []).find(r => String(r.id) === String(revId));
    }
  }
  if (!targetRev) targetRev = getContextRevision();
  if (!targetRev) {
    alert('Target revision not found.');
    return;
  }
  if (targetRev.status === 'Frozen') {
    alert('This revision is already frozen. Approver cannot be changed.');
    return;
  }

  _pendingFreezeRev = targetRev;
  _isRevisingApproverMode = true;

  const titleEl = document.getElementById('modalSelectApproverTitle');
  const subtitleEl = document.getElementById('modalSelectApproverSubtitle');
  const searchInput = document.getElementById('approverSearchInput');
  const remarksInput = document.getElementById('submissionRemarksToApprover');
  const submitBtn = document.getElementById('btnSubmitRevisionForApproval');
  const noticeEl = document.getElementById('modalSelectApproverNotice');
  const noticeIcon = document.getElementById('modalSelectApproverNoticeIcon');
  const noticeText = document.getElementById('modalSelectApproverNoticeText');

  if (titleEl) titleEl.innerText = `🔄 Change / Revise Approver for Revision ${targetRev.revNumber}`;
  if (subtitleEl) subtitleEl.innerText = `Reassign designated Approver for ${targetRev.fmeaType || 'DFMEA'}`;
  if (searchInput) searchInput.value = '';

  const appReq = targetRev.approvalRequest || {};
  if (remarksInput) {
    remarksInput.value = appReq.notes || '';
    remarksInput.placeholder = 'Add or update remarks for the newly assigned approver...';
  }

  if (submitBtn) submitBtn.innerHTML = '🔄 Update Approver &amp; Notify';

  if (noticeEl) {
    noticeEl.style.background = '#eff6ff';
    noticeEl.style.borderColor = '#bfdbfe';
    noticeEl.style.color = '#1e40af';
  }
  if (noticeIcon) noticeIcon.innerText = '🔄';
  if (noticeText) {
    const prevName = appReq.approver ? appReq.approver.name : 'current approver';
    noticeText.innerHTML = `Currently assigned to <strong>${escapeHtml(prevName)}</strong>. Select a new Approver below to reassign and notify via email.`;
  }

  if (appReq.approver && (appReq.approver.id || appReq.approver.username)) {
    _selectedApproverUserId = appReq.approver.id || appReq.approver.username;
    if (searchInput && appReq.approver.name) {
      searchInput.value = appReq.approver.name;
    }
  } else {
    _selectedApproverUserId = null;
  }

  showApproverDropdownMenu(false);
  filterApproverDirectoryList('');
  renderSelectedApproverSummaryCard();
  openModal('modalSelectRevisionApprover');
}

function openReviseApproverFromLog(logId) {
  const log = getSharedApprovalLogById(logId);
  if (!log) {
    alert('Approval request log not found.');
    return;
  }
  if (log.status !== 'Pending') {
    alert(`This revision has already been ${log.status}. Approver cannot be changed.`);
    return;
  }
  openReviseApproverModal(log.revisionId, log.fmeaType, null);
}

function openReviseApproverFromCurrentChecklist() {
  const cur = getActiveChecklistModalRevision();
  if (!cur) return;
  openReviseApproverModal(cur.id, cur.fmeaType, cur.pfmeaId);
}

function filterApproverDirectoryList(query = '') {
  const container = document.getElementById('approverDirectoryListContainer');
  if (!container) return;

  const users = (typeof systemUsers !== 'undefined' && Array.isArray(systemUsers) && systemUsers.length > 0)
    ? systemUsers
    : (typeof DEFAULT_USER_LIBRARY !== 'undefined' && Array.isArray(DEFAULT_USER_LIBRARY) ? DEFAULT_USER_LIBRARY : []);

  const q = (query || '').toLowerCase().trim();
  const filtered = users.filter(u => {
    if (!u) return false;
    // Don't show readonly user in approver selector
    if (u.username === 'readonly') return false;
    if (!q) return true;
    const nameMatch = (u.name || '').toLowerCase().includes(q);
    const roleMatch = (u.role || '').toLowerCase().includes(q);
    const emailMatch = (u.email || '').toLowerCase().includes(q);
    const deptMatch = (u.department || '').toLowerCase().includes(q);
    const plantMatch = (u.plant || '').toLowerCase().includes(q);
    return nameMatch || roleMatch || emailMatch || deptMatch || plantMatch;
  });

  const countBadge = document.getElementById('approverDirectoryCountBadge');
  if (countBadge) {
    countBadge.innerText = `${filtered.length} user${filtered.length === 1 ? '' : 's'} found`;
  }

  if (filtered.length === 0) {
    container.innerHTML = `<div style="padding:14px; text-align:center; color:#94a3b8; font-size:12px;">No matching directory users found for "${escapeHtml(q)}".</div>`;
    return;
  }

  // Pre-select priority approver if nothing is selected
  if (!_selectedApproverUserId && filtered.length > 0) {
    const priorityUser = filtered.find(u => {
      const r = (u.role || '').toLowerCase();
      return r.includes('quality') || r.includes('product leader') || r.includes('manager') || r.includes('lead');
    }) || filtered[0];
    _selectedApproverUserId = priorityUser.id || priorityUser.username;
  }

  let html = '';
  filtered.forEach(u => {
    const uId = u.id || u.username;
    const isSelected = String(_selectedApproverUserId) === String(uId);
    const initials = getApproverInitials(u.name || u.username);
    const roleBadge = u.role ? `<span style="font-size:10px; padding:1px 6px; border-radius:10px; background:#e0f2fe; color:#0369a1; font-weight:700;">${escapeHtml(u.role)}</span>` : '';
    const deptText = [u.department, u.plant].filter(Boolean).join(' • ');

    html += `
      <div class="approver-dropdown-item ${isSelected ? 'selected' : ''}" onclick="selectApproverDirectoryItem('${escapeHtml(String(uId))}')" style="display:flex; align-items:center; justify-content:space-between; padding:8px 10px; margin-bottom:3px; border-radius:6px; cursor:pointer; border:1.5px solid ${isSelected ? '#0284c7' : '#f1f5f9'}; background:${isSelected ? '#f0f9ff' : '#fff'}; transition:all 0.15s ease-in-out;">
        <div style="display:flex; align-items:center; gap:10px; min-width:0;">
          <div class="approver-avatar-circle" style="width:30px; height:30px; min-width:30px; font-size:11px; background:${isSelected ? 'linear-gradient(135deg, #0284c7, #2563eb)' : '#64748b'};">${escapeHtml(initials)}</div>
          <div style="min-width:0;">
            <div style="font-weight:700; font-size:12px; color:#0f172a; display:flex; align-items:center; gap:6px;">
              <span>${escapeHtml(u.name || u.username)}</span>
              ${roleBadge}
            </div>
            <div style="font-size:11px; color:#64748b; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
              ✉️ ${escapeHtml(u.email || 'No email registered')} ${deptText ? `· 🏢 ${escapeHtml(deptText)}` : ''}
            </div>
          </div>
        </div>
        <div style="font-size:11px; color:#0284c7; font-weight:700; flex-shrink:0; padding-left:8px;">
          ${isSelected ? '<span style="background:#0284c7; color:#fff; padding:2px 8px; border-radius:10px; font-size:10px;">✓ Selected</span>' : '<span style="color:#94a3b8; font-size:10px; border:1px solid #cbd5e1; padding:2px 6px; border-radius:4px;">Select</span>'}
        </div>
      </div>
    `;
  });

  container.innerHTML = html;
}

function selectApproverDirectoryItem(userId) {
  _selectedApproverUserId = userId;
  const searchInput = document.getElementById('approverSearchInput');
  const users = (typeof systemUsers !== 'undefined' && Array.isArray(systemUsers) && systemUsers.length > 0)
    ? systemUsers
    : (typeof DEFAULT_USER_LIBRARY !== 'undefined' && Array.isArray(DEFAULT_USER_LIBRARY) ? DEFAULT_USER_LIBRARY : []);
  const selectedUser = users.find(u => String(u.id || u.username) === String(userId));
  if (selectedUser && searchInput) {
    searchInput.value = selectedUser.name || selectedUser.username;
  }
  filterApproverDirectoryList('');
  renderSelectedApproverSummaryCard();
  showApproverDropdownMenu(false);
}

// Close approver dropdown on outside click
if (typeof document !== 'undefined') {
  document.addEventListener('click', function(e) {
    const container = document.getElementById('approverDirectoryListContainer');
    const input = document.getElementById('approverSearchInput');
    const btn = document.getElementById('btnToggleApproverDropdown');
    if (container && container.style.display === 'block') {
      if (!container.contains(e.target) && e.target !== input && e.target !== btn && !(btn && btn.contains(e.target))) {
        showApproverDropdownMenu(false);
      }
    }
  });
}

async function submitRevisionForApproval() {
  if (!_pendingFreezeRev) {
    alert('No active revision pending submission.');
    return;
  }
  if (!_selectedApproverUserId) {
    alert('Please select an Approver from the directory.');
    return;
  }

  const users = (typeof systemUsers !== 'undefined' && Array.isArray(systemUsers) && systemUsers.length > 0)
    ? systemUsers
    : (typeof DEFAULT_USER_LIBRARY !== 'undefined' && Array.isArray(DEFAULT_USER_LIBRARY) ? DEFAULT_USER_LIBRARY : []);

  const approverUser = users.find(u => String(u.id || u.username) === String(_selectedApproverUserId));
  if (!approverUser) {
    alert('Selected approver not found in user directory.');
    return;
  }

  const cur = _pendingFreezeRev;
  const remarksInput = document.getElementById('submissionRemarksToApprover');
  const copyAdminChk = document.getElementById('chkCopyAdminOnApproval');
  const notes = remarksInput ? remarksInput.value.trim() : '';
  const copyAdmin = copyAdminChk ? copyAdminChk.checked : true;

  const isRevising = _isRevisingApproverMode;
  let logId = (cur.approvalRequest && cur.approvalRequest.logId) ? cur.approvalRequest.logId : null;
  if (!logId) {
    logId = `LOG-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Date.now().toString().slice(-4)}`;
  }

  const cfg = getRevisionApprovalConfig();

  const fmeaProjectName = (fmeaData && fmeaData.projectInfo && fmeaData.projectInfo.name)
    ? fmeaData.projectInfo.name
    : (activeSharePointFileName || 'FMEA Project');

  const requestedByObj = currentUser ? {
    id: currentUser.id || currentUser.username,
    username: currentUser.username,
    name: currentUser.name,
    email: currentUser.email || '',
    role: currentUser.role || 'Engineer'
  } : ((cur.approvalRequest && cur.approvalRequest.requestedBy) ? cur.approvalRequest.requestedBy : {
    id: 'author',
    username: 'author',
    name: cur.creator || 'FMEA Author',
    email: '',
    role: 'Engineer'
  });

  const approverObj = {
    id: approverUser.id || approverUser.username,
    username: approverUser.username,
    name: approverUser.name,
    email: approverUser.email || '',
    role: approverUser.role || 'Quality Manager'
  };

  const directLinkUrl = `${cfg.webBaseUrl}?action=review_revision_approval&logId=${encodeURIComponent(logId)}&file=${encodeURIComponent(activeSharePointFileName || '')}&revId=${encodeURIComponent(cur.id)}&fmeaType=${encodeURIComponent(cur.fmeaType || 'DFMEA')}`;
  const desktopProtocolUrl = `${cfg.protocolScheme}review?logId=${encodeURIComponent(logId)}&file=${encodeURIComponent(activeSharePointFileName || '')}&revId=${encodeURIComponent(cur.id)}`;

  const logEntry = {
    id: logId,
    fmeaId: (fmeaData && fmeaData.projectInfo && fmeaData.projectInfo.fmeaNumber) ? fmeaData.projectInfo.fmeaNumber : 'FMEA-01',
    fmeaType: cur.fmeaType || 'DFMEA',
    fmeaName: fmeaProjectName,
    filePath: activeSharePointFileName || '',
    revisionId: cur.id,
    revisionNumber: cur.revNumber,
    changeDescription: cur.description || 'Revision freeze verification',
    requestedBy: requestedByObj,
    approver: approverObj,
    adminNotificationSent: copyAdmin,
    status: 'Pending',
    requestTimestamp: (cur.approvalRequest && cur.approvalRequest.requestedDate) ? cur.approvalRequest.requestedDate : new Date().toISOString(),
    lastReassignedTimestamp: isRevising ? new Date().toISOString() : null,
    notes: notes,
    directLinkUrl: directLinkUrl,
    desktopProtocolUrl: desktopProtocolUrl
  };

  // Update active revision object
  cur.status = 'Pending Approval';
  cur.approvalRequest = {
    logId: logId,
    requestedBy: requestedByObj,
    approver: approverObj,
    requestedDate: logEntry.requestTimestamp,
    lastReassignedDate: isRevising ? new Date().toISOString() : null,
    notes: notes,
    directLinkUrl: directLinkUrl
  };

  // Save to shared approval logs (replaces existing entry by logId or appends)
  saveSharedApprovalLogEntry(logEntry);

  // Dispatch Email Notification to newly designated approver
  dispatchApprovalRequestEmail(logEntry, isRevising);

  // Close modals & update UI
  closeModal('modalSelectRevisionApprover');
  closeModal('revisionChangeReportModal');
  _pendingFreezeRev = null;
  _isRevisingApproverMode = false;

  renderRevisionStatusUI();
  updateNavbarNotificationBellUI();
  renderFMEATable();
  if (typeof saveProjectToLocalStorage === 'function') saveProjectToLocalStorage();

  if (isRevising) {
    if (typeof showToast === 'function') {
      showToast(`🔄 Approver updated to ${approverUser.name}! Notification email prepared.`, 'info');
    } else {
      alert(`🔄 Approver updated to ${approverUser.name}! Notification email prepared.`);
    }
  } else {
    if (typeof showToast === 'function') {
      showToast(`🚀 Revision ${cur.revNumber} submitted for approval to ${approverUser.name}! Notification email prepared.`);
    } else {
      alert(`🚀 Revision ${cur.revNumber} submitted for approval to ${approverUser.name}!`);
    }
  }
}

// 4. Decision Handling: Accept (Approve) & Reject (Rework)
async function handleApproverDecision(decision) {
  const cur = getActiveChecklistModalRevision();
  if (!cur) {
    alert('No active revision found.');
    return;
  }

  const isAuthorized = checkUserApprovalPermission(cur);
  if (!isAuthorized) {
    alert('⚠️ Unauthorized: Only the designated approver or an Administrator can sign-off or reject this revision.');
    return;
  }

  const commentsInput = document.getElementById('modalChecklistReviewerComments');
  const comments = commentsInput ? commentsInput.value.trim() : '';

  if (decision === 'REJECT') {
    if (!comments) {
      alert('⚠️ Rejection Reason Required:\n\nPlease enter comments/remarks explaining why the revision is rejected and what rework is required before proceeding.');
      if (commentsInput) commentsInput.focus();
      return;
    }

    const confirmed = await showCustomConfirm(
      `Reject Revision ${cur.revNumber} and request rework?\n\nReview remarks will be emailed to the file author and team. The revision will remain open for edits.`,
      'Confirm Rejection',
      'warning'
    );
    if (!confirmed) return;

    cur.status = 'Rejected / Rework Required';
    cur.approvalComments = comments;
    cur.rejectionDate = new Date().toLocaleString();

    const logId = cur.approvalRequest ? cur.approvalRequest.logId : null;
    if (logId) {
      updateSharedApprovalLogStatus(logId, 'Rejected', currentUser, comments);
    }

    dispatchApprovalDecisionEmail(cur, 'Rejected', comments);

    closeOutputChecklistVerificationModal();
    renderRevisionStatusUI();
    renderFMEATable();
    if (typeof saveProjectToLocalStorage === 'function') saveProjectToLocalStorage();

    if (typeof showToast === 'function') {
      showToast(`❌ Revision ${cur.revNumber} marked as Rejected / Rework Required. Feedback sent to author.`);
    } else {
      alert(`❌ Revision ${cur.revNumber} marked as Rejected.`);
    }
    return;
  }

  if (decision === 'APPROVE') {
    const confirmed = await showCustomConfirm(
      `Confirm Sign-off & Freeze for Revision ${cur.revNumber}?\n\nOnce approved, this revision will be officially FROZEN and baseline snapshot recorded permanently.`,
      'Approve & Freeze Revision',
      'warning'
    );
    if (!confirmed) return;

    cur.status = 'Frozen';
    cur.freezeDate = new Date().toLocaleString();
    cur.approvedBy = currentUser ? {
      name: currentUser.name,
      username: currentUser.username,
      email: currentUser.email,
      role: currentUser.role
    } : { name: 'Approver' };
    cur.approvalComments = comments;

    const logId = cur.approvalRequest ? cur.approvalRequest.logId : null;
    if (logId) {
      updateSharedApprovalLogStatus(logId, 'Approved', currentUser, comments);
    }

    // Execute standard freeze snapshot & baseline
    executeFreezeCurrentRevision();

    // Dispatch approval confirmation email
    dispatchApprovalDecisionEmail(cur, 'Approved', comments);

    closeOutputChecklistVerificationModal();
    updateNavbarNotificationBellUI();

    if (typeof showToast === 'function') {
      showToast(`🎉 Revision ${cur.revNumber} successfully APPROVED & FROZEN! Baseline snapshot recorded.`);
    } else {
      alert(`🎉 Revision ${cur.revNumber} successfully APPROVED & FROZEN!`);
    }
  }
}

// 5. Notification Email Dispatchers with Dual Links
function dispatchApprovalRequestEmail(logEntry, isReassigned = false) {
  if (!logEntry) return;

  const approverEmail = (logEntry.approver && logEntry.approver.email) ? logEntry.approver.email : '';
  const adminEmails = getAllSystemAdminEmails();

  const recipientEmails = new Set();
  if (approverEmail) recipientEmails.add(approverEmail);

  // By default, System Administrators always receive approval notifications & links
  adminEmails.forEach(e => recipientEmails.add(e));

  if (recipientEmails.size === 0) {
    console.warn('No recipient emails found for approval request notification.');
    return;
  }

  const subject = isReassigned
    ? `🔄 [Approval Reassigned] FMEA Revision Sign-off: ${logEntry.fmeaName} (${logEntry.revisionNumber})`
    : `[Approval Required] FMEA Revision Sign-off: ${logEntry.fmeaName} (${logEntry.revisionNumber})`;

  const introText = isReassigned
    ? `This FMEA revision sign-off request has been REASSIGNED to you as the designated Approver (and copy to System Administrators):`
    : `A new FMEA revision has completed 100% Output Checklist verification and requires sign-off approval:`;

  const bodyLines = [
    `Dear ${logEntry.approver.name || 'Approver'} / System Administrator,`,
    ``,
    introText,
    `----------------------------------------------------------------------`,
    ` • Project Name:        ${logEntry.fmeaName}`,
    ` • FMEA Type:           ${logEntry.fmeaType}`,
    ` • Revision:            ${logEntry.revisionNumber}`,
    ` • Designated Approver: ${logEntry.approver ? logEntry.approver.name : 'Approver'} (${logEntry.approver ? logEntry.approver.role : 'Approver'})`,
    ` • Submitted By:        ${logEntry.requestedBy ? logEntry.requestedBy.name : 'Author'} (${logEntry.requestedBy ? logEntry.requestedBy.role : 'User'})`,
    ` • Submission Notes:    ${logEntry.notes || 'None'}`,
    ` • Checklist Status:    100% Verified (30/30 Checkpoints)`,
    ` • Timestamp:           ${new Date(logEntry.requestTimestamp).toLocaleString()}`,
    `----------------------------------------------------------------------`,
    ``,
    `HOW TO REVIEW & SIGN-OFF / APPROVE:`,
    `1. Launch Desktop Application directly:`,
    `   ${logEntry.desktopProtocolUrl}`,
    ``,
    `2. Or open in Web Browser:`,
    `   ${logEntry.directLinkUrl}`,
    ``,
    `3. Or open JOST FMEA Workbench, log in, and click the Bell (🔔) notification icon in the top menu bar or the Shared Approval Logs.`,
    ``,
    `[ADMIN NOTICE]: As a System Administrator, you have full global authority to review, approve/freeze, or reject any pending revision request across all FMEAs.`,
    ``,
    `Best Regards,`,
    `JOST FMEA Workbench Enterprise Suite`
  ];

  const bodyText = bodyLines.join('\r\n');
  const mailtoUrl = `mailto:${encodeURIComponent(Array.from(recipientEmails).join(';'))}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bodyText)}`;

  if (window.electronAPI && window.electronAPI.openExternalUrl) {
    window.electronAPI.openExternalUrl(mailtoUrl).catch(() => { window.location.href = mailtoUrl; });
  } else {
    window.location.href = mailtoUrl;
  }
}

function dispatchApprovalReminderEmail(logEntry) {
  if (!logEntry) return;

  const approver = logEntry.approver || {};
  const recipientEmails = new Set();

  if (approver.email) {
    recipientEmails.add(approver.email);
  }

  // By default, System Administrators are always included in reminder notifications
  const adminEmails = getAllSystemAdminEmails();
  adminEmails.forEach(e => recipientEmails.add(e));

  if (recipientEmails.size === 0) {
    alert(`Cannot send reminder: No valid email address registered for approver ${approver.name || 'User'} or admin.`);
    return;
  }

  const subject = `🔔 [REMINDER] Pending Approval Required: ${logEntry.fmeaName} (${logEntry.revisionNumber || 'Rev'})`;

  const reqTimeStr = logEntry.requestTimestamp ? new Date(logEntry.requestTimestamp).toLocaleString() : 'N/A';
  const reminderCount = (logEntry.reminderCount || 0) + 1;

  const bodyLines = [
    `Dear ${approver.name || 'Approver'} / System Administrator,`,
    ``,
    `This is a friendly reminder (Reminder #${reminderCount}) that the following FMEA revision sign-off is awaiting review and approval:`,
    `----------------------------------------------------------------------`,
    ` • Project Name:        ${logEntry.fmeaName}`,
    ` • FMEA Type:           ${logEntry.fmeaType}`,
    ` • Revision:            ${logEntry.revisionNumber || 'Rev'}`,
    ` • Designated Approver: ${approver.name || 'Approver'} (${approver.role || 'Approver'})`,
    ` • Submitted By:        ${logEntry.requestedBy ? logEntry.requestedBy.name : 'Author'} (${logEntry.requestedBy ? logEntry.requestedBy.role : 'User'})`,
    ` • Original Submission: ${reqTimeStr}`,
    ` • Submission Notes:    ${logEntry.notes || 'None'}`,
    ` • Status:              Pending Approval Sign-off`,
    `----------------------------------------------------------------------`,
    ``,
    `HOW TO REVIEW & SIGN-OFF / APPROVE:`,
    `1. Launch Desktop Application directly:`,
    `   ${logEntry.desktopProtocolUrl || 'jost-fmea://'}`,
    ``,
    `2. Or open in Web Browser:`,
    `   ${logEntry.directLinkUrl || window.location.origin}`,
    ``,
    `3. Or open JOST FMEA Workbench, log in, and click the Bell (🔔) notification icon in the top menu bar.`,
    ``,
    `[ADMIN NOTICE]: System Administrators can review and freeze or reject this revision directly via the links above or from the Shared Approval Log.`,
    ``,
    `Thank you,`,
    `JOST FMEA Workbench Enterprise Suite`
  ];

  const bodyText = bodyLines.join('\r\n');
  const mailtoUrl = `mailto:${encodeURIComponent(Array.from(recipientEmails).join(';'))}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bodyText)}`;

  // Update reminder metadata in shared logs
  try {
    const logs = getSharedApprovalLogs();
    const target = logs.find(l => String(l.id) === String(logEntry.id));
    if (target) {
      target.reminderCount = reminderCount;
      target.lastReminderTimestamp = new Date().toISOString();
      localStorage.setItem('jost_shared_approval_logs', JSON.stringify(logs));
    }
  } catch (e) {
    console.warn('Error updating reminder timestamp in shared logs:', e);
  }

  if (window.electronAPI && window.electronAPI.openExternalUrl) {
    window.electronAPI.openExternalUrl(mailtoUrl).catch(() => { window.location.href = mailtoUrl; });
  } else {
    window.location.href = mailtoUrl;
  }

  if (typeof showToast === 'function') {
    showToast(`🔔 Reminder #${reminderCount} prepared for ${approver.name || 'Approver'} & Admin`, 'info');
  } else {
    alert(`🔔 Reminder #${reminderCount} prepared for ${approver.name || 'Approver'} & Admin via default email client.`);
  }
}

function sendApprovalReminderFromLog(logId) {
  const log = getSharedApprovalLogById(logId);
  if (!log) {
    alert('Approval request log not found.');
    return;
  }
  if (log.status !== 'Pending') {
    alert(`This approval request has already been ${log.status}. No reminder needed.`);
    return;
  }
  dispatchApprovalReminderEmail(log);
  if (typeof renderSharedApprovalLogsTable === 'function') {
    renderSharedApprovalLogsTable();
  }
}

function sendApprovalReminderForRevision(revId, fmeaType, pfmeaId) {
  let targetRev = null;
  if (fmeaType === 'PFMEA' && pfmeaId) {
    const pfmea = (fmeaData.pfmeas || []).find(p => String(p.id) === String(pfmeaId));
    if (pfmea) targetRev = (pfmea.revisions || []).find(r => String(r.id) === String(revId));
  } else {
    targetRev = (fmeaData.revisions || []).find(r => String(r.id) === String(revId));
  }
  if (!targetRev) {
    alert('Target revision not found.');
    return;
  }

  // Find corresponding pending shared log
  const logs = getSharedApprovalLogs();
  let log = logs.find(l => l.revisionId === revId && l.status === 'Pending');
  if (!log) {
    log = logs.find(l => l.revisionNumber === targetRev.revNumber && l.status === 'Pending');
  }

  if (log) {
    dispatchApprovalReminderEmail(log);
    return;
  }

  // If not found in log, construct from revision approvalRequest if available
  const appReq = targetRev.approvalRequest;
  if (appReq && appReq.approver) {
    const fmeaName = (fmeaData && fmeaData.projectInfo && fmeaData.projectInfo.name)
      ? fmeaData.projectInfo.name
      : (activeSharePointFileName || 'FMEA Project');

    const cfg = getRevisionApprovalConfig();
    const tempLog = {
      id: targetRev.id,
      fmeaName: fmeaName,
      fmeaType: fmeaType || 'DFMEA',
      revisionNumber: targetRev.revNumber,
      requestedBy: appReq.requestedBy || { name: targetRev.creator || 'Author' },
      approver: appReq.approver,
      requestTimestamp: appReq.requestedDate || targetRev.createdDate,
      notes: appReq.notes || '',
      desktopProtocolUrl: `${cfg.protocolScheme}review?logId=${encodeURIComponent(targetRev.id)}&file=${encodeURIComponent(activeSharePointFileName || '')}&revId=${encodeURIComponent(targetRev.id)}`,
      directLinkUrl: `${cfg.webBaseUrl}?action=review_revision_approval&logId=${encodeURIComponent(targetRev.id)}&file=${encodeURIComponent(activeSharePointFileName || '')}&revId=${encodeURIComponent(targetRev.id)}`
    };
    dispatchApprovalReminderEmail(tempLog);
  } else {
    alert('No pending approver information found for this revision.');
  }
}

function sendApprovalReminderFromCurrentChecklist() {
  const cur = getActiveChecklistModalRevision();
  if (!cur) return;
  if (_activeApprovalLogId) {
    sendApprovalReminderFromLog(_activeApprovalLogId);
  } else {
    sendApprovalReminderForRevision(cur.id, cur.fmeaType, cur.pfmeaId);
  }
}

function dispatchApprovalDecisionEmail(curRev, decision, comments) {
  if (!curRev) return;

  const appReq = curRev.approvalRequest || {};
  const requestedBy = appReq.requestedBy || {};
  const recipientEmails = new Set();

  if (requestedBy.email) recipientEmails.add(requestedBy.email);

  // CC System Administrators on approval/rejection decisions
  const adminEmails = getAllSystemAdminEmails();
  adminEmails.forEach(e => recipientEmails.add(e));

  const fmeaProjectName = (fmeaData && fmeaData.projectInfo && fmeaData.projectInfo.name)
    ? fmeaData.projectInfo.name
    : (activeSharePointFileName || 'FMEA Project');

  const approverName = currentUser ? `${currentUser.name} (${currentUser.role})` : 'Designated Approver';

  const isApproved = (decision === 'Approved');
  const subject = isApproved
    ? `🎉 [Approved & Frozen] FMEA Revision: ${fmeaProjectName} (${curRev.revNumber})`
    : `⚠️ [Rework Required] FMEA Revision Rejected: ${fmeaProjectName} (${curRev.revNumber})`;

  const bodyLines = [
    `Dear ${requestedBy.name || 'FMEA Team'} / Administrator,`,
    ``,
    isApproved
      ? `The revision freeze request for ${fmeaProjectName} (${curRev.revNumber}) has been APPROVED and FROZEN.`
      : `The revision freeze request for ${fmeaProjectName} (${curRev.revNumber}) has been REJECTED and returned for rework.`,
    `----------------------------------------------------------------------`,
    ` • Project Name:     ${fmeaProjectName}`,
    ` • Revision:         ${curRev.revNumber}`,
    ` • Decision:         ${decision.toUpperCase()}`,
    ` • Reviewed By:      ${approverName}`,
    ` • Timestamp:        ${new Date().toLocaleString()}`,
    ` • Review Remarks:   ${comments || (isApproved ? 'All checkpoints verified and accepted.' : 'No additional comments.')}`,
    `----------------------------------------------------------------------`,
    ``,
    isApproved
      ? `The revision is now baseline locked and protected from further edits.`
      : `Please open the project in JOST FMEA Workbench, address the comments above, and re-submit the Output Checklist for freeze sign-off.`,
    ``,
    `Best Regards,`,
    `JOST FMEA Workbench Enterprise Suite`
  ];

  const bodyText = bodyLines.join('\r\n');
  if (recipientEmails.size > 0) {
    const mailtoUrl = `mailto:${encodeURIComponent(Array.from(recipientEmails).join(';'))}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bodyText)}`;
    if (window.electronAPI && window.electronAPI.openExternalUrl) {
      window.electronAPI.openExternalUrl(mailtoUrl).catch(() => { window.location.href = mailtoUrl; });
    } else {
      window.location.href = mailtoUrl;
    }
  }
}

// 6. User-Specific Pending Action List & Navbar Bell UI
function updateNavbarNotificationBellUI() {
  const badge = document.getElementById('navNotificationBadge');
  const countLabel = document.getElementById('navNotifCountLabel');
  const listContainer = document.getElementById('navNotifListContainer');

  if (!currentUser) {
    if (badge) badge.style.display = 'none';
    if (countLabel) countLabel.innerText = '0 pending';
    if (listContainer) {
      listContainer.innerHTML = `<div style="padding:16px; text-align:center; color:#94a3b8; font-size:12px;">Please log in to view pending approvals.</div>`;
    }
    return;
  }

  const pendingList = getPendingApprovalsForUser(currentUser);
  const count = pendingList.length;

  if (badge) {
    if (count > 0) {
      badge.style.display = 'inline-flex';
      badge.innerText = count > 99 ? '99+' : String(count);
    } else {
      badge.style.display = 'none';
    }
  }

  if (countLabel) {
    countLabel.innerText = `${count} pending`;
  }

  if (listContainer) {
    if (count === 0) {
      listContainer.innerHTML = `
        <div style="padding:20px 14px; text-align:center; color:#64748b; font-size:12px;">
          <div style="font-size:24px; margin-bottom:4px;">✨</div>
          <div style="font-weight:600; color:#334155;">No Pending Approval Tasks</div>
          <div style="font-size:11px; margin-top:2px;">You're all caught up with revision sign-offs.</div>
        </div>
      `;
      return;
    }

    let html = '';
    pendingList.forEach(item => {
      const isAdmOversight = isUserSystemAdmin(currentUser) && (item.approver.username !== currentUser.username);
      const timeStr = item.requestTimestamp ? new Date(item.requestTimestamp).toLocaleDateString() : '';

      html += `
        <div class="nav-pending-item-card">
          <div style="display:flex; justify-content:space-between; align-items:flex-start;">
            <span style="font-weight:700; font-size:12px; color:#0284c7;">
              ${escapeHtml(item.fmeaName || 'FMEA Project')}
            </span>
            <span style="font-size:10px; font-weight:800; padding:1px 6px; border-radius:10px; background:#fef3c7; color:#b45309;">
              ${escapeHtml(item.revisionNumber || 'Rev')}
            </span>
          </div>
          <div style="font-size:11px; color:#475569;">
            👤 Submitted by: <strong>${escapeHtml(item.requestedBy ? item.requestedBy.name : 'Author')}</strong>
            ${isAdmOversight ? `<br><span style="color:#6366f1; font-weight:600;">🛡️ Assigned to: ${escapeHtml(item.approver.name)}</span>` : ''}
          </div>
          <div style="display:flex; justify-content:space-between; align-items:center; margin-top:6px; gap:6px;">
            <span style="font-size:10px; color:#94a3b8;">📅 ${escapeHtml(timeStr)}</span>
            <div style="display:flex; gap:4px; align-items:center;">
              <button class="btn btn-sm" style="padding:2px 8px; font-size:10px; font-weight:600; background:#f59e0b; color:#ffffff; border:none; border-radius:3px;" onclick="sendApprovalReminderFromLog('${escapeHtml(item.id)}')" title="Send email reminder">
                🔔 Remind
              </button>
              <button class="btn btn-sm btn-primary" style="padding:2px 10px; font-size:11px; font-weight:700;" onclick="openApprovalReviewFromLog('${escapeHtml(item.id)}')">
                Review &amp; Sign-off →
              </button>
            </div>
          </div>
        </div>
      `;
    });

    listContainer.innerHTML = html;
  }
}

function toggleNotificationDropdown() {
  const dd = document.getElementById('menuNotifications');
  if (!dd) return;
  const isVisible = dd.style.display === 'flex' || dd.style.display === 'block';
  if (isVisible) {
    dd.style.display = 'none';
  } else {
    updateNavbarNotificationBellUI();
    dd.style.display = 'flex';
  }
}

// 7. Open Review Directly from Pending Log Item
async function openApprovalReviewFromLog(logId) {
  const log = getSharedApprovalLogById(logId);
  if (!log) {
    alert('Approval request log not found or already completed.');
    return;
  }

  // Hide notification dropdown
  const dd = document.getElementById('menuNotifications');
  if (dd) dd.style.display = 'none';

  // If different file, attempt to load file or notify user
  if (log.filePath && activeSharePointFileName !== log.filePath) {
    if (typeof loadSharePointFileByName === 'function') {
      await loadSharePointFileByName(log.filePath);
    }
  }

  // Open checklist in approval review mode
  openOutputChecklistVerificationModal(log.revisionId, log.fmeaType, null, log.id);
}

// 8. Shared Approval Logs Modal (Audit Trail)
function openAllSharedApprovalLogsModal() {
  const dd = document.getElementById('menuNotifications');
  if (dd) dd.style.display = 'none';

  renderSharedApprovalLogsTable();
  openModal('sharedApprovalLogsAuditModal');
}

function renderSharedApprovalLogsTable() {
  const tbody = document.getElementById('sharedApprovalLogsTbody');
  if (!tbody) return;

  const searchInput = document.getElementById('approvalLogSearchInput');
  const filterSelect = document.getElementById('approvalLogStatusFilter');

  const q = searchInput ? searchInput.value.toLowerCase().trim() : '';
  const statusFilter = filterSelect ? filterSelect.value : 'ALL';

  const logs = getSharedApprovalLogs();
  const filtered = logs.filter(l => {
    if (statusFilter !== 'ALL' && l.status !== statusFilter) return false;
    if (!q) return true;
    const str = `${l.id} ${l.fmeaName} ${l.revisionNumber} ${l.requestedBy ? l.requestedBy.name : ''} ${l.approver ? l.approver.name : ''} ${l.status} ${l.comments || ''}`.toLowerCase();
    return str.includes(q);
  });

  if (filtered.length === 0) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center; padding:20px; color:#94a3b8;">No approval logs match the filter criteria.</td></tr>`;
    return;
  }

  const isUserAdmin = isUserSystemAdmin(currentUser);

  let html = '';
  filtered.forEach(item => {
    const isPending = item.status === 'Pending';
    const isApproved = item.status === 'Approved';
    const isRejected = item.status === 'Rejected';

    let statusBadge = `<span style="padding:2px 8px; border-radius:10px; font-weight:700; font-size:11px; background:#fef3c7; color:#b45309;">⏳ Pending</span>`;
    if (isApproved) {
      statusBadge = `<span style="padding:2px 8px; border-radius:10px; font-weight:700; font-size:11px; background:#dcfce7; color:#15803d;">✅ Approved</span>`;
    } else if (isRejected) {
      statusBadge = `<span style="padding:2px 8px; border-radius:10px; font-weight:700; font-size:11px; background:#fee2e2; color:#b91c1c;">❌ Rejected</span>`;
    }

    const reqDate = item.requestTimestamp ? new Date(item.requestTimestamp).toLocaleString() : '';
    const decDate = item.decisionTimestamp ? `<br><span style="font-size:10px; color:#64748b;">Decision: ${new Date(item.decisionTimestamp).toLocaleString()}</span>` : '';

    html += `
      <tr style="border-bottom:1px solid #e2e8f0; font-size:12px;">
        <td style="padding:8px 10px; font-weight:600; color:#475569;">${escapeHtml(item.id)}</td>
        <td style="padding:8px 10px; font-weight:700; color:#0f172a;">${escapeHtml(item.fmeaName)}</td>
        <td style="padding:8px 10px; text-align:center; font-weight:700; color:#0284c7;">${escapeHtml(item.revisionNumber || 'Rev')}</td>
        <td style="padding:8px 10px;">${escapeHtml(item.requestedBy ? item.requestedBy.name : '-')}</td>
        <td style="padding:8px 10px;">${escapeHtml(item.approver ? item.approver.name : '-')}</td>
        <td style="padding:8px 10px; text-align:center;">${statusBadge}</td>
        <td style="padding:8px 10px; font-size:11px;">${reqDate}${decDate}</td>
        <td style="padding:8px 10px; font-size:11px; max-width:200px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${escapeHtml(item.comments || '')}">${escapeHtml(item.comments || '-')}</td>
        <td style="padding:8px 10px; text-align:center;">
          ${isPending ? `
            <div style="display:flex; gap:4px; justify-content:center; align-items:center; flex-wrap:wrap;">
              <button class="btn btn-sm ${isUserAdmin ? 'btn-success' : 'btn-primary'}" style="padding:2px 8px; font-size:11px; font-weight:700; ${isUserAdmin ? 'background:#16a34a; border-color:#16a34a; color:#fff;' : ''}" onclick="openApprovalReviewFromLog('${escapeHtml(item.id)}')" title="${isUserAdmin ? 'Admin Sign-off & Approve' : 'Inspect Revision'}">
                ${isUserAdmin ? '⚡ Sign-off' : 'Inspect'}
              </button>
              <button class="btn btn-sm btn-warning" style="padding:2px 8px; font-size:11px; background:#f59e0b; color:#ffffff; font-weight:600; border:none; border-radius:3px;" onclick="sendApprovalReminderFromLog('${escapeHtml(item.id)}')" title="Send email reminder to designated approver (${escapeHtml(item.approver ? item.approver.name : '')}) & Admin">🔔 Remind</button>
              <button class="btn btn-sm btn-outline" style="padding:2px 8px; font-size:11px; border-color:#0284c7; color:#0284c7; font-weight:600; border-radius:3px;" onclick="openReviseApproverFromLog('${escapeHtml(item.id)}')" title="Reassign designated approver">🔄 Reassign</button>
            </div>
          ` : `
            <button class="btn btn-sm btn-outline" style="padding:2px 8px; font-size:11px;" onclick="openApprovalReviewFromLog('${escapeHtml(item.id)}')">View</button>
          `}
        </td>
      </tr>
    `;
  });

  tbody.innerHTML = html;
}

function exportApprovalLogsToCSV() {
  const logs = getSharedApprovalLogs();
  if (logs.length === 0) {
    alert('No approval logs to export.');
    return;
  }

  const headers = ['Log ID', 'FMEA Name', 'FMEA Type', 'Revision', 'Status', 'Requested By', 'Assigned Approver', 'Request Timestamp', 'Decision Timestamp', 'Decision By', 'Reviewer Comments'];
  const rows = logs.map(l => [
    `"${l.id || ''}"`,
    `"${(l.fmeaName || '').replace(/"/g, '""')}"`,
    `"${l.fmeaType || ''}"`,
    `"${l.revisionNumber || ''}"`,
    `"${l.status || ''}"`,
    `"${(l.requestedBy ? l.requestedBy.name : '').replace(/"/g, '""')}"`,
    `"${(l.approver ? l.approver.name : '').replace(/"/g, '""')}"`,
    `"${l.requestTimestamp || ''}"`,
    `"${l.decisionTimestamp || ''}"`,
    `"${(l.decisionBy ? l.decisionBy.name : '').replace(/"/g, '""')}"`,
    `"${(l.comments || '').replace(/"/g, '""')}"`
  ]);

  const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\r\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `JOST_FMEA_Approval_Audit_Logs_${new Date().toISOString().slice(0,10)}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// 9. URL Deep-Link Parser & Login Gate
async function checkUrlForApprovalReview() {
  try {
    const urlParams = new URLSearchParams(window.location.search);
    const action = urlParams.get('action');
    const logId = urlParams.get('logId');

    if (action === 'review_revision_approval' && logId) {
      if (!currentUser) {
        // Stash intent for post-login auto-routing
        sessionStorage.setItem('pendingApprovalReviewIntent', JSON.stringify({ logId, file: urlParams.get('file'), revId: urlParams.get('revId') }));
        const loginOverlay = document.getElementById('loginScreenOverlay');
        if (loginOverlay) {
          loginOverlay.style.display = 'flex';
          const errDiv = document.getElementById('loginErrorMessage');
          if (errDiv) {
            errDiv.style.display = 'block';
            errDiv.style.background = '#e0f2fe';
            errDiv.style.color = '#0369a1';
            errDiv.style.borderColor = '#7dd3fc';
            errDiv.innerText = '🔐 Please log in to review and sign-off this revision approval request.';
          }
        }
      } else {
        await openApprovalReviewFromLog(logId);
      }
    }
  } catch (e) {
    console.warn('Error parsing URL for approval review:', e);
  }
}

