window.renderControlPlanPrintSummary = renderControlPlanPrintSummary;

function openExportModal() {
  if (typeof checkCanExport === 'function' && !checkCanExport()) {
    return;
  }

  const container = document.getElementById('exportNodeTree');
  let html = '';
  function buildExportTreeHTML(node) {
    if (!node) return;
    html += `
      <label class="checkbox-label" style="margin-left: 10px; display:block; font-size:12px;">
        <input type="checkbox" name="exportNodeChk" value="${node.id}" checked>
        ${escapeHtml(node.partNo || '')} - ${escapeHtml(node.name || '')}
      </label>
    `;
    if (node.children) node.children.forEach(c => buildExportTreeHTML(c));
  }
  buildExportTreeHTML(fmeaData.structure);
  if (container) container.innerHTML = html || '<span class="text-muted">No structure nodes available</span>';

  // Default export to Entire Project (DFMEA + All PFMEAs) if PFMEAs exist
  const scopeContainer = document.getElementById('exportScopeMultiSelectContainer');
  if (scopeContainer && (!scopeContainer.dataset.selectedValues || scopeContainer.dataset.selectedValues === '["ACTIVE"]')) {
    if (fmeaData.pfmeas && fmeaData.pfmeas.length > 0) {
      scopeContainer.dataset.selectedValues = JSON.stringify(['ALL']);
    }
  }

  populateFmeaScopeCheckboxDropdown('exportScopeMultiSelectContainer', 'renderExportHeaderSummary');

  const varSelect = document.getElementById('exportVariantSelect');
  if (varSelect) {
    let opts = '<option value="ALL">All Variants</option>';
    (fmeaData.variants || []).forEach(v => {
      const selectedAttr = (typeof selectedVariantFilter !== 'undefined' && selectedVariantFilter === v.id) ? 'selected' : '';
      opts += `<option value="${escapeHtml(v.id)}" ${selectedAttr}>${escapeHtml(v.name || v.id)}</option>`;
    });
    varSelect.innerHTML = opts;
    varSelect.onchange = () => renderExportHeaderSummary();
  }

  renderExportHeaderSummary();
  openModal('exportModal');
}

function executeExport() {
  if (typeof checkCanExport === 'function' && !checkCanExport()) {
    return;
  }

  const checkedNodes = Array.from(document.querySelectorAll('input[name="exportNodeChk"]:checked')).map(el => el.value);
  const formatEl = document.querySelector('input[name="exportFormat"]:checked');
  const format = formatEl ? formatEl.value : 'pdf';
  const selectedScopeVals = getSelectedScopeValues('exportScopeMultiSelectContainer');
  const targetScopes = resolveSelectedScopes(selectedScopeVals);

  const varSelect = document.getElementById('exportVariantSelect');
  const targetVariant = varSelect ? varSelect.value : (typeof selectedVariantFilter !== 'undefined' ? selectedVariantFilter : 'ALL');

  const printHeaderModeEl = document.querySelector('input[name="printHeaderMode"]:checked');
  const repeatHeaderEveryPage = printHeaderModeEl ? (printHeaderModeEl.value === 'everyPage') : false;

  if (checkedNodes.length === 0) {
    alert("Please select at least one structure element to export.");
    return;
  }

  if (format === 'excel') {
    exportToExcel(checkedNodes, targetScopes, targetVariant);
  } else {
    exportToPDF(checkedNodes, targetScopes, targetVariant, repeatHeaderEveryPage);
  }
  closeModal('exportModal');
}


/* ========================================================================================= */
/* 📋 VARIANT HEADER MATRIX & DOCUMENT-WIDE REVISION HISTORY GENERATORS                      */
/* ========================================================================================= */

function getVariantHeaderMatrixHTML(docType = 'ALL') {
  const variants = (fmeaData.variants || []).filter(v => v.active !== false);
  if (variants.length === 0) return '';

  let matrixTitle = `📋 Product &amp; Variant Master Header Matrix (${variants.length} Variants Defined)`;
  let scopeColHeader = '5T InTent / Subject';
  let leadColHeader = 'Assigned Leads &amp; CFT Members';
  let phaseColHeader = 'Phases';

  if (docType === 'DFMEA') {
    matrixTitle = `📋 Product &amp; Variant Master Header Matrix — Design FMEA (DFMEA)`;
    scopeColHeader = 'DFMEA Scope / Subject';
    leadColHeader = 'DFMEA Design Lead &amp; CFT';
    phaseColHeader = 'DFMEA Phases';
  } else if (docType === 'PFMEA') {
    matrixTitle = `📋 Product &amp; Variant Master Header Matrix — Process FMEA (PFMEA)`;
    scopeColHeader = 'PFMEA Scope / Process';
    leadColHeader = 'PFMEA Process Lead &amp; CFT';
    phaseColHeader = 'PFMEA Phases';
  } else if (docType === 'ControlPlan') {
    matrixTitle = `📋 Product &amp; Variant Master Header Matrix — Process Control Plan (CP)`;
    scopeColHeader = 'Control Plan Scope / Process';
    leadColHeader = 'Quality / Process Lead &amp; Core Team';
    phaseColHeader = 'CP Phases';
  }

  const formatBadges = (phases) => {
    const raw = phases || ['Prototype', 'Pre-Launch', 'Production'];
    return raw.map(p => {
      if (p.toLowerCase().includes('proto')) return '<span style="background:#fef3c7; color:#92400e; border:1px solid #f59e0b; padding:1px 3px; border-radius:2px; font-weight:bold; font-size:7.5px; display:inline-block; margin-bottom:2px;">🧪 Proto</span>';
      if (p.toLowerCase().includes('pre') || p.toLowerCase().includes('safe')) return '<span style="background:#e0f2fe; color:#0369a1; border:1px solid #0284c7; padding:1px 3px; border-radius:2px; font-weight:bold; font-size:7.5px; display:inline-block; margin-bottom:2px;">🚀 Pre-Launch</span>';
      return '<span style="background:#dcfce7; color:#166534; border:1px solid #16a34a; padding:1px 3px; border-radius:2px; font-weight:bold; font-size:7.5px; display:inline-block; margin-bottom:2px;">🏭 Prod</span>';
    }).join(' ');
  };

  let html = `
    <div class="variant-matrix-box" style="margin-bottom:12px; border:1px solid #334155; border-radius:6px; background:#ffffff; font-family:Arial, sans-serif; font-size:8.5px; color:#0f172a; width:100%; box-sizing:border-box; page-break-inside:avoid;">
      <div style="background:#0f172a; color:#ffffff; padding:6px 10px; display:flex; justify-content:space-between; align-items:center;">
        <span style="font-weight:bold; font-size:11px; letter-spacing:0.5px; text-transform:uppercase;">
          ${matrixTitle}
        </span>
        <span style="font-size:9px; color:#94a3b8;">IATF 16949 &amp; AIAG-VDA 5T Multi-Variant Architecture</span>
      </div>
      <table style="width:100%; border-collapse:collapse; font-size:8.5px; text-align:left; table-layout:fixed; word-break:break-word;">
        <thead>
          <tr style="background:#f1f5f9; border-bottom:1px solid #cbd5e1; color:#334155;">
            <th style="padding:4px 5px; width:3%; text-align:center; border:1px solid #cbd5e1;">#</th>
            <th style="padding:4px 5px; width:12%; border:1px solid #cbd5e1;">Variant / Assembly</th>
            <th style="padding:4px 5px; width:8%; border:1px solid #cbd5e1;">Part Number</th>
            <th style="padding:4px 5px; width:10%; border:1px solid #cbd5e1;">Customer</th>
            <th style="padding:4px 5px; width:11%; border:1px solid #cbd5e1;">Model &amp; App</th>
            <th style="padding:4px 5px; width:10%; text-align:center; border:1px solid #cbd5e1;">${phaseColHeader}</th>
            <th style="padding:4px 5px; width:15%; border:1px solid #cbd5e1;">${scopeColHeader}</th>
            <th style="padding:4px 5px; width:11%; border:1px solid #cbd5e1;">5T Timing</th>
            <th style="padding:4px 5px; width:20%; border:1px solid #cbd5e1;">${leadColHeader}</th>
          </tr>
        </thead>
        <tbody>
  `;

  variants.forEach((v, idx) => {
    const t = v.fiveT || {};
    const members = t.teamMembers || [];
    const dfmeaLead = members.find(m => m.isDfmeaLead)?.name;
    const pfmeaLead = members.find(m => m.isPfmeaLead)?.name;
    const cpLead = members.find(m => m.isCpLead)?.name;
    const cftMembers = members.filter(m => !m.isDfmeaLead && !m.isPfmeaLead && !m.isCpLead);

    const dfH = v.dfmeaHeader || {};
    const pfH = v.pfmeaHeader || {};
    const cpH = v.cpHeader || {};

    let leadsHtml = [];
    let scopeText = '';
    let phaseBadges = '';

    if (docType === 'DFMEA') {
      phaseBadges = formatBadges(dfH.phases || v.phases || t.phases);
      scopeText = dfH.subject || v.subject || t.task || v.name;
      const resp = dfH.designResp || v.designResp || (dfmeaLead ? 'Design: ' + dfmeaLead : '');
      const lead = dfH.keyLead || v.keyLead || dfmeaLead || '';
      if (resp || lead) leadsHtml.push(`<div>🎖️ DFMEA: <strong>${escapeHtml(resp || lead)}</strong></div>`);
      if (cftMembers.length > 0) {
        leadsHtml.push(`<div style="margin-top:2px; font-size:8px; color:#475569;">👥 CFT: ${cftMembers.map(m => escapeHtml(m.name)).join(', ')}</div>`);
      }
    } else if (docType === 'PFMEA') {
      phaseBadges = formatBadges(pfH.phases || v.phases || t.phases);
      scopeText = pfH.subject || v.subject || t.task || v.name;
      const resp = pfH.processResp || v.designResp || (pfmeaLead ? 'Process: ' + pfmeaLead : '');
      const lead = pfH.keyLead || v.keyLead || pfmeaLead || '';
      if (resp || lead) leadsHtml.push(`<div>🎖️ PFMEA: <strong>${escapeHtml(resp || lead)}</strong></div>`);
      if (cftMembers.length > 0) {
        leadsHtml.push(`<div style="margin-top:2px; font-size:8px; color:#475569;">👥 CFT: ${cftMembers.map(m => escapeHtml(m.name)).join(', ')}</div>`);
      }
    } else if (docType === 'ControlPlan') {
      phaseBadges = formatBadges(cpH.phases || v.phases || t.phases);
      scopeText = cpH.subject || v.subject || t.task || v.name;
      const resp = cpH.resp || v.designResp || (cpLead ? 'CP Lead: ' + cpLead : '');
      const lead = cpH.keyLead || v.keyLead || cpLead || '';
      if (resp || lead) leadsHtml.push(`<div>🎖️ Control Plan: <strong>${escapeHtml(resp || lead)}</strong></div>`);
      if (cftMembers.length > 0) {
        leadsHtml.push(`<div style="margin-top:2px; font-size:8px; color:#475569;">👥 Core Team: ${cftMembers.map(m => escapeHtml(m.name)).join(', ')}</div>`);
      }
    } else {
      // Document Type ALL: Comprehensive Breakdown
      const dfPhases = dfH.phases || v.phases || t.phases || ['Prototype', 'Pre-Launch', 'Production'];
      const pfPhases = pfH.phases || v.phases || t.phases || ['Prototype', 'Pre-Launch', 'Production'];
      const cpPhases = cpH.phases || v.phases || t.phases || ['Prototype', 'Pre-Launch', 'Production'];

      const areAllSame = JSON.stringify(dfPhases) === JSON.stringify(pfPhases) && JSON.stringify(pfPhases) === JSON.stringify(cpPhases);
      if (areAllSame) {
        phaseBadges = formatBadges(dfPhases);
      } else {
        phaseBadges = `
          <div style="font-size:7.5px; text-align:left; display:flex; flex-direction:column; gap:1px;">
            <div><strong style="color:#0284c7;">DF:</strong> ${formatBadges(dfPhases)}</div>
            <div><strong style="color:#059669;">PF:</strong> ${formatBadges(pfPhases)}</div>
            <div><strong style="color:#7c3aed;">CP:</strong> ${formatBadges(cpPhases)}</div>
          </div>
        `;
      }

      scopeText = pfH.subject || dfH.subject || v.subject || t.task || v.name;
      if (dfmeaLead || dfH.designResp) leadsHtml.push(`<div>🎖️ DFMEA: <strong>${escapeHtml(dfH.designResp || dfmeaLead)}</strong></div>`);
      if (pfmeaLead || pfH.processResp) leadsHtml.push(`<div>🎖️ PFMEA: <strong>${escapeHtml(pfH.processResp || pfmeaLead)}</strong></div>`);
      if (cpLead || cpH.resp) leadsHtml.push(`<div>🎖️ CP: <strong>${escapeHtml(cpH.resp || cpLead)}</strong></div>`);
      if (cftMembers.length > 0) {
        leadsHtml.push(`<div style="margin-top:2px; font-size:8px; color:#475569;">👥 CFT: ${cftMembers.map(m => escapeHtml(m.name)).join(', ')}</div>`);
      } else if (t.team) {
        leadsHtml.push(`<div style="margin-top:2px; font-size:8px; color:#475569;">👥 Team: ${escapeHtml(t.team)}</div>`);
      }
    }

    if (leadsHtml.length === 0) leadsHtml.push('-');
    const modelAppStr = `${v.model || ''}${v.vehicle ? (v.model ? ' / ' : '') + v.vehicle : ''}`.trim() || '-';

    html += `
      <tr style="border-bottom:1px solid #cbd5e1; background:${idx % 2 === 0 ? '#ffffff' : '#f8fafc'};">
        <td style="padding:4px 5px; text-align:center; font-weight:bold; border:1px solid #cbd5e1; color:#0284c7;">${idx + 1}</td>
        <td style="padding:4px 5px; font-weight:bold; border:1px solid #cbd5e1;">${escapeHtml(v.name)}</td>
        <td style="padding:4px 5px; font-family:monospace; border:1px solid #cbd5e1;">${escapeHtml(v.partNumber || '-')}</td>
        <td style="padding:4px 5px; border:1px solid #cbd5e1;">${escapeHtml(v.customer || '-')}</td>
        <td style="padding:4px 5px; border:1px solid #cbd5e1;">${escapeHtml(modelAppStr)}</td>
        <td style="padding:4px 5px; text-align:center; border:1px solid #cbd5e1;">${phaseBadges}</td>
        <td style="padding:4px 5px; border:1px solid #cbd5e1; color:#334155;">${escapeHtml(scopeText || '-')}</td>
        <td style="padding:4px 5px; border:1px solid #cbd5e1; font-size:8px; color:#475569;">${escapeHtml(t.timing || '-')}</td>
        <td style="padding:4px 5px; border:1px solid #cbd5e1; font-size:8.5px; line-height:1.25;">
          ${leadsHtml.join('')}
        </td>
      </tr>
    `;
  });

  html += `
        </tbody>
      </table>
    </div>
  `;
  return html;
}
window.getVariantHeaderMatrixHTML = getVariantHeaderMatrixHTML;

function getCompleteRevisionHistoryTableHTML(fmeaType = 'DFMEA', pfmeaId = '') {
  let revs = [];
  let title = 'FMEA Revision History';

  if (fmeaType === 'ControlPlan') {
    revs = fmeaData.controlPlanRevisions || [];
    title = 'Process Control Plan Revision History';
  } else if (fmeaType === 'PFMEA' && pfmeaId) {
    const pfmea = (fmeaData.pfmeas || []).find(p => String(p.id) === String(pfmeaId));
    revs = (pfmea && pfmea.revisions) || [];
    title = `Process FMEA (PFMEA) Revision History — ${pfmea ? pfmea.name : ''}`;
  } else if (fmeaType === 'PFMEA') {
    const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : null;
    revs = (ctx && ctx.pfmea && ctx.pfmea.revisions) || (fmeaData.pfmeas && fmeaData.pfmeas[0] && fmeaData.pfmeas[0].revisions) || [];
    title = 'Process FMEA (PFMEA) Revision History';
  } else {
    revs = fmeaData.revisions || [];
    title = 'Design FMEA (DFMEA) Revision History';
  }

  if (revs.length === 0) return '';

  let html = `
    <div class="revision-history-print-box" style="margin-bottom:12px; border:1px solid #cbd5e1; border-radius:4px; overflow:hidden; background:#ffffff; font-family:Arial, sans-serif; font-size:9px; width:100%; box-sizing:border-box; page-break-inside:avoid;">
      <div style="background:#1e293b; color:#ffffff; padding:5px 10px; display:flex; justify-content:space-between; align-items:center;">
        <span style="font-weight:bold; font-size:10.5px; text-transform:uppercase;">📜 ${escapeHtml(title)} (${revs.length} Releases Logged)</span>
        <span style="font-size:8.5px; color:#cbd5e1;">ISO 26262 &amp; IATF 16949 Engineering Revision Traceability</span>
      </div>
      <table style="width:100%; border-collapse:collapse; font-size:8.5px; text-align:left; table-layout:fixed; word-break:break-word;">
        <thead>
          <tr style="background:#f8fafc; border-bottom:1px solid #cbd5e1; color:#475569;">
            <th style="padding:4px 6px; width:6%; text-align:center; border:1px solid #cbd5e1;">Rev #</th>
            <th style="padding:4px 6px; width:11%; border:1px solid #cbd5e1;">Release Date</th>
            <th style="padding:4px 6px; width:55%; border:1px solid #cbd5e1;">Engineering Change Description &amp; Scope Delta</th>
            <th style="padding:4px 6px; width:18%; border:1px solid #cbd5e1;">Key Lead / Prepared By</th>
            <th style="padding:4px 6px; width:10%; text-align:center; border:1px solid #cbd5e1;">Status</th>
          </tr>
        </thead>
        <tbody>
  `;

  revs.forEach((r, idx) => {
    const revNo = r.revNumber || r.revNo || (idx + 1).toString().padStart(2, '0');
    const date = r.freezeDate || r.createdDate || r.date || '-';
    const changeDesc = r.changeDescription || r.changeDesc || 'Initial Baseline Release';
    const author = r.author || r.creator || (fmeaData.headerInfo && fmeaData.headerInfo.preparedBy) || 'Quality Engineering';
    const status = r.status || 'Frozen';
    const isFrozen = status.toLowerCase() === 'frozen' || status.toLowerCase() === 'released';

    html += `
      <tr style="border-bottom:1px solid #cbd5e1; background:${idx % 2 === 0 ? '#ffffff' : '#f8fafc'};">
        <td style="padding:4px 6px; text-align:center; font-weight:bold; border:1px solid #cbd5e1; color:${isFrozen ? '#059669' : '#d97706'};">${escapeHtml(revNo)}</td>
        <td style="padding:4px 6px; border:1px solid #cbd5e1; color:#475569;">${escapeHtml(String(date).slice(0, 10))}</td>
        <td style="padding:4px 6px; border:1px solid #cbd5e1; color:#0f172a;">${escapeHtml(changeDesc)}</td>
        <td style="padding:4px 6px; border:1px solid #cbd5e1; color:#334155;">${escapeHtml(author)}</td>
        <td style="padding:4px 6px; text-align:center; border:1px solid #cbd5e1;">
          <span style="font-weight:bold; font-size:8px; padding:2px 6px; border-radius:3px; background:${isFrozen ? '#dcfce7' : '#fef3c7'}; color:${isFrozen ? '#166534' : '#92400e'}; border:1px solid ${isFrozen ? '#16a34a' : '#f59e0b'};">${escapeHtml(status)}</span>
        </td>
      </tr>
    `;
  });

  html += `
        </tbody>
      </table>
    </div>
  `;
  return html;
}
window.getCompleteRevisionHistoryTableHTML = getCompleteRevisionHistoryTableHTML;

function syncHeaderFromVariantAnd5T() {
  const activeVarId = window.selectedVariantFilter || 'ALL';
  let targetVariant = null;

  if (activeVarId && activeVarId !== 'ALL') {
    targetVariant = (fmeaData.variants || []).find(v => v.id === activeVarId);
  }
  if (!targetVariant && fmeaData.variants && fmeaData.variants.length > 0) {
    targetVariant = fmeaData.variants[0];
  }

  if (!targetVariant) {
    alert('No active variant found to sync from. Please create a variant in the Variant Manager first.');
    return;
  }

  const t = targetVariant.fiveT || {};
  const members = t.teamMembers || [];
  const dfmeaLead = members.find(m => m.isDfmeaLead)?.name;
  const pfmeaLead = members.find(m => m.isPfmeaLead)?.name;
  const cpLead = members.find(m => m.isCpLead)?.name;
  const leadName = dfmeaLead || pfmeaLead || cpLead || (members[0]?.name) || '';

  const teamStr = members.map(m => `${m.name} (${m.dept ? m.dept + ' - ' : ''}${m.role})`).join(', ') || t.team || '';

  const subjectEl = document.getElementById('hdr_subjectSystem');
  const custEl = document.getElementById('hdr_customerName');
  const modelEl = document.getElementById('hdr_modelYear');
  const respEl = document.getElementById('hdr_designResp');
  const leadEl = document.getElementById('hdr_keyLead');
  const teamEl = document.getElementById('hdr_crossTeam');

  if (subjectEl && (t.task || targetVariant.name)) subjectEl.value = t.task || targetVariant.name;
  if (custEl && (targetVariant.customer || fmeaData.projectName)) custEl.value = targetVariant.customer || fmeaData.projectName;
  if (modelEl && targetVariant.model) modelEl.value = targetVariant.model;
  if (respEl && (dfmeaLead || pfmeaLead || cpLead)) respEl.value = `${dfmeaLead ? 'Design: ' + dfmeaLead + ' | ' : ''}${pfmeaLead ? 'Process: ' + pfmeaLead : 'Engineering Team'}`;
  if (leadEl && leadName) leadEl.value = leadName;
  if (teamEl && teamStr) teamEl.value = teamStr;

  if (typeof showToast === 'function') {
    showToast(`✓ Header synced from Variant "${targetVariant.name}" & 5T planning!`, 'success');
  } else {
    alert(`✓ Header synced from Variant "${targetVariant.name}" & 5T planning!`);
  }
}
window.syncHeaderFromVariantAnd5T = syncHeaderFromVariantAnd5T;

function getAiagVdaHeaderHTML(overrideScope, hideTitleBar = false) {
  const ctx = overrideScope || (typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false });

  let h = {};
  if (ctx && ctx.headerInfo && Object.keys(ctx.headerInfo).length > 0) {
    h = ctx.headerInfo;
  } else if (ctx && ctx.pfmea && ctx.pfmea.headerInfo && Object.keys(ctx.pfmea.headerInfo).length > 0) {
    h = ctx.pfmea.headerInfo;
  } else {
    h = fmeaData.headerInfo || fmeaData.header || {};
  }

  // Check active variant & 5T context
  const activeVarId = window.selectedVariantFilter || 'ALL';
  const isMultiVariant = activeVarId === 'ALL' || (Array.isArray(activeVarId) && activeVarId.length > 1);
  let activeVar = null;
  if (!isMultiVariant && activeVarId && activeVarId !== 'ALL') {
    activeVar = (fmeaData.variants || []).find(v => v.id === activeVarId);
  }

  const curRev = typeof getContextRevision === 'function' ? getContextRevision() : (fmeaData.currentRevision || null);
  const isPFMEA = ctx.isPFMEA || (ctx.pfmea ? true : false);
  const fmeaTitle = isPFMEA
    ? `Process Failure Mode and Effect Analysis (PROCESS-FMEA)`
    : `Design Failure Mode and Effect Analysis (DESIGN-FMEA)`;

  const revNum = (curRev && (curRev.revNumber || curRev.number || curRev.revNo)) || h.revNumber || h.revNo || '1.0';
  const cleanRevNum = String(revNum).replace(/\s*\((in progress|draft|frozen)\)/i, '').trim();
  const isOngoing = curRev
    ? (curRev.status === 'In Progress' || curRev.status === 'Draft' || (curRev.status && curRev.status.toLowerCase() !== 'frozen'))
    : (!fmeaData.status || fmeaData.status.toLowerCase() !== 'frozen');
  const revStatusSuffix = isOngoing ? ' (In Progress)' : '';
  const rawStartDate = (curRev && (curRev.createdDate || curRev.startDate || curRev.createdAt || curRev.date)) || h.startDate || h.createdDate || new Date().toISOString().slice(0, 10);
  const rawRevDate = (curRev && (curRev.freezeDate || curRev.revDate || curRev.updatedAt || curRev.createdDate)) || h.revDate || h.startDate || new Date().toISOString().slice(0, 10);

  const startDate = String(rawStartDate).slice(0, 10);
  const revDate = String(rawRevDate).slice(0, 10);

  // Dynamic Resolution from Variant Management & 5T
  let scopeSubject = h.subjectSystem;
  let customerName = h.customerName;
  let modelYear = h.modelYear;
  let designResp = h.designResp;
  let keyLead = h.keyLead;
  let crossTeam = h.crossTeam;

  let docH = {};
  if (activeVar) {
    docH = isPFMEA ? (activeVar.pfmeaHeader || {}) : (activeVar.dfmeaHeader || {});
  }

  let plantOrEngLoc = '';
  if (isMultiVariant) {
    scopeSubject = `Multiple Variants (See Variant Matrix Table)`;
    customerName = 'Multiple Customers (See Variant Matrix)';
    designResp = 'Multiple Leads (See Variant Matrix Table)';
    keyLead = 'Multiple Facilitators (See Variant Matrix Table)';
    crossTeam = 'Multiple CFT Members (See Variant Matrix Table)';
    plantOrEngLoc = 'Multiple Locations (See Variant Matrix Table)';
  } else if (activeVar) {
    // Exact sync from Variant Management & 5T Document-Specific Header
    scopeSubject = scopeSubject || docH.subject || activeVar.subject || activeVar.fiveT?.task || activeVar.name;
    customerName = customerName || activeVar.customer || fmeaData.projectName || 'Acme Motors';
    modelYear = modelYear || activeVar.model || activeVar.vehicle || '';

    const members = activeVar.fiveT?.teamMembers || [];
    const dfmeaLead = members.find(m => m.isDfmeaLead)?.name;
    const pfmeaLead = members.find(m => m.isPfmeaLead)?.name;
    const cftMembers = members.filter(m => !m.isDfmeaLead && !m.isPfmeaLead && !m.isCpLead);

    if (!designResp) {
      if (isPFMEA) {
        designResp = docH.processResp || activeVar.designResp || (pfmeaLead ? 'Process: ' + pfmeaLead : 'Manufacturing Engineering');
      } else {
        designResp = docH.designResp || activeVar.designResp || (dfmeaLead ? 'Design: ' + dfmeaLead : 'Systems Engineering');
      }
    }

    if (!keyLead) {
      if (isPFMEA) {
        keyLead = docH.keyLead || activeVar.keyLead || pfmeaLead || dfmeaLead || 'PFMEA Lead';
      } else {
        keyLead = docH.keyLead || activeVar.keyLead || dfmeaLead || pfmeaLead || 'DFMEA Lead';
      }
    }

    if (!crossTeam) {
      if (cftMembers.length > 0) {
        crossTeam = cftMembers.map(m => `${m.name}${m.dept || m.role ? ' (' + (m.dept || m.role) + ')' : ''}`).join(', ');
      } else if (members.length > 0) {
        crossTeam = members.map(m => `${m.name}${m.dept || m.role ? ' (' + (m.dept || m.role) + ')' : ''}`).join(', ');
      } else if (activeVar.fiveT?.team) {
        crossTeam = activeVar.fiveT.team;
      }
    }
  }

  scopeSubject = scopeSubject || ctx.name || (ctx.pfmea ? ctx.pfmea.name : '') || fmeaData.projectName || '';
  customerName = customerName || fmeaData.projectName || 'Acme Motors';
  designResp = designResp || (isPFMEA ? 'Manufacturing Engineering' : 'Systems Engineering');
  keyLead = keyLead || (isPFMEA ? 'PFMEA Lead' : 'DFMEA Lead');
  crossTeam = crossTeam || 'Cross-Functional Engineering Team';

  const locLabel = isPFMEA ? 'Process Plant Location:' : 'Engineering Location:';
  const locVal = isMultiVariant ? plantOrEngLoc : (isPFMEA
    ? (docH.plantLoc || activeVar?.plantLoc || h.plantLocation || h.plantLoc || fmeaData.headerInfo?.plantLoc || fmeaData.headerInfo?.plantLocation || 'Manufacturing Plant')
    : (docH.engLoc || activeVar?.engLoc || h.engLocation || h.engLoc || fmeaData.headerInfo?.engLoc || fmeaData.headerInfo?.engLocation || 'Engineering Tech Center'));

  // Phase Display Badges (DFMEA vs PFMEA specific)
  const rawPhases = (activeVar && (docH.phases || activeVar.phases || activeVar.fiveT?.phases)) || h.phases || ['Prototype', 'Pre-Launch', 'Production'];
  const headerPhaseBadges = isMultiVariant
    ? '<span style="background:#fef3c7; color:#92400e; border:1px solid #f59e0b; padding:1px 5px; border-radius:3px; font-weight:bold; font-size:8px; display:inline-block;">Multiple Phases (See Variant Matrix)</span>'
    : rawPhases.map(p => {
      if (p.toLowerCase().includes('proto')) return '<span style="background:#fef3c7; color:#92400e; border:1px solid #f59e0b; padding:1px 5px; border-radius:3px; font-weight:bold; font-size:8px; display:inline-block; margin-right:3px;">🧪 Prototype</span>';
      if (p.toLowerCase().includes('pre') || p.toLowerCase().includes('safe')) return '<span style="background:#e0f2fe; color:#0369a1; border:1px solid #0284c7; padding:1px 5px; border-radius:3px; font-weight:bold; font-size:8px; display:inline-block; margin-right:3px;">🚀 Pre-Launch</span>';
      return '<span style="background:#dcfce7; color:#166534; border:1px solid #16a34a; padding:1px 5px; border-radius:3px; font-weight:bold; font-size:8px; display:inline-block; margin-right:3px;">🏭 Production</span>';
    }).join(' ');

  const selectedLogos = (h.selectedLogos && h.selectedLogos.length > 0) ? h.selectedLogos : ['JOST'];
  const brandLogosHtml = renderHeaderLogosHTML(selectedLogos);

  return `
    <div class="fmea-project-header-box" style="border: 2px solid #0f172a; margin-bottom: 8px; font-family: Arial, sans-serif; font-size: 10px; background: #ffffff;">
      ${hideTitleBar ? '' : `
      <div style="background: #0f172a; color: #ffffff; display:flex; align-items:center; justify-content:space-between; padding: 5px 12px;">
        <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
          ${brandLogosHtml}
        </div>
        <div style="flex:1; text-align:center; font-weight:bold; font-size:13px; letter-spacing:0.5px; text-transform:uppercase; padding: 0 10px;">
          AIAG-VDA ${fmeaTitle}
        </div>
        <div style="text-align:right; font-size:9px; color:#94a3b8; white-space:nowrap;">JOST World<br>FMEA Workbench</div>
      </div>
      `}
      ${isMultiVariant ? `
        <div style="background:#fef3c7; border-bottom:1px solid #f59e0b; color:#92400e; padding:3px 8px; font-size:9px; font-weight:bold;">
          ℹ️ Multi-Variant Document: Covers all active product variants. Refer to the attached Variant Header Matrix Table for specific Part Numbers, Assemblies, Customers, Phase Applicability, and 5T CFT Teams.
        </div>
      ` : ''}
      <table style="width: 100%; border-collapse: collapse; border: none; font-size: 10px;">
        <tr style="background:#f8fafc;">
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Company Name:</strong> ${escapeHtml(h.companyName || 'JOST Group')}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Subject:</strong> ${escapeHtml(scopeSubject)}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>FMEA ID Number:</strong> ${escapeHtml(docH.docNo || activeVar?.partNumber || h.fmeaDocNo || 'FMEA-2026-001')}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Confidentiality Level:</strong> ${escapeHtml(docH.confidentiality || h.confidentiality || 'Internal Confidential')}</td>
        </tr>
        <tr>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>${locLabel}</strong> ${escapeHtml(locVal)}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>FMEA Start Date:</strong> ${escapeHtml(startDate)}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Design / Process Responsibility:</strong> ${escapeHtml(designResp)}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>FMEA Revision Date:</strong> ${escapeHtml(revDate)} (Rev ${escapeHtml(cleanRevNum)}${revStatusSuffix})</td>
        </tr>
        <tr style="background:#f8fafc;">
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Customer Name:</strong> ${escapeHtml(customerName)} ${modelYear ? '(' + escapeHtml(modelYear) + ')' : ''}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Cross-Functional Team:</strong> ${escapeHtml(crossTeam)}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Key Lead / Facilitator:</strong> ${escapeHtml(keyLead)}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px; background:#f1f5f9;"><strong>Applicable Phases:</strong> ${headerPhaseBadges}</td>
        </tr>
      </table>
    </div>
  `;
}
function getScopeTableHeaderHTML(isVDA, isPFMEA, topHeaderHtml = '') {
  const topHeaderRow = topHeaderHtml
    ? `<tr class="project-header-print-row"><th colspan="${isVDA ? 28 : 26}" style="padding:0 0 6px 0; border:none; background:transparent !important; text-align:left;">${topHeaderHtml}</th></tr>`
    : '';

  if (!isVDA) {
    return `
        <thead>
          ${topHeaderRow}
          <tr style="background:#0f172a !important; color:#ffffff !important; font-weight:bold; font-size:9.5px; text-transform:uppercase; text-align:center;">
            <th style="width:28px;">No.</th>
            <th style="width:130px;">${isPFMEA ? 'Process Step Station No. & Name' : 'Focus Element (System / Subsystem)'}</th>
            <th style="width:130px;">${isPFMEA ? 'Function & Requirement of Process Step' : 'Function & Requirement of Focus Element'}</th>
            <th style="width:120px;">${isPFMEA ? 'Failure Mode (FM) of Process Step' : 'Failure Mode (FM)'}</th>
            <th style="width:140px;">${isPFMEA ? 'Failure Effect (FE) [Higher Level / End User]' : 'Failure Effect (FE) [Higher Level]'}</th>
            <th style="width:22px;">S</th>
            <th style="width:130px;">${isPFMEA ? 'Failure Cause (FC) [Work Element & Function]' : 'Failure Cause (FC) [Lower Level Element & Function]'}</th>
            <th style="width:110px;">Lower Level Characteristic / Spec</th>
            <th style="width:40px;">Class</th>
            <th style="width:50px;">Variant</th>
            <th style="width:120px;">Current Prevention Control</th>
            <th style="width:22px;">O</th>
            <th style="width:120px;">Current Detection Control</th>
            <th style="width:22px;">D</th>
            <th style="width:48px;">RPN</th>
            <th style="width:120px;">Recommended Action</th>
            <th style="width:30px;">P/D</th>
            <th style="width:90px;">Responsible Person</th>
            <th style="width:70px;">Target Date</th>
            <th style="width:65px;">Status</th>
            <th style="width:110px;">Action Taken & Date</th>
            <th style="width:22px;">S2</th>
            <th style="width:22px;">O2</th>
            <th style="width:22px;">D2</th>
            <th style="width:48px;">RPN2</th>
            <th style="width:90px;">Comments</th>
          </tr>
        </thead>`;
  }
  return `
        <thead>
          ${topHeaderRow}
          <tr style="background:#0f172a !important; color:#ffffff !important; font-weight:bold; font-size:9.5px; text-transform:uppercase; text-align:center;">
            <th style="width:28px;" rowspan="2">No.</th>
            <th colspan="3" style="background:#1e293b !important; color:#fff !important; border:1px solid #475569;">STRUCTURAL ANALYSIS (STEP 2)</th>
            <th colspan="3" style="background:#1e3a8a !important; color:#fff !important; border:1px solid #475569;">FUNCTIONAL ANALYSIS (STEP 3)</th>
            <th colspan="4" style="background:#4c1d95 !important; color:#fff !important; border:1px solid #475569;">FAILURE ANALYSIS (STEP 4)</th>
            <th colspan="6" style="background:#065f46 !important; color:#fff !important; border:1px solid #475569;">RISK ANALYSIS (STEP 5)</th>
            <th colspan="10" style="background:#831843 !important; color:#fff !important; border:1px solid #475569;">OPTIMIZATION (STEP 6)</th>
            <th style="width:80px;" rowspan="2">Filter Code / Remarks</th>
          </tr>
          <tr style="background:#334155 !important; color:#ffffff !important; font-weight:bold; font-size:9px; text-align:center;">
            <th style="width:110px;">${isPFMEA ? '1. Process Item System, Subsystem, Element or Name of Process' : '1. System, Subsystem, Subelement or Name of System'}</th>
            <th style="width:120px;">${isPFMEA ? '2. Process Step Station No. and Name of Focus Element' : '2. Focus Element (System, Subsystem, Component)'}</th>
            <th style="width:100px;">${isPFMEA ? '3. Process Work Elements Type 4M' : '3. Next Lower Level Element'}</th>
            <th style="width:130px;">${isPFMEA ? '1. Function of Process Item & Higher System' : '1. Function of Next Higher Level Element & Higher System'}</th>
            <th style="width:120px;">${isPFMEA ? '2. Function & Requirement of Process Step' : '2. Function & Requirement of Focus Element'}</th>
            <th style="width:110px;">${isPFMEA ? '3. Function of Process Work Element' : '3. Function of Next Lower Level Element'}</th>
            <th style="width:130px;">${isPFMEA ? '1. Failure Effects (FE) to Next Higher Element / End User' : '1. Failure Effects (FE) to Higher Level / Vehicle / End User'}</th>
            <th style="width:22px;">S</th>
            <th style="width:120px;">${isPFMEA ? '2. Failure Mode (FM) of Process Step' : '2. Failure Mode (FM) of Focus Element'}</th>
            <th style="width:120px;">${isPFMEA ? '3. Failure Cause (FC) of Work Element' : '3. Failure Cause (FC) of Next Lower Level Element'}</th>
            <th style="width:120px;">Current Prevention Control (PC) of FC</th>
            <th style="width:22px;">O</th>
            <th style="width:120px;">Current Detection Control (DC) of FC or FM</th>
            <th style="width:22px;">D</th>
            <th style="width:48px;">AP</th>
            <th style="width:45px;">Class</th>
            <th style="width:110px;">Preventive Action</th>
            <th style="width:110px;">Detection Action</th>
            <th style="width:85px;">Responsible Person Name</th>
            <th style="width:70px;">Target Date</th>
            <th style="width:60px;">Status</th>
            <th style="width:100px;">Action Taken with Completion Date</th>
            <th style="width:22px;">S</th>
            <th style="width:22px;">O</th>
            <th style="width:22px;">D</th>
            <th style="width:48px;">AP2</th>
          </tr>
        </thead>`;
}

function buildScopeTableRowsHTML(scope, nodeIds, targetVariant) {
  let html = '';
  const fls = scope.functionLines || (scope.isPFMEA ? scope.pfmea?.functionLines : fmeaData.functionLines) || [];
  const functionsList = scope.functions || (scope.isPFMEA ? (scope.pfmea?.functions || fmeaData.functions || []) : (fmeaData.functions || []));
  const reqsList = getActiveRequirementsList(scope);
  const effMap = scope.failureModeEffects || (scope.isPFMEA ? scope.pfmea?.failureModeEffects : fmeaData.failureModeEffects) || {};
  const causeMap = scope.failureModeCauses || (scope.isPFMEA ? scope.pfmea?.failureModeCauses : fmeaData.failureModeCauses) || {};
  const causeControls = scope.causeControls || (scope.isPFMEA ? scope.pfmea?.causeControls : fmeaData.causeControls) || {};
  const causeActions = scope.causeActions || (scope.isPFMEA ? scope.pfmea?.causeActions : fmeaData.causeActions) || {};
  const reqMap = scope.functionRequirements || (scope.isPFMEA ? scope.pfmea?.functionRequirements : fmeaData.functionRequirements) || {};
  const isVDA = (fmeaData.methodologyMode === 'AIAG-VDA');
  let rowCounter = 0;

  const systemOrProcessItemStr = scope.name || (scope.isPFMEA ? (scope.pfmea?.name || 'Process Item') : 'System Element');

  fls.forEach(fl => {
    let structNode = null;
    if (scope.isPFMEA && scope.pfmea && scope.pfmea.processSteps) {
      const pstep = scope.pfmea.processSteps.find(ps => ps.id === fl.structId);
      if (pstep) {
        structNode = {
          id: pstep.id,
          partNo: pstep.stepNo,
          name: pstep.name,
          description: pstep.description,
          variantId: pstep.variantId,
          dfmeaStructId: pstep.dfmeaStructId,
          workElement: pstep.workElement || pstep.type4M || ''
        };
      }
    }
    if (!structNode) {
      structNode = getStructureNodeById(fmeaData.structure, fl.structId);
    }

    let structCellText = scope.isPFMEA ? 'Process Step' : 'Focus Element';
    let workElementStr = scope.isPFMEA ? '-' : '-';
    if (structNode) {
      structCellText = `${structNode.partNo ? structNode.partNo + ' ' : ''}${structNode.name || ''}`.trim();
      workElementStr = structNode.workElement || structNode.type4M || structNode.description || '-';
    }

    if (nodeIds && nodeIds.length > 0) {
      if (scope.isPFMEA) {
        const allDfmeaNodes = getStructureNodesArray(fmeaData.structure);
        const isAllDfmeaChecked = allDfmeaNodes.every(n => nodeIds.includes(n.id));
        if (!isAllDfmeaChecked) {
          const isDirectMatch = nodeIds.includes(fl.structId);
          const isStructMatch = structNode && nodeIds.includes(structNode.id);
          const isDfmeaParentMatch = structNode && structNode.dfmeaStructId && nodeIds.includes(structNode.dfmeaStructId);
          if (!isDirectMatch && !isStructMatch && !isDfmeaParentMatch) return;
        }
      } else {
        const isDirectMatch = nodeIds.includes(fl.structId);
        const isStructMatch = structNode && nodeIds.includes(structNode.id);
        if (!isDirectMatch && !isStructMatch) return;
      }
    }

    if (structNode && !matchesVariantFilter(structNode.variantId, targetVariant)) return;

    // Resolve funcId with functionId alias (WB4 legacy flat-format compatibility)
    const resolvedFuncId = fl.funcId || fl.functionId;
    let funcObj = functionsList.find(f => f.id === resolvedFuncId);
    // If function not found in library but functionName is set (WB4 flat format), synthesize it
    if (!funcObj && (fl.functionName || fl.functionId)) {
      funcObj = { id: resolvedFuncId || fl.id, name: fl.functionName || 'Function', type: fl.functionCategory || 'Primary function', structId: fl.structId };
    }
    if (!funcObj || fl.isConsidered === false) return;
    if (!matchesVariantFilter(funcObj.variants || funcObj.variantId, targetVariant, structNode ? structNode.variantId : null)) return;

    const higherLevelFuncStr = funcObj.higherLevelFunc || (scope.isPFMEA ? 'Process Item Function' : 'System Function');
    const reqIds = reqMap[fl.id] || [];
    const assignedReqs = reqsList.filter(r => reqIds.includes(r.id) && matchesVariantFilter(r.variants || r.variantId, targetVariant, funcObj.variants || (structNode ? structNode.variantId : null)));
    const reqTextStr = assignedReqs.length > 0 ? assignedReqs.map(r => `${r.reqNo ? r.reqNo + ': ' : ''}${r.text}`).join('; ') : '-';

    (fl.failureModes || []).forEach(fm => {
      if (!matchesVariantFilter(fm.variants || fm.variantId, targetVariant, funcObj.variants || (structNode ? structNode.variantId : null))) return;
      const fmNameStr = formatCleanCellText(fm.name || fl.failureModeName);
      const linkedEffIds = effMap[fm.id] || [];
      const linkedEffects = (fmeaData.libraries && fmeaData.libraries.effects || []).filter(e => linkedEffIds.includes(e.id));
      let validEffects = linkedEffects.filter(e => {
        const desc = (e.desc || e.details || e.description || e.name || '').trim();
        return desc && desc !== '-' && !desc.toLowerCase().includes('(click to edit)');
      });
      // Legacy WB4 flat-format fallback: if no effects in libraries but fl has effectName, synthesize one
      if (validEffects.length === 0 && (fl.effectName || fm.effectName)) {
        const effDesc = fl.effectName || fm.effectName || 'System consequence';
        const effSev = parseInt(fl.severity || fm.severity, 10) || 8;
        validEffects = [{ id: fm.id + '-eff', desc: effDesc, severity: effSev, systemName: '' }];
      }
      const hasValidEffect = validEffects.length > 0;
      const maxSev = hasValidEffect ? validEffects.reduce((max, e) => Math.max(max, parseInt(e.severity) || 10), 1) : (parseInt(fm.severity || fl.severity, 10) || 10);

      const effectsText = hasValidEffect
        ? validEffects.map((e, idx) => {
          const numPrefix = validEffects.length > 1 ? `${idx + 1}. ` : '';
          return `${numPrefix}${escapeHtml(formatCleanCellText(e.desc || e.details || e.description))} <strong>(S:${e.severity || 10})</strong>`;
        }).join('<br>')
        : '-';

      // Calculate Higher Level System Names for Column 1 (Strict 1:1 Link with Failure Effects in Column 8)
      let higherSystemCellHTML = '-';
      if (hasValidEffect) {
        higherSystemCellHTML = validEffects.map((e, idx) => {
          const numPrefix = validEffects.length > 1 ? `${idx + 1}. ` : '';
          const rawSys = (e.systemName || e.system || e.higherLevelSystem || '').trim();
          const sName = (rawSys && rawSys !== '-' && !rawSys.toLowerCase().includes('(click to edit)'))
            ? formatCleanCellText(rawSys)
            : '-';
          return `${numPrefix}${escapeHtml(sName)}`;
        }).join('<br>');
      }

      // Calculate Higher Level Function Names for Column 4 (Strict 1:1 Link with Failure Effects in Column 8)
      let higherFuncCellHTML = '-';
      if (hasValidEffect) {
        higherFuncCellHTML = validEffects.map((e, idx) => {
          const numPrefix = validEffects.length > 1 ? `${idx + 1}. ` : '';
          const rawFunc = (e.functionName || e.function || e.higherLevelFunc || '').trim();
          const fName = (rawFunc && rawFunc !== '-' && !rawFunc.toLowerCase().includes('(click to edit)'))
            ? formatCleanCellText(rawFunc)
            : '-';
          return `${numPrefix}${escapeHtml(fName)}`;
        }).join('<br>');
      }

      const linkedCauseIds = causeMap[fm.id] || [];
      let linkedCauses = (fmeaData.libraries && fmeaData.libraries.causes || []).filter(c => linkedCauseIds.includes(c.id) && matchesVariantFilter(c.variants || c.variantId, targetVariant, fm.variants || funcObj.variants || (structNode ? structNode.variantId : null)));
      // Legacy WB4 flat-format fallback: synthesize a cause from fl fields if libraries is empty
      if (linkedCauses.length === 0 && (fl.causeName || fl.causeId)) {
        const legacyCause = {
          id: fl.causeId || (fm.id + '-cause'),
          details: fl.causeName || 'Root cause',
          desc: fl.causeName || 'Root cause',
          name: fl.causeName || 'Root cause',
          characteristics: fl.characteristic || '-',
          occurrence: parseInt(fl.occurrence, 10) || 3,
          detection: parseInt(fl.detection, 10) || 3,
          ap: fl.actionPriority || 'M',
          variants: ['ALL']
        };
        linkedCauses = [legacyCause];
        // Also synthesize controls from flat fields
        if (fl.preventionControl || fl.detectionControl) {
          const synthCtrlIds = [];
          if (fl.preventionControl) {
            fmeaData.libraries = fmeaData.libraries || {};
            fmeaData.libraries.controls = fmeaData.libraries.controls || [];
            const prevId = legacyCause.id + '-prev';
            if (!fmeaData.libraries.controls.find(c => c.id === prevId)) {
              fmeaData.libraries.controls.push({ id: prevId, desc: fl.preventionControl, type: 'Prevention' });
            }
            synthCtrlIds.push(prevId);
          }
          if (fl.detectionControl) {
            fmeaData.libraries = fmeaData.libraries || {};
            fmeaData.libraries.controls = fmeaData.libraries.controls || [];
            const detId = legacyCause.id + '-det';
            if (!fmeaData.libraries.controls.find(c => c.id === detId)) {
              fmeaData.libraries.controls.push({ id: detId, desc: fl.detectionControl, type: 'Detection' });
            }
            synthCtrlIds.push(detId);
          }
          if (!fmeaData.causeControls) fmeaData.causeControls = {};
          fmeaData.causeControls[legacyCause.id] = synthCtrlIds;
        }
      }

      let fmTotalRows = 0;
      if (linkedCauses.length === 0) {
        fmTotalRows = 1;
      } else {
        linkedCauses.forEach(cause => {
          const actIds = causeActions[cause.id] || [];
          const linkedActions = (fmeaData.libraries && fmeaData.libraries.actions || []).filter(a => actIds.includes(a.id) && matchesVariantFilter(a.variants || a.variantId, targetVariant));
          fmTotalRows += Math.max(1, linkedActions.length);
        });
      }

      let isFirstRowForFm = true;

      if (linkedCauses.length === 0) {
        rowCounter++;
        const fallbackRpnBadge = formatAPBadge(maxSev, 1, 1, isVDA);
        const fallbackRiskStyle = getRiskRatingStyle(maxSev, 1, 1, isVDA);
        if (!isVDA) {
          // AIAG 4th Ed layout (25 Cols)
          html += `<tr>
            <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>
            <td rowspan="${fmTotalRows}">
              <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
              ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
            </td>
            <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>
            <td rowspan="${fmTotalRows}">${effectsText}</td>
            <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${fallbackRiskStyle}">${maxSev}</td>
            <td>-</td>
            <td>-</td>
            <td style="text-align:center;">-</td>
            <td style="text-align:center;">ALL</td>
            <td>-</td>
            <td style="text-align:center; font-weight:bold; ${fallbackRiskStyle}">1</td>
            <td>-</td>
            <td style="text-align:center;">1</td>
            <td style="text-align:center; font-weight:bold;">${fallbackRpnBadge}</td>
            <td>-</td>
            <td style="text-align:center;">-</td>
            <td>-</td>
            <td style="text-align:center;">-</td>
            <td style="text-align:center;">-</td>
            <td>-</td>
            <td style="text-align:center;">-</td>
            <td style="text-align:center;">-</td>
            <td style="text-align:center;">-</td>
            <td style="text-align:center; font-weight:bold;">-</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(formatCleanCellText(fm.comments))}</td>
          </tr>`;
        } else {
          // AIAG-VDA 7-Step layout (28 Cols)
          html += `<tr>
            <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>
            <td rowspan="${fmTotalRows}">${higherSystemCellHTML}</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>
            <td>-</td>
            <td rowspan="${fmTotalRows}">${higherFuncCellHTML}</td>
            <td rowspan="${fmTotalRows}">
              <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
              ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
            </td>
            <td>-</td>
            <td rowspan="${fmTotalRows}">${effectsText}</td>
            <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${fallbackRiskStyle}">${maxSev}</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>
            <td>-</td>
            <td>-</td><td style="text-align:center; font-weight:bold; ${fallbackRiskStyle}">1</td><td>-</td><td style="text-align:center;">1</td>
            <td style="text-align:center; font-weight:bold;">${fallbackRpnBadge}</td>
            <td style="text-align:center;">-</td>
            <td>-</td><td>-</td><td>-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td><td>-</td>
            <td style="text-align:center;">-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(formatCleanCellText(fm.comments))}</td>
          </tr>`;
        }
        return;
      }

      linkedCauses.forEach((cause, cIdx) => {
        const causeNum = linkedCauses.length > 1 ? `${cIdx + 1}. ` : '';
        const causeDetailsStr = `${causeNum}<strong>${escapeHtml(formatCleanCellText(cause.details || ''))}</strong>`;

        const rawCauseElem = (cause.systemElement || cause.workElement || cause.processStep || '').trim();
        const causeWorkElemStr = (rawCauseElem && rawCauseElem !== '-' && !rawCauseElem.toLowerCase().includes('(click to edit)'))
          ? formatCleanCellText(rawCauseElem)
          : '-';

        const rawCauseFunc = (cause.function || cause.lowerLevelFunc || '').trim();
        const causeFuncStr = (rawCauseFunc && rawCauseFunc !== '-' && !rawCauseFunc.toLowerCase().includes('(click to edit)'))
          ? formatCleanCellText(rawCauseFunc)
          : '-';

        const ctrlIds = causeControls[cause.id] || [];
        const linkedCtrls = (fmeaData.libraries && fmeaData.libraries.controls || []).filter(c => ctrlIds.includes(c.id) && matchesVariantFilter(c.variants || c.variantId, targetVariant));
        const prevCtrls = linkedCtrls.filter(c => c.type === 'Prevention').map(c => c.desc).join('; ') || '-';
        const detCtrls = linkedCtrls.filter(c => c.type === 'Detection').map(c => c.desc).join('; ') || '-';

        const occ = parseInt(cause.occurrence) || 1;
        const det = parseInt(cause.detection) || 1;
        const rpnBadge = formatAPBadge(maxSev, occ, det, isVDA);
        const causeRiskStyle = getRiskRatingStyle(maxSev, occ, det, isVDA);
        const causeVarNames = getVariantNamesDisplay(cause.variants) || 'ALL';
        const causeClassSym = cause.classSymbol || cause.class || '-';

        const actIds = causeActions[cause.id] || [];
        const linkedActions = (fmeaData.libraries && fmeaData.libraries.actions || []).filter(a => actIds.includes(a.id) && matchesVariantFilter(a.variants || a.variantId, targetVariant));

        const causeRowspan = Math.max(1, linkedActions.length);
        const causeComments = cause.comments || (fm ? fm.comments : null) || '';
        const causeCommentsStr = formatCleanCellText(causeComments);

        if (linkedActions.length === 0) {
          rowCounter++;
          if (!isVDA) {
            // AIAG 4th Ed (26 cols)
            html += `<tr>
              <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>`;
            if (isFirstRowForFm) {
              html += `
              <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>
              <td rowspan="${fmTotalRows}">
                <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
                ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
              </td>
              <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>
              <td rowspan="${fmTotalRows}">${effectsText}</td>
              <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${maxSev}</td>`;
              isFirstRowForFm = false;
            }
            const causeFullText = `${causeDetailsStr}${causeFuncStr !== '-' ? '<br/><span style="color:#64748b; font-size:10px;">Func: ' + escapeHtml(causeFuncStr) + '</span>' : ''}`;
            html += `
              <td>${causeFullText}</td>
              <td>${escapeHtml(formatCleanCellText(cause.characteristics || cause.characteristic || cause.spec || '-'))}</td>
              <td style="text-align:center;">${escapeHtml(causeClassSym)}</td>
              <td style="text-align:center;">${escapeHtml(causeVarNames)}</td>
              <td>${escapeHtml(prevCtrls)}</td>
              <td style="text-align:center; font-weight:bold; ${causeRiskStyle}">${occ}</td>
              <td>${escapeHtml(detCtrls)}</td>
              <td style="text-align:center;">${det}</td>
              <td style="text-align:center; font-weight:bold;">${rpnBadge}</td>
              <td>-</td>
              <td style="text-align:center;">-</td>
              <td>-</td>
              <td style="text-align:center;">-</td>
              <td style="text-align:center;">-</td>
              <td>-</td>
              <td style="text-align:center;">-</td>
              <td style="text-align:center;">-</td>
              <td style="text-align:center;">-</td>
              <td style="text-align:center; font-weight:bold;">-</td>
              <td>${escapeHtml(causeCommentsStr)}</td>
            </tr>`;
          } else {
            // AIAG-VDA 7-Step (28 cols)
            html += `<tr>
              <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>`;
            if (isFirstRowForFm) {
              html += `
              <td rowspan="${fmTotalRows}">${higherSystemCellHTML}</td>
              <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>`;
            }
            html += `<td>${escapeHtml(causeWorkElemStr)}</td>`;
            if (isFirstRowForFm) {
              html += `
              <td rowspan="${fmTotalRows}">${higherFuncCellHTML}</td>
              <td rowspan="${fmTotalRows}">
                <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
                ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
              </td>`;
            }
            html += `<td>${escapeHtml(causeFuncStr)}</td>`;
            if (isFirstRowForFm) {
              html += `
              <td rowspan="${fmTotalRows}">${effectsText}</td>
              <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${maxSev}</td>
              <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>`;
              isFirstRowForFm = false;
            }
            html += `
              <td>${causeDetailsStr}</td>
              <td>${escapeHtml(prevCtrls)}</td>
              <td style="text-align:center; font-weight:bold; ${causeRiskStyle}">${occ}</td>
              <td>${escapeHtml(detCtrls)}</td>
              <td style="text-align:center;">${det}</td>
              <td style="text-align:center; font-weight:bold;">${rpnBadge}</td>
              <td style="text-align:center;">${escapeHtml(causeClassSym)}</td>
              <td>-</td><td>-</td><td>-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td><td>-</td>
              <td style="text-align:center;">-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td>
              <td>${escapeHtml(causeCommentsStr)}</td>
            </tr>`;
          }
        } else {
          const activeActions = linkedActions.filter(a => a.status !== 'Cancelled' && a.status !== 'Discarded');
          const hasActiveActionDetail = activeActions.some(a => a.detail && String(a.detail).trim() !== '' && a.detail !== '-');
          const hasAnyActionDetail = hasActiveActionDetail;
          const firstAct = activeActions[0] || linkedActions[0] || {};
          const s2 = parseInt(cause.s2) || maxSev;
          const o2 = parseInt(cause.o2) || occ;
          const d2 = parseInt(cause.d2) || det;
          const rpn2Badge = hasAnyActionDetail ? formatAPBadge(s2, o2, d2, isVDA) : '-';
          const actRiskStyle = hasAnyActionDetail ? getRiskRatingStyle(s2, o2, d2, isVDA) : '';

          linkedActions.forEach((act, actIdx) => {
            rowCounter++;
            const isFirstRowForCause = (actIdx === 0);
            const actDetailStr = formatCleanCellText(act.detail || act.desc || act.actionDetails || '');
            const isPreventive = (act.type === 'Prevention' || act.actionType === 'Prevention');
            const prevActStr = isPreventive ? actDetailStr : '-';
            const detActStr = !isPreventive ? actDetailStr : '-';
            const actStatusStr = act.status || (act.completionDate ? 'Passed' : (actDetailStr !== '-' ? 'Planned' : '-'));
            const actTakenStr = actDetailStr !== '-' ? (act.actionTaken ? act.actionTaken + (act.completionDate ? ' (' + act.completionDate + ')' : '') : '-') : '-';

            if (!isVDA) {
              // AIAG 4th Ed (26 cols)
              html += `<tr>
                <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>`;
              if (isFirstRowForFm) {
                html += `
                <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>
                <td rowspan="${fmTotalRows}">
                  <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
                  ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
                </td>
                <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>
                <td rowspan="${fmTotalRows}">${effectsText}</td>
                <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${maxSev}</td>`;
                isFirstRowForFm = false;
              }
              if (isFirstRowForCause) {
                const causeFullText = `${causeDetailsStr}${causeFuncStr !== '-' ? '<br/><span style="color:#64748b; font-size:10px;">Func: ' + escapeHtml(causeFuncStr) + '</span>' : ''}`;
                html += `
                  <td rowspan="${causeRowspan}">${causeFullText}</td>
                  <td rowspan="${causeRowspan}">${escapeHtml(formatCleanCellText(cause.characteristics || cause.characteristic || cause.spec || '-'))}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center;">${escapeHtml(causeClassSym)}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center;">${escapeHtml(causeVarNames)}</td>
                  <td rowspan="${causeRowspan}">${escapeHtml(prevCtrls)}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${occ}</td>
                  <td rowspan="${causeRowspan}">${escapeHtml(detCtrls)}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center;">${det}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold;">${rpnBadge}</td>`;
              }
              html += `
                <td>${escapeHtml(actDetailStr)}</td>
                <td style="text-align:center;">${isPreventive ? 'P' : (actDetailStr !== '-' ? 'D' : '-')}</td>
                <td>${actDetailStr !== '-' ? escapeHtml(act.responsible || '-') : '-'}</td>
                <td style="text-align:center;">${actDetailStr !== '-' ? (act.targetDate || '-') : '-'}</td>
                <td style="text-align:center;">${actDetailStr !== '-' ? escapeHtml(actStatusStr) : '-'}</td>
                <td>${escapeHtml(actTakenStr)}</td>`;
              if (isFirstRowForCause) {
                html += `
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold; ${actRiskStyle}">${hasAnyActionDetail ? s2 : '-'}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold; ${actRiskStyle}">${hasAnyActionDetail ? o2 : '-'}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center;">${hasAnyActionDetail ? d2 : '-'}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold;">${rpn2Badge}</td>
                  <td rowspan="${causeRowspan}">${escapeHtml(causeCommentsStr)}</td>`;
              }
              html += `</tr>`;
            } else {
              // AIAG-VDA 7-Step (28 cols)
              html += `<tr>
                <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>`;
              if (isFirstRowForFm) {
                html += `
                <td rowspan="${fmTotalRows}">${higherSystemCellHTML}</td>
                <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>`;
              }
              if (isFirstRowForCause) {
                html += `<td rowspan="${causeRowspan}">${escapeHtml(causeWorkElemStr)}</td>`;
              }
              if (isFirstRowForFm) {
                html += `
                <td rowspan="${fmTotalRows}">${higherFuncCellHTML}</td>
                <td rowspan="${fmTotalRows}">
                  <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
                  ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
                </td>`;
              }
              if (isFirstRowForCause) {
                html += `<td rowspan="${causeRowspan}">${escapeHtml(causeFuncStr)}</td>`;
              }
              if (isFirstRowForFm) {
                html += `
                <td rowspan="${fmTotalRows}">${effectsText}</td>
                <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${maxSev}</td>
                <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>`;
                isFirstRowForFm = false;
              }
              if (isFirstRowForCause) {
                html += `
                  <td rowspan="${causeRowspan}">${causeDetailsStr}</td>
                  <td rowspan="${causeRowspan}">${escapeHtml(prevCtrls)}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${occ}</td>
                  <td rowspan="${causeRowspan}">${escapeHtml(detCtrls)}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center;">${det}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold;">${rpnBadge}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center;">${escapeHtml(causeClassSym)}</td>`;
              }
              html += `
                <td>${escapeHtml(prevActStr)}</td>
                <td>${escapeHtml(detActStr)}</td>
                <td>${actDetailStr !== '-' ? escapeHtml(act.responsible || '-') : '-'}</td>
                <td style="text-align:center;">${actDetailStr !== '-' ? (act.targetDate || '-') : '-'}</td>
                <td style="text-align:center;">${actDetailStr !== '-' ? escapeHtml(actStatusStr) : '-'}</td>
                <td>${escapeHtml(actTakenStr)}</td>`;
              if (isFirstRowForCause) {
                html += `
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold; ${actRiskStyle}">${hasAnyActionDetail ? s2 : '-'}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold; ${actRiskStyle}">${hasAnyActionDetail ? o2 : '-'}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center;">${hasAnyActionDetail ? d2 : '-'}</td>
                  <td rowspan="${causeRowspan}" style="text-align:center; font-weight:bold;">${rpn2Badge}</td>
                  <td rowspan="${causeRowspan}">${escapeHtml(causeCommentsStr)}</td>`;
              }
              html += `</tr>`;
            }
          });
        }
      });
    });
  });

  return html;
}

async function exportToExcel(nodeIds, targetScopes, targetVariant) {
  if (!targetScopes || targetScopes.length === 0) {
    const selectedScopeVals = getSelectedScopeValues('exportScopeMultiSelectContainer');
    targetScopes = resolveSelectedScopes(selectedScopeVals);
  }
  if (!targetVariant) {
    const varSelect = document.getElementById('exportVariantSelect');
    targetVariant = varSelect ? varSelect.value : (typeof selectedVariantFilter !== 'undefined' ? selectedVariantFilter : 'ALL');
  }

  const isVDA = (fmeaData.methodologyMode === 'AIAG-VDA');

  let html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
  <head><meta charset="utf-8"/><style>
    table { border-collapse: collapse; width: 100%; font-family: Arial, sans-serif; font-size: 11px; margin-bottom: 20px; }
    th { background-color: #1e293b; color: #ffffff; border: 1px solid #475569; padding: 6px; text-align: center; font-size: 10px; }
    td { border: 1px solid #cbd5e1; padding: 5px; vertical-align: top; }
  </style></head>
  <body>`;

  targetScopes.forEach(scope => {
    const rowsHtml = buildScopeTableRowsHTML(scope, nodeIds, targetVariant);
    const headerBlock = getAiagVdaHeaderHTML(scope, false);
    const varDisplay = targetVariant && targetVariant !== 'ALL' ? ` (Variant: ${escapeHtml(targetVariant)})` : '';
    const isPFMEA = scope.isPFMEA;

    html += `
    <div style="margin-bottom:20px;">
      ${headerBlock}
      ${varDisplay ? `<div style="font-weight:bold; font-size:11px; margin-bottom:6px; color:#1e293b;">🔍 ${varDisplay}</div>` : ''}
      <table>
        ${getScopeTableHeaderHTML(isVDA, isPFMEA)}
        <tbody>
          ${rowsHtml || `<tr><td colspan="${isVDA ? 29 : 26}" style="text-align:center; padding:15px;">No FMEA items defined for ${escapeHtml(scope.name || 'Scope')}${varDisplay}.</td></tr>`}
        </tbody>
      </table>
    </div><br/>`;
  });

  html += `</body></html>`;

  const fileName = `AIAG_VDA_FMEA_Report_${new Date().toISOString().slice(0, 10)}.xls`;

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const saveFn = window.electronAPI.showSaveDialog || window.electronAPI.saveDialog;
      const saveRes = await saveFn(fileName);
      if (saveRes && !saveRes.canceled && saveRes.filePath) {
        const writeRes = await window.electronAPI.writeFile(saveRes.filePath, html);
        if (writeRes && writeRes.success !== false) {
          showToast(`📊 Exported FMEA Excel report to: ${saveRes.filePath}`);
        } else {
          alert(`Error saving Excel file: ${writeRes ? writeRes.error : 'Unknown error'}`);
        }
        return;
      }
    } catch (e) {
      console.warn("Electron Excel save fallback:", e);
    }
  }

  const blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  showToast(`📊 Downloaded FMEA Excel report!`);
}

function getInsightsExportDataset() {
  const selectedScopeVals = getSelectedScopeValues('dashScopeMultiSelectContainer');
  const targetScopes = resolveSelectedScopes(selectedScopeVals);
  const variantFilter = document.getElementById('dashVariantSelect')?.value || 'ALL';

  fmeaData.rpnSettings = fmeaData.rpnSettings || { mode: 'AIAG', highThreshold: 100, medThreshold: 80 };
  const rpnCriteriaMode = document.getElementById('dashRpnCriteriaSelect')?.value || fmeaData.rpnSettings.mode || 'AIAG';
  const rpnHighThreshold = parseInt(document.getElementById('dashRpnHighThresholdInput')?.value) || fmeaData.rpnSettings.highThreshold || 100;
  const rpnMedThreshold = parseInt(document.getElementById('dashRpnMedThresholdInput')?.value) || fmeaData.rpnSettings.medThreshold || 80;

  const libraries = fmeaData.libraries || {};
  const allEffects = libraries.effects || [];
  const allCauses = libraries.causes || [];
  const allActions = libraries.actions || [];
  const todayStr = new Date().toISOString().slice(0, 10);

  const itemsList = [];
  const actionsList = [];
  const processedActionIds = new Set();

  let totalItemsCount = 0;
  let currentHighCount = 0, currentMedCount = 0, currentLowCount = 0;

  targetScopes.forEach(scope => {
    const scopeName = scope.name || (scope.isPFMEA ? 'PFMEA' : 'DFMEA');
    const fmeaType = scope.isPFMEA ? 'PFMEA' : 'DFMEA';
    const fls = scope.functionLines || [];
    const effMap = scope.failureModeEffects || fmeaData.failureModeEffects || {};
    const causeMap = scope.failureModeCauses || fmeaData.failureModeCauses || {};
    const causeActionsMap = scope.causeActions || fmeaData.causeActions || {};

    fls.forEach(fl => {
      if (variantFilter !== 'ALL') {
        const flVars = Array.isArray(fl.variantId) ? fl.variantId : [fl.variantId];
        if (!flVars.includes('ALL') && !flVars.includes(variantFilter)) return;
      }

      const processOrFunction = (fl.functionName || fl.processName || fl.elementName || fl.name || 'General Process').trim();

      (fl.failureModes || []).forEach(fm => {
        const fmName = (fm.name || fm.failureModeName || 'General Failure Mode').trim();
        const linkedEffIds = effMap[fm.id] || [];
        let linkedEffects = allEffects.filter(e => linkedEffIds.includes(e.id));
        if (linkedEffects.length === 0 && (fm.effects || []).length > 0) linkedEffects = fm.effects;

        const validEffects = linkedEffects.filter(e => {
          const desc = (e.desc || e.details || e.description || e.name || '').trim();
          return desc && desc !== '-' && !desc.toLowerCase().includes('(click to edit)');
        });
        if (validEffects.length === 0) return; // Exclude items without linked effect

        const effectDesc = validEffects.map(e => e.description || e.desc || e.name || '').filter(Boolean).join('; ') || 'No Effect Specified';
        const s1 = validEffects.reduce((max, e) => Math.max(max, parseInt(e.severity) || 10), 1);

        const linkedCauseIds = causeMap[fm.id] || [];
        let linkedCauses = allCauses.filter(c => linkedCauseIds.includes(c.id));
        if (linkedCauses.length === 0 && (fm.causes || []).length > 0) linkedCauses = fm.causes;

        const validCauses = linkedCauses.filter(c => {
          const detail = (c.details || c.desc || c.description || c.name || '').trim();
          return detail && detail !== '-' && !detail.toLowerCase().includes('(click to edit)');
        });
        if (validCauses.length === 0) return; // Exclude items without linked cause

        validCauses.forEach(c => {
          totalItemsCount++;
          const causeDesc = (c.details || c.description || c.name || 'No Cause Specified').trim();
          const o1 = parseInt(c.occurrence) || 10;
          const d1 = parseInt(c.detection) || 10;
          const rpn1 = s1 * o1 * d1;
          const ap1 = computeAP(s1, o1, d1);

          const currentCat = evalRiskCategory(s1, rpn1, rpnHighThreshold, rpnMedThreshold, 40);
          if ((activeDashboardMode === 'AIAG' && currentCat === 'H') || (activeDashboardMode !== 'AIAG' && ap1 === 'H')) currentHighCount++;
          else if ((activeDashboardMode === 'AIAG' && currentCat === 'M') || (activeDashboardMode !== 'AIAG' && ap1 === 'M')) currentMedCount++;
          else currentLowCount++;

          const directActions = c.recommendedActions || c.actions || (c.recommendedAction ? [c.recommendedAction] : []);
          const actIds = causeActionsMap[c.id] || [];
          const libraryActions = allActions.filter(a => actIds.includes(a.id));

          const combinedActList = [...directActions];
          libraryActions.forEach(la => {
            if (!combinedActList.some(da => da.id === la.id)) combinedActList.push(la);
          });

          const validActList = combinedActList.filter(act => {
            const detail = (act.detail || act.details || act.name || act.actionDetails || act.desc || '').trim();
            return detail && detail.toLowerCase() !== 'recommended action' && !detail.toLowerCase().includes('(click to edit)');
          });

          let actDetail = '', actOwner = '', targetDate = '', actTaken = '', compDate = '', actStatus = 'None';
          let s2 = s1, o2 = o1, d2 = d1, rpn2 = rpn1, ap2 = ap1;

          if (validActList.length > 0) {
            const act = validActList[0];
            actDetail = (act.detail || act.details || act.name || act.actionDetails || act.desc || '').trim();
            actOwner = (act.responsible || act.owner || act.respPerson || act.assignee || 'Unassigned').trim();
            targetDate = act.targetDate || act.target_date || 'TBD';
            actTaken = act.actionTaken || act.notes || act.remarks || act.comment || '-';
            compDate = act.completionDate || act.completion_date || '-';

            const rawStatus = act.status || (act.completionDate ? 'Passed' : 'Planned');
            const isOverdue = act.targetDate && act.targetDate < todayStr && rawStatus !== 'Passed' && rawStatus !== 'Completed';
            actStatus = isOverdue ? 'Overdue' : rawStatus;

            const activeActions = validActList.filter(a => a.status !== 'Cancelled' && a.status !== 'Discarded');
            const hasActiveAction = activeActions.length > 0;
            const completedActions = activeActions.filter(a => a.status === 'Passed' || a.status === 'Completed' || (a.completionDate && a.completionDate !== '-'));
            const allActiveCompleted = hasActiveAction && (completedActions.length === activeActions.length);
            s2 = hasActiveAction ? (parseInt(c.s2) || parseInt(act.revisedSev || act.s2) || s1) : s1;
            o2 = hasActiveAction ? (parseInt(c.o2) || parseInt(act.revisedOcc || act.o2) || o1) : o1;
            d2 = hasActiveAction ? (parseInt(c.d2) || parseInt(act.revisedDet || act.d2) || d1) : d1;
            rpn2 = s2 * o2 * d2;
            ap2 = computeAP(s2, o2, d2);

            validActList.forEach(aItem => {
              const aKey = aItem.id || `${scopeName}_${fmName}_${actDetail.toLowerCase()}`;
              if (!processedActionIds.has(aKey)) {
                processedActionIds.add(aKey);
                actionsList.push({
                  actionId: aKey,
                  scopeName: scopeName,
                  fmeaType: fmeaType,
                  failureMode: fmName,
                  actionDetails: (aItem.detail || aItem.details || aItem.name || '').trim(),
                  owner: (aItem.responsible || aItem.owner || 'Unassigned').trim(),
                  targetDate: aItem.targetDate || 'TBD',
                  actionTaken: aItem.actionTaken || '-',
                  completionDate: aItem.completionDate || '-',
                  status: aItem.targetDate && aItem.targetDate < todayStr && aItem.status !== 'Passed' && aItem.status !== 'Completed' ? 'Overdue' : (aItem.status || 'Planned')
                });
              }
            });
          }

          itemsList.push({
            Scope_Name: scopeName,
            FMEA_Type: fmeaType,
            Process_Function: processOrFunction,
            Failure_Mode: fmName,
            Effect_Details: effectDesc,
            Cause_Details: causeDesc,
            Severity_S1: s1,
            Occurrence_O1: o1,
            Detection_D1: d1,
            RPN_1: rpn1,
            AP_1: ap1,
            Risk_Level_1: currentCat === 'H' ? 'High' : (currentCat === 'M' ? 'Medium' : 'Low'),
            Action_Details: actDetail || 'None',
            Action_Owner: actOwner || 'Unassigned',
            Target_Date: targetDate || 'TBD',
            Action_Taken: actTaken || '-',
            Completion_Date: compDate || '-',
            Action_Status: actStatus,
            Revised_S2: s2,
            Revised_O2: o2,
            Revised_D2: d2,
            RPN_2: rpn2,
            AP_2: ap2
          });
        });
      });
    });
  });

  return {
    metadata: {
      exportedAt: new Date().toISOString(),
      activeDashboardMode: activeDashboardMode,
      selectedScopes: targetScopes.map(s => s.name || (s.isPFMEA ? 'PFMEA' : 'DFMEA')),
      variantFilter: variantFilter,
      rpnCriteria: { mode: rpnCriteriaMode, highThreshold: rpnHighThreshold, medThreshold: rpnMedThreshold }
    },
    summaryMetrics: {
      totalItemsEvaluated: totalItemsCount,
      riskDistribution: { high: currentHighCount, medium: currentMedCount, low: currentLowCount },
      totalRegisteredActions: actionsList.length
    },
    riskItems: itemsList,
    actionsList: actionsList
  };
}

async function exportDashboardInsightsToJSON() {
  const dataset = buildPowerBIDashboardData(fmeaData, activeSharePointFileName) || getInsightsExportDataset();
  const jsonStr = JSON.stringify(dataset, null, 2);
  const fileName = `JOST_PowerBI_Dashboard_Data_${new Date().toISOString().slice(0, 10)}.json`;

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const saveFn = window.electronAPI.showSaveDialog || window.electronAPI.saveDialog;
      const saveRes = await saveFn(fileName);
      if (saveRes && !saveRes.canceled && saveRes.filePath) {
        await window.electronAPI.writeFile(saveRes.filePath, jsonStr);
        showToast(`📊 Exported PowerBI JSON Insights to [${saveRes.filePath}]`);
        return;
      }
    } catch (e) {
      console.warn("Electron save dialog fallback:", e);
    }
  }

  const blob = new Blob([jsonStr], { type: 'application/json;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  showToast(`📊 Downloaded PowerBI JSON Insights file!`);
}

async function exportDashboardInsightsToExcel() {
  const dataset = getInsightsExportDataset();
  const items = dataset.riskItems;

  if (!items || items.length === 0) {
    alert("No risk items available to export.");
    return;
  }

  const headers = Object.keys(items[0]);
  const csvRows = [];
  csvRows.push(headers.join('\t'));

  items.forEach(item => {
    const row = headers.map(h => {
      let val = item[h] !== undefined && item[h] !== null ? String(item[h]) : '';
      val = val.replace(/\r?\n|\r/g, ' ').replace(/\t/g, ' ');
      return val;
    });
    csvRows.push(row.join('\t'));
  });

  const fileContent = csvRows.join('\n');
  const fileName = `JOST_FMEA_Dashboard_Insights_${new Date().toISOString().slice(0, 10)}.xls`;

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const saveFn = window.electronAPI.showSaveDialog || window.electronAPI.saveDialog;
      const saveRes = await saveFn(fileName);
      if (saveRes && !saveRes.canceled && saveRes.filePath) {
        await window.electronAPI.writeFile(saveRes.filePath, fileContent);
        showToast(`📊 Exported PowerBI Excel/CSV Insights to [${saveRes.filePath}]`);
        return;
      }
    } catch (e) {
      console.warn("Electron save dialog fallback:", e);
    }
  }

  const blob = new Blob(['\ufeff' + fileContent], { type: 'application/vnd.ms-excel;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  showToast(`📊 Downloaded PowerBI Excel/CSV Insights file!`);
}

function exportToPDF(nodeIds, targetScopes, targetVariant, repeatHeaderEveryPage = false) {
  if (!targetScopes || targetScopes.length === 0) {
    const selectedScopeVals = getSelectedScopeValues('exportScopeMultiSelectContainer');
    targetScopes = resolveSelectedScopes(selectedScopeVals);
  }
  if (!targetVariant) {
    const varSelect = document.getElementById('exportVariantSelect');
    targetVariant = varSelect ? varSelect.value : (typeof selectedVariantFilter !== 'undefined' ? selectedVariantFilter : 'ALL');
  }

  const isVDA = (fmeaData.methodologyMode === 'AIAG-VDA');

  // Check section inclusion options from modal
  const includeVariantMatrix = document.getElementById('chk_exportIncludeVariantMatrix') ? document.getElementById('chk_exportIncludeVariantMatrix').checked : true;
  const includeRevHistory = document.getElementById('chk_exportIncludeRevHistory') ? document.getElementById('chk_exportIncludeRevHistory').checked : true;
  const includeFmeaData = document.getElementById('chk_exportIncludeFmeaData') ? document.getElementById('chk_exportIncludeFmeaData').checked : true;

  let pagesHTML = '';

  // 1. Page 1: Product & Variant Master Matrix Table (if checked & variants exist)
  if (includeVariantMatrix) {
    const isPFMEAExport = targetScopes.some(s => s.isPFMEA || s.pfmea);
    const docType = isPFMEAExport ? 'PFMEA' : 'DFMEA';
    const matrixHTML = getVariantHeaderMatrixHTML(docType);
    if (matrixHTML && matrixHTML.trim()) {
      pagesHTML += `
        <div class="scope-section print-page-cover" style="page-break-after:always; break-after:page; margin-bottom:15px;">
          ${matrixHTML}
        </div>
      `;
    }
  }

  // 2. Page 2: Complete Revision History Table (Relevant to exported scopes)
  if (includeRevHistory) {
    let revSectionsHTML = '';
    const seenScopes = new Set();
    targetScopes.forEach(scope => {
      const isPFMEA = scope.isPFMEA || (scope.pfmea ? true : false);
      const scopeKey = isPFMEA ? `PFMEA_${scope.id || (scope.pfmea && scope.pfmea.id) || ''}` : 'DFMEA';
      if (!seenScopes.has(scopeKey)) {
        seenScopes.add(scopeKey);
        const pfId = isPFMEA ? (scope.id || (scope.pfmea && scope.pfmea.id)) : '';
        const revHTML = getCompleteRevisionHistoryTableHTML(isPFMEA ? 'PFMEA' : 'DFMEA', pfId);
        if (revHTML && revHTML.trim()) {
          revSectionsHTML += revHTML;
        }
      }
    });

    if (revSectionsHTML && revSectionsHTML.trim()) {
      pagesHTML += `
        <div class="scope-section print-page-revision" style="page-break-after:always; break-after:page; margin-bottom:15px;">
          ${revSectionsHTML}
        </div>
      `;
    }
  }

  // 3. Subsequent Pages: FMEA Scope Data Tables (if checked)
  if (includeFmeaData) {
    targetScopes.forEach(scope => {
      const headerHTML = getAiagVdaHeaderHTML(scope, false);
      const rowsHtml = buildScopeTableRowsHTML(scope, nodeIds, targetVariant);
      const isPFMEA = scope.isPFMEA || (scope.pfmea ? true : false);
      const varDisplay = targetVariant && targetVariant !== 'ALL' ? ` (Variant Filter: ${escapeHtml(targetVariant)})` : '';

      if (repeatHeaderEveryPage) {
        pagesHTML += `
          <div class="scope-section">
            ${varDisplay ? `<div style="font-weight:bold; font-size:11px; margin-bottom:6px; color:#1e293b;">🔍 ${varDisplay}</div>` : ''}
            <table>
              ${getScopeTableHeaderHTML(isVDA, isPFMEA, headerHTML)}
              <tbody>
                ${rowsHtml || `<tr><td colspan="${isVDA ? 29 : 26}" style="text-align:center; padding:15px; color:#64748b;">No FMEA items defined for this scope ${varDisplay}.</td></tr>`}
              </tbody>
            </table>
          </div>
        `;
      } else {
        pagesHTML += `
          <div class="scope-section">
            ${headerHTML}
            ${varDisplay ? `<div style="font-weight:bold; font-size:11px; margin-bottom:6px; color:#1e293b;">🔍 ${varDisplay}</div>` : ''}
            <table>
              ${getScopeTableHeaderHTML(isVDA, isPFMEA)}
              <tbody>
                ${rowsHtml || `<tr><td colspan="${isVDA ? 29 : 26}" style="text-align:center; padding:15px; color:#64748b;">No FMEA items defined for this scope ${varDisplay}.</td></tr>`}
              </tbody>
            </table>
          </div>
        `;
      }
    });
  }

  const projectName = (fmeaData && fmeaData.projectInfo && fmeaData.projectInfo.name) || fmeaData.projectName || 'JOST FMEA';
  const reportDocTitle = `${isVDA ? 'AIAG-VDA' : 'AIAG'} FMEA Report — ${projectName}`;

  const reportHtml = `<!DOCTYPE html>
    <html>
      <head>
        <title>${escapeHtml(reportDocTitle)}</title>
        <style>
          @page {
            size: A3 landscape;
            margin: 10mm 6mm 10mm 6mm;
          }
          * {
            box-sizing: border-box;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
            color-adjust: exact !important;
          }
          body {
            font-family: 'Segoe UI', Arial, sans-serif;
            padding: 0;
            margin: 0;
            font-size: 8.5px;
            color: #000;
            background: #fff;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
          }
          .scope-section {
            page-break-after: always;
            break-after: page;
            margin-bottom: 0px;
          }
          .scope-section:last-child {
            page-break-after: auto;
            break-after: auto;
          }
          table {
            width: 100%;
            border-collapse: collapse;
            font-size: 8.5px;
            page-break-inside: auto;
            break-inside: auto;
          }
          thead {
            display: table-header-group !important;
          }
          tfoot {
            display: table-footer-group !important;
          }
          tbody {
            display: table-row-group !important;
          }
          tr {
            page-break-inside: avoid;
            break-inside: avoid;
            page-break-after: auto;
            break-after: auto;
          }
          .project-header-print-row th {
            background: transparent !important;
            border: none !important;
            padding: 0 0 6px 0 !important;
          }
          th, td {
            border: 1px solid #334155;
            padding: 2.5px 4px;
            vertical-align: top;
            text-align: left;
            word-break: break-word;
            line-height: 1.25;
          }
          th {
            background: #e2e8f0 !important;
            color: #0f172a !important;
            font-weight: bold;
            text-align: center;
            font-size: 8.5px;
            -webkit-print-color-adjust: exact !important;
          }
        </style>
      </head>
      <body>
        ${pagesHTML}
      </body>
    </html>`;

  if (typeof window !== 'undefined' && typeof window.executeHtmlPrint === 'function') {
    window.executeHtmlPrint(reportHtml);
  } else {
    executeHtmlPrint(reportHtml);
  }
}

function unlockApplicationPointerEvents() {
  document.querySelectorAll('.nav-dropdown').forEach(m => {
    m.style.display = 'none';
  });
  if (document.activeElement && document.activeElement !== document.body) {
    try { document.activeElement.blur(); } catch (e) { }
  }
  document.body.style.pointerEvents = 'auto';

  const ws = document.getElementById('appWorkspaceWrapper') || document.body;
  if (ws) {
    const prevPos = ws.style.position;
    ws.style.position = 'relative';
    ws.offsetHeight;
    ws.style.position = prevPos;
  }

  window.dispatchEvent(new Event('resize'));
  try {
    window.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, clientX: 10, clientY: 10 }));
  } catch (e) { }
}

window.addEventListener('focus', unlockApplicationPointerEvents);
window.addEventListener('afterprint', unlockApplicationPointerEvents);

async function executeHtmlPrint(htmlContent) {
  // ── Electron native PDF path ───────────────────────────────────────────────
  if (window.electronAPI && typeof window.electronAPI.printToPdf === 'function') {
    // Show a non-blocking progress toast
    const toastId = '_pdfGenToast';
    let toastEl = document.getElementById(toastId);
    if (!toastEl) {
      toastEl = document.createElement('div');
      toastEl.id = toastId;
      toastEl.style.cssText = `
        position:fixed; bottom:28px; left:50%; transform:translateX(-50%);
        background:#1e293b; color:#f8fafc; font-size:13px; font-weight:600;
        padding:12px 24px; border-radius:10px; z-index:9999999;
        border:1px solid #334155; box-shadow:0 8px 32px rgba(0,0,0,0.5);
        display:flex; align-items:center; gap:10px; white-space:nowrap;
      `;
      document.body.appendChild(toastEl);
    }
    toastEl.innerHTML = `<span style="font-size:16px;">⏳</span> Generating PDF… please wait`;
    toastEl.style.display = 'flex';

    const removeToast = () => { if (toastEl) toastEl.style.display = 'none'; };

    try {
      const result = await window.electronAPI.printToPdf(htmlContent);

      if (!result || !result.success) {
        removeToast();
        const errMsg = (result && result.error) ? result.error : 'Unknown error';
        if (typeof showToast === 'function') showToast(`❌ PDF generation failed: ${errMsg}`, 'error');
        else alert(`PDF generation failed: ${errMsg}`);
        unlockApplicationPointerEvents();
        return;
      }

      // Ask the user where to save
      const projectName = (fmeaData && fmeaData.projectInfo && fmeaData.projectInfo.name)
        ? fmeaData.projectInfo.name.replace(/[^a-zA-Z0-9_\-]/g, '_')
        : 'FMEA_Report';
      const defaultName = `${projectName}_${new Date().toISOString().slice(0, 10)}.pdf`;

      const saveResult = await window.electronAPI.showSaveDialog(defaultName);

      if (!saveResult || saveResult.canceled || !saveResult.filePath) {
        removeToast();
        unlockApplicationPointerEvents();
        return; // User cancelled
      }

      // Convert Base64 back to binary and write via IPC (write-file handles path resolution)
      const savePath = saveResult.filePath.endsWith('.pdf') ? saveResult.filePath : saveResult.filePath + '.pdf';

      // Write the raw base64 data as binary via a direct IPC write (pass flag for binary)
      const writeResult = await window.electronAPI.writeFile(savePath + '?binary=1', result.data);

      removeToast();

      if (writeResult && writeResult.success) {
        const finalPath = writeResult.filePath || savePath;
        if (typeof showToast === 'function') {
          showToast(`✅ PDF saved successfully!`, 'success');
        }
        // Offer to reveal in Explorer
        if (typeof window.electronAPI.showItemInFolder === 'function') {
          window.electronAPI.showItemInFolder(finalPath);
        }
      } else {
        const errMsg = (writeResult && writeResult.error) ? writeResult.error : 'Write failed';
        if (typeof showToast === 'function') showToast(`❌ Could not save PDF: ${errMsg}`, 'error');
        else alert(`Could not save PDF: ${errMsg}`);
      }
    } catch (err) {
      removeToast();
      if (typeof showToast === 'function') showToast(`❌ PDF error: ${err.message}`, 'error');
      else alert('PDF error: ' + err.message);
    } finally {
      unlockApplicationPointerEvents();
    }
    return;
  }

  // ── Browser / fallback: iframe print dialog ────────────────────────────────
  const cleanHtml = htmlContent.replace(/<script>[\s\S]*?window\.print\(\);[\s\S]*?<\/script>/gi, '');

  let printIframe = document.getElementById('appPrintIframe');
  if (!printIframe) {
    printIframe = document.createElement('iframe');
    printIframe.id = 'appPrintIframe';
    printIframe.name = 'appPrintIframe';
    printIframe.style.position = 'fixed';
    printIframe.style.right = '0';
    printIframe.style.bottom = '0';
    printIframe.style.width = '1px';
    printIframe.style.height = '1px';
    printIframe.style.border = '0';
    printIframe.style.opacity = '0.01';
    printIframe.style.pointerEvents = 'none';
    document.body.appendChild(printIframe);
  }

  const iframeWin = printIframe.contentWindow;
  const iframeDoc = iframeWin.document;

  iframeDoc.open();
  iframeDoc.write(cleanHtml);
  iframeDoc.close();

  let printed = false;
  const doPrint = () => {
    if (printed) return;
    printed = true;
    try {
      iframeWin.focus();
      iframeWin.print();
    } catch (e) {
      console.warn('Print execution notice:', e);
    } finally {
      setTimeout(unlockApplicationPointerEvents, 100);
      setTimeout(unlockApplicationPointerEvents, 400);
    }
  };

  if (iframeDoc.readyState === 'complete') {
    setTimeout(doPrint, 250);
  } else {
    printIframe.onload = () => setTimeout(doPrint, 250);
    setTimeout(doPrint, 500);
  }
}

let activeModalStackZIndex = 100000;

function openModal(id) {
  try {
    const modal = (typeof id === 'string') ? document.getElementById(id) : id;
    if (!modal) return;

    // Ensure modal is attached to document.body
    if (modal.parentElement !== document.body) {
      document.body.appendChild(modal);
    }

    // Elevate z-index above failureNetworkModal (which is 9999999) if it is open
    const fnModal = document.getElementById('failureNetworkModal');
    if (fnModal && fnModal.style.display !== 'none' && id !== 'failureNetworkModal') {
      activeModalStackZIndex = Math.max(activeModalStackZIndex, 10000050);
    }

    // Calculate dynamic z-index so stacked modals always appear on top
    activeModalStackZIndex += 10;
    modal.style.zIndex = activeModalStackZIndex;
    modal.style.display = 'flex';

    setTimeout(() => {
      try {
        const input = modal.querySelector('input:not([type="hidden"]), select, textarea, button');
        if (input) input.focus();
      } catch (e) { }
    }, 50);
  } catch (err) {
    console.error('Error opening modal:', id, err);
  }
}
window.openModal = openModal;

function closeModal(id) {
  try {
    if (!id) return;
    const modalId = (typeof id === 'string') ? id : (id && id.id);
    const modal = (typeof id === 'string') ? document.getElementById(id) : id;
    if (!modal) return;
    if (document.activeElement && modal.contains && modal.contains(document.activeElement)) {
      document.activeElement.blur();
    }
    modal.style.display = 'none';
    window.focus();

    // 1. Clear any cached severity / render computations so fresh data is computed
    if (window._fmeaRenderSeverityCache && typeof window._fmeaRenderSeverityCache.clear === 'function') {
      window._fmeaRenderSeverityCache.clear();
    }

    // 2. Modals closing should refresh the FMEA table debounced without causing duplicate synchronous renders
    const nonFmeaModals = [
      'loginModal', 'loginScreenOverlay', 'splashScreenOverlay', 'saveNotificationModal',
      'exportModal', 'sharePointBrowserModal', 'fmeaHeaderFilterPopup', 'headerFilterMenu',
      'quickHelpModal', 'systemLogsModal', 'userLogModal',
      'changePasswordModal', 'fileRightsModal', 'sharePointLocationModal', 'aboutModal',
      'meetingRecordsModal', 'checklistReportModal', 'viewSnapshotModal',
      'sharePointFileListModal', 'userGuideModal'
    ];

    if (!modalId || !nonFmeaModals.includes(modalId)) {
      if (typeof scheduleFmeaRender === 'function') {
        scheduleFmeaRender(25, true);
      } else if (typeof renderFMEATable === 'function') {
        renderFMEATable(true);
      }
    }

    requestAnimationFrame(() => {
      window.dispatchEvent(new Event('resize'));
    });
  } catch (err) {
    console.error('Error closing modal:', id, err);
  }
}
window.closeModal = closeModal;

// Global Delegated Close Button Handler for all screens & modals
document.addEventListener('click', function (e) {
  const closeTrigger = e.target.closest('.close-btn, [data-close-modal], .modal-close-btn, .btn-close-modal');
  if (closeTrigger) {
    // If it has inline onclick that already handles specific logic, allow it but catch any unhandled modal
    const targetModal = closeTrigger.closest('.modal') || (closeTrigger.dataset && closeTrigger.dataset.target && document.querySelector(closeTrigger.dataset.target));
    if (targetModal && targetModal.id) {
      if (targetModal.id === 'aiWorkbench4Modal' && typeof closeAiWorkbench4Modal === 'function') {
        try { closeAiWorkbench4Modal(); } catch (err) { closeModal('aiWorkbench4Modal'); }
      } else if (targetModal.id === 'aiWorkbench3Modal' && typeof closeAiWorkbench3Modal === 'function') {
        try { closeAiWorkbench3Modal(); } catch (err) { closeModal('aiWorkbench3Modal'); }
      } else if (targetModal.id === 'aiWorkbench2Modal' && typeof closeAiWorkbench2Modal === 'function') {
        try { closeAiWorkbench2Modal(); } catch (err) { closeModal('aiWorkbench2Modal'); }
      } else {
        closeModal(targetModal.id);
      }
    } else if (targetModal) {
      targetModal.style.display = 'none';
    }
  }
});

// Global Escape Key Handler to close top modal
document.addEventListener('keydown', function (e) {
  if (e.key === 'Escape') {
    const visibleModals = Array.from(document.querySelectorAll('.modal'))
      .filter(m => m.style.display !== 'none' && m.style.display !== '' && window.getComputedStyle(m).display !== 'none');
    if (visibleModals.length > 0) {
      visibleModals.sort((a, b) => {
        const za = parseInt(window.getComputedStyle(a).zIndex) || 0;
        const zb = parseInt(window.getComputedStyle(b).zIndex) || 0;
        return zb - za;
      });
      const topModal = visibleModals[0];
      if (topModal.id === 'aiWorkbench4Modal' && typeof closeAiWorkbench4Modal === 'function') {
        try { closeAiWorkbench4Modal(); } catch (err) { closeModal('aiWorkbench4Modal'); }
      } else if (topModal.id === 'aiWorkbench3Modal' && typeof closeAiWorkbench3Modal === 'function') {
        try { closeAiWorkbench3Modal(); } catch (err) { closeModal('aiWorkbench3Modal'); }
      } else if (topModal.id === 'aiWorkbench2Modal' && typeof closeAiWorkbench2Modal === 'function') {
        try { closeAiWorkbench2Modal(); } catch (err) { closeModal('aiWorkbench2Modal'); }
      } else {
        closeModal(topModal.id);
      }
    }
  }
});

function escapeXml(str) { return escapeHtml(str); }

function showToast(message, duration = 3000) {
  let container = document.getElementById('toastContainer');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toastContainer';
    container.style.cssText = 'position:fixed; bottom:20px; right:20px; z-index:2000000 !important; display:flex; flex-direction:column; gap:8px; pointer-events:none;';
    document.body.appendChild(container);
  } else {
    container.style.zIndex = '2000000';
  }

  const toast = document.createElement('div');
  toast.style.cssText = 'background:#0f172a; color:#ffffff; border:1px solid #3b82f6; border-left:5px solid #10b981; border-radius:8px; padding:12px 18px; font-size:13px; font-weight:600; box-shadow:0 12px 30px rgba(0,0,0,0.5); transition:all 0.3s ease; opacity:0; transform:translateY(10px); pointer-events:auto;';
  toast.textContent = message;

  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '1';
    toast.style.transform = 'translateY(0)';
  }, 10);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(10px)';
    setTimeout(() => toast.remove(), 300);
  }, duration);
}

function evalRiskCategory(s, rpn, highThreshold = 100, medThreshold = 80, sevHighRpnThreshold = 40) {
  s = parseInt(s) || 1;
  rpn = parseInt(rpn) || 1;

  if (s >= 9) {
    if (rpn > sevHighRpnThreshold) return 'H';
    return 'L';
  } else {
    if (rpn > highThreshold) return 'H';
    if (rpn > medThreshold && rpn <= highThreshold) return 'M';
    return 'L';
  }
}

function populateFmeaScopeCheckboxDropdown(containerId, callbackFuncName) {
  const container = document.getElementById(containerId);
  if (!container) return;

  const activeCtx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false };
  const activeName = activeCtx.isPFMEA ? `Active PFMEA: ${activeCtx.pfmea?.name || ''}` : 'Active DFMEA Master';

  const isDvp = (containerId === 'dvpScopeMultiSelectContainer');
  if (isDvp) {
    container.innerHTML = `
      <div style="position:relative; display:inline-block;">
        <button type="button" class="scope-dropdown-btn" disabled style="padding:4px 10px; font-size:11px; border:1px solid var(--border-color, #cbd5e1); border-radius:4px; background:var(--bg-card, #f1f5f9); font-weight:bold; cursor:not-allowed; opacity:0.85; display:flex; align-items:center; justify-content:space-between; min-width:210px; height:32px; color:var(--text-primary, #1e293b);" title="Scope is locked to active file">
          <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:180px;">📍 ${escapeHtml(activeName)}</span>
          <span style="font-size:10px; color:var(--text-muted, #64748b); margin-left:6px;">🔒</span>
        </button>
      </div>
    `;
    container.dataset.selectedValues = JSON.stringify(['ACTIVE']);
    return;
  }

  let currentValues = [];
  if (container.dataset.selectedValues) {
    try { currentValues = JSON.parse(container.dataset.selectedValues); } catch (e) { }
  }
  if (!currentValues || currentValues.length === 0) {
    currentValues = ['ACTIVE'];
  }
  const selectedSet = new Set(currentValues);

  const optionsList = [
    { value: 'ACTIVE', label: `📍 ${activeName}` },
    { value: 'DFMEA', label: '🚗 DFMEA Master Only' }
  ];

  const pfmeas = fmeaData.pfmeas || [];
  if (pfmeas.length > 0) {
    optionsList.push({ isGroupHeader: true, label: 'Process FMEAs (PFMEAs)' });
    optionsList.push({ value: 'ALL_PFMEA', label: `🏭 All PFMEAs (${pfmeas.length})` });
    pfmeas.forEach(p => {
      optionsList.push({ value: `PFMEA_${p.id}`, label: `🏭 PFMEA: ${p.name}` });
    });
  }

  optionsList.push({ isGroupHeader: true, label: 'Entire Project' });
  optionsList.push({ value: 'ALL', label: '🌐 Entire Project (DFMEA + PFMEAs)' });

  let btnLabel = '📍 ' + activeName;
  if (selectedSet.has('ALL')) {
    btnLabel = '🌐 Entire Project (DFMEA + PFMEAs)';
  } else if (selectedSet.size === 1) {
    const singleVal = Array.from(selectedSet)[0];
    const match = optionsList.find(o => o.value === singleVal);
    if (match) btnLabel = match.label;
  } else if (selectedSet.size > 1) {
    btnLabel = `${selectedSet.size} Scopes Selected`;
  }

  let menuHtml = `
    <div style="position:relative; display:inline-block;">
      <button type="button" class="scope-dropdown-btn" onclick="toggleScopeDropdownMenu('${containerId}')" style="padding:4px 10px; font-size:11px; border:1px solid #cbd5e1; border-radius:4px; background:#ffffff; font-weight:bold; cursor:pointer; display:flex; align-items:center; justify-content:space-between; min-width:210px; height:32px; color:#1e293b;">
        <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:180px;">${escapeHtml(btnLabel)}</span>
        <span style="font-size:9px; color:#64748b; margin-left:6px;">▼</span>
      </button>
      <div id="${containerId}_menu" class="scope-dropdown-menu" style="display:none; position:absolute; top:100%; left:0; z-index:1000; background:#ffffff; border:1px solid #cbd5e1; border-radius:6px; box-shadow:0 10px 25px rgba(0,0,0,0.15); width:270px; max-height:260px; overflow-y:auto; padding:6px 0; margin-top:4px;">
  `;

  optionsList.forEach(opt => {
    if (opt.isGroupHeader) {
      menuHtml += `<div style="font-size:10px; font-weight:bold; color:#64748b; padding:6px 12px 2px 12px; text-transform:uppercase; background:#f8fafc; border-top:1px solid #e2e8f0; border-bottom:1px solid #e2e8f0; margin:4px 0 2px 0;">${escapeHtml(opt.label)}</div>`;
    } else {
      const checked = selectedSet.has(opt.value) ? 'checked' : '';
      menuHtml += `
        <label style="display:flex; align-items:center; gap:8px; padding:6px 12px; font-size:12px; color:#334155; cursor:pointer; user-select:none; transition:background 0.15s;" onmouseover="this.style.background='#f1f5f9'" onmouseout="this.style.background='transparent'">
          <input type="checkbox" class="scope-chk-item" value="${escapeHtml(opt.value)}" ${checked} onchange="handleScopeCheckboxChange('${containerId}', '${callbackFuncName}')" style="cursor:pointer; accent-color:#3b82f6;">
          <span style="font-weight:${checked ? '600' : 'normal'};">${escapeHtml(opt.label)}</span>
        </label>
      `;
    }
  });

  menuHtml += `
      </div>
    </div>
  `;

  container.innerHTML = menuHtml;
  container.dataset.selectedValues = JSON.stringify(Array.from(selectedSet));
}

function populateFmeaScopeDropdown(containerOrSelectId) {
  const containerId = containerOrSelectId === 'dvpFmeaScopeSelect' ? 'dvpScopeMultiSelectContainer' : (containerOrSelectId === 'dashFmeaScopeSelect' ? 'dashScopeMultiSelectContainer' : containerOrSelectId);
  const callbackName = containerId.includes('dvp') ? 'renderDvpTable' : 'renderInsightsDashboard';
  populateFmeaScopeCheckboxDropdown(containerId, callbackName);
}

function toggleScopeDropdownMenu(containerId) {
  const menu = document.getElementById(`${containerId}_menu`);
  if (!menu) return;
  const isHidden = menu.style.display === 'none';
  document.querySelectorAll('.scope-dropdown-menu').forEach(m => m.style.display = 'none');
  if (isHidden) {
    menu.style.display = 'block';
  }
}

function handleScopeCheckboxChange(containerId, callbackFuncName) {
  const container = document.getElementById(containerId);
  if (!container) return;

  const checkedBoxes = Array.from(container.querySelectorAll('.scope-chk-item:checked')).map(c => c.value);
  container.dataset.selectedValues = JSON.stringify(checkedBoxes);

  const btnSpan = container.querySelector('.scope-dropdown-btn span');
  if (btnSpan) {
    if (checkedBoxes.includes('ALL')) {
      btnSpan.textContent = '🌐 Entire Project (DFMEA + PFMEAs)';
    } else if (checkedBoxes.length === 1) {
      const singleChk = container.querySelector(`.scope-chk-item[value="${checkedBoxes[0]}"]`);
      const labelText = singleChk ? singleChk.parentElement.textContent.trim() : checkedBoxes[0];
      btnSpan.textContent = labelText;
    } else if (checkedBoxes.length > 1) {
      btnSpan.textContent = `${checkedBoxes.length} Scopes Selected`;
    } else {
      btnSpan.textContent = 'Select Scopes';
    }
  }

  if (typeof window[callbackFuncName] === 'function') {
    window[callbackFuncName]();
  }
}

function getSelectedScopeValues(containerId) {
  const container = document.getElementById(containerId);
  if (container && container.dataset.selectedValues) {
    try {
      const vals = JSON.parse(container.dataset.selectedValues);
      if (Array.isArray(vals) && vals.length > 0) return vals;
    } catch (e) { }
  }
  return ['ACTIVE'];
}

document.addEventListener('click', function (e) {
  if (!e.target.closest('.custom-multiselect')) {
    document.querySelectorAll('.scope-dropdown-menu').forEach(m => m.style.display = 'none');
  }
});

function resolveSelectedScopes(selectedValues) {
  let values = Array.isArray(selectedValues) ? selectedValues : [selectedValues];
  if (values.length === 0) values = ['ACTIVE'];

  const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false };
  let targetScopes = [];
  const addedKeys = new Set();

  values.forEach(val => {
    if (val === 'ALL') {
      if (!addedKeys.has('DFMEA')) {
        addedKeys.add('DFMEA');
        targetScopes.push({
          isPFMEA: false,
          name: 'DFMEA Master',
          functions: fmeaData.functions || [],
          requirements: fmeaData.requirements || [],
          functionRequirements: fmeaData.functionRequirements || {},
          functionLines: fmeaData.functionLines || [],
          failureModeEffects: fmeaData.failureModeEffects || {},
          failureModeCauses: fmeaData.failureModeCauses || {},
          causeControls: fmeaData.causeControls || {},
          causeActions: fmeaData.causeActions || {}
        });
      }
      (fmeaData.pfmeas || []).forEach(p => {
        const key = `PFMEA_${p.id}`;
        if (!addedKeys.has(key)) {
          addedKeys.add(key);
          targetScopes.push({
            isPFMEA: true,
            pfmea: p,
            name: `PFMEA: ${p.name || 'Process FMEA'}`,
            processSteps: p.processSteps || [],
            functions: p.functions || [],
            requirements: p.requirements || [],
            functionRequirements: p.functionRequirements || {},
            functionLines: p.functionLines || [],
            failureModeEffects: p.failureModeEffects || {},
            failureModeCauses: p.failureModeCauses || {},
            causeControls: p.causeControls || {},
            causeActions: p.causeActions || {}
          });
        }
      });
    } else if (val === 'ACTIVE') {
      const activeKey = ctx.isPFMEA ? `PFMEA_${ctx.pfmea?.id}` : 'DFMEA';
      if (!addedKeys.has(activeKey)) {
        addedKeys.add(activeKey);
        targetScopes.push(ctx);
      }
    } else if (val === 'DFMEA') {
      if (!addedKeys.has('DFMEA')) {
        addedKeys.add('DFMEA');
        targetScopes.push({
          isPFMEA: false,
          name: 'DFMEA Master',
          functions: fmeaData.functions || [],
          requirements: fmeaData.requirements || [],
          functionRequirements: fmeaData.functionRequirements || {},
          functionLines: fmeaData.functionLines || [],
          failureModeEffects: fmeaData.failureModeEffects || {},
          failureModeCauses: fmeaData.failureModeCauses || {},
          causeControls: fmeaData.causeControls || {},
          causeActions: fmeaData.causeActions || {}
        });
      }
    } else if (val === 'ALL_PFMEA') {
      (fmeaData.pfmeas || []).forEach(p => {
        const key = `PFMEA_${p.id}`;
        if (!addedKeys.has(key)) {
          addedKeys.add(key);
          targetScopes.push({
            isPFMEA: true,
            pfmea: p,
            name: `PFMEA: ${p.name || 'Process FMEA'}`,
            processSteps: p.processSteps || [],
            functions: p.functions || [],
            requirements: p.requirements || [],
            functionRequirements: p.functionRequirements || {},
            functionLines: p.functionLines || [],
            failureModeEffects: p.failureModeEffects || {},
            failureModeCauses: p.failureModeCauses || {},
            causeControls: p.causeControls || {},
            causeActions: p.causeActions || {}
          });
        }
      });
    } else if (val.startsWith('PFMEA_')) {
      const pId = val.replace('PFMEA_', '');
      const p = (fmeaData.pfmeas || []).find(pf => pf.id === pId);
      if (p && !addedKeys.has(val)) {
        addedKeys.add(val);
        targetScopes.push({
          isPFMEA: true,
          pfmea: p,
          name: `PFMEA: ${p.name || 'Process FMEA'}`,
          processSteps: p.processSteps || [],
          functions: p.functions || [],
          requirements: p.requirements || [],
          functionRequirements: p.functionRequirements || {},
          functionLines: p.functionLines || [],
          failureModeEffects: p.failureModeEffects || {},
          failureModeCauses: p.failureModeCauses || {},
          causeControls: p.causeControls || {},
          causeActions: p.causeActions || {}
        });
      }
    }
  });

  if (targetScopes.length === 0) {
    targetScopes.push(ctx);
  }

  return targetScopes;
}

// ----------------------------------------------------
// 24. DVP & Action Plan View Functions
// ----------------------------------------------------
function populateDvpVariantDropdown() {
  const select = document.getElementById('dvpFilterVariant');
  if (!select) return;
  const currentVal = select.value || 'ALL';
  const variants = fmeaData.variants || [];

  let html = `<option value="ALL">All Variants</option>`;
  variants.forEach(v => {
    const vId = typeof v === 'object' ? v.id : v;
    const vName = typeof v === 'object' ? v.name : v;
    html += `<option value="${escapeHtml(vId)}">🚗 ${escapeHtml(vName)}</option>`;
  });

  select.innerHTML = html;
  select.value = currentVal;
}

function openDvpViewModal() {
  populateFmeaScopeCheckboxDropdown('dvpScopeMultiSelectContainer', 'renderDvpTable');
  populateDvpVariantDropdown();
  renderDvpTable();
  openModal('dvpViewModal');
}

function getDvpItemsList(targetScopes) {
  if (!targetScopes || targetScopes.length === 0) {
    const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false };
    targetScopes = [ctx];
  }

  const items = [];
  const libraries = fmeaData.libraries || {};
  const controls = libraries.controls || [];
  const actions = libraries.actions || [];
  const causes = libraries.causes || [];

  const causeMapObj = {};
  causes.forEach(c => { causeMapObj[c.id] = c.details; });

  // Map causes & context paths across ALL target scopes
  const causeContextMap = {};
  targetScopes.forEach(scope => {
    const scopeName = scope.name || (scope.isPFMEA ? 'PFMEA' : 'DFMEA Master');
    const functionLines = scope.functionLines || (scope.isPFMEA ? (scope.pfmea?.functionLines || []) : (fmeaData.functionLines || []));
    const causeMap = scope.failureModeCauses || (scope.isPFMEA ? (scope.pfmea?.failureModeCauses || {}) : (fmeaData.failureModeCauses || {}));

    functionLines.forEach(fl => {
      const structNode = !scope.isPFMEA ? getStructureNodeById(fmeaData.structure, fl.structId) : null;
      const structName = structNode ? `${structNode.partNo || ''} ${structNode.name || ''}`.trim() : (fl.structName || (scope.isPFMEA ? 'Process Step' : 'System Element'));
      (fl.failureModes || []).forEach(fm => {
        const causeIds = causeMap[fm.id] || [];
        causeIds.forEach(cId => {
          const causeDetail = causeMapObj[cId] || 'Cause';
          causeContextMap[cId] = `[${scopeName} - ${structName}] ${fm.name} → ${causeDetail}`;
        });
      });
    });
  });

  // Collect Controls (Strictly those linked to causes in active scope)
  controls.forEach(ctrl => {
    let linkedCauseTexts = [];
    targetScopes.forEach(scope => {
      const causeMap = scope.causeControls || (scope.isPFMEA ? scope.pfmea?.causeControls : fmeaData.causeControls) || {};
      Object.keys(causeMap).forEach(cId => {
        if ((causeMap[cId] || []).includes(ctrl.id)) {
          const cLabel = causeContextMap[cId] || (causeMapObj[cId] ? `[${scope.name || 'FMEA'}] ${causeMapObj[cId]}` : `[${scope.name || 'FMEA'}] Cause #${cId}`);
          linkedCauseTexts.push(cLabel);
        }
      });
    });

    if (linkedCauseTexts.length > 0) {
      const isDet = (ctrl.type === 'Detection' || ctrl.type === 'D');
      items.push({
        id: ctrl.id,
        itemType: 'Control',
        category: 'Control',
        pd: isDet ? 'Detection' : 'Prevention',
        context: linkedCauseTexts.join('; '),
        desc: ctrl.desc || '',
        responsible: ctrl.responsible || '',
        targetDate: ctrl.targetDate || '',
        completionDate: ctrl.completionDate || '',
        status: ctrl.status || (ctrl.completionDate ? 'Passed' : 'Planned'),
        remark: ctrl.remark || ctrl.actionTaken || '',
        variants: ctrl.variants || ctrl.variantId || ['ALL'],
        isControl: true,
        rawRef: ctrl
      });
    }
  });

  // Collect Recommended Actions (Strictly those linked to causes in active scope)
  actions.forEach(act => {
    let linkedCauseTexts = [];
    targetScopes.forEach(scope => {
      const causeMap = scope.causeActions || (scope.isPFMEA ? scope.pfmea?.causeActions : fmeaData.causeActions) || {};
      Object.keys(causeMap).forEach(cId => {
        if ((causeMap[cId] || []).includes(act.id)) {
          const cLabel = causeContextMap[cId] || (causeMapObj[cId] ? `[${scope.name || 'FMEA'}] ${causeMapObj[cId]}` : `[${scope.name || 'FMEA'}] Cause #${cId}`);
          linkedCauseTexts.push(cLabel);
        }
      });
    });

    if (linkedCauseTexts.length > 0) {
      const isDetAct = (act.pd === 'Detection' || act.pd === 'D' || act.type === 'Detection' || act.actionType === 'Detection');
      items.push({
        id: act.id,
        itemType: 'Action',
        category: 'Action',
        pd: isDetAct ? 'Detection' : 'Prevention',
        context: linkedCauseTexts.join('; '),
        desc: act.detail || '',
        responsible: act.responsible || '',
        targetDate: act.targetDate || '',
        completionDate: act.completionDate || '',
        status: act.status || (act.completionDate ? 'Passed' : (act.targetDate ? 'In Progress' : 'Planned')),
        remark: act.remark || act.actionTaken || act.comments || '',
        variants: act.variants || act.variantId || ['ALL'],
        isControl: false,
        rawRef: act
      });
    }
  });

  return items;
}

function getFilteredDvpItems(options = {}) {
  const selectedScopeVals = getSelectedScopeValues('dvpScopeMultiSelectContainer');
  const targetScopes = resolveSelectedScopes(selectedScopeVals);

  const variantFilter = document.getElementById('dvpFilterVariant')?.value || 'ALL';
  const searchText = (document.getElementById('dvpSearchInput')?.value || '').toLowerCase().trim();

  let items = getDvpItemsList(targetScopes);

  if (variantFilter !== 'ALL') {
    items = items.filter(item => {
      const vars = Array.isArray(item.variants) ? item.variants : [item.variants];
      return vars.includes('ALL') || vars.includes(variantFilter);
    });
  }

  if (searchText) {
    items = items.filter(i =>
      (i.desc && i.desc.toLowerCase().includes(searchText)) ||
      (i.responsible && i.responsible.toLowerCase().includes(searchText)) ||
      (i.context && i.context.toLowerCase().includes(searchText)) ||
      (i.remark && i.remark.toLowerCase().includes(searchText))
    );
  }

  if (!options.ignoreColumnFilters && dvpColumnFilters && Object.keys(dvpColumnFilters).length > 0) {
    items = items.filter(item => {
      for (const [colKey, set] of Object.entries(dvpColumnFilters)) {
        if (!set) continue;
        let val = '';
        if (colKey === 'itemType') val = item.itemType || item.category || '-';
        else if (colKey === 'pd') val = item.pd || '-';
        else if (colKey === 'desc') val = item.desc || '-';
        else if (colKey === 'responsible') val = item.responsible || '-';
        else if (colKey === 'targetDate') val = item.targetDate || '-';
        else if (colKey === 'completionDate') val = item.completionDate || '-';
        else if (colKey === 'status') val = item.status || '-';
        else if (colKey === 'remark') val = item.remark || '-';

        if (!set.has(val)) {
          return false;
        }
      }
      return true;
    });
  }

  return items;
}

function renderDvpTable() {
  const tbody = document.getElementById('dvpTableBody');
  const cardsContainer = document.getElementById('dvpTableSummaryCards');
  if (!tbody) return;

  const selectedScopeVals = getSelectedScopeValues('dvpScopeMultiSelectContainer');
  const targetScopes = resolveSelectedScopes(selectedScopeVals);

  const badge = document.getElementById('dvpScopeBadge');
  if (badge) {
    const scopeNamesStr = targetScopes.map(s => s.name || (s.isPFMEA ? 'PFMEA' : 'DFMEA')).join(', ');
    badge.textContent = `Scopes: ${scopeNamesStr}`;
  }

  const items = getFilteredDvpItems();

  // Summary Metrics
  const totalCount = items.length;
  const plannedCount = items.filter(i => i.status === 'Planned').length;
  const inProgressCount = items.filter(i => i.status === 'In Progress').length;
  const passedCount = items.filter(i => i.status === 'Passed').length;
  const failedCount = items.filter(i => i.status === 'Failed').length;

  if (cardsContainer) {
    cardsContainer.innerHTML = `
      <div style="background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #3b82f6; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:11px; color:var(--text-muted); font-weight:bold; text-transform:uppercase;">Total DVP Items</span>
        <div style="font-size:20px; font-weight:bold; color:var(--text-primary);">${totalCount}</div>
      </div>
      <div style="background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #f59e0b; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:11px; color:var(--text-muted); font-weight:bold; text-transform:uppercase;">Planned / In Progress</span>
        <div style="font-size:20px; font-weight:bold; color:#d97706;">${plannedCount + inProgressCount}</div>
      </div>
      <div style="background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #10b981; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:11px; color:var(--text-muted); font-weight:bold; text-transform:uppercase;">Passed / Completed</span>
        <div style="font-size:20px; font-weight:bold; color:#059669;">${passedCount}</div>
      </div>
      <div style="background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #ef4444; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:11px; color:var(--text-muted); font-weight:bold; text-transform:uppercase;">Failed / Action Needed</span>
        <div style="font-size:20px; font-weight:bold; color:#dc2626;">${failedCount}</div>
      </div>
    `;
  }

  if (items.length === 0) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center; padding:16px; color:var(--text-muted);">No DVP controls or actions matching active filter criteria.</td></tr>`;
    updateDvpHeaderFilterButtonsUI();
    return;
  }

  tbody.innerHTML = items.map((item, idx) => {
    const isCtrl = item.isControl;
    const typeBadge = isCtrl
      ? '<span class="badge" style="background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd; font-weight:700;">Control</span>'
      : '<span class="badge" style="background:#f3e8ff; color:#7e22ce; border:1px solid #e9d5ff; font-weight:700;">Action</span>';

    const pdBadge = item.pd === 'Prevention'
      ? '<span class="badge" style="background:#ecfdf5; color:#047857; border:1px solid #a7f3d0; font-weight:700;">🛡 Prevention</span>'
      : '<span class="badge" style="background:#fffbeb; color:#b45309; border:1px solid #fde68a; font-weight:700;">🔍 Detection</span>';

    return `
      <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
        <td style="padding:8px; text-align:center; font-weight:bold; color:var(--text-muted);">${idx + 1}</td>
        <td style="padding:8px;">${typeBadge}</td>
        <td style="padding:8px; text-align:center;">${pdBadge}</td>
        <td style="padding:8px; font-weight:600; color:var(--text-primary);">${escapeHtml(item.desc)}</td>
        <td style="padding:6px;">
          <input type="text" value="${escapeHtml(item.responsible)}" placeholder="Assign responsible..." style="width:100%; padding:4px 6px; border:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary); border-radius:4px; font-size:11px;" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'responsible', this.value)">
        </td>
        <td style="padding:6px; text-align:center;">
          <input type="date" value="${item.targetDate}" style="width:100%; padding:3px 4px; border:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary); border-radius:4px; font-size:11px;" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'targetDate', this.value)">
        </td>
        <td style="padding:6px; text-align:center;">
          <input type="date" value="${item.completionDate}" style="width:100%; padding:3px 4px; border:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary); border-radius:4px; font-size:11px;" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'completionDate', this.value)">
        </td>
        <td style="padding:6px; text-align:center;">
          <select style="width:100%; padding:4px 6px; border:1px solid var(--border-color); border-radius:4px; font-size:11px; font-weight:bold; ${item.status === 'Passed' ? 'background:#dcfce7; color:#15803d;' : (item.status === 'Failed' ? 'background:#fee2e2; color:#b91c1c;' : 'background:var(--bg-card); color:var(--text-primary);')}" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'status', this.value)">
            <option value="Planned" ${item.status === 'Planned' ? 'selected' : ''}>Planned</option>
            <option value="In Progress" ${item.status === 'In Progress' ? 'selected' : ''}>In Progress</option>
            <option value="Passed" ${item.status === 'Passed' ? 'selected' : ''}>Passed / Complete</option>
            <option value="Failed" ${item.status === 'Failed' ? 'selected' : ''}>Failed / Action Req.</option>
          </select>
        </td>
        <td style="padding:6px;">
          <input type="text" value="${escapeHtml(item.remark)}" placeholder="Action taken / remarks..." style="width:100%; padding:4px 6px; border:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary); border-radius:4px; font-size:11px;" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'remark', this.value)">
        </td>
      </tr>
    `;
  }).join('');

  updateDvpHeaderFilterButtonsUI();
}

function updateDvpItemField(itemId, isControl, field, value) {
  const libraries = fmeaData.libraries || {};
  const list = isControl ? (libraries.controls || []) : (libraries.actions || []);
  const item = list.find(i => i.id === itemId);
  if (item) {
    if (field === 'pd') {
      if (isControl) {
        item.type = value;
      } else {
        item.pd = value;
        item.type = value;
        item.actionType = value;
      }
    } else {
      item[field] = value;
      if (field === 'remark') {
        item.actionTaken = value;
        item.comments = value;
      }
    }
    showToast(`Saved DVP ${field}`);
    renderFMEATable();
  }
}

async function exportDvpToExcel() {
  const items = getFilteredDvpItems();
  const h = fmeaData.headerInfo || fmeaData.header || {};

  let html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
  <head><meta charset="utf-8"/><style>
    table { border-collapse: collapse; width: 100%; font-family: Arial, sans-serif; font-size: 11px; }
    .hdr-title { background-color: #0f172a; color: #ffffff; font-weight: bold; font-size: 14px; text-align: center; padding: 8px; }
    th { background-color: #1e293b; color: #ffffff; border: 1px solid #475569; padding: 6px; text-align: center; }
    td { border: 1px solid #cbd5e1; padding: 5px; vertical-align: top; }
  </style></head>
  <body>
  <table>
    <tr><td colspan="9" class="hdr-title">DESIGN VERIFICATION PLAN &amp; REPORT (DVP&amp;R) - CONTROL ACTION MATRIX</td></tr>
    <tr><td colspan="9">Company: ${escapeHtml(h.companyName || '-')} | Project: ${escapeHtml(h.customerName || h.projectName || fmeaData.projectName || '-')} | Date: ${new Date().toLocaleDateString()}</td></tr>
    <tr><td colspan="9" style="height:10px; border:none;"></td></tr>
    <thead>
      <tr>
        <th>#</th>
        <th>Item Type</th>
        <th>P&amp;D</th>
        <th>Control / Action Description</th>
        <th>Responsible Person</th>
        <th>Target Date</th>
        <th>Completion Date</th>
        <th>Status</th>
        <th>Action Taken / Remarks</th>
      </tr>
    </thead>
    <tbody>`;

  if (items.length === 0) {
    html += `<tr><td colspan="9" style="text-align:center; padding:15px; color:#64748b;">No DVP items found matching current filters.</td></tr>`;
  } else {
    items.forEach((item, idx) => {
      html += `<tr>
        <td style="text-align:center;">${idx + 1}</td>
        <td style="text-align:center;">${escapeHtml(item.itemType || '')}</td>
        <td style="text-align:center;">${escapeHtml(item.pd || 'Prevention')}</td>
        <td>${escapeHtml(item.desc || '')}</td>
        <td>${item.responsible && item.responsible !== 'Unassigned' && item.responsible !== '-' ? escapeHtml(item.responsible) : '-'}</td>
        <td style="text-align:center;">${item.targetDate || '-'}</td>
        <td style="text-align:center;">${item.completionDate || '-'}</td>
        <td style="text-align:center;">${escapeHtml(item.status || '')}</td>
        <td>${item.remark || '-'}</td>
      </tr>`;
    });
  }

  html += `</tbody></table></body></html>`;

  const fileName = `DVP_Action_Report_${new Date().toISOString().slice(0, 10)}.xls`;

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const saveFn = window.electronAPI.showSaveDialog || window.electronAPI.saveDialog;
      const saveRes = await saveFn(fileName);
      if (saveRes && !saveRes.canceled && saveRes.filePath) {
        const writeRes = await window.electronAPI.writeFile(saveRes.filePath, html);
        if (writeRes && writeRes.success !== false) {
          showToast(`📊 Exported DVP Action Report to: ${saveRes.filePath}`);
        } else {
          alert(`Error saving DVP report: ${writeRes ? writeRes.error : 'Unknown error'}`);
        }
        return;
      }
    } catch (e) {
      console.warn("Electron DVP save fallback:", e);
    }
  }

  const blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  showToast(`📊 Downloaded DVP Action Report!`);
}

