// ====================================================
// DFMEA BOUNDARY DIAGRAM & PFMEA PROCESS FLOW DIAGRAM MODULE
// ====================================================

let activeBoundarySelectedNodeId = null;
let activeBoundarySelectedNodeIds = []; // Ctrl-click multi-select (up to 2 nodes for linkage)
let activePfdSelectedStepId = null;

// External block type definitions
const EXTERNAL_BLOCK_TYPES = {
  VEHICLE: { label: 'Vehicle / Platform', emoji: '🚗', color: '#7c3aed', bg: 'rgba(124,58,237,0.15)' },
  USER: { label: 'User / Operator', emoji: '👤', color: '#0891b2', bg: 'rgba(8,145,178,0.15)' },
  ENVIRONMENT: { label: 'Environment / Ambient', emoji: '🌍', color: '#16a34a', bg: 'rgba(22,163,74,0.15)' },
  SUPPLIER: { label: 'Supplier / Upstream System', emoji: '🏭', color: '#d97706', bg: 'rgba(217,119,6,0.15)' },
  POWER: { label: 'Power / Energy Source', emoji: '⚡', color: '#dc2626', bg: 'rgba(220,38,38,0.15)' },
  CLOUD: { label: 'Cloud / Remote Server', emoji: '☁️', color: '#6366f1', bg: 'rgba(99,102,241,0.15)' },
  REGULATOR: { label: 'Regulatory / Standard', emoji: '⚖️', color: '#e11d48', bg: 'rgba(225,29,72,0.15)' },
  CUSTOM: { label: 'Custom External', emoji: '🔷', color: '#64748b', bg: 'rgba(100,116,139,0.15)' }
};

/** Returns all boundary nodes (FMEA structure + external) merged into one array */
function getAllBoundaryNodes() {
  if (!fmeaData || !fmeaData.boundaryDiagram) return [];
  const nodes = fmeaData.boundaryDiagram.nodes || [];
  const extNodes = fmeaData.boundaryDiagram.externalNodes || [];
  return [...nodes, ...extNodes];
}
window.getAllBoundaryNodes = getAllBoundaryNodes;

/** Resolve a node name by id — searches both FMEA nodes and external nodes */
function getBoundaryNodeName(nodeId) {
  const all = getAllBoundaryNodes();
  const n = all.find(n => n.id === nodeId);
  return n ? n.name : nodeId;
}

function clearBoundaryNodeSelection() {
  activeBoundarySelectedNodeIds = [];
  activeBoundarySelectedNodeId = null;
  renderBoundaryDiagram();
  updateBoundaryAddLinkageButtonState();
}

function handleBoundaryNodeClick(nodeId, evt) {
  const isCtrl = (evt && (evt.ctrlKey || evt.metaKey));

  if (isCtrl) {
    const existingIdx = activeBoundarySelectedNodeIds.indexOf(nodeId);
    if (existingIdx !== -1) {
      activeBoundarySelectedNodeIds.splice(existingIdx, 1);
    } else {
      if (activeBoundarySelectedNodeIds.length >= 2) {
        activeBoundarySelectedNodeIds[1] = nodeId;
      } else {
        activeBoundarySelectedNodeIds.push(nodeId);
      }
    }
  } else {
    activeBoundarySelectedNodeIds = [nodeId];
  }

  activeBoundarySelectedNodeId = activeBoundarySelectedNodeIds[activeBoundarySelectedNodeIds.length - 1] || nodeId;
  inspectBoundaryNode(nodeId);
  renderBoundaryDiagram();
  updateBoundaryAddLinkageButtonState();
}

function updateBoundaryAddLinkageButtonState() {
  const btn = document.getElementById('btnBoundaryAddLinkage');
  const bar = document.getElementById('boundaryMultiSelectBar');
  const barText = document.getElementById('boundarySelectBarText');

  const count = activeBoundarySelectedNodeIds.length;

  if (count === 2) {
    const elemAId = activeBoundarySelectedNodeIds[0];
    const elemBId = activeBoundarySelectedNodeIds[1];
    const nameA = getBoundaryNodeName(elemAId) || 'Element 1';
    const nameB = getBoundaryNodeName(elemBId) || 'Element 2';

    const extNodes = (fmeaData && fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.externalNodes) || [];
    const isAExt = extNodes.some(n => n.id === elemAId);
    const isBExt = extNodes.some(n => n.id === elemBId);
    const isBothExt = isAExt && isBExt;

    const existingIface = (fmeaData.interfaceMatrix || []).find(i =>
      (i.elementIdA === elemAId && i.elementIdB === elemBId) ||
      (i.elementIdA === elemBId && i.elementIdB === elemAId)
    );

    if (btn) {
      if (isBothExt) {
        btn.style.background = '#dc2626';
        btn.style.color = '#ffffff';
        btn.style.borderColor = '#ef4444';
        btn.style.fontWeight = '700';
        btn.style.boxShadow = '0 0 10px rgba(239, 68, 68, 0.5)';
        btn.innerHTML = `⚠️ External ↔ External Not Allowed`;
      } else {
        btn.style.background = existingIface ? '#0284c7' : '#059669';
        btn.style.color = '#ffffff';
        btn.style.borderColor = existingIface ? '#38bdf8' : '#34d399';
        btn.style.fontWeight = '700';
        btn.style.boxShadow = '0 0 10px rgba(56, 189, 248, 0.5)';
        btn.innerHTML = existingIface
          ? `✏️ Edit Interface Linkage (${escapeHtml(nameA)} ↔ ${escapeHtml(nameB)})`
          : `🔗 Define Interface Linkage (${escapeHtml(nameA)} ↔ ${escapeHtml(nameB)})`;
      }
    }

    if (bar) {
      bar.style.display = 'flex';
      if (barText) {
        if (isBothExt) {
          barText.innerHTML = `<span style="color:#ef4444; font-weight:bold;">⚠️ Cannot connect 2 External Elements</span>: <strong>${escapeHtml(nameA)}</strong> & <strong>${escapeHtml(nameB)}</strong>`;
        } else {
          barText.innerHTML = `${existingIface ? '✏️ Existing Linkage Detected' : '⚡ 2 Elements Selected'}: <strong style="color:#38bdf8">${escapeHtml(nameA)}</strong> ↔ <strong style="color:#22c55e">${escapeHtml(nameB)}</strong>`;
        }
      }
    }
  } else if (count === 1) {
    const nameA = getBoundaryNodeName(activeBoundarySelectedNodeIds[0]) || 'Element 1';

    if (btn) {
      btn.style.background = '';
      btn.style.color = '';
      btn.style.borderColor = '';
      btn.style.fontWeight = '600';
      btn.style.boxShadow = '';
      btn.innerHTML = `🔗 Add Linkage (1/2 Selected - Ctrl+Click 2nd Element)`;
    }

    if (bar) {
      bar.style.display = 'none';
    }
  } else {
    if (btn) {
      btn.style.background = '';
      btn.style.color = '';
      btn.style.borderColor = '';
      btn.style.fontWeight = '600';
      btn.style.boxShadow = '';
      btn.innerHTML = `🔗 Add Linkage`;
    }

    if (bar) {
      bar.style.display = 'none';
    }
  }
}

function handleBoundaryAddLinkageClick() {
  if (activeBoundarySelectedNodeIds.length === 2) {
    const elemAId = activeBoundarySelectedNodeIds[0];
    const elemBId = activeBoundarySelectedNodeIds[1];

    const extNodes = (fmeaData && fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.externalNodes) || [];
    const isAExt = extNodes.some(n => n.id === elemAId);
    const isBExt = extNodes.some(n => n.id === elemBId);
    if (isAExt && isBExt) {
      if (typeof showToast === 'function') showToast('⚠️ Direct connection between two external elements is not allowed. Interface connections must connect to at least one system element.', 'warning');
      else alert('Connection between two external elements is not allowed.');
      return;
    }

    const existingIface = (fmeaData.interfaceMatrix || []).find(i =>
      (i.elementIdA === elemAId && i.elementIdB === elemBId) ||
      (i.elementIdA === elemBId && i.elementIdB === elemAId)
    );
    openInterfaceLinkEditorModal(elemAId, elemBId, existingIface ? existingIface.id : null);
  } else if (activeBoundarySelectedNodeIds.length === 1) {
    showCustomAlert("Please hold Ctrl and click a 2nd System Block to select two elements for linkage.", "Select 2 Elements Required", "info");
  } else {
    openAddBoundaryConnectionModal();
  }
}

// Self-contained helper functions for tree traversal & node manipulation
function getStructureNodeByIdHelper(root, id) {
  if (!root) return null;
  if (root.id === id) return root;
  if (root.children && Array.isArray(root.children)) {
    for (let child of root.children) {
      const found = getStructureNodeByIdHelper(child, id);
      if (found) return found;
    }
  }
  return null;
}

function deleteStructureNodeHelper(nodeId) {
  if (!fmeaData || !fmeaData.structure) return;
  if (fmeaData.structure.id === nodeId) return;
  function removeChild(parent) {
    if (!parent.children) return false;
    const idx = parent.children.findIndex(c => c.id === nodeId);
    if (idx !== -1) {
      parent.children.splice(idx, 1);
      return true;
    }
    for (let c of parent.children) {
      if (removeChild(c)) return true;
    }
    return false;
  }
  removeChild(fmeaData.structure);
}

function deleteProcessStepHelper(stepId) {
  return deleteProcessStepAndAllData(stepId, true);
}

function openActiveDiagramModal() {
  if (!fmeaData || !fmeaData.structure) {
    alert('Please open or create an FMEA project first.');
    return;
  }
  const ctx = getActiveFmeaData();
  if (ctx && ctx.isPFMEA) {
    openProcessFlowDiagramModal();
  } else {
    openBoundaryDiagramModal();
  }
}

// ----------------------------------------------------
// 1. DFMEA Boundary Diagram Engine
// ----------------------------------------------------
function openBoundaryDiagramModal() {
  const ctx = getActiveFmeaData();
  if (ctx && ctx.isPFMEA) {
    if (typeof showToast === 'function') showToast('⚠️ Boundary Diagram is disabled in PFMEA mode.', 'warning');
    else alert('Boundary Diagram is disabled in PFMEA mode.');
    return;
  }
  if (!fmeaData || !fmeaData.structure) {
    alert('Please open an FMEA project first.');
    return;
  }
  fmeaData.boundaryDiagram = fmeaData.boundaryDiagram || { nodes: [], connections: [], externalNodes: [] };
  fmeaData.boundaryDiagram.externalNodes = fmeaData.boundaryDiagram.externalNodes || [];
  syncBoundaryDiagramWithStructure();
  openModal('boundaryDiagramModal');
  renderBoundaryDiagram();
  inspectBoundaryNode(null);
  renderBoundaryConnectionsList();
}

function syncBoundaryDiagramWithStructure() {
  if (!fmeaData || !fmeaData.structure) return;
  fmeaData.boundaryDiagram = fmeaData.boundaryDiagram || { nodes: [], connections: [] };
  fmeaData.interfaceMatrix = fmeaData.interfaceMatrix || [];

  const structNodes = getFlatStructureNodes(fmeaData.structure);
  const existingMap = new Map();
  (fmeaData.boundaryDiagram.nodes || []).forEach(n => existingMap.set(n.id, n));

  const updatedNodes = [];
  const rootId = fmeaData.structure.id;

  structNodes.forEach((sn, idx) => {
    let diagramNode = existingMap.get(sn.id);
    const isRoot = (sn.id === rootId);
    if (!diagramNode) {
      const row = Math.floor(idx / 3);
      const col = idx % 3;
      diagramNode = {
        id: sn.id,
        partNo: sn.partNo || '',
        name: sn.name || '',
        type: isRoot ? 'SYSTEM_ROOT' : (sn.children && sn.children.length > 0 ? 'SUBSYSTEM' : 'COMPONENT'),
        x: isRoot ? 50 : 80 + col * 260,
        y: isRoot ? 40 : 160 + row * 150,
        width: isRoot ? 220 : 200,
        height: isRoot ? 90 : 80
      };
    } else {
      diagramNode.partNo = sn.partNo || diagramNode.partNo || '';
      diagramNode.name = sn.name || diagramNode.name || '';
      diagramNode.type = isRoot ? 'SYSTEM_ROOT' : (sn.children && sn.children.length > 0 ? 'SUBSYSTEM' : 'COMPONENT');
    }
    updatedNodes.push(diagramNode);
  });

  fmeaData.boundaryDiagram.nodes = updatedNodes;

  // Sync connections from interfaceMatrix
  fmeaData.interfaceMatrix.forEach(iface => {
    let conn = fmeaData.boundaryDiagram.connections.find(c => c.interfaceId === iface.id);
    if (!conn) {
      conn = fmeaData.boundaryDiagram.connections.find(c => !c.interfaceId && ((c.fromId === iface.elementIdA && c.toId === iface.elementIdB) || (c.fromId === iface.elementIdB && c.toId === iface.elementIdA)));
    }
    if (!conn) {
      fmeaData.boundaryDiagram.connections.push({
        id: 'conn-' + Date.now() + '-' + Math.random().toString(36).substring(2, 6),
        interfaceId: iface.id,
        fromId: iface.elementIdA,
        toId: iface.elementIdB,
        label: iface.name,
        type: iface.interfaceType || (iface.types ? iface.types[0] : 'General'),
        types: iface.types || [iface.interfaceType || 'General']
      });
    } else {
      conn.interfaceId = iface.id;
      conn.label = iface.name;
      conn.type = iface.interfaceType || (iface.types ? iface.types[0] : 'General');
      conn.types = iface.types || [iface.interfaceType || 'General'];
    }
  });

  const validIds = new Set(updatedNodes.map(n => n.id));
  // Also include external node ids as valid endpoints so their connections are preserved
  (fmeaData.boundaryDiagram.externalNodes || []).forEach(en => validIds.add(en.id));
  fmeaData.boundaryDiagram.connections = (fmeaData.boundaryDiagram.connections || []).filter(
    c => validIds.has(c.fromId) && validIds.has(c.toId)
  );
}

function getInterfaceTypeInitials(type) {
  if (type === 'Mechanical') return 'M';
  if (type === 'Electrical') return 'E';
  if (type === 'Thermal') return 'T';
  if (type === 'Signal') return 'S';
  if (type === 'Fluid') return 'F';
  if (type === 'Material') return 'Ma';
  if (type === 'Software') return 'Sw';
  return type ? type.substring(0, 2).toUpperCase() : 'G';
}

function getBoundaryNearestEdgePoints(nodeA, nodeB) {
  const svgCanvas = document.getElementById('boundaryDiagramSvgCanvas');
  const domA = document.getElementById(`boundary-node-${nodeA.id}`);
  const domB = document.getElementById(`boundary-node-${nodeB.id}`);

  let xA = Number(nodeA.x) || 50;
  let yA = Number(nodeA.y) || 50;
  let wA = Number(nodeA.width) || 200;
  let hA = Number(nodeA.height) || 80;

  let xB = Number(nodeB.x) || 50;
  let yB = Number(nodeB.y) || 50;
  let wB = Number(nodeB.width) || 200;
  let hB = Number(nodeB.height) || 80;

  if (svgCanvas && domA && domB) {
    const svgRect = svgCanvas.getBoundingClientRect();
    const rectA = domA.getBoundingClientRect();
    const rectB = domB.getBoundingClientRect();

    if (rectA.width > 0 && rectB.width > 0) {
      xA = rectA.left - svgRect.left;
      yA = rectA.top - svgRect.top;
      wA = rectA.width;
      hA = rectA.height;

      xB = rectB.left - svgRect.left;
      yB = rectB.top - svgRect.top;
      wB = rectB.width;
      hB = rectB.height;
    }
  }

  nodeA.width = wA; nodeA.height = hA;
  nodeB.width = wB; nodeB.height = hB;

  const cxA = xA + wA / 2;
  const cyA = yA + hA / 2;

  const cxB = xB + wB / 2;
  const cyB = yB + hB / 2;

  const dx = cxB - cxA;
  const dy = cyB - cyA;

  if (Math.hypot(dx, dy) === 0) {
    return { x1: cxA, y1: cyA, x2: cxB, y2: cyB };
  }

  const absDx = Math.abs(dx);
  const absDy = Math.abs(dy);

  // Intersection with Node A boundary along center-to-center ray
  const txA = absDx > 0 ? (wA / 2) / absDx : Infinity;
  const tyA = absDy > 0 ? (hA / 2) / absDy : Infinity;
  const tA = Math.min(txA, tyA);

  const x1 = cxA + dx * tA;
  const y1 = cyA + dy * tA;

  // Intersection with Node B boundary along center-to-center ray
  const txB = absDx > 0 ? (wB / 2) / absDx : Infinity;
  const tyB = absDy > 0 ? (hB / 2) / absDy : Infinity;
  const tB = Math.min(txB, tyB);

  const x2 = cxB - dx * tB;
  const y2 = cyB - dy * tB;

  return { x1, y1, x2, y2 };
}

function renderBoundaryDiagram() {
  const container = document.getElementById('boundaryNodesContainer');
  const svgGroup = document.getElementById('boundaryConnectionsGroup');
  if (!container || !svgGroup) return;

  container.innerHTML = '';
  svgGroup.innerHTML = '';

  const nodes = fmeaData.boundaryDiagram.nodes || [];
  const extNodes = fmeaData.boundaryDiagram.externalNodes || [];
  const connections = fmeaData.boundaryDiagram.connections || [];
  const allNodes = [...nodes, ...extNodes];

  // 1. Render FMEA structure nodes
  nodes.forEach(node => {
    if (node.hidden) return; // skip hidden nodes

    const selIndex = activeBoundarySelectedNodeIds.indexOf(node.id);
    const isSelected = (selIndex !== -1);
    const isRoot = (node.type === 'SYSTEM_ROOT');
    const isSub = (node.type === 'SUBSYSTEM');

    let badgeColor = isRoot ? '#0284c7' : (isSub ? '#059669' : '#64748b');
    let borderColor = isSelected ? (selIndex === 0 ? '#38bdf8' : '#22c55e') : (isRoot ? '#0284c7' : '#334155');
    let bgGradient = isRoot
      ? 'linear-gradient(135deg, #1e293b, #0f172a)'
      : 'linear-gradient(135deg, #1e293b, #1e293b)';

    const selBadgeHtml = isSelected
      ? `<span style="position:absolute; top:-10px; right:10px; font-size:9px; font-weight:800; padding:2px 6px; border-radius:10px; background:${selIndex === 0 ? '#0284c7' : '#15803d'}; color:#ffffff; text-transform:uppercase; z-index:10; box-shadow:0 2px 6px rgba(0,0,0,0.4);">Selected #${selIndex + 1}</span>`
      : '';

    const el = document.createElement('div');
    el.id = `boundary-node-${node.id}`;
    el.className = 'boundary-diagram-node';
    el.style.cssText = `
      position: absolute;
      left: ${node.x || 50}px;
      top: ${node.y || 50}px;
      width: ${node.width || 200}px;
      min-height: ${node.height || 80}px;
      background: ${bgGradient};
      border: 2px solid ${borderColor};
      border-radius: 8px;
      box-shadow: ${isSelected ? (selIndex === 0 ? '0 0 20px rgba(56, 189, 248, 0.6)' : '0 0 20px rgba(34, 197, 94, 0.6)') : '0 4px 12px rgba(0,0,0,0.3)'};
      color: #f8fafc;
      font-family: sans-serif;
      cursor: move;
      user-select: none;
      pointer-events: auto;
      box-sizing: border-box;
      padding: 10px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      transition: border 0.15s ease, box-shadow 0.15s ease;
    `;

    el.innerHTML = `
      ${selBadgeHtml}
      <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #334155; padding-bottom:4px; margin-bottom:6px;">
        <span style="background:${badgeColor}; color:#ffffff; font-size:9px; font-weight:bold; padding:2px 6px; border-radius:4px; text-transform:uppercase;">${node.type || 'BLOCK'}</span>
        <span style="font-size:10px; color:#94a3b8; font-weight:bold;">${escapeHtml(node.partNo || '')}</span>
      </div>
      <div style="font-size:12px; font-weight:bold; word-break:break-word; line-height:1.3;">
        ${escapeHtml(node.name || 'Unnamed Element')}
      </div>
      <div style="display:flex; justify-content:flex-end; gap:4px; margin-top:6px;">
        <button type="button" class="btn btn-xs" style="font-size:9px; padding:1px 5px; cursor:pointer; background:rgba(100,116,139,0.2); border:1px solid #475569; color:#94a3b8; border-radius:3px;" onclick="event.stopPropagation(); toggleBoundaryNodeVisibility('${node.id}')" title="Hide this block from diagram">👁️ Hide</button>
        <button type="button" class="btn btn-xs btn-outline-info" style="font-size:9px; padding:1px 5px; cursor:pointer;" onclick="event.stopPropagation(); openEditBoundaryNodeModal('${node.id}')" title="Edit Block">✏️ Edit</button>
        ${isRoot ? '' : `<button type="button" class="btn btn-xs btn-outline-danger" style="font-size:9px; padding:1px 5px; cursor:pointer;" onclick="event.stopPropagation(); deleteBoundaryNode('${node.id}')" title="Delete Block">🗑️</button>`}
      </div>
    `;

    el.onclick = (evt) => {
      evt.stopPropagation();
      handleBoundaryNodeClick(node.id, evt);
    };

    el.ondblclick = (evt) => {
      evt.stopPropagation();
      openEditBoundaryNodeModal(node.id);
    };

    let isDragging = false;
    let startX = 0, startY = 0, initialLeft = node.x || 50, initialTop = node.y || 50;

    el.onmousedown = (evt) => {
      if (evt.target.tagName === 'BUTTON' || evt.target.tagName === 'INPUT') return;
      isDragging = true;
      startX = evt.clientX;
      startY = evt.clientY;
      initialLeft = node.x || 50;
      initialTop = node.y || 50;
      el.style.zIndex = '100';

      const onMouseMove = (moveEvt) => {
        if (!isDragging) return;
        const dx = moveEvt.clientX - startX;
        const dy = moveEvt.clientY - startY;
        node.x = Math.max(10, initialLeft + dx);
        node.y = Math.max(10, initialTop + dy);
        el.style.left = node.x + 'px';
        el.style.top = node.y + 'px';
        renderBoundaryConnectionsOnly();
      };

      const onMouseUp = () => {
        isDragging = false;
        el.style.zIndex = '';
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
      };

      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
    };

    container.appendChild(el);
  });

  // 2. Render External blocks
  extNodes.forEach(node => {
    if (node.hidden) return;

    const selIndex = activeBoundarySelectedNodeIds.indexOf(node.id);
    const isSelected = (selIndex !== -1);
    const typeDef = EXTERNAL_BLOCK_TYPES[node.externalType] || EXTERNAL_BLOCK_TYPES.CUSTOM;
    const accentColor = node.color || typeDef.color;
    const borderColor = isSelected ? (selIndex === 0 ? '#38bdf8' : '#22c55e') : accentColor;

    const selBadgeHtml = isSelected
      ? `<span style="position:absolute; top:-10px; right:10px; font-size:9px; font-weight:800; padding:2px 6px; border-radius:10px; background:${selIndex === 0 ? '#0284c7' : '#15803d'}; color:#ffffff; text-transform:uppercase; z-index:10; box-shadow:0 2px 6px rgba(0,0,0,0.4);">Selected #${selIndex + 1}</span>`
      : '';

    const el = document.createElement('div');
    el.id = `boundary-node-${node.id}`;
    el.className = 'boundary-diagram-node boundary-external-node';
    el.style.cssText = `
      position: absolute;
      left: ${node.x || 50}px;
      top: ${node.y || 50}px;
      width: ${node.width || 200}px;
      min-height: ${node.height || 80}px;
      background: ${typeDef.bg};
      border: 2px dashed ${borderColor};
      border-radius: 10px;
      box-shadow: ${isSelected ? '0 0 20px rgba(168,85,247,0.5)' : `0 4px 14px rgba(0,0,0,0.35)`};
      color: #f8fafc;
      font-family: sans-serif;
      cursor: move;
      user-select: none;
      pointer-events: auto;
      box-sizing: border-box;
      padding: 10px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      transition: border 0.15s ease, box-shadow 0.15s ease;
    `;

    el.innerHTML = `
      ${selBadgeHtml}
      <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px dashed ${accentColor}40; padding-bottom:4px; margin-bottom:6px;">
        <span style="background:${accentColor}; color:#ffffff; font-size:9px; font-weight:bold; padding:2px 6px; border-radius:4px; text-transform:uppercase; letter-spacing:0.3px;">${typeDef.emoji} EXTERNAL · ${node.externalType || 'CUSTOM'}</span>
        <span style="font-size:12px;">🌐</span>
      </div>
      <div style="font-size:12px; font-weight:700; word-break:break-word; line-height:1.3; color:${accentColor};">
        ${escapeHtml(node.name || 'External Block')}
      </div>
      ${node.description ? `<div style="font-size:10px; color:#94a3b8; margin-top:3px; font-style:italic; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${escapeHtml(node.description)}">${escapeHtml(node.description)}</div>` : ''}
      <div style="display:flex; justify-content:flex-end; gap:4px; margin-top:6px;">
        <button type="button" class="btn btn-xs" style="font-size:9px; padding:1px 5px; cursor:pointer; background:rgba(100,116,139,0.2); border:1px solid #475569; color:#94a3b8; border-radius:3px;" onclick="event.stopPropagation(); toggleExternalBlockVisibility('${node.id}')" title="Hide this block from diagram">👁️ Hide</button>
        <button type="button" class="btn btn-xs" style="font-size:9px; padding:1px 5px; cursor:pointer; background:${accentColor}20; border:1px solid ${accentColor}60; color:${accentColor}; border-radius:3px;" onclick="event.stopPropagation(); openEditExternalBlockModal('${node.id}')" title="Edit External Block">✏️ Edit</button>
        <button type="button" class="btn btn-xs btn-outline-danger" style="font-size:9px; padding:1px 5px; cursor:pointer;" onclick="event.stopPropagation(); deleteExternalBlock('${node.id}')" title="Delete External Block">🗑️</button>
      </div>
    `;

    el.onclick = (evt) => {
      evt.stopPropagation();
      handleBoundaryNodeClick(node.id, evt);
    };

    el.ondblclick = (evt) => {
      evt.stopPropagation();
      openEditExternalBlockModal(node.id);
    };

    let isDragging = false;
    let startX = 0, startY = 0, initialLeft = node.x || 50, initialTop = node.y || 50;

    el.onmousedown = (evt) => {
      if (evt.target.tagName === 'BUTTON' || evt.target.tagName === 'INPUT') return;
      isDragging = true;
      startX = evt.clientX;
      startY = evt.clientY;
      initialLeft = node.x || 50;
      initialTop = node.y || 50;
      el.style.zIndex = '100';

      const onMouseMove = (moveEvt) => {
        if (!isDragging) return;
        const dx = moveEvt.clientX - startX;
        const dy = moveEvt.clientY - startY;
        node.x = Math.max(10, initialLeft + dx);
        node.y = Math.max(10, initialTop + dy);
        el.style.left = node.x + 'px';
        el.style.top = node.y + 'px';
        renderBoundaryConnectionsOnly();
      };

      const onMouseUp = () => {
        isDragging = false;
        el.style.zIndex = '';
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
      };

      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
    };

    container.appendChild(el);
  });

  // 3. Render connections (skip if either endpoint is hidden)
  const hiddenIds = new Set();
  [...nodes, ...extNodes].forEach(n => { if (n.hidden) hiddenIds.add(n.id); });

  connections.forEach(conn => {
    if (hiddenIds.has(conn.fromId) || hiddenIds.has(conn.toId)) return;
    renderSingleBoundaryConnectionSvg(conn, allNodes, svgGroup);
  });

  renderBoundaryConnectionsList();
  renderBoundaryVisibilityPanel();
}

function renderSingleBoundaryConnectionSvg(conn, nodes, svgGroup) {
  const fromNode = nodes.find(n => n.id === conn.fromId);
  const toNode = nodes.find(n => n.id === conn.toId);
  if (!fromNode || !toNode) return;

  const pts = getBoundaryNearestEdgePoints(fromNode, toNode);
  const x1 = pts.x1, y1 = pts.y1, x2 = pts.x2, y2 = pts.y2;

  const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
  line.setAttribute('x1', x1);
  line.setAttribute('y1', y1);
  line.setAttribute('x2', x2);
  line.setAttribute('y2', y2);

  let strokeColor = '#3b82f6';
  let markerId = 'arrowHeadPhysical';
  const mainType = conn.type || (conn.types ? conn.types[0] : 'Electrical');

  if (mainType === 'Mechanical') { strokeColor = '#64748b'; markerId = 'arrowHeadPhysical'; }
  else if (mainType === 'Electrical') { strokeColor = '#3b82f6'; markerId = 'arrowHeadPhysical'; }
  else if (mainType === 'Thermal') { strokeColor = '#ef4444'; markerId = 'arrowHeadEnergy'; }
  else if (mainType === 'Signal') { strokeColor = '#a855f7'; markerId = 'arrowHeadData'; }
  else if (mainType === 'Fluid') { strokeColor = '#06b6d4'; markerId = 'arrowHeadMaterial'; }
  else if (mainType === 'Material') { strokeColor = '#10b981'; markerId = 'arrowHeadMaterial'; }
  else if (mainType === 'Software') { strokeColor = '#f59e0b'; markerId = 'arrowHeadData'; }

  const typesList = (conn.types && conn.types.length > 0) ? conn.types : [mainType];

  let typeDirs = conn.typeDirections || {};
  if (conn.interfaceId && fmeaData.interfaceMatrix) {
    const iface = fmeaData.interfaceMatrix.find(i => i.id === conn.interfaceId);
    if (iface && iface.typeDirections) {
      typeDirs = Object.assign({}, iface.typeDirections, typeDirs);
    }
  }

  const hasExplicitDirs = typesList.some(t => typeDirs[t] && (typeDirs[t] === 'BOTH' || typeDirs[t] === 'FROM_TO' || typeDirs[t] === 'TO_FROM'));

  const bothTypes = typesList.filter(t => {
    if (typeDirs[t]) return typeDirs[t] === 'BOTH';
    return !hasExplicitDirs;
  });
  const fromToTypes = typesList.filter(t => typeDirs[t] === 'FROM_TO');
  const toFromTypes = typesList.filter(t => typeDirs[t] === 'TO_FROM');

  const groupList = [];
  if (bothTypes.length > 0) {
    const initStr = bothTypes.map(t => getInterfaceTypeInitials(t)).join(', ');
    groupList.push(`↔ [${initStr}]`);
  }
  if (fromToTypes.length > 0) {
    const initStr = fromToTypes.map(t => getInterfaceTypeInitials(t)).join(', ');
    groupList.push(`➔ [${initStr}]`);
  }
  if (toFromTypes.length > 0) {
    const initStr = toFromTypes.map(t => getInterfaceTypeInitials(t)).join(', ');
    groupList.push(`⬅ [${initStr}]`);
  }

  const hasForward = (bothTypes.length > 0) || (fromToTypes.length > 0);
  const hasReverse = (bothTypes.length > 0) || (toFromTypes.length > 0);

  line.setAttribute('stroke', strokeColor);
  line.setAttribute('stroke-width', '3');
  line.setAttribute('style', 'cursor:pointer; pointer-events:stroke;');
  line.setAttribute('stroke-dasharray', (mainType === 'Signal' || mainType === 'Software') ? '5,5' : 'none');

  if (hasForward) line.setAttribute('marker-end', `url(#${markerId})`);
  if (hasReverse) line.setAttribute('marker-start', `url(#${markerId})`);

  line.onclick = (e) => {
    e.stopPropagation();
    openInterfaceLinkEditorModal(conn.fromId, conn.toId, conn.interfaceId || null);
  };

  svgGroup.appendChild(line);

  // SVG Connection Badge Pill with Multi-line Direction Groups, ✏️ Edit & 🗑️ Delete
  const midX = (x1 + x2) / 2;
  const midY = (y1 + y2) / 2;

  const textGroup = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  textGroup.setAttribute('transform', `translate(${midX}, ${midY})`);
  textGroup.setAttribute('style', 'cursor:pointer; pointer-events:all;');

  const numLines = groupList.length;
  const maxCharCount = Math.max(...groupList.map(g => g.length), 6);
  const pillWidth = Math.max(98, maxCharCount * 8 + 48);
  const lineHeight = 15;
  const pillHeight = Math.max(26, numLines * lineHeight + 10);

  // Background Rect
  const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
  rect.setAttribute('x', -pillWidth / 2);
  rect.setAttribute('y', -pillHeight / 2);
  rect.setAttribute('width', pillWidth);
  rect.setAttribute('height', pillHeight);
  rect.setAttribute('rx', '8');
  rect.setAttribute('fill', '#0f172a');
  rect.setAttribute('stroke', strokeColor);
  rect.setAttribute('stroke-width', '1.5');
  textGroup.appendChild(rect);

  // Stacked Direction Group Texts (Line 1, Line 2, etc.)
  const textEl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
  textEl.setAttribute('font-size', '11');
  textEl.setAttribute('font-weight', '800');

  const startY = -((numLines - 1) * lineHeight) / 2 + 4;

  groupList.forEach((grpStr, idx) => {
    const tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
    tspan.setAttribute('x', -pillWidth / 2 + 10);
    tspan.setAttribute('y', startY + (idx * lineHeight));

    if (grpStr.includes('↔')) {
      tspan.setAttribute('fill', '#38bdf8'); // Sky Blue for bidirectional
    } else if (grpStr.includes('➔')) {
      tspan.setAttribute('fill', '#4ade80'); // Green for source -> target
    } else if (grpStr.includes('⬅')) {
      tspan.setAttribute('fill', '#facc15'); // Yellow/Amber for target -> source
    } else {
      tspan.setAttribute('fill', '#38bdf8');
    }

    tspan.textContent = grpStr;
    textEl.appendChild(tspan);
  });
  textGroup.appendChild(textEl);

  // Edit Pencil Icon ✏️
  const editG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  editG.setAttribute('transform', `translate(${pillWidth / 2 - 28}, 0)`);
  editG.setAttribute('style', 'cursor:pointer; pointer-events:all;');

  const editIcon = document.createElementNS('http://www.w3.org/2000/svg', 'text');
  editIcon.setAttribute('x', 0);
  editIcon.setAttribute('y', 4);
  editIcon.setAttribute('font-size', '11');
  editIcon.setAttribute('text-anchor', 'middle');
  editIcon.textContent = '✏️';
  editG.appendChild(editIcon);

  editG.onclick = (e) => {
    e.stopPropagation();
    openInterfaceLinkEditorModal(conn.fromId, conn.toId, conn.interfaceId || null);
  };
  textGroup.appendChild(editG);

  // Delete Trash Icon 🗑️
  const deleteG = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  deleteG.setAttribute('transform', `translate(${pillWidth / 2 - 10}, 0)`);
  deleteG.setAttribute('style', 'cursor:pointer; pointer-events:all;');

  const deleteIcon = document.createElementNS('http://www.w3.org/2000/svg', 'text');
  deleteIcon.setAttribute('x', 0);
  deleteIcon.setAttribute('y', 4);
  deleteIcon.setAttribute('font-size', '11');
  deleteIcon.setAttribute('text-anchor', 'middle');
  deleteIcon.textContent = '🗑️';
  deleteG.appendChild(deleteIcon);

  deleteG.onclick = (e) => {
    e.stopPropagation();
    deleteBoundaryConnection(conn.id);
  };
  textGroup.appendChild(deleteG);

  // Main pill background click handler
  textGroup.onclick = (e) => {
    e.stopPropagation();
    openInterfaceLinkEditorModal(conn.fromId, conn.toId, conn.interfaceId || null);
  };

  svgGroup.appendChild(textGroup);
}

function renderBoundaryConnectionsOnly() {
  const svgGroup = document.getElementById('boundaryConnectionsGroup');
  if (!svgGroup) return;
  svgGroup.innerHTML = '';

  const nodes = fmeaData.boundaryDiagram.nodes || [];
  const extNodes = fmeaData.boundaryDiagram.externalNodes || [];
  const allNodes = [...nodes, ...extNodes];
  const connections = fmeaData.boundaryDiagram.connections || [];

  const hiddenIds = new Set();
  allNodes.forEach(n => { if (n.hidden) hiddenIds.add(n.id); });

  connections.forEach(conn => {
    if (hiddenIds.has(conn.fromId) || hiddenIds.has(conn.toId)) return;
    renderSingleBoundaryConnectionSvg(conn, allNodes, svgGroup);
  });

  renderBoundaryConnectionsList();
}

function autoLayoutBoundaryDiagram() {
  const nodes = fmeaData.boundaryDiagram.nodes || [];
  const extNodes = fmeaData.boundaryDiagram.externalNodes || [];

  const rootNode = nodes.find(n => n.type === 'SYSTEM_ROOT') || nodes[0];
  if (rootNode) {
    rootNode.x = 300;
    rootNode.y = 40;
    rootNode.width = 240;
    rootNode.height = 90;
  }

  // Layout visible FMEA child nodes in a grid
  const visibleChildren = nodes.filter(n => n !== rootNode && !n.hidden);
  visibleChildren.forEach((node, idx) => {
    const col = idx % 4;
    const row = Math.floor(idx / 4);
    node.x = 50 + col * 260;
    node.y = 200 + row * 150;
    node.width = 220;
    node.height = 85;
  });

  // Layout external nodes on the right flank
  const visibleExt = extNodes.filter(n => !n.hidden);
  const canvasRight = 50 + 4 * 260 + 60;
  visibleExt.forEach((node, idx) => {
    node.x = canvasRight;
    node.y = 40 + idx * 130;
    node.width = 210;
    node.height = 85;
  });

  renderBoundaryDiagram();
}

function inspectBoundaryNode(nodeId) {
  activeBoundarySelectedNodeId = nodeId;
  const node = (fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.nodes ? fmeaData.boundaryDiagram.nodes : []).find(n => n.id === nodeId);
  const container = document.getElementById('boundaryInspectorContent');
  if (!container) {
    if (node) openEditBoundaryNodeModal(nodeId);
    return;
  }

  if (!node) {
    container.innerHTML = `<div style="color:#94a3b8; font-size:12px; padding:6px 0;">Select a block in the diagram to inspect properties.</div>`;
    return;
  }

  container.innerHTML = `
    <div style="background:#1e293b; border:1px solid #334155; border-radius:6px; padding:12px;">
      <div style="margin-bottom:8px;">
        <label style="font-size:10px; color:#94a3b8; text-transform:uppercase; font-weight:bold; display:block; margin-bottom:4px;">Part / Element Code</label>
        <input type="text" id="inspBoundaryPartNo" value="${escapeHtml(node.partNo || '')}" style="width:100%; font-size:11px; padding:6px 8px; background:#0f172a; border:1px solid #334155; color:#fff; border-radius:4px; box-sizing:border-box;">
      </div>
      <div style="margin-bottom:8px;">
        <label style="font-size:10px; color:#94a3b8; text-transform:uppercase; font-weight:bold; display:block; margin-bottom:4px;">Element Name</label>
        <input type="text" id="inspBoundaryName" value="${escapeHtml(node.name || '')}" style="width:100%; font-size:11px; padding:6px 8px; background:#0f172a; border:1px solid #334155; color:#fff; border-radius:4px; box-sizing:border-box;">
      </div>
      <div style="margin-bottom:12px;">
        <label style="font-size:10px; color:#94a3b8; text-transform:uppercase; font-weight:bold; display:block; margin-bottom:4px;">Element Level / Type</label>
        <div style="font-size:11px; color:#38bdf8; font-weight:bold; background:#0f172a; padding:4px 8px; border-radius:4px; border:1px solid #334155;">${node.type || 'BLOCK'}</div>
      </div>
      <div style="display:flex; gap:6px;">
        <button type="button" class="btn btn-xs btn-primary" style="flex:1; padding:5px 8px; font-weight:700;" onclick="saveBoundaryNodeFromInspector('${node.id}')">💾 Save Changes</button>
        ${node.type === 'SYSTEM_ROOT' ? '' : `<button type="button" class="btn btn-xs btn-danger" style="padding:5px 8px;" onclick="deleteBoundaryNode('${node.id}')">🗑️ Delete</button>`}
      </div>
    </div>
  `;
}
window.inspectBoundaryNode = inspectBoundaryNode;

function saveBoundaryNodeFromInspector(nodeId) {
  const partInput = document.getElementById('inspBoundaryPartNo');
  const nameInput = document.getElementById('inspBoundaryName');
  if (!partInput || !nameInput) return;

  const newPartNo = partInput.value.trim();
  const newName = nameInput.value.trim();
  if (!newName) {
    if (typeof showToast === 'function') showToast('Element name cannot be empty.', 'warning');
    else alert('Element name cannot be empty.');
    return;
  }

  // 1. Update boundary diagram node
  if (fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.nodes) {
    const bNode = fmeaData.boundaryDiagram.nodes.find(n => n.id === nodeId);
    if (bNode) {
      bNode.partNo = newPartNo;
      bNode.name = newName;
    }
  }

  // 2. Update structure node in fmeaData.structure
  const structNode = getStructureNodeByIdHelper(fmeaData.structure, nodeId);
  if (structNode) {
    structNode.partNo = newPartNo;
    structNode.name = newName;
  }

  // 3. Re-render diagram and UI
  renderBoundaryDiagram();
  if (typeof renderTreeSidebar === 'function') renderTreeSidebar();
  if (typeof renderFMEATable === 'function') renderFMEATable();
  inspectBoundaryNode(nodeId);
  if (typeof showToast === 'function') showToast('✅ Block properties saved successfully.', 'success');
}
window.saveBoundaryNodeFromInspector = saveBoundaryNodeFromInspector;

function openEditBoundaryNodeModal(nodeId) {
  const node = (fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.nodes)
    ? fmeaData.boundaryDiagram.nodes.find(n => n.id === nodeId)
    : null;
  if (!node) {
    if (typeof showToast === 'function') showToast('Block not found.', 'warning');
    return;
  }

  const idInput = document.getElementById('editBlockIdInput');
  const nameInput = document.getElementById('editBlockNameInput');
  const partInput = document.getElementById('editBlockPartNoInput');
  const typeDisplay = document.getElementById('editBlockTypeDisplay');

  if (idInput) idInput.value = node.id;
  if (nameInput) nameInput.value = node.name || '';
  if (partInput) partInput.value = node.partNo || '';
  if (typeDisplay) typeDisplay.textContent = node.type || 'BLOCK';

  inspectBoundaryNode(nodeId);
  openModal('boundaryEditNodeModal');
  if (nameInput) setTimeout(() => nameInput.focus(), 100);
}
window.openEditBoundaryNodeModal = openEditBoundaryNodeModal;

function submitEditBoundaryNodeModal() {
  const idInput = document.getElementById('editBlockIdInput');
  const nameInput = document.getElementById('editBlockNameInput');
  const partInput = document.getElementById('editBlockPartNoInput');
  if (!idInput || !nameInput) return;

  const nodeId = idInput.value;
  const newName = nameInput.value.trim();
  const newPartNo = partInput ? partInput.value.trim() : '';

  if (!newName) {
    if (typeof showToast === 'function') showToast('Element name cannot be empty.', 'warning');
    else alert('Element name cannot be empty.');
    return;
  }

  // 1. Update boundary diagram node
  if (fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.nodes) {
    const bNode = fmeaData.boundaryDiagram.nodes.find(n => n.id === nodeId);
    if (bNode) {
      bNode.partNo = newPartNo;
      bNode.name = newName;
    }
  }

  // 2. Update structure node
  const structNode = getStructureNodeByIdHelper(fmeaData.structure, nodeId);
  if (structNode) {
    structNode.partNo = newPartNo;
    structNode.name = newName;
  }

  closeModal('boundaryEditNodeModal');
  renderBoundaryDiagram();
  if (typeof renderTreeSidebar === 'function') renderTreeSidebar();
  if (typeof renderFMEATable === 'function') renderFMEATable();
  inspectBoundaryNode(nodeId);
  if (typeof showToast === 'function') showToast('✅ Block updated successfully.', 'success');
}
window.submitEditBoundaryNodeModal = submitEditBoundaryNodeModal;

function openAddBoundaryNodeModal() {
  const nameInput = document.getElementById('addBlockNameInput');
  const partInput = document.getElementById('addBlockPartNoInput');
  if (nameInput) nameInput.value = '';
  if (partInput) partInput.value = '1.1';
  openModal('boundaryAddNodeModal');
}

function submitAddBoundaryNodeModal() {
  const nameInput = document.getElementById('addBlockNameInput');
  const partInput = document.getElementById('addBlockPartNoInput');
  const name = nameInput ? nameInput.value.trim() : '';
  const partNo = partInput ? partInput.value.trim() : '1.1';

  if (!name) return;

  const root = fmeaData.structure;
  const newNode = {
    id: 'struct_' + Date.now(),
    partNo: partNo || '1.1',
    name: name,
    description: '',
    variantId: ['ALL'],
    children: []
  };

  root.children = root.children || [];
  root.children.push(newNode);

  closeModal('boundaryAddNodeModal');
  syncBoundaryDiagramWithStructure();
  if (typeof renderTreeSidebar === 'function') renderTreeSidebar();
  if (typeof renderFMEATable === 'function') renderFMEATable();
  renderBoundaryDiagram();
}

function openAddBoundaryConnectionModal() {
  const allNodes = getAllBoundaryNodes();
  if (allNodes.length < 2) {
    if (typeof showToast === 'function') showToast('At least 2 blocks are needed to create an interface connection.', 'info');
    return;
  }

  const extNodes = (fmeaData && fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.externalNodes) || [];
  const extIdSet = new Set(extNodes.map(n => n.id));

  const srcSelect = document.getElementById('addConnSourceSelect');
  const tgtSelect = document.getElementById('addConnTargetSelect');
  if (srcSelect && tgtSelect) {
    const optionsHtml = allNodes.map(n => {
      const isExt = extIdSet.has(n.id);
      const prefix = isExt ? '🌐 [External] ' : (n.partNo ? `${n.partNo} - ` : '');
      return `<option value="${n.id}">${escapeHtml(prefix + n.name)}</option>`;
    }).join('');
    srcSelect.innerHTML = optionsHtml;
    tgtSelect.innerHTML = optionsHtml;
    if (allNodes.length > 1) tgtSelect.selectedIndex = 1;
  }

  openModal('boundaryAddConnectionModal');
}

function submitAddBoundaryConnectionModal() {
  const srcSelect = document.getElementById('addConnSourceSelect');
  const tgtSelect = document.getElementById('addConnTargetSelect');
  const fromId = srcSelect ? srcSelect.value : null;
  const toId = tgtSelect ? tgtSelect.value : null;

  if (!fromId || !toId || fromId === toId) {
    if (typeof showToast === 'function') showToast('Please select two distinct blocks.', 'warning');
    return;
  }

  const extNodes = (fmeaData && fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.externalNodes) || [];
  const extIdSet = new Set(extNodes.map(n => n.id));
  if (extIdSet.has(fromId) && extIdSet.has(toId)) {
    if (typeof showToast === 'function') showToast('⚠️ Direct connection between two external elements is not allowed. Interface connections must connect to at least one system element.', 'warning');
    else alert('Connection between two external elements is not allowed.');
    return;
  }

  closeModal('boundaryAddConnectionModal');
  openInterfaceLinkEditorModal(fromId, toId);
}

function renderBoundaryConnectionsList() {
  const container = document.getElementById('boundaryConnectionsList');
  if (!container) return;

  const connections = fmeaData.boundaryDiagram.connections || [];
  const allNodes = getAllBoundaryNodes();
  const hiddenIds = new Set(allNodes.filter(n => n.hidden).map(n => n.id));
  const extIds = new Set((fmeaData.boundaryDiagram.externalNodes || []).map(n => n.id));

  const visibleConns = connections.filter(c => !hiddenIds.has(c.fromId) && !hiddenIds.has(c.toId));

  if (visibleConns.length === 0) {
    container.innerHTML = `<div style="font-size:11px; color:#64748b;">No interface connections to show. (Hidden nodes' connections are also hidden.)</div>`;
    return;
  }

  let html = '';
  visibleConns.forEach(conn => {
    const fromNode = allNodes.find(n => n.id === conn.fromId);
    const toNode = allNodes.find(n => n.id === conn.toId);
    const typesList = (conn.types && conn.types.length > 0) ? conn.types : [conn.type || 'General'];
    const initialsStr = typesList.map(t => getInterfaceTypeInitials(t)).join(', ');
    const isExtConn = extIds.has(conn.fromId) || extIds.has(conn.toId);
    const connBadge = isExtConn ? `<span style="font-size:9px; background:rgba(168,85,247,0.2); border:1px solid #a855f7; color:#a855f7; padding:1px 4px; border-radius:4px; font-weight:700;">🌐 EXT</span>` : '';

    html += `
      <div style="background:#1e293b; border:1px solid ${isExtConn ? '#a855f740' : '#334155'}; border-radius:6px; padding:8px 10px; font-size:11px; display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
        <div style="cursor:pointer; flex:1;" onclick="openInterfaceLinkEditorModal('${conn.fromId}', '${conn.toId}', '${conn.interfaceId || ''}')" title="Click to Edit Interface Linkage">
          <div style="font-weight:bold; color:#38bdf8; display:flex; align-items:center; gap:6px;">
            ${connBadge}
            <span>${escapeHtml(conn.label || 'Interface Link')}</span>
            <span style="font-size:10px; font-weight:800; background:rgba(56, 189, 248, 0.2); border:1px solid #38bdf8; color:#38bdf8; padding:1px 5px; border-radius:10px;">[${initialsStr}]</span>
          </div>
          <div style="font-size:10px; color:#cbd5e1; margin-top:2px;">${escapeHtml(fromNode ? fromNode.name : 'Unknown')} ➔ ${escapeHtml(toNode ? toNode.name : 'Unknown')}</div>
        </div>
        <div style="display:flex; gap:4px; align-items:center; margin-left:8px;">
          <button class="btn btn-xs btn-outline-info" style="padding:2px 6px; font-size:10px; font-weight:700;" onclick="openInterfaceLinkEditorModal('${conn.fromId}', '${conn.toId}', '${conn.interfaceId || ''}')" title="Edit Interface Linkage">✏️ Edit</button>
          <button class="btn btn-xs btn-outline-danger" style="padding:2px 6px; font-size:10px;" onclick="deleteBoundaryConnection('${conn.id}')" title="Delete Interface Linkage">🗑️</button>
        </div>
      </div>
    `;
  });

  container.innerHTML = html;
}

async function deleteBoundaryConnection(connId) {
  const conn = (fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.connections)
    ? fmeaData.boundaryDiagram.connections.find(c => c.id === connId) : null;
  const label = conn ? (conn.label || conn.type || 'Connection') : 'Connection';
  const isConfirmed = await showCustomConfirm(`Are you sure you want to delete boundary connection "${label}"?`, 'Delete Boundary Connection', 'warning');
  if (!isConfirmed) return;

  if (conn && conn.interfaceId) {
    const ifaceId = conn.interfaceId;
    fmeaData.interfaceMatrix = (fmeaData.interfaceMatrix || []).filter(i => i.id !== ifaceId);
    fmeaData.functions = (fmeaData.functions || []).filter(f => f.interfaceId !== ifaceId);
    fmeaData.functionLines = (fmeaData.functionLines || []).filter(fl => fl.interfaceId !== ifaceId);
  }

  fmeaData.boundaryDiagram.connections = (fmeaData.boundaryDiagram.connections || []).filter(c => c.id !== connId);
  renderBoundaryDiagram();
  if (typeof renderInterfaceMatrix === 'function') renderInterfaceMatrix();
  if (typeof renderFMEATable === 'function') renderFMEATable();
}

async function deleteBoundaryNode(nodeId) {
  const isConfirmed = await showCustomConfirm('Are you sure you want to delete this block and remove it from the DFMEA Structure Tree?', 'Delete Boundary Block', 'warning');
  if (!isConfirmed) return;

  deleteStructureNodeHelper(nodeId);
  syncBoundaryDiagramWithStructure();
  if (typeof renderTreeSidebar === 'function') renderTreeSidebar();
  if (typeof renderFMEATable === 'function') renderFMEATable();
  renderBoundaryDiagram();
}

function exportBoundaryDiagramPNG() {
  alert('Exporting Boundary Diagram PNG layout view...');
  try { window.print(); } catch (e) { }
  setTimeout(unlockApplicationPointerEvents, 200);
}

// ============================================================
// HIDE / UNHIDE FEATURE
// ============================================================

function toggleBoundaryNodeVisibility(nodeId) {
  if (!fmeaData.boundaryDiagram) return;
  const node = (fmeaData.boundaryDiagram.nodes || []).find(n => n.id === nodeId);
  if (!node) return;
  node.hidden = !node.hidden;
  renderBoundaryDiagram();
  if (typeof showToast === 'function') showToast(node.hidden ? '🙈 Block hidden from diagram.' : '👁️ Block is now visible.', 'info');
}
window.toggleBoundaryNodeVisibility = toggleBoundaryNodeVisibility;

function toggleExternalBlockVisibility(extId) {
  if (!fmeaData.boundaryDiagram) return;
  const node = (fmeaData.boundaryDiagram.externalNodes || []).find(n => n.id === extId);
  if (!node) return;
  node.hidden = !node.hidden;
  renderBoundaryDiagram();
  if (typeof showToast === 'function') showToast(node.hidden ? '🙈 External block hidden.' : '👁️ External block visible.', 'info');
}
window.toggleExternalBlockVisibility = toggleExternalBlockVisibility;

function showAllBoundaryNodes() {
  if (!fmeaData.boundaryDiagram) return;
  (fmeaData.boundaryDiagram.nodes || []).forEach(n => { n.hidden = false; });
  (fmeaData.boundaryDiagram.externalNodes || []).forEach(n => { n.hidden = false; });
  renderBoundaryDiagram();
  if (typeof showToast === 'function') showToast('👁️ All blocks are now visible.', 'success');
}
window.showAllBoundaryNodes = showAllBoundaryNodes;

function hideAllBoundaryNodesExceptRoot() {
  if (!fmeaData.boundaryDiagram) return;
  (fmeaData.boundaryDiagram.nodes || []).forEach(n => { if (n.type !== 'SYSTEM_ROOT') n.hidden = true; });
  (fmeaData.boundaryDiagram.externalNodes || []).forEach(n => { n.hidden = true; });
  renderBoundaryDiagram();
  if (typeof showToast === 'function') showToast('🙈 All non-root blocks hidden.', 'info');
}
window.hideAllBoundaryNodesExceptRoot = hideAllBoundaryNodesExceptRoot;

function renderBoundaryVisibilityPanel() {
  const panel = document.getElementById('boundaryVisibilityPanel');
  if (!panel) return;

  const nodes = fmeaData.boundaryDiagram ? (fmeaData.boundaryDiagram.nodes || []) : [];
  const extNodes = fmeaData.boundaryDiagram ? (fmeaData.boundaryDiagram.externalNodes || []) : [];

  if (nodes.length === 0 && extNodes.length === 0) {
    panel.innerHTML = '<div style="font-size:11px;color:#64748b;">No blocks yet.</div>';
    return;
  }

  let html = '';

  nodes.forEach(node => {
    const isHidden = !!node.hidden;
    const isRoot = node.type === 'SYSTEM_ROOT';
    const badgeColor = isRoot ? '#0284c7' : (node.type === 'SUBSYSTEM' ? '#059669' : '#475569');
    html += `
      <div style="display:flex; align-items:center; gap:6px; padding:5px 0; border-bottom:1px solid #1e293b;">
        <button onclick="toggleBoundaryNodeVisibility('${node.id}')" title="${isHidden ? 'Show' : 'Hide'}" style="background:none;border:none;cursor:pointer;font-size:14px;padding:0;line-height:1;opacity:${isHidden ? 0.4 : 1};">${isHidden ? '🙈' : '👁️'}</button>
        <span style="font-size:9px;font-weight:700;padding:1px 5px;border-radius:3px;background:${badgeColor};color:#fff;text-transform:uppercase;flex-shrink:0;">${node.type || 'BLK'}</span>
        <span style="font-size:11px;color:${isHidden ? '#475569' : '#cbd5e1'};flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;${isHidden ? 'text-decoration:line-through;' : ''}" title="${escapeHtml(node.name)}">${escapeHtml(node.name)}</span>
      </div>`;
  });

  if (extNodes.length > 0) {
    html += `<div style="font-size:9px;font-weight:700;color:#a855f7;text-transform:uppercase;letter-spacing:0.5px;padding:6px 0 2px;">🌐 External Blocks</div>`;
    extNodes.forEach(node => {
      const isHidden = !!node.hidden;
      const typeDef = EXTERNAL_BLOCK_TYPES[node.externalType] || EXTERNAL_BLOCK_TYPES.CUSTOM;
      html += `
        <div style="display:flex; align-items:center; gap:6px; padding:5px 0; border-bottom:1px solid #1e293b;">
          <button onclick="toggleExternalBlockVisibility('${node.id}')" title="${isHidden ? 'Show' : 'Hide'}" style="background:none;border:none;cursor:pointer;font-size:14px;padding:0;line-height:1;opacity:${isHidden ? 0.4 : 1};">${isHidden ? '🙈' : '👁️'}</button>
          <span style="font-size:9px;font-weight:700;padding:1px 5px;border-radius:3px;background:${typeDef.color};color:#fff;text-transform:uppercase;flex-shrink:0;">${typeDef.emoji}</span>
          <span style="font-size:11px;color:${isHidden ? '#475569' : '#c4b5fd'};flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;${isHidden ? 'text-decoration:line-through;' : ''}" title="${escapeHtml(node.name)}">${escapeHtml(node.name)}</span>
        </div>`;
    });
  }

  panel.innerHTML = html;
}
