async function deleteExternalBlock(extId) {
  const node = (fmeaData.boundaryDiagram && fmeaData.boundaryDiagram.externalNodes)
    ? fmeaData.boundaryDiagram.externalNodes.find(n => n.id === extId)
    : null;
  const label = node ? node.name : 'External Block';
  const confirmed = await showCustomConfirm(`Delete external block "${label}"? This will also remove its connections and associated interface functions from FMEA.`, 'Delete External Block', 'warning');
  if (!confirmed) return;

  // 1. Remove from externalNodes
  fmeaData.boundaryDiagram.externalNodes = (fmeaData.boundaryDiagram.externalNodes || []).filter(n => n.id !== extId);

  // 2. Remove diagram connections
  fmeaData.boundaryDiagram.connections = (fmeaData.boundaryDiagram.connections || []).filter(
    c => c.fromId !== extId && c.toId !== extId
  );

  // 3. Remove associated interfaceMatrix records and clean up interface functions
  const removedIfaceIds = new Set();
  fmeaData.interfaceMatrix = (fmeaData.interfaceMatrix || []).filter(i => {
    if (i.elementIdA === extId || i.elementIdB === extId) {
      removedIfaceIds.add(i.id);
      return false;
    }
    return true;
  });

  if (removedIfaceIds.size > 0) {
    fmeaData.functions = (fmeaData.functions || []).filter(f => !removedIfaceIds.has(f.interfaceId));
    fmeaData.functionLines = (fmeaData.functionLines || []).filter(fl => !removedIfaceIds.has(fl.interfaceId));
  }

  closeModal('boundaryEditExternalBlockModal');
  renderBoundaryDiagram();
  if (typeof renderInterfaceMatrix === 'function') renderInterfaceMatrix();
  if (typeof renderFMEATable === 'function') renderFMEATable();
  if (typeof showToast === 'function') showToast(`🗑️ External block "${label}" deleted.`, 'info');
}
window.deleteExternalBlock = deleteExternalBlock;

