function setWb2CustomParamsPreset(type) {
  const target = document.getElementById('wb2ApiCustomParams');
  if (!target) return;
  if (type === 'nvidia_k3') {
    target.value = '{\n  "max_tokens": 16384,\n  "temperature": 1,\n  "reasoning_effort": "max",\n  "seed": 0\n}';
  } else if (type === 'reasoning') {
    target.value = '{\n  "reasoning_effort": "max"\n}';
  } else if (type === 'deterministic') {
    target.value = '{\n  "seed": 0,\n  "temperature": 0.2\n}';
  } else if (type === 'clear') {
    target.value = '';
  }
}

function saveWb2ApiSettings() {
  const prov = document.getElementById('wb2ApiProvider')?.value || 'nvidia';
  const key = document.getElementById('wb2ApiKey')?.value.trim() || '';
  const ep = document.getElementById('wb2ApiEndpoint')?.value.trim() || 'https://integrate.api.nvidia.com/v1/chat/completions';
  const mod = document.getElementById('wb2ApiModel')?.value.trim() || 'moonshotai/kimi-k3';
  const customHeaders = document.getElementById('wb2ApiCustomHeaders')?.value.trim() || '';
  const customParams = document.getElementById('wb2ApiCustomParams')?.value.trim() || '';
  const customFormat = document.getElementById('wb2ApiCustomFormat')?.value || 'chat';

  if (customHeaders) {
    try {
      JSON.parse(customHeaders);
    } catch (err) {
      alert("Invalid Custom HTTP Headers JSON: " + err.message);
      return;
    }
  }
  if (customParams) {
    try {
      JSON.parse(customParams);
    } catch (err) {
      alert("Invalid Custom Body Parameters JSON: " + err.message);
      return;
    }
  }

  const settingsObj = {
    provider: prov,
    apiKey: key,
    endpoint: ep,
    model: mod,
    customHeaders,
    customParams,
    customFormat
  };

  aiWorkbench2State.apiSettings = Object.assign({}, settingsObj);
  if (typeof aiWorkbench3State !== 'undefined') {
    aiWorkbench3State.apiSettings = Object.assign({}, settingsObj);
  }

  try {
    localStorage.setItem('jost_wb2_api_config', JSON.stringify(settingsObj));
  } catch (e) {
    console.warn('Failed to save to localStorage:', e);
  }

  closeModal('wb2ApiSettingsModal');
  if (typeof showToast === 'function') showToast('⚙️ Saved AI API settings!', 'success');
}

async function testWb2ApiConnection() {
  const status = document.getElementById('wb2ApiTestStatus');
  if (!status) return;
  status.style.display = 'block';
  status.style.background = '#1e293b';
  status.style.color = '#38bdf8';
  status.textContent = 'Testing connection...';

  const prov = document.getElementById('wb2ApiProvider')?.value || 'nvidia';
  const key = document.getElementById('wb2ApiKey')?.value.trim() || '';
  const ep = document.getElementById('wb2ApiEndpoint')?.value.trim() || '';
  const mod = document.getElementById('wb2ApiModel')?.value.trim() || 'moonshotai/kimi-k3';
  const customHeadersRaw = document.getElementById('wb2ApiCustomHeaders')?.value.trim() || '';
  const customParamsRaw = document.getElementById('wb2ApiCustomParams')?.value.trim() || '';

  let extraHeaders = {};
  if (customHeadersRaw) {
    try { extraHeaders = JSON.parse(customHeadersRaw); } catch (e) { }
  }
  let extraParams = {};
  if (customParamsRaw) {
    try { extraParams = JSON.parse(customParamsRaw); } catch (e) { }
  }

  try {
    let res;
    const isResponsesApi = prov === 'openai_responses' || (ep && ep.includes('/responses'));
    const isNvidia = prov === 'nvidia' || (ep && ep.includes('nvidia.com'));

    if (isResponsesApi) {
      res = await fetch(ep, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` }, extraHeaders),
        body: JSON.stringify(Object.assign({ model: mod, input: 'Reply with OK', store: true }, extraParams))
      });
    } else if (isNvidia) {
      res = await fetch(ep, {
        method: 'POST',
        headers: Object.assign({
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${key}`,
          'Accept': 'application/json'
        }, extraHeaders),
        body: JSON.stringify(Object.assign({
          model: mod,
          messages: [{ role: 'user', content: 'Reply with OK' }],
          max_tokens: 32,
          temperature: 1,
          stream: false
        }, extraParams))
      });
    } else if (prov === 'openai' || prov === 'azure' || prov === 'custom' || prov === 'openrouter' || prov === 'openrouter_free' || prov === 'groq' || prov === 'groq_free') {
      res = await fetch(ep, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` }, extraHeaders),
        body: JSON.stringify(Object.assign({
          model: mod,
          messages: [{ role: 'user', content: 'Reply with OK' }],
          max_tokens: 10
        }, extraParams))
      });
    } else if (prov === 'gemini' || prov === 'gemini_free' || prov === 'google_gemini') {
      const url = ep.includes('key=') ? ep : `${ep}${ep.includes('?') ? '&' : '?'}key=${key}`;
      res = await fetch(url, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json', 'x-goog-api-key': key }, extraHeaders),
        body: JSON.stringify(Object.assign({ contents: [{ parts: [{ text: 'Reply with OK' }] }] }, extraParams))
      });
    } else if (prov === 'ollama') {
      res = await fetch(ep, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json' }, extraHeaders),
        body: JSON.stringify(Object.assign({ model: mod, messages: [{ role: 'user', content: 'Reply with OK' }], stream: false }, extraParams))
      });
    }

    if (res && res.ok) {
      status.style.background = '#064e3b';
      status.style.color = '#34d399';
      status.textContent = `✅ Connection successful! ${prov.toUpperCase()} responded with HTTP ${res.status} OK.`;
    } else {
      const txt = res ? await res.text() : 'No response';
      status.style.background = '#450a0a';
      status.style.color = '#f87171';
      status.textContent = `❌ Connection failed (HTTP ${res ? res.status : 'ERR'}): ${txt.slice(0, 180)}`;
    }
  } catch (err) {
    status.style.background = '#450a0a';
    status.style.color = '#f87171';
    status.textContent = `❌ Network Error: ${err.message}`;
  }
}

async function executeWb2ApiQuery(promptText, statusElId, buttonId) {
  const cfg = aiWorkbench2State.apiSettings;
  const statusEl = document.getElementById(statusElId);
  const btn = document.getElementById(buttonId);

  if (!cfg.apiKey && cfg.provider !== 'ollama') {
    alert("API Key is missing. Click 'API Config' to set your API Key, or switch to Manual Mode.");
    return null;
  }

  if (statusEl) { statusEl.style.display = 'block'; statusEl.textContent = 'Querying AI model...'; statusEl.style.color = '#38bdf8'; }
  if (btn) btn.disabled = true;

  try {
    let resultText = '';
    const isResponsesApi = cfg.provider === 'openai_responses' || (cfg.endpoint && cfg.endpoint.includes('/responses'));
    const isNvidia = cfg.provider === 'nvidia' || (cfg.endpoint && cfg.endpoint.includes('nvidia.com'));

    let extraHeaders = {};
    if (cfg.customHeaders) {
      try { extraHeaders = typeof cfg.customHeaders === 'string' ? JSON.parse(cfg.customHeaders) : cfg.customHeaders; } catch (e) { }
    }
    let extraParams = {};
    if (cfg.customParams) {
      try { extraParams = typeof cfg.customParams === 'string' ? JSON.parse(cfg.customParams) : cfg.customParams; } catch (e) { }
    }

    if (isResponsesApi) {
      const resp = await fetch(cfg.endpoint, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json', 'Authorization': `Bearer ${cfg.apiKey}` }, extraHeaders),
        body: JSON.stringify(Object.assign({ model: cfg.model, input: promptText, store: true }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      resultText = extractResponsesApiText(data);
    } else if (isNvidia) {
      const resp = await fetch(cfg.endpoint, {
        method: 'POST',
        headers: Object.assign({
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${cfg.apiKey}`,
          'Accept': 'application/json'
        }, extraHeaders),
        body: JSON.stringify(Object.assign({
          model: cfg.model || 'moonshotai/kimi-k3',
          messages: [{ role: 'user', content: promptText }],
          max_tokens: 16384,
          temperature: 1,
          reasoning_effort: 'max',
          seed: 0,
          stream: false
        }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      resultText = (data.choices && (data.choices[0]?.message?.content || data.choices[0]?.message?.reasoning_content || data.choices[0]?.delta?.content)) || '';
    } else if (cfg.provider === 'openai' || cfg.provider === 'azure' || cfg.provider === 'custom' || cfg.provider === 'openrouter' || cfg.provider === 'openrouter_free' || cfg.provider === 'groq' || cfg.provider === 'groq_free') {
      const resp = await fetch(cfg.endpoint, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json', 'Authorization': `Bearer ${cfg.apiKey}` }, extraHeaders),
        body: JSON.stringify(Object.assign({
          model: cfg.model,
          messages: [{ role: 'user', content: promptText }],
          temperature: 0.2
        }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      resultText = data.choices && (data.choices[0]?.message?.content || data.choices[0]?.message?.reasoning_content);
    } else if (cfg.provider === 'gemini' || cfg.provider === 'gemini_free' || cfg.provider === 'google_gemini') {
      const url = cfg.endpoint.includes('key=') ? cfg.endpoint : `${cfg.endpoint}${cfg.endpoint.includes('?') ? '&' : '?'}key=${cfg.apiKey}`;
      const resp = await fetch(url, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json', 'x-goog-api-key': cfg.apiKey }, extraHeaders),
        body: JSON.stringify(Object.assign({ contents: [{ parts: [{ text: promptText }] }] }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      if (data.candidates && data.candidates[0]?.content?.parts) {
        const parts = data.candidates[0].content.parts;
        const part = parts.find(p => p.text && !p.thought) || parts[parts.length - 1];
        resultText = part ? part.text : '';
      } else {
        resultText = '';
      }
    } else if (cfg.provider === 'ollama') {
      const resp = await fetch(cfg.endpoint, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json' }, extraHeaders),
        body: JSON.stringify(Object.assign({ model: cfg.model, messages: [{ role: 'user', content: promptText }], stream: false }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      resultText = data.message?.content;
    }

    if (statusEl) { statusEl.textContent = '✅ Completed successfully!'; statusEl.style.color = '#34d399'; }
    return resultText;
  } catch (err) {
    if (statusEl) { statusEl.textContent = `❌ Error: ${err.message}`; statusEl.style.color = '#f87171'; }
    alert("AI Query Failed: " + err.message);
    return null;
  } finally {
    if (btn) btn.disabled = false;
  }
}

