function autoDetectComponentTypes(itemName = '', itemDesc = '', material = '') {
  const text = `${itemName} ${itemDesc} ${material}`.toLowerCase();
  const detected = [];

  if (text.match(/\b(spring|helical|coil|torsion|leaf|belleville|flexure)\b/)) {
    detected.push('Springs & Elastic Elements');
  }
  if (text.match(/\b(shaft|pin|axle|rod|spindle|journal|dowel|crank|camshaft|pivot pin|kingpin)\b/)) {
    detected.push('Shafts, Pins & Axles');
  }
  if (text.match(/\b(plate|bracket|sheet|flange|mount|gusset|stiffener|reinforcement|tray|panel|chassis)\b/)) {
    detected.push('Structural Plates & Brackets');
  }
  if (text.match(/\b(tube|pipe|hose|hollow|duct|cylinder barrel|conduit|manifold)\b/)) {
    detected.push('Tubes, Pipes & Structural Hollow Sections');
  }
  if (text.match(/\b(cast|forg|housing|block|knuckle|bracket casting|yoke|carrier|arm|jaw)\b/)) {
    detected.push('Castings & Forgings');
  }
  if (text.match(/\b(bushing|sleeve|bearing|liner|wear ring|collar|needle bearing|roller bearing)\b/)) {
    detected.push('Bushings, Sleeves & Bearings');
  }
  if (text.match(/\b(plastic|nylon|pa66|pom|ptfe|polymer|molded|cover|cap|plug|clip|housing plastic|delrin)\b/)) {
    detected.push('Plastic & Molded Components');
  }
  if (text.match(/\b(seal|gasket|o-ring|oring|packing|wiper|diaphragm|elastomer|rubber|fkm|epdm|nbr)\b/)) {
    detected.push('Seals, Gaskets & Elastomers');
  }
  if (text.match(/\b(cylinder|hydraulic|pneumatic|actuator|ram|piston rod|piston cylinder|air cylinder)\b/)) {
    detected.push('Hydraulic / Pneumatic Cylinders');
  }

  // Fallback: if nothing matched, default to 'Structural Plates & Brackets'
  if (detected.length === 0) {
    detected.push('Structural Plates & Brackets');
  }
  return detected;
}

function resolveWb3ComponentTypeKey(key) {
  if (!key) return null;
  const k = String(key).trim().toLowerCase();
  if (k.includes('plate') || k.includes('bracket')) return 'Structural Plates & Brackets';
  if (k.includes('tube') || k.includes('pipe') || k.includes('hollow')) return 'Tubes, Pipes & Structural Hollow Sections';
  if (k.includes('shaft') || k.includes('pin') || k.includes('axle')) return 'Shafts, Pins & Axles';
  if (k.includes('cast') || k.includes('forg')) return 'Castings & Forgings';
  if (k.includes('spring') || k.includes('elastic')) return 'Springs & Elastic Elements';
  if (k.includes('bush') || k.includes('sleeve') || k.includes('bearing')) return 'Bushings, Sleeves & Bearings';
  if (k.includes('plastic') || k.includes('mold') || k.includes('polymer')) return 'Plastic & Molded Components';
  if (k.includes('seal') || k.includes('gasket') || k.includes('elastomer')) return 'Seals, Gaskets & Elastomers';
  if (k.includes('hydraul') || k.includes('pneumat') || k.includes('cylinder') || k.includes('actuator') || k.includes('ram')) return 'Hydraulic / Pneumatic Cylinders';
  return key;
}

function buildWb3ComponentCharacteristicsPromptText(selectedCompTypes = [], customTypesText = '') {
  const sections = [];
  const handled = new Set();

  if (Array.isArray(selectedCompTypes)) {
    selectedCompTypes.forEach(t => {
      const resolvedName = (typeof resolveWb3ComponentTypeKey === 'function') ? resolveWb3ComponentTypeKey(t) : t;
      if (!resolvedName || handled.has(resolvedName)) return;
      handled.add(resolvedName);
      const items = (typeof WB3_COMPONENT_CHARACTERISTICS !== 'undefined') ? WB3_COMPONENT_CHARACTERISTICS[resolvedName] : null;
      if (Array.isArray(items) && items.length > 0) {
        sections.push(`### ${resolvedName}\n${items.map(it => `* **${it.char}:** ${it.spec}`).join('\n')}`);
      } else {
        sections.push(`### ${resolvedName}\n* **Material & Section Properties:** Grade, wall thickness, yield strength, hardness\n* **Dimensions & GD&T:** Critical tolerances, runout, surface finish Ra`);
      }
    });
  }

  if (customTypesText && typeof customTypesText === 'string') {
    customTypesText.split(/[,;\n]/).forEach(line => {
      const trimmed = line.trim();
      if (!trimmed || handled.has(trimmed)) return;
      handled.add(trimmed);
      sections.push(`* **${trimmed} (User Specified):** Address this exact characteristic / requirement as specified by user`);
    });
  }

  if (sections.length === 0) return '';
  return `\n════════════════════════════════════════════════════════════════════════════════\nSELECTED COMPONENT CHARACTERISTICS (DERIVE CAUSES ONLY FROM THESE CHECKED TYPES):\nCheck these physical component characteristics when formulating failure causes:\nCRITICAL INSTRUCTION FOR CAUSE FORMULATION:\nLink ONLY those characteristics that are logically and physically relevant to the specific failure mode, component function, and root cause mechanism under consideration (do not mechanically copy or link illogical characteristics).\n\n${sections.join('\n\n')}\n════════════════════════════════════════════════════════════════════════════════\n`;
}

