// ══════════════════════════════════════════════════════════════════════════════
// WB3 API LOCK — Prevent navigation / double-trigger during API calls
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Lock or unlock all WB3 step navigation controls while an API call is in flight.
 * @param {boolean} lock  true = disable navigation, false = re-enable
 */
function wb3SetApiLock(lock) {
  aiWorkbench3State.apiInProgress = lock;
  const ids = ['wb3BtnPrevStep', 'wb3BtnNextStep'];
  ids.forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.disabled = lock;
      el.style.opacity = lock ? '0.4' : '';
      el.style.cursor = lock ? 'not-allowed' : '';
    }
  });
  // Dim step badges while locked so user sees they are blocked
  for (let i = 1; i <= 8; i++) {
    const badge = document.getElementById(`wb3StepBadge${i}`);
    if (badge) {
      badge.style.pointerEvents = lock ? 'none' : '';
      badge.style.opacity = lock ? '0.5' : '';
    }
  }
}


