function executeWorkbenchClearScope(wbType = 'WB3') {
  const modal = document.getElementById('wbClearScopeModal');
  const selectedRadio = modal ? modal.querySelector('input[name="wbClearScopeRadio"]:checked') : null;
  const scope = selectedRadio ? selectedRadio.value : 'step';
  if (modal) modal.remove();

  if (wbType === 'WB4') {
    executeWb4ClearScope(scope);
  } else {
    executeWb3ClearScope(scope);
  }
}

function executeWb3ClearScope(scope) {
  const nodeId = aiWorkbench3State.currentNodeId;
  const currentStep = aiWorkbench3State.currentStep || 1;
  const ctx = getActiveFmeaData();
  const node = (ctx && ctx.structure && nodeId) ? getStructureNodeById(ctx.structure, nodeId) : null;
  const elementName = (node ? node.name : '') || (aiWorkbench3State.nodeContexts[nodeId] ? aiWorkbench3State.nodeContexts[nodeId].itemName : '') || 'Element';

  if (scope === 'step') {
    if (currentStep === 1) {
      delete aiWorkbench3State.nodeContexts[nodeId];
      delete aiWorkbench3State.nodeRequirements[nodeId];
      ['wb3InputItemName', 'wb3InputPartNumber', 'wb3InputItemDesc', 'wb3InputMaterial', 'wb3InputGdt', 'wb3InputEnvironment', 'wb3InputControlsList', 'wb3Step1TopReqsInput'].forEach(id => {
        const el = document.getElementById(id); if (el) el.value = '';
      });
      loadWb3NodeContext(nodeId);
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 1 Drawing Context for "${elementName}".`, 'info');
    } else if (currentStep === 2) {
      delete aiWorkbench3State.nodeFunctions[nodeId];
      renderWb3FunctionsTable();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 2 Functions for "${elementName}".`, 'info');
    } else if (currentStep === 3) {
      delete aiWorkbench3State.nodeFailures[nodeId];
      renderWb3FailureModesList();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 3 Failure Modes for "${elementName}".`, 'info');
    } else if (currentStep === 4) {
      const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
      fms.forEach(f => { delete f.effectsList; delete f.linkedHigherFailureId; });
      delete aiWorkbench3State.updatedEffectsLibrary[nodeId];
      aiWorkbench3State.step4FmPointer[nodeId] = 0;
      renderWb3Step4MicroNav();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 4 Effects & Linkages for "${elementName}".`, 'info');
    } else if (currentStep === 5) {
      delete aiWorkbench3State.nodeCauses[nodeId];
      delete aiWorkbench3State.updatedCausesLibrary[nodeId];
      aiWorkbench3State.step5FmPointer[nodeId] = 0;
      renderWb3Step5MicroNav();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 5 Root Causes for "${elementName}".`, 'info');
    } else if (currentStep === 6) {
      delete aiWorkbench3State.nodeControls[nodeId];
      aiWorkbench3State.step6FmPointer[nodeId] = 0;
      renderWb3Step6MicroNav();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 6 Controls for "${elementName}".`, 'info');
    } else if (currentStep >= 7) {
      updateWb3Step8Dashboard();
      if (typeof showToast === 'function') showToast(`🗑️ Refreshed dashboard for "${elementName}".`, 'info');
    }
  } else if (scope === 'element') {
    delete aiWorkbench3State.nodeContexts[nodeId];
    delete aiWorkbench3State.nodeFunctions[nodeId];
    delete aiWorkbench3State.nodeFailures[nodeId];
    delete aiWorkbench3State.nodeCauses[nodeId];
    delete aiWorkbench3State.nodeControls[nodeId];
    delete aiWorkbench3State.nodeRequirements[nodeId];
    delete aiWorkbench3State.updatedEffectsLibrary[nodeId];
    delete aiWorkbench3State.updatedCausesLibrary[nodeId];
    delete aiWorkbench3State.step4FmPointer[nodeId];
    delete aiWorkbench3State.step5FmPointer[nodeId];
    delete aiWorkbench3State.step6FmPointer[nodeId];
    delete aiWorkbench3State.topLevelRequirements[nodeId];
    aiWorkbench3State.processedNodes.delete(nodeId);
    if (aiWorkbench3State.ingestedNodes) aiWorkbench3State.ingestedNodes.delete(nodeId);
    ['wb3InputItemName', 'wb3InputPartNumber', 'wb3InputItemDesc', 'wb3InputMaterial', 'wb3InputGdt', 'wb3InputEnvironment', 'wb3InputControlsList', 'wb3Step1TopReqsInput'].forEach(id => {
      const el = document.getElementById(id); if (el) el.value = '';
    });
    goToWb3Step(1);
    if (typeof showToast === 'function') showToast(`🗑️ Cleared ALL steps for "${elementName}". Restarting at Step 1.`, 'info');
  } else if (scope === 'all_elements') {
    aiWorkbench3State.nodeContexts = {};
    aiWorkbench3State.nodeFunctions = {};
    aiWorkbench3State.nodeFailures = {};
    aiWorkbench3State.nodeCauses = {};
    aiWorkbench3State.nodeControls = {};
    aiWorkbench3State.nodeRequirements = {};
    aiWorkbench3State.updatedEffectsLibrary = {};
    aiWorkbench3State.updatedCausesLibrary = {};
    aiWorkbench3State.step4FmPointer = {};
    aiWorkbench3State.step5FmPointer = {};
    aiWorkbench3State.step6FmPointer = {};
    aiWorkbench3State.topLevelRequirements = {};
    aiWorkbench3State.processedNodes = new Set();
    aiWorkbench3State.ingestedNodes = new Set();
    ['wb3InputItemName', 'wb3InputPartNumber', 'wb3InputItemDesc', 'wb3InputMaterial', 'wb3InputGdt', 'wb3InputEnvironment', 'wb3InputControlsList', 'wb3Step1TopReqsInput'].forEach(id => {
      const el = document.getElementById(id); if (el) el.value = '';
    });
    goToWb3Step(1);
    if (typeof showToast === 'function') showToast('🗑️ Cleared Workbench 3.0 data for ALL components and elements.', 'info');
  }

  if (typeof syncWorkbenchStateToProjectData === 'function') syncWorkbenchStateToProjectData();
}

function executeWb4ClearScope(scope) {
  const nodeId = aiWorkbench4State.currentNodeId;
  const currentStep = aiWorkbench4State.currentStep || 1;
  const ctx = getActiveFmeaData();
  const node = (ctx && ctx.structure && nodeId) ? getStructureNodeById(ctx.structure, nodeId) : null;
  const elementName = (node ? node.name : '') || (aiWorkbench4State.nodeContexts && aiWorkbench4State.nodeContexts[nodeId] ? aiWorkbench4State.nodeContexts[nodeId].itemName : '') || 'Element';

  if (scope === 'step') {
    if (currentStep === 1) {
      if (aiWorkbench4State.nodeDrawingData) delete aiWorkbench4State.nodeDrawingData[nodeId];
      if (aiWorkbench4State.nodeContexts) delete aiWorkbench4State.nodeContexts[nodeId];
      const el = document.getElementById('wb4RawDrawingInput'); if (el) el.value = '';
      if (typeof loadWb4NodeContext === 'function') loadWb4NodeContext(nodeId);
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 1 Drawing Context for "${elementName}".`, 'info');
    } else if (currentStep === 2) {
      if (aiWorkbench4State.nodeFunctions) delete aiWorkbench4State.nodeFunctions[nodeId];
      if (typeof renderWb4FunctionsTable === 'function') renderWb4FunctionsTable();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 2 Functions for "${elementName}".`, 'info');
    } else if (currentStep === 3) {
      if (aiWorkbench4State.nodeFailures) delete aiWorkbench4State.nodeFailures[nodeId];
      if (typeof renderWb4FailureModesList === 'function') renderWb4FailureModesList();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 3 Failure Modes for "${elementName}".`, 'info');
    } else if (currentStep === 4) {
      if (aiWorkbench4State.nodeCauses) delete aiWorkbench4State.nodeCauses[nodeId];
      if (aiWorkbench4State.step4FmPointer) aiWorkbench4State.step4FmPointer[nodeId] = 0;
      if (typeof renderWb4Step4MicroNav === 'function') renderWb4Step4MicroNav();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 4 Characteristic Causes for "${elementName}".`, 'info');
    } else if (currentStep === 5) {
      if (aiWorkbench4State.nodeEffects) delete aiWorkbench4State.nodeEffects[nodeId];
      if (aiWorkbench4State.step5FmPointer) aiWorkbench4State.step5FmPointer[nodeId] = 0;
      if (typeof renderWb4Step5MicroNav === 'function') renderWb4Step5MicroNav();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 5 Failure Effects for "${elementName}".`, 'info');
    } else if (currentStep === 6) {
      if (aiWorkbench4State.nodeControls) delete aiWorkbench4State.nodeControls[nodeId];
      if (aiWorkbench4State.step6FmPointer) aiWorkbench4State.step6FmPointer[nodeId] = 0;
      if (typeof renderWb4Step6MicroNav === 'function') renderWb4Step6MicroNav();
      if (typeof showToast === 'function') showToast(`🗑️ Cleared Step 6 Controls for "${elementName}".`, 'info');
    } else if (currentStep >= 7) {
      if (typeof updateWb4Step8Dashboard === 'function') updateWb4Step8Dashboard();
      if (typeof window.checkAndRenderFmeaLessonLearnedBanner === 'function') window.checkAndRenderFmeaLessonLearnedBanner();
      if (typeof showToast === 'function') showToast(`🗑️ Refreshed dashboard for "${elementName}".`, 'info');
    }
  } else if (scope === 'element') {
    if (aiWorkbench4State.nodeDrawingData) delete aiWorkbench4State.nodeDrawingData[nodeId];
    if (aiWorkbench4State.nodeContexts) delete aiWorkbench4State.nodeContexts[nodeId];
    if (aiWorkbench4State.nodeFunctions) delete aiWorkbench4State.nodeFunctions[nodeId];
    if (aiWorkbench4State.nodeFailures) delete aiWorkbench4State.nodeFailures[nodeId];
    if (aiWorkbench4State.nodeCauses) delete aiWorkbench4State.nodeCauses[nodeId];
    if (aiWorkbench4State.nodeEffects) delete aiWorkbench4State.nodeEffects[nodeId];
    if (aiWorkbench4State.nodeControls) delete aiWorkbench4State.nodeControls[nodeId];
    if (aiWorkbench4State.step4FmPointer) delete aiWorkbench4State.step4FmPointer[nodeId];
    if (aiWorkbench4State.step5FmPointer) delete aiWorkbench4State.step5FmPointer[nodeId];
    if (aiWorkbench4State.step6FmPointer) delete aiWorkbench4State.step6FmPointer[nodeId];
    if (aiWorkbench4State.processedNodes) aiWorkbench4State.processedNodes.delete(nodeId);
    if (aiWorkbench4State.ingestedNodes) aiWorkbench4State.ingestedNodes.delete(nodeId);
    const el = document.getElementById('wb4RawDrawingInput'); if (el) el.value = '';
    goToWb4Step(1);
    if (typeof showToast === 'function') showToast(`🗑️ Cleared ALL steps for "${elementName}". Restarting at Step 1.`, 'info');
  } else if (scope === 'all_elements') {
    aiWorkbench4State.nodeDrawingData = {};
    aiWorkbench4State.nodeContexts = {};
    aiWorkbench4State.nodeFunctions = {};
    aiWorkbench4State.nodeFailures = {};
    aiWorkbench4State.nodeCauses = {};
    aiWorkbench4State.nodeEffects = {};
    aiWorkbench4State.nodeControls = {};
    aiWorkbench4State.step4FmPointer = {};
    aiWorkbench4State.step5FmPointer = {};
    aiWorkbench4State.step6FmPointer = {};
    aiWorkbench4State.processedNodes = new Set();
    aiWorkbench4State.ingestedNodes = new Set();
    const el = document.getElementById('wb4RawDrawingInput'); if (el) el.value = '';
    goToWb4Step(1);
    if (typeof showToast === 'function') showToast('🗑️ Cleared Workbench 4.0 data for ALL components and elements.', 'info');
  }

  if (typeof syncWorkbenchStateToProjectData === 'function') syncWorkbenchStateToProjectData();
}

function clearWb3NodeState() {
  showWorkbenchClearScopeModal('WB3');
}

window.showWorkbenchClearScopeModal = showWorkbenchClearScopeModal;
window.executeWorkbenchClearScope = executeWorkbenchClearScope;
window.executeWb3ClearScope = executeWb3ClearScope;
window.executeWb4ClearScope = executeWb4ClearScope;
window.clearWb3NodeState = clearWb3NodeState;
window.clearWb4NodeState = clearWb4NodeState;

function renderWb3StructureNavBar() {
  const nav = document.getElementById('wb3StructureNavBar');
  if (!nav) return;

  const ctx = getActiveFmeaData();
  if (!ctx || !ctx.structure) return;

  const allNodes = [];
  function traverse(node, depth = 0) {
    if (!node) return;
    allNodes.push({ node, depth });
    if (Array.isArray(node.children)) node.children.forEach(ch => traverse(ch, depth + 1));
  }
  traverse(ctx.structure);

  nav.innerHTML = allNodes.map(({ node, depth }) => {
    const isActive = (node.id === aiWorkbench3State.currentNodeId);
    const isIngested = aiWorkbench3State.ingestedNodes && aiWorkbench3State.ingestedNodes.has(node.id);
    const hasAiData = aiWorkbench3State.processedNodes.has(node.id) ||
      (ctx.functionLines || []).some(fl => fl.structId === node.id) ||
      ((aiWorkbench3State.nodeFunctions[node.id] || []).length > 0);
    const isRoot = (node.id === ctx.structure.id);
    const borderCol = isActive ? '#38bdf8' : (isIngested ? '#059669' : (hasAiData ? '#d97706' : '#334155'));
    const bgCol = isActive ? '#1e293b' : (isIngested ? '#064e3b' : (hasAiData ? '#451a03' : '#0f172a'));
    const textCol = isActive ? '#38bdf8' : (isIngested ? '#a7f3d0' : (hasAiData ? '#fde68a' : '#94a3b8'));
    return `
      <button type="button" class="btn btn-sm" onclick="switchWb3ActiveElement('${node.id}')"
        style="padding:3px 10px; font-size:11px; font-weight:700; border-radius:6px; background:${bgCol}; color:${textCol}; border:1px solid ${borderCol}; white-space:nowrap; display:inline-flex; align-items:center; gap:6px; cursor:pointer;"
        title="${escapeHtml(node.name)} (${isRoot ? 'System' : 'Level ' + depth})">
        ${isIngested ? '<span style="color:#34d399; font-size:11px;">✅</span>' : (hasAiData ? '<span style="color:#f59e0b; font-size:11px;">⚡</span>' : '<span style="color:#64748b; font-size:10px;">○</span>')}
        <span>${escapeHtml(node.name || 'Element')}</span>
        ${isActive ? '<span style="font-size:9px; background:#0284c7; color:#fff; padding:1px 4px; border-radius:3px;">ACTIVE</span>' : ''}
      </button>
    `;
  }).join('<span style="color:#475569; font-size:10px;">➔</span>');

  const statusBadge = document.getElementById('wb3CurrentNavStatusBadge');
  if (statusBadge) {
    const activeNode = getStructureNodeById(ctx.structure, aiWorkbench3State.currentNodeId);
    const hasActiveAi = activeNode && (aiWorkbench3State.processedNodes.has(activeNode.id) || (ctx.functionLines || []).some(fl => fl.structId === activeNode.id));
    const saved = aiWorkbench3State.nodeContexts[aiWorkbench3State.currentNodeId] || {};
    const isCat = (saved.isCatalogueItem !== undefined) ? !!saved.isCatalogueItem : !!(activeNode && activeNode.isCatalogueItem);
    const catBadge = isCat ? '<span style="color:#fbbf24; background:rgba(245,158,11,0.15); border:1px solid rgba(245,158,11,0.3); padding:1px 6px; border-radius:4px; margin-left:4px; font-size:9.5px;">📖 Catalogue Part</span>' : '';
    statusBadge.innerHTML = (hasActiveAi
      ? '<span style="color:#34d399; font-weight:800;">✨ AI-Generated</span>'
      : '<span style="color:#94a3b8;">○ Not Generated</span>') + catBadge;
  }
}

function switchWb3ActiveElement(nodeId) {
  saveCurrentWb3Inputs();
  aiWorkbench3State.currentNodeId = nodeId;
  renderWb3StructureNavBar();
  loadWb3NodeContext(nodeId);
  goToWb3Step(1);
}

function loadWb3NodeContext(nodeId) {
  const ctx = getActiveFmeaData();
  const node = getStructureNodeById(ctx.structure, nodeId);
  if (!node) return;

  const isRoot = (node.id === ctx.structure.id);
  const parentNode = isRoot ? null : getParentStructureNode(ctx.structure, nodeId);

  const levelTag = document.getElementById('wb3Step1LevelTag');
  if (levelTag) {
    levelTag.textContent = isRoot ? 'Root / System Level' : (parentNode && parentNode.id === ctx.structure.id ? 'Sub-system (Level n)' : 'Component (Level n)');
    levelTag.style.background = isRoot ? '#0284c7' : '#7c3aed';
  }

  const saved = aiWorkbench3State.nodeContexts[nodeId] || {};

  const itemNameInput = document.getElementById('wb3InputItemName');
  const partNoInput = document.getElementById('wb3InputPartNumber');
  const typeSelect = document.getElementById('wb3ItemTypeSelect');
  const descInput = document.getElementById('wb3InputItemDesc');
  const matInput = document.getElementById('wb3InputMaterial');
  const gdtInput = document.getElementById('wb3InputGdt');
  const envInput = document.getElementById('wb3InputEnvironment');
  const ctrlsArea = document.getElementById('wb3InputControlsList');
  const chkCtrl = document.getElementById('wb3ChkHasControlsList');
  const ctrlBox = document.getElementById('wb3ControlsListInputBox');
  const chkReqs = document.getElementById('wb3ChkRequirementsNeeded');

  if (itemNameInput) itemNameInput.value = saved.itemName || node.name || '';
  if (partNoInput) partNoInput.value = saved.partNumber || node.partNo || node.partNumber || 'PN-001';
  if (typeSelect) typeSelect.value = saved.itemType || (isRoot ? 'Assembly' : (node.type || 'Component'));
  if (descInput) descInput.value = saved.itemDesc || node.desc || node.description || '';
  if (matInput) matInput.value = saved.material || '';
  if (gdtInput) gdtInput.value = saved.gdt || '';
  if (envInput) envInput.value = saved.env || '';
  if (ctrlsArea) ctrlsArea.value = saved.controlsList || '';
  if (chkCtrl) {
    chkCtrl.checked = !!(saved.controlsList);
    if (ctrlBox) ctrlBox.style.display = chkCtrl.checked ? 'block' : 'none';
  }
  if (chkReqs) chkReqs.checked = !!(saved.requirementsNeeded);
  aiWorkbench3State.requirementsNeeded = !!(saved.requirementsNeeded);
  aiWorkbench3State.controlsListProvided = !!(saved.controlsList);

  // Restore Catalogue Item Checkbox (Design Responsible vs Catalogue Selection)
  const chkCatalogue = document.getElementById('wb3ChkCatalogueItem');
  const isCatalogue = (saved.isCatalogueItem !== undefined)
    ? !!saved.isCatalogueItem
    : !!(node && node.isCatalogueItem);
  if (chkCatalogue) chkCatalogue.checked = isCatalogue;
  const catContainer = document.getElementById('wb3CataloguePartContainer');
  if (catContainer) {
    catContainer.style.borderColor = isCatalogue ? '#f59e0b' : '#334155';
    catContainer.style.background = isCatalogue ? 'rgba(245, 158, 11, 0.08)' : '#080d1a';
  }

  // Restore top-level requirements
  const chkTopReqs = document.getElementById('wb3ChkTopLevelReqs');
  const topReqsInput = document.getElementById('wb3Step1TopReqsInput');
  const topReqsBox = document.getElementById('wb3TopReqsInputBox');
  const hasTopReqs = !!(saved.topReqsRaw);
  if (chkTopReqs) chkTopReqs.checked = hasTopReqs;
  if (topReqsInput) topReqsInput.value = saved.topReqsRaw || '';
  if (topReqsBox) topReqsBox.style.display = hasTopReqs ? 'block' : 'none';
  aiWorkbench3State.topLevelReqsProvided = (aiWorkbench3State.topLevelRequirements[nodeId] || []).length > 0;


  const parentBox = document.getElementById('wb3ParentContextPanel');
  const parentNameText = document.getElementById('wb3ParentNameText');
  const parentPartNoBadge = document.getElementById('wb3ParentPartNoBadge');
  const parentFnsList = document.getElementById('wb3ParentFunctionsList');

  if (isRoot) {
    if (parentBox) parentBox.style.display = 'none';
  } else {
    if (parentBox) parentBox.style.display = 'block';
    if (parentNameText) parentNameText.textContent = parentNode ? parentNode.name : 'Unknown Parent';
    if (parentPartNoBadge) parentPartNoBadge.textContent = parentNode ? (parentNode.partNo || parentNode.partNumber || 'N/A') : '';
    if (parentFnsList) {
      const parentFns = (ctx.functions || []).filter(f => f.structId === (parentNode ? parentNode.id : ''));
      parentFnsList.innerHTML = parentFns.length === 0
        ? '<div style="color:#64748b; font-size:10.5px; font-style:italic;">No parent functions yet.</div>'
        : parentFns.map(f => `<div style="font-size:10.5px; color:#cbd5e1; padding:2px 0; border-bottom:1px solid #1e293b;">• ${escapeHtml(f.name)} <span style="color:#7c3aed;">(${f.type || 'Primary'})</span></div>`).join('');
    }
  }

  const savedJoints = Array.isArray(saved.joints) ? saved.joints : [];
  document.querySelectorAll('.wb3-joint-chk').forEach(chk => { chk.checked = savedJoints.includes(chk.value); });
  const wb3CustomJointInput = document.getElementById('wb3CustomJointCharsInput');
  if (wb3CustomJointInput) {
    wb3CustomJointInput.value = saved.customJointChars || '';
  }

  // Load component characteristics and types strictly from saved state
  const savedCompChars = Array.isArray(saved.componentCharacteristics) ? saved.componentCharacteristics : (Array.isArray(saved.componentTypes) ? saved.componentTypes : []);
  if (typeof initWb3ComponentCharacteristicsSelector === 'function') {
    initWb3ComponentCharacteristicsSelector(savedCompChars);
  }
  const savedCompTypes = Array.isArray(saved.componentTypes) ? saved.componentTypes : [];
  document.querySelectorAll('.wb3-comp-type-chk').forEach(chk => {
    chk.checked = savedCompTypes.includes(chk.value);
  });
  const customTypesInput = document.getElementById('wb3CompCustomTypesInput');
  if (customTypesInput) {
    customTypesInput.value = saved.customComponentTypes || '';
  }

  // Load component features strictly from saved state
  const savedCompFeatures = Array.isArray(saved.componentFeatures) ? saved.componentFeatures : [];
  document.querySelectorAll('.wb3-comp-feature-chk').forEach(chk => {
    chk.checked = savedCompFeatures.includes(chk.value);
  });
  const customFeaturesInput = document.getElementById('wb3CompCustomFeaturesInput');
  if (customFeaturesInput) {
    customFeaturesInput.value = '';
  }
  window.wb3ComponentCustomFeatures = [];
  if (saved.customComponentFeatures) {
    saved.customComponentFeatures.split(/[,;\n]/).forEach(t => {
      const tr = t.trim();
      if (tr) window.wb3ComponentCustomFeatures.push({ name: tr, spec: 'Custom feature specifications & tolerance limits' });
    });
  }
  if (Array.isArray(saved.customComponentFeaturesList)) {
    window.wb3ComponentCustomFeatures = saved.customComponentFeaturesList.map(f => typeof f === 'string' ? { name: f, spec: 'Custom feature specifications & tolerance limits' } : f);
  }
  if (typeof renderWb3ConsideredCharacteristicsTable === 'function') {
    renderWb3ConsideredCharacteristicsTable();
  }

  // Root Level Strict Function Types Box (Root Element Only)
  const rootFnBox = document.getElementById('wb3RootFunctionTypesBox');
  if (rootFnBox) {
    rootFnBox.style.display = isRoot ? 'block' : 'none';
    const strictTypes = Array.isArray(saved.strictFunctionTypes) ? saved.strictFunctionTypes : [];
    document.querySelectorAll('.wb3-root-fn-type-chk').forEach(chk => {
      chk.checked = strictTypes.includes(chk.value);
    });
  }

  // Mixed Components Chips & Live Joint Preview
  renderWb3MixedComponentsChips();
  updateWb3JointCharacteristicsPreview();

  const savedMode = saved.analysisMode || aiWorkbench3State.analysisMode || 'moderate';
  setWb3AnalysisMode(savedMode);

  onWb3ItemTypeChange();
}

function saveCurrentWb3Inputs() {
  const modal = document.getElementById('aiWorkbench3Modal');
  if (!modal || (modal.style.display !== 'flex' && modal.style.display !== 'block')) {
    return; // Modal is not currently open, do not overwrite in-memory state with blank DOM inputs
  }

  const nodeId = aiWorkbench3State.currentNodeId;
  if (!nodeId) return;

  const prevCtx = aiWorkbench3State.nodeContexts[nodeId] || {};
  const itemNameInput = document.getElementById('wb3InputItemName');
  if (!itemNameInput) return; // Inputs not mounted in DOM

  const itemName = itemNameInput.value.trim() || prevCtx.itemName || '';
  const partNumber = document.getElementById('wb3InputPartNumber')?.value?.trim() || prevCtx.partNumber || '';
  const itemType = document.getElementById('wb3ItemTypeSelect')?.value || prevCtx.itemType || 'Assembly';
  const itemDesc = document.getElementById('wb3InputItemDesc')?.value?.trim() || prevCtx.itemDesc || '';
  const material = document.getElementById('wb3InputMaterial')?.value?.trim() || prevCtx.material || '';
  const gdt = document.getElementById('wb3InputGdt')?.value?.trim() || prevCtx.gdt || '';
  const env = document.getElementById('wb3InputEnvironment')?.value?.trim() || prevCtx.env || '';
  const controlsList = document.getElementById('wb3InputControlsList')?.value?.trim() || prevCtx.controlsList || '';
  const chkReqs = document.getElementById('wb3ChkRequirementsNeeded');
  const requirementsNeeded = (chkReqs && typeof chkReqs.checked === 'boolean') ? chkReqs.checked : (prevCtx.requirementsNeeded || false);
  const chkCat = document.getElementById('wb3ChkCatalogueItem');
  const isCatalogueItem = (chkCat && typeof chkCat.checked === 'boolean') ? chkCat.checked : (prevCtx.isCatalogueItem || false);
  const topReqsEnabled = document.getElementById('wb3ChkTopLevelReqs')?.checked || false;
  const topReqsRaw = topReqsEnabled ? (document.getElementById('wb3Step1TopReqsInput')?.value || '') : (prevCtx.topReqsRaw || '');
  const analysisMode = aiWorkbench3State.analysisMode || prevCtx.analysisMode || 'moderate';

  // Parse top-level requirements: one per line
  const topReqsParsed = topReqsRaw.split('\n').map((l, i) => ({
    tempId: `sys-req-${i + 1}`,
    desc: l.trim(),
    spec: '____'
  })).filter(r => r.desc.length > 0);

  const joints = [];
  document.querySelectorAll('.wb3-joint-chk:checked').forEach(chk => joints.push(chk.value));
  const customJointChars = document.getElementById('wb3CustomJointCharsInput')?.value?.trim() || prevCtx.customJointChars || '';

  const componentTypes = [];
  let customComponentTypes = '';
  const componentFeatures = [];
  let customComponentFeatures = '';

  let componentCharacteristics = [];
  if (itemType === 'Component') {
    document.querySelectorAll('.wb3-comp-type-chk:checked').forEach(chk => componentTypes.push(chk.value));
    customComponentTypes = document.getElementById('wb3CompCustomTypesInput')?.value?.trim() || '';
    document.querySelectorAll('.wb3-comp-feature-chk:checked').forEach(chk => componentFeatures.push(chk.value));
    const customFeatsRaw = (window.wb3ComponentCustomFeatures || []).map(f => typeof f === 'string' ? f : f.name).join(', ');
    customComponentFeatures = customFeatsRaw;
    componentCharacteristics = Array.isArray(window.wb3ComponentSelectedChars) ? [...window.wb3ComponentSelectedChars] : [];
    if (componentCharacteristics.length > 0 && componentTypes.length === 0) {
      componentCharacteristics.forEach(c => { if (!componentTypes.includes(c.name)) componentTypes.push(c.name); });
    }
  }

  const strictFunctionTypes = [];
  document.querySelectorAll('.wb3-root-fn-type-chk:checked').forEach(chk => strictFunctionTypes.push(chk.value));

  const existingSubComps = (aiWorkbench3State.nodeContexts[nodeId] && aiWorkbench3State.nodeContexts[nodeId].subComponents) || [];

  aiWorkbench3State.nodeContexts[nodeId] = {
    itemName, partNumber, itemType, itemDesc, joints,
    customJointChars,
    componentTypes, customComponentTypes,
    componentCharacteristics,
    componentFeatures, customComponentFeatures,
    customComponentFeaturesList: window.wb3ComponentCustomFeatures || [],
    material, gdt, env,
    controlsList, requirementsNeeded,
    topReqsRaw, topReqsParsed,
    analysisMode,
    strictFunctionTypes,
    isCatalogueItem,
    subComponents: existingSubComps
  };
  aiWorkbench3State.requirementsNeeded = requirementsNeeded;
  aiWorkbench3State.controlsListProvided = !!(controlsList.trim());
  aiWorkbench3State.userControlsList = controlsList;
  aiWorkbench3State.topLevelRequirements[nodeId] = topReqsParsed;
  aiWorkbench3State.topLevelReqsProvided = topReqsParsed.length > 0;

  // Seed top-level reqs into nodeRequirements so Step 7 can skip generation for these
  if (topReqsParsed.length > 0) {
    aiWorkbench3State.nodeRequirements[nodeId] = topReqsParsed;
  }

  const ctx = getActiveFmeaData();
  const node = getStructureNodeById(ctx.structure, nodeId);
  if (node && itemName) {
    node.name = itemName;
    if (partNumber) node.partNo = partNumber;
    if (itemDesc) node.desc = itemDesc;
  }
}

function onWb3CatalogueItemChange() {
  const chk = document.getElementById('wb3ChkCatalogueItem');
  const isCat = chk ? chk.checked : false;
  const container = document.getElementById('wb3CataloguePartContainer');
  if (container) {
    container.style.borderColor = isCat ? '#f59e0b' : '#334155';
    container.style.background = isCat ? 'rgba(245, 158, 11, 0.08)' : '#080d1a';
  }
  saveCurrentWb3Inputs();
  renderWb3StructureNavBar();
  if (typeof showToast === 'function') {
    if (isCat) {
      showToast('📖 Element set to Catalogue Selection: AI causes restricted to product specification selection.', 'info');
    } else {
      showToast('🛠️ Element set to Design Responsible: AI causes cover full engineering design.', 'info');
    }
  }
}

function onWb2CatalogueItemChange() {
  const chk = document.getElementById('wb2ChkCatalogueItem');
  const isCat = chk ? chk.checked : false;
  const container = document.getElementById('wb2CataloguePartContainer');
  if (container) {
    container.style.borderColor = isCat ? '#f59e0b' : '#334155';
    container.style.background = isCat ? 'rgba(245, 158, 11, 0.08)' : '#080d1a';
  }
  if (typeof saveCurrentWb2Inputs === 'function') saveCurrentWb2Inputs();
}

function onWb3ItemTypeChange() {
  const select = document.getElementById('wb3ItemTypeSelect');
  const jointBox = document.getElementById('wb3JointSelectionBox');
  const compBox = document.getElementById('wb3ComponentSelectionBox');
  const mixedBox = document.getElementById('wb3MixedComponentsBox');
  if (!select) return;
  const val = select.value;
  if (val === 'Component') {
    if (jointBox) jointBox.style.display = 'none';
    if (compBox) compBox.style.display = 'block';
    if (mixedBox) mixedBox.style.display = 'none';
    document.querySelectorAll('.wb3-joint-chk').forEach(chk => { chk.disabled = true; });
    if (typeof initWb3ComponentCharacteristicsSelector === 'function') {
      const activeCtx = (aiWorkbench3State.currentNodeId && aiWorkbench3State.nodeContexts[aiWorkbench3State.currentNodeId]) || {};
      initWb3ComponentCharacteristicsSelector(activeCtx.componentCharacteristics || window.wb3ComponentSelectedChars || []);
    }
    document.querySelectorAll('.wb3-comp-type-chk').forEach(chk => { chk.disabled = false; });
  } else if (val === 'Mixed') {
    // For Mixed: show only Assembly joints. Component types are configured per component inside the component addition window.
    if (jointBox) jointBox.style.display = 'block';
    if (compBox) compBox.style.display = 'none';
    if (mixedBox) mixedBox.style.display = 'block';
    document.querySelectorAll('.wb3-joint-chk').forEach(chk => { chk.disabled = false; });
    document.querySelectorAll('.wb3-comp-type-chk').forEach(chk => { chk.disabled = true; });
    renderWb3MixedComponentsChips();
  } else {
    // Assembly
    if (jointBox) jointBox.style.display = 'block';
    if (compBox) compBox.style.display = 'none';
    if (mixedBox) mixedBox.style.display = 'none';
    document.querySelectorAll('.wb3-joint-chk').forEach(chk => { chk.disabled = false; });
    document.querySelectorAll('.wb3-comp-type-chk').forEach(chk => { chk.disabled = true; });
  }
  updateWb3JointCharacteristicsPreview();
  updateWb3ComponentCharacteristicsPreview();
}

function toggleWb3ControlsListInput(checked) {
  const box = document.getElementById('wb3ControlsListInputBox');
  if (box) box.style.display = checked ? 'block' : 'none';
}

function toggleWb3TopReqsInput(checked) {
  const box = document.getElementById('wb3TopReqsInputBox');
  if (box) box.style.display = checked ? 'block' : 'none';
  if (!checked) {
    const ta = document.getElementById('wb3Step1TopReqsInput');
    if (ta) ta.value = '';
  }
}

function setWb3AnalysisMode(mode) {
  const validModes = ['basic', 'moderate', 'good', 'excellent'];
  if (!validModes.includes(mode)) mode = 'moderate';
  aiWorkbench3State.analysisMode = mode;

  // Update radio input if in DOM
  const radio = document.querySelector(`input[name="wb3AnalysisModeRadio"][value="${mode}"]`);
  if (radio) radio.checked = true;

  // Update visual card borders & backgrounds
  validModes.forEach(m => {
    const card = document.getElementById(`wb3ModeCard_${m}`);
    if (!card) return;
    if (m === mode) {
      if (m === 'basic') { card.style.borderColor = '#10b981'; card.style.background = 'rgba(16,185,129,0.12)'; }
      else if (m === 'moderate') { card.style.borderColor = '#0284c7'; card.style.background = 'rgba(2,132,199,0.12)'; }
      else if (m === 'good') { card.style.borderColor = '#f59e0b'; card.style.background = 'rgba(245,158,11,0.12)'; }
      else if (m === 'excellent') { card.style.borderColor = '#8b5cf6'; card.style.background = 'rgba(139,92,246,0.15)'; }
    } else {
      card.style.borderColor = '#1e293b';
      card.style.background = '#080d1a';
    }
  });

  // Update badge in step 1 header
  const badge = document.getElementById('wb3AnalysisModeBadge');
  if (badge) {
    if (mode === 'basic') {
      badge.textContent = '🟢 Basic (Core Only, Max 2-3 FMs)';
      badge.style.background = 'rgba(16,185,129,0.15)';
      badge.style.color = '#34d399';
      badge.style.borderColor = '#10b981';
    } else if (mode === 'moderate') {
      badge.textContent = '🟡 Moderate (All Functions, Max 3-4 FMs)';
      badge.style.background = 'rgba(2,132,199,0.15)';
      badge.style.color = '#38bdf8';
      badge.style.borderColor = '#0284c7';
    } else if (mode === 'good') {
      badge.textContent = '🔵 Good (All Functions, Max 5-6 FMs)';
      badge.style.background = 'rgba(245,158,11,0.15)';
      badge.style.color = '#fbbf24';
      badge.style.borderColor = '#f59e0b';
    } else if (mode === 'excellent') {
      badge.textContent = '🟣 Excellent (All Functions, All 7 Types Uncapped)';
      badge.style.background = 'rgba(139,92,246,0.15)';
      badge.style.color = '#c084fc';
      badge.style.borderColor = '#8b5cf6';
    }
  }

  try {
    localStorage.setItem('jost_wb3_analysis_mode', mode);
  } catch (e) { }

  // If currently in step 2, 3, etc., re-render prompt preview so changes take effect immediately
  if (aiWorkbench3State.currentStep === 2) generateWb3Step2Prompt();
  else if (aiWorkbench3State.currentStep === 3) generateWb3Step3Prompt();
  else if (aiWorkbench3State.currentStep === 4) {
    const nodeId = aiWorkbench3State.currentNodeId;
    const ptr = aiWorkbench3State.step4FmPointer[nodeId] || 0;
    const pt = generateWb3Step4FmPromptText(nodeId, ptr);
    const pv = document.getElementById('wb3Step4FmPromptPreview');
    if (pv) pv.value = pt;
  } else if (aiWorkbench3State.currentStep === 5) {
    const nodeId = aiWorkbench3State.currentNodeId;
    const ptr = aiWorkbench3State.step5FmPointer[nodeId] || 0;
    const pt = generateWb3Step5FmPromptText(nodeId, ptr);
    const pv = document.getElementById('wb3Step5FmPromptPreview');
    if (pv) pv.value = pt;
  }
}

function getWb3AnalysisModeDirectives(step) {
  const mode = aiWorkbench3State.analysisMode || 'moderate';
  if (step === 2) {
    if (mode === 'basic') return '\nDEPTH: BASIC — 1-2 core primary functions only. No fillers.\n';
    if (mode === 'moderate') return '\nDEPTH: MODERATE — All genuine Primary, Safety & Structural functions. No fillers.\n';
    if (mode === 'good') return '\nDEPTH: GOOD — All domains: Primary, Safety, Regulatory, Durability, Secondary. Active Verb+Noun, no duplicates.\n';
    return '\nDEPTH: EXCELLENT — Exhaustive: Primary, Safety, Regulatory, Durability, NVH, Diagnostics, Serviceability. Measurable syntax.\n';
  }
  if (step === 3) {
    if (mode === 'basic') return '\nDEPTH: BASIC — Max 2-3 most critical failure modes per function only.\n';
    if (mode === 'moderate') return '\nDEPTH: MODERATE — Max 3-4 prominent failure modes (primary loss & degradation).\n';
    if (mode === 'good') return '\nDEPTH: GOOD — Max 5-6 modes covering loss, degradation, intermittent, exceeding.\n';
    return '\nDEPTH: EXCELLENT — All 7 AIAG-VDA types, all credible modes, no ceiling.\n';
  }
  if (step === 4) {
    if (mode === 'basic') return '\nDEPTH: BASIC — Max 1 effect per tier.\n';
    if (mode === 'moderate') return '\nDEPTH: MODERATE — Max 2-3 distinct effects per tier.\n';
    if (mode === 'good') return '\nDEPTH: GOOD — Max 2-3 effects per tier (operational loss, annoyance, plant rework).\n';
    return '\nDEPTH: EXCELLENT — All credible effects per tier with distinct AIAG-VDA severities.\n';
  }
  if (step === 5) {
    if (mode === 'basic') return '\nDEPTH: BASIC — Max 2-3 primary root causes. No fillers.\n';
    if (mode === 'moderate') return '\nDEPTH: MODERATE — All possible causes . most important one. No fillers.\n';
    if (mode === 'good') return '\nDEPTH: GOOD — All possible causes covering all mechanisum of failures.\n';
    return '\nDEPTH: EXCELLENT — All micro-mechanisms (Kt, fatigue, fretting, clamp relaxation, tolerance stack, corrosion). No clubbing.\n';
  }
  if (step === 6) {
    if (mode === 'basic') return '\nDEPTH: BASIC — 1 PC + 1 DC per cause. include most effective one\n';
    if (mode === 'moderate') return '\nDEPTH: MODERATE — 3-5 PC + 3-5 DC per cause if possible. dont force it.include most effective one\n';
    if (mode === 'good') return '\nDEPTH: GOOD — 3-5 PC + 3-5 DC per cause if possible. dont force it.include most effective one\n';
    return '\nDEPTH: EXCELLENT — Multi-barrier controls (design guidelines, CAE, bench endurance, vehicle durability, accelerated testing).\n';
  }
  return '';
}



function setWb3ExecutionMode(mode) {
  aiWorkbench3State.executionMode = mode;
  const btnManual = document.getElementById('wb3ModeBtnManual');
  const btnApi = document.getElementById('wb3ModeBtnApi');
  const compArea = document.getElementById('wb3CompanionArea');

  if (mode === 'API') {
    if (btnApi) { btnApi.style.background = '#7c3aed'; btnApi.style.color = '#fff'; }
    if (btnManual) { btnManual.style.background = 'transparent'; btnManual.style.color = '#94a3b8'; }
    if (compArea) compArea.style.display = 'none';
    ['Step2', 'Step3'].forEach(step => {
      const manArea = document.getElementById(`wb3${step}ManualArea`);
      const apiArea = document.getElementById(`wb3${step}ApiArea`);
      if (manArea) manArea.style.display = 'none';
      if (apiArea) apiArea.style.display = 'block';
    });
    const s4api = document.getElementById('wb3Step4ApiAllBtn');
    if (s4api) s4api.style.display = 'inline-flex';
    const s5api = document.getElementById('wb3Step5ApiAllBtn');
    if (s5api) s5api.style.display = 'inline-flex';
    const s6api = document.getElementById('wb3Step6ApiAllBtn');
    if (s6api) s6api.style.display = 'inline-flex';
    if (typeof showToast === 'function') {
      showToast('⚡ WB3 Mode: Direct API (Automatic execution)', 'info');
    }
  } else {
    if (btnManual) { btnManual.style.background = '#0284c7'; btnManual.style.color = '#fff'; }
    if (btnApi) { btnApi.style.background = 'transparent'; btnApi.style.color = '#94a3b8'; }
    if (compArea) compArea.style.display = 'inline-flex';
    ['Step2', 'Step3'].forEach(step => {
      const manArea = document.getElementById(`wb3${step}ManualArea`);
      const apiArea = document.getElementById(`wb3${step}ApiArea`);
      if (manArea) manArea.style.display = 'block';
      if (apiArea) apiArea.style.display = 'none';
    });
    const s4api = document.getElementById('wb3Step4ApiAllBtn');
    if (s4api) s4api.style.display = 'none';
    const s5api = document.getElementById('wb3Step5ApiAllBtn');
    if (s5api) s5api.style.display = 'none';
    const s6api = document.getElementById('wb3Step6ApiAllBtn');
    if (s6api) s6api.style.display = 'none';
    if (typeof showToast === 'function') {
      showToast('📋 WB3 Mode: Manual (Chat Companion / Prompts)', 'info');
    }
  }
}

function goToWb3Step(step, force = false) {
  if (!force && aiWorkbench3State.apiInProgress) {
    if (typeof showToast === 'function') showToast('⏳ API call in progress — please wait before navigating.', 'warning');
    return;
  }
  saveCurrentWb3Inputs();
  aiWorkbench3State.currentStep = step;
  if (typeof updateWb3StartFromHereButton === 'function') updateWb3StartFromHereButton();

  for (let i = 1; i <= 8; i++) {
    const badge = document.getElementById(`wb3StepBadge${i}`);
    const line = document.getElementById(`wb3StepLine${i}`);
    const panel = document.getElementById(`wb3Step${i}Panel`);
    if (badge) {
      if (i === step) badge.className = 'stepper-step active';
      else if (i < step) badge.className = 'stepper-step completed';
      else badge.className = 'stepper-step';
    }
    if (line) line.className = (i < step) ? 'stepper-line completed' : 'stepper-line';
    if (panel) panel.style.display = (i === step) ? 'block' : 'none';
  }

  const btnPrev = document.getElementById('wb3BtnPrevStep');
  const btnNext = document.getElementById('wb3BtnNextStep');
  if (btnPrev) btnPrev.style.display = (step > 1) ? 'inline-block' : 'none';

  if (btnNext) {
    if (step === 1) btnNext.innerHTML = 'Next Step: Functions ➡️';
    else if (step === 2) btnNext.innerHTML = 'Next Step: Failure Modes ➡️';
    else if (step === 3) btnNext.innerHTML = 'Next Step: Effects (Micro-Step) ➡️';
    else if (step === 4) btnNext.innerHTML = 'Next Step: Causes (Micro-Step) ➡️';
    else if (step === 5) btnNext.innerHTML = 'Next Step: Controls ➡️';
    else if (step === 6) {
      btnNext.innerHTML = aiWorkbench3State.requirementsNeeded ? 'Next Step: Req Library ➡️' : 'Skip to Ingest ➡️';
    }
    else if (step === 7) btnNext.innerHTML = 'Next Step: Ingest & Review ➡️';
    else if (step === 8) btnNext.innerHTML = '✓ Finish & Commit';
  }

  if (step === 2) {
    generateWb3Step2Prompt();
    renderWb3FunctionsTable();
  } else if (step === 3) {
    generateWb3Step3Prompt();
    renderWb3FailureModesList();
  } else if (step === 4) {
    const nodeId = aiWorkbench3State.currentNodeId;
    if (!aiWorkbench3State.step4FmPointer[nodeId]) aiWorkbench3State.step4FmPointer[nodeId] = 0;
    if (!aiWorkbench3State.updatedEffectsLibrary[nodeId]) {
      const ctx = getActiveFmeaData();
      const masterEffects = (fmeaData && fmeaData.libraries && fmeaData.libraries.effects)
        ? fmeaData.libraries.effects
        : ((ctx.libraries && ctx.libraries.effects) ? ctx.libraries.effects : []);
      aiWorkbench3State.updatedEffectsLibrary[nodeId] = masterEffects.map(e => Object.assign({}, e));
    }
    renderWb3Step4MicroNav();
  } else if (step === 5) {
    const nodeId = aiWorkbench3State.currentNodeId;
    if (!aiWorkbench3State.step5FmPointer[nodeId]) aiWorkbench3State.step5FmPointer[nodeId] = 0;
    renderWb3Step5MicroNav();
  } else if (step === 6) {
    const nodeId = aiWorkbench3State.currentNodeId;
    const saved = aiWorkbench3State.nodeContexts[nodeId] || {};
    if (aiWorkbench3State.controlsListProvided && saved.controlsList) {
      const ctrlNotice = document.getElementById('wb3Step6ControlsListNotice');
      const ctrlAiArea = document.getElementById('wb3Step6AiArea');
      if (ctrlNotice) ctrlNotice.style.display = 'block';
      if (ctrlAiArea) ctrlAiArea.style.display = 'none';
      ingestWb3UserControlsList(nodeId, saved.controlsList);
    } else {
      const ctrlNotice = document.getElementById('wb3Step6ControlsListNotice');
      const ctrlAiArea = document.getElementById('wb3Step6AiArea');
      if (ctrlNotice) ctrlNotice.style.display = 'none';
      if (ctrlAiArea) ctrlAiArea.style.display = 'block';
      if (!aiWorkbench3State.step6FmPointer[nodeId]) aiWorkbench3State.step6FmPointer[nodeId] = 0;
      renderWb3Step6MicroNav();
    }
    renderWb3ControlsList();
  } else if (step === 7) {
    const bypassBox = document.getElementById('wb3Step7BypassNotice');
    const activeBox = document.getElementById('wb3Step7ActiveArea');
    if (!aiWorkbench3State.requirementsNeeded) {
      if (bypassBox) bypassBox.style.display = 'block';
      if (activeBox) activeBox.style.display = 'none';
    } else {
      if (bypassBox) bypassBox.style.display = 'none';
      if (activeBox) activeBox.style.display = 'block';
      generateWb3Step7Prompt();
      renderWb3RequirementsList();
    }
  } else if (step === 8) {
    updateWb3Step8Dashboard();
  }
}

async function nextWb3Step() {
  if (aiWorkbench3State.apiInProgress) {
    if (typeof showToast === 'function') showToast('⏳ API call in progress — please wait before navigating.', 'warning');
    return;
  }
  const cur = aiWorkbench3State.currentStep;
  if (cur === 8) {
    ingestWb3IntoProject();
    return;
  }

  // Pre-Step Verification: Ensure all items for the current step are covered before advancing
  if (cur >= 2 && cur <= 6) {
    const coverage = getWb3StepCoverageStatus(aiWorkbench3State.currentNodeId, cur);
    if (!coverage.isCovered) {
      const proceedWithRemaining = await showCustomConfirm(`⚠️ Step ${cur} Incomplete:\n${coverage.details}\n\nWould you like to complete the remaining items automatically before advancing to Step ${cur === 6 && !aiWorkbench3State.requirementsNeeded ? 8 : cur + 1}?\n\nClick OK to complete remaining items, or Cancel to review.`, 'Step Incomplete', 'warning');
      if (proceedWithRemaining) {
        const completed = await completeWb3RemainingStepItems(aiWorkbench3State.currentNodeId, cur, aiWorkbench3State.executionMode);
        if (!completed) {
          alert(`Could not fully complete Step ${cur}. Please review and complete manually.`);
          return;
        }
      } else {
        return;
      }
    }
  }

  if (cur === 6 && !aiWorkbench3State.requirementsNeeded) {
    goToWb3Step(8);
    return;
  }
  goToWb3Step(cur + 1);
}

function prevWb3Step() {
  if (aiWorkbench3State.apiInProgress) {
    if (typeof showToast === 'function') showToast('⏳ API call in progress — please wait before navigating.', 'warning');
    return;
  }
  const cur = aiWorkbench3State.currentStep;
  if (cur === 8 && !aiWorkbench3State.requirementsNeeded) {
    goToWb3Step(6);
    return;
  }
  if (cur > 1) goToWb3Step(cur - 1);
}

// ══════════════════════════════════════════════════════════════════════════════
// WB3 STEP 2: FUNCTIONS
// ══════════════════════════════════════════════════════════════════════════════

function generateWb3Step2Prompt() {
  const ctx = getActiveFmeaData();
  const nodeId = aiWorkbench3State.currentNodeId;
  const node = (ctx && ctx.structure) ? getStructureNodeById(ctx.structure, nodeId) : null;
  if (!node) return '';
  const isRoot = (ctx && ctx.structure && node && node.id === ctx.structure.id);
  const userCtx = aiWorkbench3State.nodeContexts[nodeId] || {};
  const isCatalogue = !!userCtx.isCatalogueItem;
  const catalogueTag = isCatalogue ? ' [CATALOGUE / OFF-THE-SHELF PART — NOT DESIGN RESPONSIBLE]' : '';
  const catalogueFnRule = isCatalogue ? '\n11. CATALOGUE PART SELECTION: This element is selected from a product catalogue (we are NOT design responsible for internal component design). Formulate functions based on intended application performance, ratings, integration, and interface capabilities.\n' : '';

  const matPart = userCtx.material ? ` | Mat: "${userCtx.material}"` : '';
  const gdtPart = userCtx.gdt ? ` | GDT: "${userCtx.gdt}"` : '';
  const envPart = userCtx.env ? ` | Env: "${userCtx.env}"` : '';
  const ts = Date.now();

  const allFunctionTypesMap = {
    'Primary': '* Primary: Main intended purpose(s). ALL distinct genuine functions; no limit.',
    'Secondary': '* Secondary: Supporting/additional intended function. MAX 1.',
    'Durability': '* Durability: Durability/life requirement. MAX 1.',
    'Regulatory': '* Regulatory: Legal/regulatory requirement. MAX 1.',
    'Appearance': '* Appearance: Appearance requirement. MAX 1.',
    'Manufacturing': '* Manufacturing: Manufacturing requirement. MAX 1.',
    'Assembly': '* Assembly: Assembly requirement. MAX 1.',
    'Packaging': '* Packaging: Packaging requirement. MAX 1.',
    'Safety': '* Safety: Safety requirement. MAX 1.',
    'Traceability': '* Traceability: Identification/traceability requirement. MAX 1.',
    'Service': '* Service: Service/maintenance requirement. MAX 1.',
    'Weight': '* Weight: Mass/weight requirement. MAX 1.',
    'NVH': '* NVH: Noise, vibration, and harshness (acoustic/vibration/harshness) requirement. MAX 1.'
  };

  let compCharsContext = '';
  if (userCtx.itemType === 'Component') {
    const chars = Array.isArray(userCtx.componentCharacteristics) && userCtx.componentCharacteristics.length > 0
      ? userCtx.componentCharacteristics
      : (window.wb3ComponentSelectedChars || []);
    if (chars.length > 0) {
      compCharsContext = `\n\nLINKED COMPONENT CHARACTERISTICS & SPECIFICATIONS:\n` +
        chars.map(c => `• [${c.category || 'Component'}] ${c.name}${c.spec ? ' — Spec: ' + c.spec : ''}`).join('\n') +
        `\nTASK DIRECTIVE: Derive component-level functions addressing each of the linked characteristics and specifications above.\n`;
    }
  }

  let mixedCompContext = '';
  if (userCtx.itemType === 'Mixed') {
    const comps = userCtx.subComponents || [];
    const compListStr = comps.length > 0
      ? comps.map((c, i) => {
        const allChars = Array.isArray(c.componentCharacteristics) && c.componentCharacteristics.length > 0
          ? c.componentCharacteristics.map(ch => ch.name + (ch.spec ? ' (' + ch.spec + ')' : ''))
          : [...(Array.isArray(c.componentTypes) ? c.componentTypes : [])];
        if (c.customTypes) c.customTypes.split(/[,;\n]/).forEach(t => { if (t.trim()) allChars.push(t.trim()); });
        const allFeats = [...(Array.isArray(c.componentFeatures) ? c.componentFeatures : [])];
        if (c.customFeatures) c.customFeatures.split(/[,;\n]/).forEach(f => { if (f.trim()) allFeats.push(f.trim()); });
        const typesTag = allChars.length > 0 ? ` [Characteristics: ${allChars.join(', ')}]` : '';
        const featsTag = allFeats.length > 0 ? ` [Features: ${allFeats.join(', ')}]` : '';
        return `  ${i + 1}. "${c.name}" (${c.partNumber || 'N/A'})${typesTag}${featsTag} — Description: ${c.desc}${c.material ? ' | Mat: ' + c.material : ''}`;
      }).join('\n')
      : '  (No sub-components explicitly defined)';
    const jointsStr = (userCtx.joints && userCtx.joints.length > 0) ? userCtx.joints.join(', ') : 'None specified';
    mixedCompContext = `\n\nMIXED ARCHITECTURE CONTEXT:\nConstituent components under this mixed element:\n${compListStr}\nSelected Joints between components: ${jointsStr}\nTASK DIRECTIVE: Derive functions addressing both the overall mixed assembly integration AND key constituent component roles.\n`;
  }

  let prompt = '';

  if (isRoot) {
    const strictTypes = Array.isArray(userCtx.strictFunctionTypes) ? userCtx.strictFunctionTypes : [];
    const hasStrictTypes = (strictTypes.length > 0 && strictTypes.length < Object.keys(allFunctionTypesMap).length);

    let typesListText = '';
    let strictDirective = '';

    if (hasStrictTypes) {
      typesListText = strictTypes.map(t => allFunctionTypesMap[t] || `* ${t}: Specific requirement. MAX 1.`).join('\n');
      strictDirective = `\n\nSTRICT SCOPE DIRECTIVE:\nThe user has strictly specified that ONLY the following function type(s) shall be considered: ${strictTypes.join(', ')}.\nONLY derive functions for these specified types. Do NOT generate or speculate functions for any omitted types.\n`;
    } else {
      typesListText = Object.values(allFunctionTypesMap).join('\n');
    }

    prompt = `DFMEA Step 2 — Function Analysis (AIAG-VDA 1st Ed.)

ELEMENT: "${userCtx.itemName || node.name}"${catalogueTag} | PN: ${userCtx.partNumber || node.partNo || 'SYS-100'} | Type: ${userCtx.itemType || 'Assembly'} | Desc: "${userCtx.itemDesc || node.desc || userCtx.itemName || node.name}"${matPart}${gdtPart}${envPart}${mixedCompContext}

TASK: Derive ALL genuine, applicable **system-level functions** and assign the correct function type. Do not speculate, add fillers, or create functions solely to populate a type. Omit non-applicable types.${strictDirective}
FUNCTION TYPES:

${typesListText}

RULES:

1. Requirement-specific functions MUST use their corresponding type; never classify Regulatory, Safety, Durability, Appearance, Manufacturing, Assembly, Packaging, Traceability, Service, Weight, or NVH as Primary/Secondary.
2. Primary functions = distinct main intended purposes at system level. Split materially different purposes; do not duplicate, overlap, combine distinct purposes, or create trivial sub-functions.
3. Only include functions genuinely supported by the input. When uncertain, omit.
4. Function name = **Active Verb + measurable/observable Noun**. Keep minimal and function-oriented.
5. Do not include failure modes, causes, effects, design solutions, components, specifications, or implementation details in names.
6. Avoid vague verbs (provide, ensure, handle, support, perform) unless genuinely necessary.
7. \`tempId\` = \`<current_timestamp>-fn-<sequence>\`; same timestamp for all; sequence starts at 1 and increments consecutively.
8. \`parentFunctionId\` = \`""\` unless known.
9. \`existingLibraryId\` = \`""\` unless known.
10. Output JSON only; no explanations, comments, markdown, or text outside JSON.
${catalogueFnRule}
OUTPUT:
{"functions":[{"tempId":"${ts}-fn-1","name":"","type":"","parentFunctionIds":[],"parentFunctionId":"","existingLibraryId":""}]}`;
  } else {
    const parentNode = getParentStructureNode(ctx.structure, nodeId);
    const parentFns = (parentNode && aiWorkbench3State.nodeFunctions[parentNode.id]) || [];
    const parentFnsContext = parentFns.length > 0
      ? `\nPARENT FUNCTIONS TO SUPPORT:\n` + parentFns.map(pf => `- [${pf.tempId}] ${pf.name} (${pf.type})`).join('\n')
      : '';

    prompt = `DFMEA Step 2 — Function Analysis (AIAG-VDA 1st Ed.)

ELEMENT: "${userCtx.itemName || node.name}"${catalogueTag} | PN: ${userCtx.partNumber || node.partNo || 'PN-001'} | Type: ${userCtx.itemType || node.type || 'Component'} | Desc: "${userCtx.itemDesc || node.desc || userCtx.itemName || node.name}"${matPart}${gdtPart}${envPart}${parentFnsContext}${mixedCompContext}${compCharsContext}

TASK: Given the N+1 level parent functions above, identify and derive all applicable N-level (**component-level functions**).

AIAG-VDA STEP 3 FUNCTION NETWORK DEDUPLICATION & MULTI-PARENT LINKAGE DIRECTIVE:
- One component-level function (Level N) CAN support ONE OR MORE N+1 parent functions.
- CRITICAL DEDUPLICATION RULE: DO NOT create duplicate component functions for different parent functions! If a component function supports multiple parent functions, derive that unique component function ONCE only.
- In output JSON, list all supported N+1 parent function tempIds in array: "parentFunctionIds": ["parent_tempId_1", "parent_tempId_2"].
- If a component function does not support any parent function, provide "parentFunctionIds": [].

TASK: Derive ALL genuine, applicable **component-level functions** and assign the correct function type. Do not speculate, add fillers, or create functions solely to populate a type. Omit non-applicable types.

FUNCTION TYPES:

* Primary: Main intended purpose(s). ALL distinct genuine functions; no limit.
* Secondary: Supporting/additional intended function. MAX 1 for this type.
* Durability: Durability/life requirement. MAX 1 for this type.
* Regulatory: Legal/regulatory requirement. MAX 1 for this type.
* Appearance: Appearance requirement. MAX 1 for this type.
* Manufacturing: Manufacturing requirement. MAX 1 for this type.
* Assembly: Assembly requirement. MAX 1 for this type.
* Packaging: Packaging requirement. MAX 1 for this type.
* Safety: Safety requirement. MAX 1 for this type.
* Traceability: Identification/traceability requirement. MAX 1 for this type.
* Service: Service/maintenance requirement. MAX 1 for this type.
* Weight: Mass/weight requirement. MAX 1 for this type.
* NVH: Noise, vibration, and harshness (acoustic/vibration/harshness) requirement. MAX 1 for this type.

RULES:

1. Requirement-specific functions MUST use their corresponding type; never classify Regulatory, Safety, Durability, Appearance, Manufacturing, Assembly, Packaging, Traceability, Service, Weight, or NVH as Primary/Secondary.
2. Primary functions = distinct main intended purposes at component level. Split materially different purposes; do not duplicate, overlap, combine distinct purposes, or create trivial sub-functions.
3. Only include functions genuinely supported by the input. When uncertain, omit.
4. Function name = **Active Verb + measurable/observable Noun**. Keep minimal and function-oriented.
5. Do not include failure modes, causes, effects, design solutions, components, specifications, or implementation details in names.
6. Avoid vague verbs (provide, ensure, handle, support, perform) unless genuinely necessary.
7. \`tempId\` = \`<current_timestamp>-fn-<sequence>\`; same timestamp for all; sequence starts at 1 and increments consecutively.
8. \`parentFunctionId\` = \`""\` unless known.
9. \`existingLibraryId\` = \`""\` unless known.
10. Output JSON only; no explanations, comments, markdown, or text outside JSON.
${catalogueFnRule}
OUTPUT:
{"functions":[{"tempId":"${ts}-fn-1","name":"","type":"","parentFunctionIds":${parentFns[0] ? `["${parentFns[0].tempId}"]` : "[]"},"parentFunctionId":"","existingLibraryId":""}]}`;
  }

  const promptInput = document.getElementById('wb3Step2PromptPreview') || document.getElementById('wb3Step2GeneratedPrompt');
  if (promptInput) promptInput.value = prompt;
  return prompt;
}

function parseWb3Step2Json() {
  const input = document.getElementById('wb3Step2JsonResponseInput');
  if (!input || !input.value.trim()) {
    alert("Please paste the JSON response from your AI first.");
    return;
  }
  try {
    const raw = sanitizeJsonString(input.value);
    const parsed = JSON.parse(raw);
    const fns = parsed.functions || (Array.isArray(parsed) ? parsed : []);
    if (!Array.isArray(fns) || fns.length === 0) {
      alert("No valid functions found in JSON response.");
      return;
    }
    const nodeId = aiWorkbench3State.currentNodeId;
    aiWorkbench3State.nodeFunctions[nodeId] = fns.map((fn, idx) => {
      let pIds = [];
      if (Array.isArray(fn.parentFunctionIds)) {
        pIds = fn.parentFunctionIds.map(x => String(x).trim()).filter(Boolean);
      } else if (typeof fn.parentFunctionIds === 'string' && fn.parentFunctionIds.trim()) {
        pIds = fn.parentFunctionIds.split(/[,;]/).map(x => x.trim()).filter(Boolean);
      } else if (fn.parentFunctionId) {
        pIds = [String(fn.parentFunctionId).trim()];
      }
      return {
        tempId: fn.tempId || fn.id || `fn-temp-${idx + 1}`,
        name: fn.name || 'Unnamed Function',
        type: typeof normalizeWb2FunctionType === 'function' ? normalizeWb2FunctionType(fn.type) : (fn.type || 'Primary function'),
        parentFunctionIds: pIds,
        parentFunctionId: pIds[0] || '',
        existingLibraryId: fn.existingLibraryId || ''
      };
    });
    renderWb3FunctionsTable();
    if (typeof showToast === 'function') showToast(`📥 Loaded ${fns.length} functions!`, 'success');
  } catch (err) {
    alert("JSON Parsing Error: " + err.message);
  }
}

function renderWb3FunctionsTable() {
  const nodeId = aiWorkbench3State.currentNodeId;
  const tbody = document.getElementById('wb3FunctionsTableBody');
  const countEl = document.getElementById('wb3FunctionsCount');
  if (!tbody) return;
  const fns = aiWorkbench3State.nodeFunctions[nodeId] || [];
  if (countEl) countEl.textContent = fns.length;
  if (fns.length === 0) {
    tbody.innerHTML = '<tr><td colspan="4" style="text-align:center; padding:18px; color:#64748b;">No functions generated yet.</td></tr>';
    return;
  }
  const typeColors = { 'Primary function': '#0284c7', 'Safety function': '#ef4444', 'Regulatory function': '#f59e0b', 'Secondary function': '#8b5cf6', 'Secondary / Convenience': '#8b5cf6', 'Durability function': '#10b981', 'Durability / Structural': '#10b981', 'Appearance function': '#ec4899', 'Manufacturing function': '#f97316', 'Assembly function': '#eab308', 'Packaging function': '#a855f7', 'Traceability function': '#06b6d4', 'Service function': '#14b8a6', 'Weight function': '#64748b', 'NVH function': '#818cf8', 'NVH': '#818cf8' };
  tbody.innerHTML = fns.map((fn, idx) => {
    const normType = typeof normalizeWb2FunctionType === 'function' ? normalizeWb2FunctionType(fn.type) : fn.type;
    const tc = typeColors[normType] || '#64748b';
    return `<tr style="border-bottom:1px solid #1e293b;">
      <td style="padding:6px 8px; color:#cbd5e1; font-weight:600; font-size:11px;">${escapeHtml(fn.name)}</td>
      <td style="padding:6px 8px;"><span style="font-size:10px; font-weight:700; color:${tc}; background:${tc}22; padding:1px 6px; border-radius:3px;">${escapeHtml(normType || 'Primary')}</span></td>
      <td style="padding:6px 8px; font-size:10px; color:#64748b;">${escapeHtml(fn.parentFunctionId || '—')}</td>
      <td style="padding:6px 8px; text-align:center;"><button class="btn btn-sm" onclick="deleteWb3Function(${idx})" style="padding:1px 6px; font-size:10px; color:#ef4444; background:transparent; border:1px solid #ef4444;">✕</button></td>
    </tr>`;
  }).join('');
}

async function deleteWb3Function(idx) {
  const nodeId = aiWorkbench3State.currentNodeId;
  const f = aiWorkbench3State.nodeFunctions[nodeId] ? aiWorkbench3State.nodeFunctions[nodeId][idx] : null;
  const fName = f ? f.name : 'Function';
  const isConfirmed = await showCustomConfirm(`Are you sure you want to delete function "${fName}"?`, 'Delete Function', 'warning');
  if (!isConfirmed) return;
  if (aiWorkbench3State.nodeFunctions[nodeId]) {
    aiWorkbench3State.nodeFunctions[nodeId].splice(idx, 1);
    renderWb3FunctionsTable();
  }
}

