function copyWb3StepPrompt(step) {
  let prompt = '';
  if (step === 2) prompt = generateWb3Step2Prompt();
  else if (step === 3) prompt = generateWb3Step3Prompt();
  else if (step === 7) prompt = generateWb3Step7Prompt();

  if (prompt) {
    navigator.clipboard.writeText(prompt).then(() => {
      if (typeof showToast === 'function') showToast(`📋 Copied Step ${step} prompt!`, 'success');
    });
  }
}

