let wb3CompanionListenersSetUp = false;

function playWb3CompletionChime() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(523.25, now); // C5
    osc.frequency.setValueAtTime(659.25, now + 0.15); // E5
    osc.frequency.setValueAtTime(783.99, now + 0.30); // G5
    osc.frequency.setValueAtTime(1046.50, now + 0.45); // C6
    gain.gain.setValueAtTime(0.18, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.85);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.85);
  } catch (e) { }
}

function openWb3ChatCompanion(targetUrl = null) {
  const url = targetUrl || getWb3CompanionUrl();
  if (window.electronAPI && typeof window.electronAPI.openChatCompanion === 'function') {
    window.electronAPI.openChatCompanion(url);
    setupWb3CompanionListeners();
    if (typeof showToast === 'function') showToast("🤖 Opened AI Chat Companion. Log in once and keep it open!", "info");
  } else {
    window.open(url, '_blank', 'width=780,height=900');
    if (typeof showToast === 'function') showToast("Opened ChatGPT in new window. For full automated DOM injection, run the JOST Desktop App.", "info");
  }
}

function setupWb3CompanionListeners() {
  if (wb3CompanionListenersSetUp || !window.electronAPI) return;
  wb3CompanionListenersSetUp = true;
  if (window.electronAPI.onChatCompanionStatus) {
    window.electronAPI.onChatCompanionStatus((data) => {
      const badge = document.getElementById('wb3CompanionBtnText');
      if (badge && data && data.state) {
        if (data.state === 'generating') badge.textContent = 'Typing...';
        else if (data.state === 'completed') badge.textContent = 'Ready';
        else if (data.state === 'ready') badge.textContent = 'Ready';
        else badge.textContent = 'AI Companion';
      }
    });
  }
}


