const MASTER_LIBRARY_FILE_NAME = 'fmea_master_library.enc';

function ensureMasterLibraryData() {
  if (!fmeaData) return;
  if (!fmeaData.libraries) fmeaData.libraries = {};
  if (!fmeaData.libraries.masterTable || !Array.isArray(fmeaData.libraries.masterTable) || fmeaData.libraries.masterTable.length === 0) {
    fmeaData.libraries.masterTable = getInitialMasterLibraryTable();
  }
}

async function checkAndInitMasterLibrary() {
  const isElectron = window.electronAPI && window.electronAPI.isElectron;
  if (!fmeaData.libraries) fmeaData.libraries = {};

  if (isElectron && window.electronAPI.readFileContent) {
    try {
      const baseDir = getEffectiveSharePointPath();
      const sep = (baseDir.includes('/') && !baseDir.includes('\\')) ? '/' : '\\';
      const filePath = (baseDir.endsWith('\\') || baseDir.endsWith('/')) ? `${baseDir}${MASTER_LIBRARY_FILE_NAME}` : `${baseDir}${sep}${MASTER_LIBRARY_FILE_NAME}`;

      let readRes = await window.electronAPI.readFileContent(filePath);
      if (!readRes || !readRes.success) {
        const localPath = `d:\\Jost\\${MASTER_LIBRARY_FILE_NAME}`;
        readRes = await window.electronAPI.readFileContent(localPath);
      }
      if (!readRes || !readRes.success) {
        // Auto-migration fallback from master_engineering_controls_library.json if present
        const jsonPath = `d:\\Jost\\master_engineering_controls_library.json`;
        readRes = await window.electronAPI.readFileContent(jsonPath);
      }

      if (readRes && readRes.success && readRes.content) {
        const decrypted = decryptDataPayload(readRes.content);
        if (Array.isArray(decrypted) && decrypted.length > 0) {
          fmeaData.libraries.masterTable = decrypted;
          return fmeaData.libraries.masterTable;
        }
      }
    } catch (err) {
      console.warn("Error loading master library from disk:", err);
    }
  }

  ensureMasterLibraryData();
  return fmeaData.libraries.masterTable;
}

async function saveMasterLibraryToDisk() {
  const isElectron = window.electronAPI && window.electronAPI.isElectron;
  ensureMasterLibraryData();
  const rows = fmeaData.libraries.masterTable;
  const encryptedContent = encryptDataPayload(rows, LIB_MAGIC_HEADER);

  if (isElectron && window.electronAPI.writeFile && encryptedContent) {
    try {
      const baseDir = getEffectiveSharePointPath();
      const sep = (baseDir.includes('/') && !baseDir.includes('\\')) ? '/' : '\\';
      const filePath = (baseDir.endsWith('\\') || baseDir.endsWith('/')) ? `${baseDir}${MASTER_LIBRARY_FILE_NAME}` : `${baseDir}${sep}${MASTER_LIBRARY_FILE_NAME}`;
      await window.electronAPI.writeFile(filePath, encryptedContent);

      const localPath = `d:\\Jost\\${MASTER_LIBRARY_FILE_NAME}`;
      if (localPath.toLowerCase() !== filePath.toLowerCase()) {
        try { await window.electronAPI.writeFile(localPath, encryptedContent); } catch (e) { }
      }
      return true;
    } catch (err) {
      console.warn("Failed to write fmea_master_library.enc:", err);
    }
  }
  return false;
}

