function renderMasterLibraryTable(rowsToRender = null) {
  ensureMasterLibraryData();
  const rows = rowsToRender || fmeaData.libraries.masterTable;
  const tbody = document.getElementById('masterLibraryTableBody');
  if (!tbody) return;

  if (!rows || rows.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="5" style="padding: 30px; text-align: center; color: var(--text-muted);">
          <span style="font-size: 24px;">📭</span><br>
          No library entries found. Click <strong>+ Add Library Row</strong> or <strong>Import Library (JSON)</strong> to add entries.
        </td>
      </tr>
    `;
    return;
  }

  tbody.innerHTML = rows.map(row => {
    return `
      <tr style="border-bottom: 1px solid var(--border-color); background: transparent; transition: background 0.15s;">
        <td style="padding: 10px 12px; font-weight: 700; color: var(--accent-color);">
          ${escapeHtml(row.system || '-')}
        </td>
        <td style="padding: 10px 12px; color: var(--text-primary);">
          ${escapeHtml(row.function || '-')}
        </td>
        <td style="padding: 10px 12px; color: var(--text-secondary);">
          ${escapeHtml(row.requirement || '-')}
        </td>
        <td style="padding: 10px 12px; color: var(--risk-high-text); font-weight: 600;">
          💥 ${escapeHtml(row.failure || '-')}
        </td>
        <td style="padding: 10px 12px; text-align: center; white-space: nowrap;">
          <button class="btn btn-sm btn-outline" style="padding: 2px 6px; font-size: 11px;" onclick="editMasterLibraryRow('${row.id}')" title="Edit Entry">✏️</button>
          <button class="btn btn-sm" style="background: var(--risk-high-bg); color: var(--risk-high-text); border: 1px solid var(--risk-high-border); padding: 2px 6px; font-size: 11px; margin-left: 4px;" onclick="deleteMasterLibraryRow('${row.id}')" title="Delete Entry">🗑️</button>
        </td>
      </tr>
    `;
  }).join('');
}

function filterMasterLibraryTable() {
  ensureMasterLibraryData();
  const search = (document.getElementById('masterLibSearchInput')?.value || '').trim().toLowerCase();
  if (!search) {
    renderMasterLibraryTable();
    return;
  }

  const filtered = fmeaData.libraries.masterTable.filter(row =>
    (row.system && row.system.toLowerCase().includes(search)) ||
    (row.function && row.function.toLowerCase().includes(search)) ||
    (row.requirement && row.requirement.toLowerCase().includes(search)) ||
    (row.failure && row.failure.toLowerCase().includes(search))
  );

  renderMasterLibraryTable(filtered);
}

