window.toggleFocusBelowChain = toggleFocusBelowChain;

function toggleExpandAllAbove() {
  if (activeFailureNetworkState.isAboveCollapsed) {
    activeFailureNetworkState.isAboveCollapsed = false;
  }
  activeFailureNetworkState.isAllAboveExpanded = !activeFailureNetworkState.isAllAboveExpanded;
  if (!activeFailureNetworkState.isAllAboveExpanded) {
    if (activeFailureNetworkState.expandedAboveNodeIds) activeFailureNetworkState.expandedAboveNodeIds.clear();
  } else if (activeFailureNetworkState.rawGraph) {
    if (!activeFailureNetworkState.expandedAboveNodeIds) activeFailureNetworkState.expandedAboveNodeIds = new Set();
    activeFailureNetworkState.rawGraph.nodes.forEach(n => {
      if (n.levelIndex > 0) activeFailureNetworkState.expandedAboveNodeIds.add(String(n.id));
    });
  }
  updateExpandAllButtonsUI();
  activeFailureNetworkState.graph = getFilteredFailureNetworkGraph();
  renderFailureNetworkDiagram();
  setTimeout(() => { if (typeof fitFailureNetworkView === 'function') fitFailureNetworkView(); }, 50);
}
