function parseAndNormalizeAiStructure(raw) {
  if (!raw || !raw.trim()) throw new Error('Input is empty.');

  const sanitized = (typeof sanitizeJsonString === 'function')
    ? sanitizeJsonString(raw)
    : raw.replace(/^\s*```json/i, '').replace(/^\s*```/i, '').replace(/```\s*$/i, '').trim();

  let parsed = JSON.parse(sanitized);

  let root = null;
  let projectName = parsed.projectName || parsed.name || 'AI Generated FMEA Study';

  if (parsed.structure && typeof parsed.structure === 'object') {
    root = parsed.structure;
  } else if (parsed.root && typeof parsed.root === 'object') {
    root = parsed.root;
  } else if (parsed.system && typeof parsed.system === 'object') {
    root = parsed.system;
  } else if (Array.isArray(parsed)) {
    const nodeMap = {};
    parsed.forEach((n, idx) => {
      const nid = String(n.id || n.structId || ('node-' + idx));
      nodeMap[nid] = Object.assign({}, n, { id: nid, children: Array.isArray(n.children) ? n.children.slice() : [] });
    });
    let topRoot = null;
    parsed.forEach((n, idx) => {
      const nid = String(n.id || n.structId || ('node-' + idx));
      const pid = n.parentId ? String(n.parentId) : null;
      if (pid && nodeMap[pid]) {
        if (!nodeMap[pid].children) nodeMap[pid].children = [];
        nodeMap[pid].children.push(nodeMap[nid]);
      } else if (!topRoot) {
        topRoot = nodeMap[nid];
      }
    });
    root = topRoot || nodeMap[Object.keys(nodeMap)[0]];
  } else if (parsed.name && (parsed.children || parsed.type || parsed.desc)) {
    root = parsed;
  }

  if (!root || typeof root !== 'object') {
    throw new Error('Could not detect a valid structure root element in JSON.');
  }

  // Normalize recursive tree
  let idCounter = 1;
  const flatNodes = [];
  let stats = { systems: 0, subsystems: 0, components: 0, catalogueItems: 0 };

  function normalizeNode(node, depth = 0, parentId = null) {
    if (!node || typeof node !== 'object') return null;
    const isRoot = (depth === 0);
    const hasChildren = Array.isArray(node.children) && node.children.length > 0;

    let cleanId = String(node.id || node.structId || (isRoot ? 'sys-1' : (hasChildren ? ('sub-' + idCounter) : ('comp-' + idCounter))));
    idCounter++;

    let defaultType = isRoot ? 'Assembly' : (hasChildren ? 'Assembly' : 'Component');
    let cleanType = node.type || node.itemType || defaultType;
    if (cleanType.toLowerCase().includes('system') || cleanType.toLowerCase().includes('assembly')) {
      cleanType = 'Assembly';
    } else {
      cleanType = 'Component';
    }

    const isCat = !!(node.isCatalogueItem || node.isCatalogue || node.catalogue || node.offTheShelf);

    if (isRoot) stats.systems++;
    else if (cleanType === 'Assembly') stats.subsystems++;
    else stats.components++;

    if (isCat) stats.catalogueItems++;

    const norm = {
      id: cleanId,
      parentId: parentId,
      name: String(node.name || node.itemName || node.title || (isRoot ? 'System' : 'Component')).trim(),
      partNo: String(node.partNo || node.partNumber || node.pn || `PN-${cleanId}`).trim(),
      type: cleanType,
      desc: String(node.desc || node.description || node.itemDesc || '').trim(),
      material: String(node.material || node.mat || '').trim(),
      gdt: String(node.gdt || node.tolerances || '').trim(),
      env: String(node.env || node.environment || '').trim(),
      joints: Array.isArray(node.joints) ? node.joints : [],
      isCatalogueItem: isCat,
      children: []
    };

    flatNodes.push(norm);

    if (Array.isArray(node.children)) {
      node.children.forEach(child => {
        const childNorm = normalizeNode(child, depth + 1, cleanId);
        if (childNorm) norm.children.push(childNorm);
      });
    }

    return norm;
  }

  const normalizedRoot = normalizeNode(root, 0, null);
  return { root: normalizedRoot, flatNodes, stats, projectName };
}

function previewAiStructureJson() {
  const jsonInput = document.getElementById('aiStructJsonResponseInput');
  const preview = document.getElementById('aiStructPreviewContainer');
  const statusBadge = document.getElementById('aiStructParseStatusBadge');
  const ingestBtn = document.getElementById('btnIngestAiStructure');

  if (!jsonInput || !jsonInput.value.trim()) {
    if (statusBadge) { statusBadge.textContent = 'No input'; statusBadge.style.color = '#94a3b8'; }
    if (ingestBtn) { ingestBtn.disabled = true; ingestBtn.style.opacity = '0.5'; ingestBtn.style.cursor = 'not-allowed'; }
    return;
  }

  try {
    const res = parseAndNormalizeAiStructure(jsonInput.value);
    parsedAiStructureCache = res;

    if (statusBadge) {
      statusBadge.innerHTML = `✅ Valid: ${res.flatNodes.length} nodes (${res.stats.subsystems} subs, ${res.stats.components} comps, ${res.stats.catalogueItems} catalogue)`;
      statusBadge.style.color = '#34d399';
    }

    if (preview) {
      function renderNodePreviewHtml(node, depth = 0) {
        const isRoot = (depth === 0);
        const indent = depth * 18;
        const typeBadge = node.type === 'Assembly'
          ? '<span style="font-size:9.5px; padding:1px 5px; border-radius:3px; background:#1e3a8a; color:#93c5fd; font-weight:700;">Assembly</span>'
          : '<span style="font-size:9.5px; padding:1px 5px; border-radius:3px; background:#4c1d95; color:#c4b5fd; font-weight:700;">Component</span>';

        const catBadge = node.isCatalogueItem
          ? '<span style="font-size:9.5px; padding:1px 5px; border-radius:3px; background:rgba(245,158,11,0.18); color:#fde68a; border:1px solid #f59e0b; font-weight:700;">📖 Catalogue Part</span>'
          : '<span style="font-size:9.5px; padding:1px 5px; border-radius:3px; background:rgba(16,185,129,0.15); color:#a7f3d0; font-weight:600;">🛠️ Design Resp.</span>';

        const descSnippet = node.desc ? `<div style="font-size:10px; color:#94a3b8; margin-top:2px; line-height:1.35; padding-left:20px;">${escapeHtml(node.desc)}</div>` : '';
        const matSnippet = node.material ? `<div style="font-size:9.5px; color:#64748b; margin-top:1px; padding-left:20px;"><strong>Mat:</strong> ${escapeHtml(node.material)} ${node.gdt ? '| <strong>GD&T:</strong> ' + escapeHtml(node.gdt) : ''}</div>` : '';

        const childrenHtml = (node.children && node.children.length > 0)
          ? node.children.map(c => renderNodePreviewHtml(c, depth + 1)).join('')
          : '';

        return `
          <div style="margin-left:${indent}px; margin-bottom:6px; background:${isRoot ? '#0f172a' : '#080d1a'}; border:1px solid ${isRoot ? '#0284c7' : '#1e293b'}; border-radius:6px; padding:6px 8px;">
            <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:4px;">
              <div style="display:flex; align-items:center; gap:6px;">
                <span>${isRoot ? '🚗' : (node.type === 'Assembly' ? '📦' : '⚙️')}</span>
                <span style="font-weight:700; color:#f8fafc; font-size:11.5px;">${escapeHtml(node.name)}</span>
                <span style="font-family:monospace; color:#38bdf8; font-size:10.5px;">[${escapeHtml(node.partNo)}]</span>
              </div>
              <div style="display:flex; align-items:center; gap:6px;">
                ${typeBadge}
                ${catBadge}
              </div>
            </div>
            ${descSnippet}
            ${matSnippet}
          </div>
          ${childrenHtml}
        `;
      }

      preview.innerHTML = renderNodePreviewHtml(res.root, 0);
    }

    if (ingestBtn) {
      ingestBtn.disabled = false;
      ingestBtn.style.opacity = '1';
      ingestBtn.style.cursor = 'pointer';
    }
  } catch (err) {
    parsedAiStructureCache = null;
    if (statusBadge) {
      statusBadge.textContent = '❌ JSON Error: ' + err.message;
      statusBadge.style.color = '#f87171';
    }
    if (ingestBtn) {
      ingestBtn.disabled = true;
      ingestBtn.style.opacity = '0.5';
      ingestBtn.style.cursor = 'not-allowed';
    }
  }
}

async function ingestAiStructureIntoProject(overrideStructure) {
  const cache = overrideStructure || parsedAiStructureCache;
  if (!cache || !cache.root) {
    alert('Please paste and validate a valid structure JSON first.');
    return;
  }

  const { root, flatNodes, projectName } = cache;

  const count = flatNodes.length;
  const isConfirmed = await showCustomConfirm(`📥 Ingest AI Structure Hierarchy into FMEA project?\n\nTotal Elements: ${count}\nRoot System: "${root.name}"\n\nThis will load the new hierarchy into your FMEA project tree and pre-load all engineering descriptions & catalogue part flags directly into AI Workbench 3.0.\n\nProceed?`, 'Ingest AI Structure', 'info');
  if (!isConfirmed) {
    return;
  }

  // 1. Update Project Info
  if (fmeaData) {
    if (!fmeaData.projectInfo) fmeaData.projectInfo = {};
    if (projectName && (!fmeaData.projectInfo.name || fmeaData.projectInfo.name === 'Imported FMEA Project' || fmeaData.projectInfo.name.startsWith('DFMEA-'))) {
      fmeaData.projectInfo.name = projectName;
    }

    // 2. Set new structure
    fmeaData.structure = root;
    if (typeof getFlatStructureNodes === 'function') {
      fmeaData.structureTree = getFlatStructureNodes(root);
    } else {
      fmeaData.structureTree = flatNodes;
    }
  }

  // 3. Pre-load node contexts into AI Workbench 3.0 for all elements
  if (typeof aiWorkbench3State !== 'undefined') {
    if (!aiWorkbench3State.nodeContexts) aiWorkbench3State.nodeContexts = {};

    flatNodes.forEach(item => {
      aiWorkbench3State.nodeContexts[item.id] = {
        itemName: item.name,
        partNumber: item.partNo || item.partNumber || `PN-${item.id}`,
        itemType: item.type || (item.children && item.children.length ? 'Assembly' : 'Component'),
        itemDesc: item.desc || item.description || '',
        material: item.material || '',
        gdt: item.gdt || '',
        env: item.env || '',
        joints: Array.isArray(item.joints) ? item.joints : [],
        isCatalogueItem: !!item.isCatalogueItem,
        controlsList: '',
        requirementsNeeded: false
      };
    });

    // Point active node to root
    aiWorkbench3State.currentNodeId = root.id;
  }

  // Set focused node
  selectedStructureId = root.id;
  const focusedNodeLabel = document.getElementById('focusedNodeName');
  if (focusedNodeLabel) {
    focusedNodeLabel.textContent = `${root.partNo ? root.partNo + ' - ' : ''}${root.name}`;
  }

  // 4. Render all UI Views
  if (typeof renderTreeSidebar === 'function') renderTreeSidebar();
  if (typeof renderFMEATable === 'function') renderFMEATable();
  if (typeof updateHeaderRevisionBadge === 'function') updateHeaderRevisionBadge();
  if (typeof performAutoSave === 'function') performAutoSave('AI Structure Tree Import');

  closeModal('aiStructureImportModal');

  const preloadWb3 = document.getElementById('aiStructPreloadWb3Chk')?.checked !== false;

  if (typeof showCustomAlert === 'function') {
    showCustomAlert(
      `🎉 Structure Hierarchy with ${count} elements imported successfully into FMEA!\n\nEvery element has been pre-configured with rich descriptions, part numbers, and catalogue part flags ready for AI Workbench 3.0.\n\nClick 'Open AI Workbench 3.0' below to review settings and run your automated DFMEA analysis.`,
      'Structure Imported Successfully',
      'success',
      () => {
        if (typeof openAiWorkbench3Modal === 'function') {
          openAiWorkbench3Modal(root.id);
        }
      },
      '🚀 Open AI Workbench 3.0'
    );
  } else if (typeof showToast === 'function') {
    showToast(`🎉 Ingested ${count} structure elements into FMEA! Ready for Workbench 3.0.`, 'success');
    const shouldOpenWb3 = preloadWb3 ? (await showCustomConfirm('Structure imported successfully! Open AI Workbench 3.0 now?', 'Open Workbench 3.0', 'info')) : false;
    if (shouldOpenWb3) {
      if (typeof openAiWorkbench3Modal === 'function') openAiWorkbench3Modal(root.id);
    }
  } else {
    alert(`Structure hierarchy with ${count} elements imported successfully!`);
  }
}

