// ══════════════════════════════════════════════════════════════════════════
// INTERACTIVE FAILURE NETWORK ELEMENT LINKING (EFFECT & CAUSE SIDES)
// ══════════════════════════════════════════════════════════════════════════

window.activeFnLinkState = null;

/**
 * Refreshes the Failure Network Diagram if the modal is currently open.
 */
function refreshActiveFailureNetworkIfOpen() {
  const fnModal = document.getElementById('failureNetworkModal');
  if (!fnModal || fnModal.style.display === 'none') return;
  if (!activeFailureNetworkState.focusTarget && !activeFailureNetworkState.focusFmId && !activeFailureNetworkState.focusFuncId) return;

  const currentInspected = activeFailureNetworkState.inspectedNodeId;
  if (activeFailureNetworkState.chainType === 'FUNCTION_REQ') {
    const target = activeFailureNetworkState.focusTarget || activeFailureNetworkState.focusFuncId;
    if (typeof openFunctionNetworkModal === 'function') {
      openFunctionNetworkModal(target, null, true, true);
    }
  } else {
    const target = activeFailureNetworkState.focusTarget || activeFailureNetworkState.focusFmId;
    openFailureNetworkModal(target, null, true, true);
  }
  if (currentInspected) {
    setTimeout(() => { inspectFailureNetworkNode(currentInspected); }, 60);
  }
}
window.refreshActiveFailureNetworkIfOpen = refreshActiveFailureNetworkIfOpen;

/**
 * Opens the interactive linking popup modal for linking Effects or Causes
 * directly from the Failure Network Diagram.
 * @param {string} fmId Target Failure Mode ID
 * @param {'EFFECT'|'CAUSE'} type Whether linking an Effect or Cause
 */
function openFailureNetLinkModal(fmId, type) {
  if (!fmId) return;

  const ctx = (typeof getActiveFmeaData === 'function') ? getActiveFmeaData() : fmeaData;
  const isPfmea = !!(ctx && ctx.isPFMEA);

  // 1. Resolve Failure Mode Name & Object
  const allModes = (typeof getAllProjectFailureModesWithContext === 'function') ? getAllProjectFailureModesWithContext() : [];
  let fmObj = allModes.find(m => String(m.fm.id) === String(fmId));
  if (!fmObj && typeof findFailureModeObjById === 'function') {
    fmObj = findFailureModeObjById(fmId);
  }
  let fmName = fmObj?.fm?.name;
  if (!fmName && activeFailureNetworkState.graph && activeFailureNetworkState.graph.nodes) {
    const matchedNode = activeFailureNetworkState.graph.nodes.find(n => n.id === fmId || n.fmId === fmId);
    if (matchedNode) fmName = matchedNode.label;
  }
  if (!fmName) fmName = `Failure Mode (${fmId})`;

  // 2. Resolve Currently Linked Element IDs
  const currentLinked = new Set();
  if (type === 'EFFECT') {
    if (ctx.failureModeEffects && Array.isArray(ctx.failureModeEffects[fmId])) {
      ctx.failureModeEffects[fmId].forEach(id => currentLinked.add(String(id)));
    }
    if (fmeaData.failureModeEffects && Array.isArray(fmeaData.failureModeEffects[fmId])) {
      fmeaData.failureModeEffects[fmId].forEach(id => currentLinked.add(String(id)));
    }
    if (ctx.pfmea?.failureModeEffects && Array.isArray(ctx.pfmea.failureModeEffects[fmId])) {
      ctx.pfmea.failureModeEffects[fmId].forEach(id => currentLinked.add(String(id)));
    }
    if (typeof getAllProjectEffectsForFm === 'function') {
      try {
        const effs = getAllProjectEffectsForFm(fmId, fmObj);
        effs.forEach(e => { if (e && e.id) currentLinked.add(String(e.id)); });
      } catch (err) { }
    }
  } else {
    // CAUSE
    if (ctx.failureModeCauses && Array.isArray(ctx.failureModeCauses[fmId])) {
      ctx.failureModeCauses[fmId].forEach(id => currentLinked.add(String(id)));
    }
    if (fmeaData.failureModeCauses && Array.isArray(fmeaData.failureModeCauses[fmId])) {
      fmeaData.failureModeCauses[fmId].forEach(id => currentLinked.add(String(id)));
    }
    if (ctx.pfmea?.failureModeCauses && Array.isArray(ctx.pfmea.failureModeCauses[fmId])) {
      ctx.pfmea.failureModeCauses[fmId].forEach(id => currentLinked.add(String(id)));
    }
    if (typeof getAllProjectCausesForFm === 'function') {
      try {
        const causes = getAllProjectCausesForFm(fmId, fmObj);
        causes.forEach(c => { if (c && c.id) currentLinked.add(String(c.id)); });
      } catch (err) { }
    }
  }

  // 3. Collect Candidate Items from Libraries & Project Scopes
  const allItems = [];
  const seenIds = new Set();

  if (type === 'EFFECT') {
    function addCandidateEffect(e, origin) {
      if (!e || !e.id) return;
      const idStr = String(e.id);
      if (seenIds.has(idStr)) return;
      const text = (e.desc || e.name || e.description || e.details || e.effectText || '').trim();
      if (!text || text === '-' || text.toLowerCase().includes('(click to edit)')) return;

      seenIds.add(idStr);
      allItems.push({
        id: idStr,
        label: text,
        severity: parseInt(e.severity || e.sev || 7, 10),
        origin: origin || e.origin || (isPfmea ? 'PFMEA' : 'DFMEA'),
        systemName: e.systemName || e.scope || ''
      });
    }

    (fmeaData.libraries?.effects || []).forEach(e => addCandidateEffect(e, 'Library'));
    if (ctx.pfmea?.libraries?.effects) {
      ctx.pfmea.libraries.effects.forEach(e => addCandidateEffect(e, 'PFMEA'));
    }
    if (typeof getAllProjectScopes === 'function') {
      getAllProjectScopes().forEach(s => {
        (s.libraries?.effects || []).forEach(e => addCandidateEffect(e, s.isPFMEA ? 'PFMEA' : 'DFMEA'));
      });
    }
    if (typeof getAllProjectEffectsForFm === 'function') {
      try {
        const existingEffs = getAllProjectEffectsForFm(fmId, fmObj);
        existingEffs.forEach(e => addCandidateEffect(e, e.origin || 'Linked'));
      } catch (err) { }
    }
  } else {
    // CAUSE
    function addCandidateCause(c, origin) {
      if (!c || !c.id) return;
      const idStr = String(c.id);
      if (seenIds.has(idStr)) return;
      const text = (c.details || c.desc || c.description || c.name || c.causeText || '').trim();
      if (!text || text === '-' || text.toLowerCase().includes('(click to edit)')) return;

      seenIds.add(idStr);
      allItems.push({
        id: idStr,
        label: text,
        occurrence: parseInt(c.occurrence || c.occ || 4, 10),
        detection: parseInt(c.detection || c.det || 3, 10),
        ap: c.ap || '-',
        origin: origin || c.origin || (isPfmea ? 'PFMEA' : 'DFMEA'),
        systemElement: c.systemElement || ''
      });
    }

    (fmeaData.libraries?.causes || []).forEach(c => addCandidateCause(c, 'Library'));
    if (ctx.pfmea?.libraries?.causes) {
      ctx.pfmea.libraries.causes.forEach(c => addCandidateCause(c, 'PFMEA'));
    }
    if (typeof getAllProjectScopes === 'function') {
      getAllProjectScopes().forEach(s => {
        (s.libraries?.causes || []).forEach(c => addCandidateCause(c, s.isPFMEA ? 'PFMEA' : 'DFMEA'));
      });
    }
    if (typeof getAllProjectCausesForFm === 'function') {
      try {
        const existingCauses = getAllProjectCausesForFm(fmId, fmObj);
        existingCauses.forEach(c => addCandidateCause(c, c.origin || 'Linked'));
      } catch (err) { }
    }
  }

  // Sort candidate items: Linked items at the top!
  allItems.sort((a, b) => {
    const aLinked = currentLinked.has(a.id) ? 1 : 0;
    const bLinked = currentLinked.has(b.id) ? 1 : 0;
    if (aLinked !== bLinked) return bLinked - aLinked;
    return a.label.localeCompare(b.label);
  });

  // 4. Initialize Active State
  window.activeFnLinkState = {
    fmId,
    type,
    fmName,
    isPFMEA: isPfmea,
    selectedIds: currentLinked,
    allItems,
    filteredItems: [...allItems]
  };

  // 5. Update Header & Subtitles
  const modal = document.getElementById('failureNetLinkElementsModal');
  const headerEl = document.getElementById('fnLinkModalHeader');
  const iconEl = document.getElementById('fnLinkModalIcon');
  const titleEl = document.getElementById('fnLinkModalTitle');
  const targetFmNameEl = document.getElementById('fnLinkTargetFmName');
  const searchInput = document.getElementById('fnLinkSearchInput');
  const confirmBtn = document.getElementById('fnLinkBtnConfirm');

  if (targetFmNameEl) targetFmNameEl.textContent = fmName;
  if (searchInput) searchInput.value = '';

  if (type === 'EFFECT') {
    if (iconEl) iconEl.textContent = '💥';
    if (titleEl) {
      titleEl.innerHTML = `Link Effects &bull; <span style="color:#f87171;">Effect Side (Level N+1)</span>`;
    }
    if (headerEl) {
      headerEl.style.background = 'linear-gradient(135deg, #1e1b4b 0%, #311313 100%)';
      headerEl.style.borderBottom = '1px solid #7f1d1d';
    }
    if (confirmBtn) {
      confirmBtn.style.background = '#dc2626';
      confirmBtn.style.borderColor = '#fca5a5';
      confirmBtn.style.boxShadow = '0 0 14px rgba(220, 38, 38, 0.5)';
      confirmBtn.innerHTML = '✓ Confirm &amp; Update Diagram';
    }
  } else {
    if (iconEl) iconEl.textContent = '⚙️';
    if (titleEl) {
      titleEl.innerHTML = `Link Causes &bull; <span style="color:#34d399;">Cause Side (Level N-1)</span>`;
    }
    if (headerEl) {
      headerEl.style.background = 'linear-gradient(135deg, #1e1b4b 0%, #06281e 100%)';
      headerEl.style.borderBottom = '1px solid #064e3b';
    }
    if (confirmBtn) {
      confirmBtn.style.background = '#059669';
      confirmBtn.style.borderColor = '#6ee7b7';
      confirmBtn.style.boxShadow = '0 0 14px rgba(5, 150, 105, 0.5)';
      confirmBtn.innerHTML = '✓ Confirm &amp; Update Diagram';
    }
  }

  // Render list & quick add container
  renderFailureNetLinkList();
  renderFailureNetQuickAddBox();

  if (modal) {
    if (modal.parentElement !== document.body) {
      document.body.appendChild(modal);
    }
    modal.style.display = 'flex';
  }
}
window.openFailureNetLinkModal = openFailureNetLinkModal;

/**
 * Closes the failure network linking modal.
 */
function closeFailureNetLinkModal() {
  const modal = document.getElementById('failureNetLinkElementsModal');
  if (modal) modal.style.display = 'none';
  window.activeFnLinkState = null;
}
window.closeFailureNetLinkModal = closeFailureNetLinkModal;

/**
 * Renders the candidate items list with selection checkboxes and metadata badges.
 */
function renderFailureNetLinkList() {
  const container = document.getElementById('fnLinkItemsListContainer');
  const badgeEl = document.getElementById('fnLinkSelectedCountBadge');
  if (!container || !window.activeFnLinkState) return;

  const { type, selectedIds, filteredItems } = window.activeFnLinkState;
  if (badgeEl) {
    badgeEl.textContent = `${selectedIds.size} Selected`;
  }

  if (!filteredItems || filteredItems.length === 0) {
    container.innerHTML = `
      <div style="padding: 24px; text-align: center; color: #64748b; font-size: 12.5px;">
        🔍 No matching ${type === 'EFFECT' ? 'effects' : 'causes'} found in library. Use <strong>+ Quick Add</strong> below to create and link a new one immediately.
      </div>
    `;
    return;
  }

  let html = '';
  filteredItems.forEach(item => {
    const isChecked = selectedIds.has(item.id);
    let badgeHtml = '';

    if (type === 'EFFECT') {
      const sevStyle = (typeof getSeverityColorStyle === 'function') ? getSeverityColorStyle(item.severity) : 'background:#fee2e2; color:#991b1b;';
      badgeHtml = `<span style="${sevStyle} font-size:9.5px; font-weight:800; padding:2px 6px; border-radius:4px; flex-shrink:0;">S: ${item.severity}</span>`;
    } else {
      const occStyle = (typeof getOccurrenceColorStyle === 'function') ? getOccurrenceColorStyle(item.occurrence) : 'background:#fef3c7; color:#92400e;';
      const detStyle = (typeof getDetectionColorStyle === 'function') ? getDetectionColorStyle(item.detection) : 'background:#e0f2fe; color:#075985;';
      badgeHtml = `
        <span style="${occStyle} font-size:9px; font-weight:800; padding:2px 5px; border-radius:4px; flex-shrink:0;">O: ${item.occurrence}</span>
        <span style="${detStyle} font-size:9px; font-weight:800; padding:2px 5px; border-radius:4px; flex-shrink:0;">D: ${item.detection}</span>
      `;
    }

    const originBadge = item.origin === 'PFMEA'
      ? `<span style="background:rgba(217,70,239,0.2); border:1px solid #d946ef; color:#f0abfc; font-size:9px; font-weight:800; padding:1px 5px; border-radius:3px; flex-shrink:0;">PFMEA</span>`
      : `<span style="background:rgba(56,189,248,0.15); border:1px solid #38bdf8; color:#bae6fd; font-size:9px; font-weight:700; padding:1px 5px; border-radius:3px; flex-shrink:0;">DFMEA</span>`;

    html += `
      <div class="fn-link-item-row ${isChecked ? 'is-selected' : ''}" onclick="toggleFailureNetItemCheck('${item.id}')">
        <input type="checkbox" ${isChecked ? 'checked' : ''} onclick="event.stopPropagation(); toggleFailureNetItemCheck('${item.id}');">
        <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;">
          ${badgeHtml}
          ${originBadge}
        </div>
        <div style="flex:1; font-size:12px; font-weight:600; color:${isChecked ? '#ffffff' : '#cbd5e1'}; line-height:1.35; word-break:break-word;">
          ${escapeHtml(item.label)}
        </div>
      </div>
    `;
  });

  container.innerHTML = html;
}
window.renderFailureNetLinkList = renderFailureNetLinkList;

/**
 * Filters the list of items based on real-time text input.
 */
function filterFailureNetLinkList() {
  if (!window.activeFnLinkState) return;
  const input = document.getElementById('fnLinkSearchInput');
  const q = (input ? input.value : '').trim().toLowerCase();

  if (!q) {
    window.activeFnLinkState.filteredItems = [...window.activeFnLinkState.allItems];
  } else {
    window.activeFnLinkState.filteredItems = window.activeFnLinkState.allItems.filter(item => {
      const matchLabel = (item.label || '').toLowerCase().includes(q);
      const matchOrigin = (item.origin || '').toLowerCase().includes(q);
      const matchSys = (item.systemName || item.systemElement || '').toLowerCase().includes(q);
      return matchLabel || matchOrigin || matchSys;
    });
  }
  renderFailureNetLinkList();
}
window.filterFailureNetLinkList = filterFailureNetLinkList;

/**
 * Toggles the checked state for an item in activeFnLinkState.
 */
function toggleFailureNetItemCheck(id) {
  if (!window.activeFnLinkState) return;
  const { selectedIds } = window.activeFnLinkState;
  const idStr = String(id);

  if (selectedIds.has(idStr)) {
    selectedIds.delete(idStr);
  } else {
    selectedIds.add(idStr);
  }

  renderFailureNetLinkList();
}
window.toggleFailureNetItemCheck = toggleFailureNetItemCheck;

/**
 * Selects all or clears all filtered items in the linking modal.
 */
function toggleAllFailureNetLinkItems(selectAll) {
  if (!window.activeFnLinkState) return;
  const { selectedIds, filteredItems } = window.activeFnLinkState;

  filteredItems.forEach(item => {
    if (selectAll) {
      selectedIds.add(String(item.id));
    } else {
      selectedIds.delete(String(item.id));
    }
  });

  renderFailureNetLinkList();
}
window.toggleAllFailureNetLinkItems = toggleAllFailureNetLinkItems;

