/**
 * Creates a brand new Effect or Cause entry and automatically marks it as checked.
 */
function addQuickFailureNetItem() {
  if (!window.activeFnLinkState) return;
  const textInput = document.getElementById('fnLinkQuickAddText');
  const rawText = (textInput ? textInput.value : '').trim();
  if (!rawText) {
    if (typeof showToast === 'function') showToast("Please enter a description for the new element.", "warning");
    else alert("Please enter a description for the new element.");
    return;
  }

  const { type, isPFMEA, allItems, filteredItems, selectedIds } = window.activeFnLinkState;
  const ctx = (typeof getActiveFmeaData === 'function') ? getActiveFmeaData() : fmeaData;

  if (type === 'EFFECT') {
    const sevSelect = document.getElementById('fnLinkQuickAddSev');
    const sevVal = parseInt(sevSelect ? sevSelect.value : 8, 10);
    const newId = `lib-eff-${Date.now()}`;
    const newEff = {
      id: newId,
      name: rawText,
      desc: rawText,
      details: rawText,
      description: rawText,
      severity: sevVal,
      origin: isPFMEA ? 'PFMEA' : 'DFMEA'
    };

    fmeaData.libraries = fmeaData.libraries || {};
    fmeaData.libraries.effects = fmeaData.libraries.effects || [];
    fmeaData.libraries.effects.push(newEff);

    if (ctx.pfmea && isPFMEA) {
      ctx.pfmea.libraries = ctx.pfmea.libraries || {};
      ctx.pfmea.libraries.effects = ctx.pfmea.libraries.effects || [];
      ctx.pfmea.libraries.effects.push(newEff);
    }

    const newItem = {
      id: newId,
      label: rawText,
      severity: sevVal,
      origin: isPFMEA ? 'PFMEA' : 'DFMEA',
      systemName: ''
    };

    selectedIds.add(newId);
    allItems.unshift(newItem);
    filteredItems.unshift(newItem);
  } else {
    // CAUSE
    const occSelect = document.getElementById('fnLinkQuickAddOcc');
    const detSelect = document.getElementById('fnLinkQuickAddDet');
    const occVal = parseInt(occSelect ? occSelect.value : 4, 10);
    const detVal = parseInt(detSelect ? detSelect.value : 3, 10);
    const newId = `lib-cause-${Date.now()}`;

    const newCause = {
      id: newId,
      details: rawText,
      desc: rawText,
      name: rawText,
      description: rawText,
      occurrence: occVal,
      detection: detVal,
      origin: isPFMEA ? 'PFMEA' : 'DFMEA'
    };

    fmeaData.libraries = fmeaData.libraries || {};
    fmeaData.libraries.causes = fmeaData.libraries.causes || [];
    fmeaData.libraries.causes.push(newCause);

    if (ctx.pfmea && isPFMEA) {
      ctx.pfmea.libraries = ctx.pfmea.libraries || {};
      ctx.pfmea.libraries.causes = ctx.pfmea.libraries.causes || [];
      ctx.pfmea.libraries.causes.push(newCause);
    }

    const newItem = {
      id: newId,
      label: rawText,
      occurrence: occVal,
      detection: detVal,
      ap: '-',
      origin: isPFMEA ? 'PFMEA' : 'DFMEA',
      systemElement: ''
    };

    selectedIds.add(newId);
    allItems.unshift(newItem);
    filteredItems.unshift(newItem);
  }

  if (textInput) textInput.value = '';
  renderFailureNetLinkList();
  if (typeof showToast === 'function') {
    showToast(`Added and selected "${rawText}".`, "success");
  }
}
window.addQuickFailureNetItem = addQuickFailureNetItem;

/**
 * Confirms selected element linkages, saves data, and automatically refreshes the failure network diagram.
 */
function confirmFailureNetLinkElements() {
  if (!window.activeFnLinkState) return;
  const { fmId, type, selectedIds, fmName } = window.activeFnLinkState;
  const finalIds = Array.from(selectedIds);
  const ctx = (typeof getActiveFmeaData === 'function') ? getActiveFmeaData() : fmeaData;

  if (type === 'EFFECT') {
    ctx.failureModeEffects = ctx.failureModeEffects || {};
    ctx.failureModeEffects[fmId] = [...finalIds];

    fmeaData.failureModeEffects = fmeaData.failureModeEffects || {};
    fmeaData.failureModeEffects[fmId] = [...finalIds];

    if (ctx.pfmea) {
      ctx.pfmea.failureModeEffects = ctx.pfmea.failureModeEffects || {};
      ctx.pfmea.failureModeEffects[fmId] = [...finalIds];
    }

    // Also update function line failureModes
    const allFl = (ctx.functionLines || []).concat(ctx.pfmea?.functionLines || []).concat(fmeaData.functionLines || []);
    allFl.forEach(fl => {
      (fl.failureModes || []).forEach(m => {
        if (String(m.id) === String(fmId)) {
          m.effectIds = [...finalIds];
        }
      });
    });
  } else {
    // CAUSE
    ctx.failureModeCauses = ctx.failureModeCauses || {};
    ctx.failureModeCauses[fmId] = [...finalIds];

    fmeaData.failureModeCauses = fmeaData.failureModeCauses || {};
    fmeaData.failureModeCauses[fmId] = [...finalIds];

    if (ctx.pfmea) {
      ctx.pfmea.failureModeCauses = ctx.pfmea.failureModeCauses || {};
      ctx.pfmea.failureModeCauses[fmId] = [...finalIds];
    }

    // Also update function line failureModes
    const allFl = (ctx.functionLines || []).concat(ctx.pfmea?.functionLines || []).concat(fmeaData.functionLines || []);
    allFl.forEach(fl => {
      (fl.failureModes || []).forEach(m => {
        if (String(m.id) === String(fmId)) {
          m.causeIds = [...finalIds];
        }
      });
    });
  }

  // Persist state
  if (typeof markDataChanged === 'function') markDataChanged();
  if (typeof saveProjectToLocalStorage === 'function') saveProjectToLocalStorage();

  // Close modal
  closeFailureNetLinkModal();

  // Immediately refresh Failure Network Diagram with newly linked nodes & edges!
  refreshActiveFailureNetworkIfOpen();

  // Also refresh background FMEA table
  if (typeof renderFMEATable === 'function') renderFMEATable();

  if (typeof showToast === 'function') {
    showToast(`✓ Successfully linked ${finalIds.length} ${type === 'EFFECT' ? 'effects' : 'causes'} to "${fmName}". Network diagram updated.`, "success");
  }
}
window.confirmFailureNetLinkElements = confirmFailureNetLinkElements;

/**
 * Bridges from the quick linking modal to the full master library modal if requested.
 */
function openFullLibFromNetworkLinkModal() {
  if (!window.activeFnLinkState) return;
  const { fmId, type } = window.activeFnLinkState;
  closeFailureNetLinkModal();

  activeFailureModeId = fmId;

  // Elevate full library modals z-index so they sit nicely on top of failureNetworkModal
  const effModal = document.getElementById('effectModal');
  const causeModal = document.getElementById('causeModal');
  if (effModal) effModal.style.zIndex = '10000060';
  if (causeModal) causeModal.style.zIndex = '10000060';

  if (type === 'EFFECT') {
    openEffectModal(fmId);
  } else {
    openCauseModal(fmId);
  }
}
window.openFullLibFromNetworkLinkModal = openFullLibFromNetworkLinkModal;

/**
 * Right-click context menu handler for linking effects or causes.
 */
function handleFailureNetContextLink(type) {
  const nodeId = activeFailureNetworkState.contextNodeId;
  closeFailureNetContextMenu();
  if (!nodeId) return;
  openFailureNetLinkModal(nodeId, type);
}
window.handleFailureNetContextLink = handleFailureNetContextLink;


/**
 * Opens the FMEA table and navigates directly to the specified Failure Mode row,
 * switching context (DFMEA vs PFMEA) or structure node if necessary, and highlights the row.
 * @param {string} fmId Target Failure Mode ID
 */
function jumpToFailureModeInFMEATable(fmId) {
  if (!fmId) return;

  // 1. Close Failure Network Modal
  const fnModal = document.getElementById('failureNetworkModal');
  if (fnModal) fnModal.style.display = 'none';

  // 2. Locate Failure Mode object across all project modes
  const allModes = (typeof getAllProjectFailureModesWithContext === 'function') ? getAllProjectFailureModesWithContext() : [];
  let targetObj = allModes.find(m => String(m.fm.id) === String(fmId));
  if (!targetObj && typeof findFailureModeObjById === 'function') {
    targetObj = findFailureModeObjById(fmId);
  }

  // 3. Switch context if needed (DFMEA vs PFMEA)
  const ctx = (typeof getActiveFmeaData === 'function') ? getActiveFmeaData() : fmeaData;
  const currentIsPFMEA = !!(ctx && ctx.isPFMEA);
  const targetIsPFMEA = !!(targetObj?.isPFMEA || (targetObj?.scope && targetObj.scope.isPFMEA));

  if (targetIsPFMEA && !currentIsPFMEA) {
    if (typeof switchFmeaContext === 'function') {
      const targetPfmeaId = targetObj.scope?.id || targetObj.pfmeaId || fmeaData.activePfmeaId || (fmeaData.pfmeas && fmeaData.pfmeas[0]?.id);
      switchFmeaContext(targetPfmeaId ? `PFMEA-${targetPfmeaId}` : 'PFMEA');
    }
  } else if (!targetIsPFMEA && currentIsPFMEA) {
    if (typeof switchFmeaContext === 'function') {
      switchFmeaContext('DFMEA');
    }
  }

  // 4. Select structure node if available
  if (targetObj && targetObj.structId) {
    selectedStructureId = targetObj.structId;
    const currentCtx = (typeof getActiveFmeaData === 'function') ? getActiveFmeaData() : fmeaData;
    const node = (typeof getStructureNodeById === 'function') ? getStructureNodeById(currentCtx.structure, selectedStructureId) : null;
    const nameEl = document.getElementById('focusedNodeName');
    if (nameEl) nameEl.innerText = node ? `${node.partNo} - ${node.name}` : 'None Selected (Showing All System Elements)';
    if (typeof renderTreeSidebar === 'function') renderTreeSidebar();
  }

  // 5. Re-render FMEA table
  if (typeof renderFMEATable === 'function') renderFMEATable();

  // 6. Smoothly scroll to the failure mode cell/row and pulse-highlight
  setTimeout(() => {
    const el = document.getElementById(`fmea-cell-fm-${fmId}`) ||
      document.getElementById(`fmea-row-${fmId}`) ||
      document.querySelector(`[data-fm-id="${fmId}"]`);

    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      el.classList.add('highlight-pulse-cell');
      setTimeout(() => el.classList.remove('highlight-pulse-cell'), 2600);
    }

    const fmLabel = targetObj?.fm?.name || fmId;
    if (typeof showToast === 'function') {
      showToast(`📍 Located "${fmLabel}" in FMEA Table.`, 'info');
    }
  }, 120);
}
window.jumpToFailureModeInFMEATable = jumpToFailureModeInFMEATable;


