window.activeSelectedStructCharacteristics = window.activeSelectedStructCharacteristics || [];
window.activeStructCharCategoryFilter = window.activeStructCharCategoryFilter || 'ALL';

function initStructCharacteristicsUI(initialChars = []) {
  window.activeSelectedStructCharacteristics = Array.isArray(initialChars) ? [...initialChars] : (initialChars ? [String(initialChars)] : []);
  renderStructCharCategoryTabs();
  renderStructSelectedCharsBadges();
  renderStructCharacteristicsCatalogue();
}

function renderStructCharCategoryTabs() {
  const container = document.getElementById('structCharCategoryTabs');
  if (!container) return;

  const current = window.activeStructCharCategoryFilter || 'ALL';
  let html = `<button type="button" class="comp-char-category-btn ${current === 'ALL' ? 'active' : ''}" onclick="setStructCharCategoryFilter('ALL')">All Categories</button>`;

  MASTER_COMPONENT_CHARACTERISTICS_DATA.forEach(cat => {
    const isActive = (current === cat.category);
    html += `<button type="button" class="comp-char-category-btn ${isActive ? 'active' : ''}" onclick="setStructCharCategoryFilter('${cat.category}')">${escapeHtml(cat.category)}</button>`;
  });

  container.innerHTML = html;
}

function setStructCharCategoryFilter(category) {
  window.activeStructCharCategoryFilter = category;
  renderStructCharCategoryTabs();
  renderStructCharacteristicsCatalogue();
}

function renderStructSelectedCharsBadges() {
  const container = document.getElementById('structSelectedCharsContainer');
  const countBadge = document.getElementById('structCharCountBadge');
  if (!container) return;

  const selected = window.activeSelectedStructCharacteristics || [];
  if (countBadge) countBadge.textContent = `${selected.length} Selected`;

  if (selected.length === 0) {
    container.innerHTML = `<span style="font-size:10px; color:#64748b; font-style:italic; padding:2px;">No characteristics selected yet. Pick from catalogue below or enter custom specs.</span>`;
    return;
  }

  container.innerHTML = selected.map(charName => `
    <span class="comp-char-selected-badge">
      <span>${escapeHtml(charName)}</span>
      <span class="badge-remove" onclick="toggleStructCharacteristic('${escapeHtml(charName)}', event)" title="Remove">✕</span>
    </span>
  `).join('');
}

function renderStructCharacteristicsCatalogue() {
  const container = document.getElementById('structCharCatalogueList');
  if (!container) return;

  const currentCat = window.activeStructCharCategoryFilter || 'ALL';
  const query = (document.getElementById('structCharSearchInput')?.value || '').trim().toLowerCase();
  const selected = window.activeSelectedStructCharacteristics || [];

  let pool = [];
  MASTER_COMPONENT_CHARACTERISTICS_DATA.forEach(cat => {
    if (currentCat === 'ALL' || currentCat === cat.category) {
      cat.items.forEach(it => {
        pool.push({ category: cat.category, name: it.name, spec: it.spec });
      });
    }
  });

  if (query) {
    pool = pool.filter(it => it.name.toLowerCase().includes(query) || it.spec.toLowerCase().includes(query) || it.category.toLowerCase().includes(query));
  }

  if (pool.length === 0) {
    container.innerHTML = `<span style="font-size:10.5px; color:#64748b; font-style:italic; padding:4px;">No matching component characteristics found.</span>`;
    return;
  }

  container.innerHTML = pool.map(it => {
    const isSel = selected.includes(it.name);
    return `
      <span class="comp-char-item-chip ${isSel ? 'is-selected' : ''}" onclick="toggleStructCharacteristic('${escapeHtml(it.name)}', event)" title="${escapeHtml(it.spec)}">
        <span>${isSel ? '✓' : '+'}</span>
        <span>${escapeHtml(it.name)}</span>
      </span>
    `;
  }).join('');
}

function toggleStructCharacteristic(charName, event) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  window.activeSelectedStructCharacteristics = window.activeSelectedStructCharacteristics || [];
  const idx = window.activeSelectedStructCharacteristics.indexOf(charName);
  if (idx > -1) {
    window.activeSelectedStructCharacteristics.splice(idx, 1);
  } else {
    window.activeSelectedStructCharacteristics.push(charName);
  }
  renderStructSelectedCharsBadges();
  renderStructCharacteristicsCatalogue();
}

function clearStructCharSelections() {
  window.activeSelectedStructCharacteristics = [];
  renderStructSelectedCharsBadges();
  renderStructCharacteristicsCatalogue();
}


// ══════════════════════════════════════════════════════════════════════════
// 44. STRUCTURE TREE COLLAPSE & EXPAND CONTROLLER
// ══════════════════════════════════════════════════════════════════════════

window.treeCollapsedNodeIds = window.treeCollapsedNodeIds || new Set();

function toggleTreeNodeCollapse(nodeId, isEditableModal = false, event = null) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  window.treeCollapsedNodeIds = window.treeCollapsedNodeIds || new Set();
  const sId = String(nodeId);
  const isNowCollapsed = !window.treeCollapsedNodeIds.has(sId);
  if (isNowCollapsed) {
    window.treeCollapsedNodeIds.add(sId);
  } else {
    window.treeCollapsedNodeIds.delete(sId);
  }

  const prefix = isEditableModal ? 'modal-tree-node-' : 'sidebar-tree-node-';
  const nodeEl = document.getElementById(prefix + sId) || document.getElementById('tree-node-' + sId);
  if (nodeEl) {
    nodeEl.classList.toggle('is-collapsed', isNowCollapsed);
    const toggler = nodeEl.querySelector(':scope > .tree-item .tree-toggler');
    if (toggler) {
      toggler.textContent = isNowCollapsed ? '▶' : '▼';
      toggler.title = isNowCollapsed ? 'Click to expand' : 'Click to collapse';
    }
    const icon = nodeEl.querySelector(':scope > .tree-item .tree-icon');
    if (icon) {
      icon.textContent = isNowCollapsed ? '📁' : '📂';
    }
    const childrenContainer = nodeEl.querySelector(':scope > .tree-children');
    if (childrenContainer) {
      childrenContainer.style.display = isNowCollapsed ? 'none' : '';
    }
  } else {
    if (isEditableModal) {
      const container = document.getElementById('modalTreeContainer');
      const ctx = getActiveFmeaData();
      if (container && ctx && ctx.structure) container.innerHTML = buildTreeHTML(ctx.structure, true);
    } else {
      renderTreeSidebar();
    }
  }
}

function toggleCollapseAllTree(collapse = true) {
  window.treeCollapsedNodeIds = window.treeCollapsedNodeIds || new Set();
  const ctx = getActiveFmeaData();
  const root = (ctx && ctx.structure) ? ctx.structure : (fmeaData ? fmeaData.structure : null);
  if (!root) return;

  if (!collapse) {
    window.treeCollapsedNodeIds.clear();
  } else {
    function collectParentNodes(node) {
      if (!node) return;
      if (node.children && node.children.length > 0) {
        window.treeCollapsedNodeIds.add(String(node.id));
        node.children.forEach(collectParentNodes);
      }
    }
    collectParentNodes(root);
  }

  renderTreeSidebar();
  const container = document.getElementById('modalTreeContainer');
  if (container && root) container.innerHTML = buildTreeHTML(root, true);
}

