function handleFmCellDblClick(event, td, flId, fmId) {
  if (event) {
    if (typeof event.stopPropagation === 'function') event.stopPropagation();
    if (typeof event.preventDefault === 'function') event.preventDefault();
  }
  if (!event || (!event.ctrlKey && !event.metaKey)) {
    if (typeof showToast === 'function') {
      showToast('Failure Mode edit requires Ctrl + Double-Click', 'info');
    }
    return;
  }
  if (typeof openQuickFieldEditModal === 'function') { openQuickFieldEditModal('FAILURE_MODE', { flId, fmId, td }); } else { editInlineCell(event, td, flId, fmId, 'fmName'); }
}
window.handleFmCellDblClick = handleFmCellDblClick;

// ----------------------------------------------------
// Select All / None / Invert Modal Helpers
// ----------------------------------------------------
function charSelectAll(action) {
  const checkboxes = document.querySelectorAll('#masterCharacteristicsContainer input[type="checkbox"]');
  checkboxes.forEach(chk => {
    let newState = chk.checked;
    if (action === 'all') newState = true;
    else if (action === 'none') newState = false;
    else if (action === 'invert') newState = !chk.checked;
    if (chk.checked !== newState) {
      chk.checked = newState;
      chk.dispatchEvent(new Event('change'));
    }
  });
}
window.charSelectAll = charSelectAll;

