window.selectedCharLinkageElementId = null;
window.selectedCharLinkageOpId = 'ALL';
window.activeCharLinkageSource = 'characteristics'; // 'characteristics', 'requirements', 'both'
window.activeCharLinkageFilter = 'ALL'; // 'ALL', 'GAPS', 'LINKED', 'TRANSIENT', 'CP'
