function openControlPlanChangeReportModal(revNo) {
  initControlPlanDefaults();
  const revs = fmeaData.controlPlanRevisions || [];
  const targetRev = (revNo ? revs.find(r => r.revNo === revNo) : getActiveControlPlanRevision()) || getActiveControlPlanRevision();
  if (!targetRev) return;

  const sortedRevs = [...revs].sort((a, b) => (parseInt(a.revNo || '0', 10) - parseInt(b.revNo || '0', 10)));
  const revIdx = sortedRevs.findIndex(r => r.revNo === targetRev.revNo);

  if (revIdx <= 0 && !targetRev.changeReport) {
    alert(`Revision ${targetRev.revNo} is the initial baseline revision with no previous revision to compare against.`);
    return;
  }

  const prevRev = sortedRevs[revIdx - 1];
  const report = targetRev.changeReport || generateControlPlanRevisionChangeReport(prevRev, targetRev);

  const titleEl = document.getElementById('cpRevReportTitle');
  const subTitleEl = document.getElementById('cpRevReportSubtitle');
  const bodyEl = document.getElementById('cpRevReportModalBody');
  const freezeBtn = document.getElementById('btnConfirmFreezeCpInReportModal');

  if (titleEl) titleEl.innerText = `📊 Control Plan Rev ${targetRev.revNo} — Summary of Changes`;
  if (subTitleEl) subTitleEl.innerText = `Baseline Comparison against Rev ${prevRev ? prevRev.revNo : 'Previous'} | ${targetRev.status === 'Frozen' ? 'Frozen on ' + targetRev.freezeDate : 'In Progress'}`;
  if (bodyEl) bodyEl.innerHTML = renderControlPlanChangeReportHTML(report);
  if (freezeBtn) freezeBtn.style.display = 'none';

  const modal = document.getElementById('controlPlanChangeReportModal');
  if (modal) modal.style.display = 'flex';
}
