function buildControlPlanComparisonDiffMap(prevRev, curRev) {
  const diffMap = {
    lines: new Map(),
    deletedRows: []
  };

  const prevRows = (prevRev && prevRev.snapshotData && prevRev.snapshotData.rows) ? prevRev.snapshotData.rows : [];
  const curRows = (curRev && curRev.snapshotData && curRev.snapshotData.rows) ? curRev.snapshotData.rows : [];

  function flattenCpRows(groupsOrRows) {
    if (!Array.isArray(groupsOrRows)) return [];
    if (groupsOrRows.length > 0 && groupsOrRows[0].rows && Array.isArray(groupsOrRows[0].rows)) {
      const flat = [];
      groupsOrRows.forEach(g => {
        (g.rows || []).forEach(r => {
          flat.push({ ...r, opNo: g.opNo, opName: g.opName, elementPartNo: g.elementPartNo });
        });
      });
      return flat;
    }
    return groupsOrRows;
  }

  const prevFlat = flattenCpRows(prevRows);
  const curFlat = flattenCpRows(curRows);

  function getRowKey(r) {
    return r.lineCpKey || (r.opNo + '_' + (r.charNo || '') + '_' + (r.prevCtrl ? r.prevCtrl.desc : '') + '_' + (r.detCtrl ? r.detCtrl.desc : ''));
  }

  const prevMap = new Map();
  prevFlat.forEach(r => prevMap.set(getRowKey(r), r));

  const curMap = new Map();
  curFlat.forEach(r => curMap.set(getRowKey(r), r));

  curFlat.forEach(r => {
    const key = getRowKey(r);
    if (!prevMap.has(key)) {
      diffMap.lines.set(key, { type: 'ADDED' });
    } else {
      const p = prevMap.get(key);
      const fieldDiffs = {};
      if (p.spec !== r.spec) fieldDiffs.spec = { old: p.spec, new: r.spec };
      if (p.specialClass !== r.specialClass) fieldDiffs.specialClass = { old: p.specialClass, new: r.specialClass };
      if (p.machineTooling !== r.machineTooling) fieldDiffs.machineTooling = { old: p.machineTooling, new: r.machineTooling };
      if (p.sampleSize !== r.sampleSize) fieldDiffs.sampleSize = { old: p.sampleSize, new: r.sampleSize };
      if (p.sampleFreq !== r.sampleFreq) fieldDiffs.sampleFreq = { old: p.sampleFreq, new: r.sampleFreq };
      if (p.evaluator !== r.evaluator) fieldDiffs.evaluator = { old: p.evaluator, new: r.evaluator };
      if (p.reactionPlan !== r.reactionPlan) fieldDiffs.reactionPlan = { old: p.reactionPlan, new: r.reactionPlan };

      if (Object.keys(fieldDiffs).length > 0) {
        diffMap.lines.set(key, { type: 'MODIFIED', fieldDiffs });
      }
    }
  });

  prevFlat.forEach(r => {
    const key = getRowKey(r);
    if (!curMap.has(key)) {
      diffMap.deletedRows.push(r);
    }
  });

  return diffMap;
}
window.buildControlPlanComparisonDiffMap = buildControlPlanComparisonDiffMap;

function activateControlPlanTableComparison(revNo) {
  initControlPlanDefaults();
  const revs = fmeaData.controlPlanRevisions || [];
  const targetRev = (revNo ? revs.find(r => r.revNo === revNo) : getActiveControlPlanRevision()) || getActiveControlPlanRevision();
  if (!targetRev) return;

  const sortedRevs = [...revs].sort((a, b) => (parseInt(a.revNo || '0', 10) - parseInt(b.revNo || '0', 10)));
  const revIdx = sortedRevs.findIndex(r => r.revNo === targetRev.revNo);

  if (revIdx <= 0) {
    alert(`Revision ${targetRev.revNo} is the 1st revision with no baseline to compare against.`);
    return;
  }

  const prevRev = sortedRevs[revIdx - 1];
  const candidateCur = { ...targetRev, snapshotData: targetRev.snapshotData || captureControlPlanSnapshot() };
  const report = targetRev.changeReport || generateControlPlanRevisionChangeReport(prevRev, candidateCur);
  const diffMap = buildControlPlanComparisonDiffMap(prevRev, candidateCur);

  activeControlPlanComparisonState = {
    targetRev: candidateCur,
    prevRev,
    report,
    diffMap
  };

  exitControlPlanSnapshotView(false);
  closeControlPlanRevisionModal();
  renderControlPlanTable();
  if (typeof showToast === 'function') showToast(`🔍 Comparison Mode Activated: Rev ${targetRev.revNo} vs Rev ${prevRev.revNo}`);
}
window.activateControlPlanTableComparison = activateControlPlanTableComparison;

function exitControlPlanTableComparison() {
  activeControlPlanComparisonState = null;
  renderControlPlanTable();
}
window.exitControlPlanTableComparison = exitControlPlanTableComparison;

