function renderControlPlanRevisionUI() {
  initControlPlanDefaults();
  const curRev = getActiveControlPlanRevision();
  const revs = fmeaData.controlPlanRevisions || [];
  const inProgressCpRev = revs.find(r => r && r.status !== 'Frozen' && r.status !== 'Released') || null;
  const isCurFrozen = curRev.status === 'Frozen' || curRev.status === 'Released';

  const curNoSpan = document.getElementById('cpCurRevNo');
  const curPhaseSpan = document.getElementById('cpCurRevPhase');
  const curStatusSpan = document.getElementById('cpCurRevStatus');
  const curAuthorSpan = document.getElementById('cpCurRevAuthor');
  const curDateSpan = document.getElementById('cpCurRevDate');
  const curDescSpan = document.getElementById('cpCurRevDesc');
  const activeStatusTag = document.getElementById('cpActiveStatusTag');
  const checklistScoreSpan = document.getElementById('cpActiveChecklistScore');
  const cpChecklistPctBadge = document.getElementById('cpChecklistPctBadge');
  const btnFreezeCp = document.getElementById('btnFreezeCpRevision');
  const btnPreviewCp = document.getElementById('btnPreviewCpRevisionChanges');
  const cpCreateRevFormControls = document.getElementById('cpCreateRevFormControls');
  const cpCreateRevNotice = document.getElementById('cpCreateRevNotice');

  const { completedCount, totalCount, percentage } = calculateControlPlanChecklistCompletion(curRev);

  if (curNoSpan) curNoSpan.textContent = curRev.revNo || '01';
  if (curPhaseSpan) curPhaseSpan.textContent = curRev.phase || 'Production';
  if (curStatusSpan) curStatusSpan.textContent = curRev.status || 'In Progress';
  if (curAuthorSpan) curAuthorSpan.textContent = curRev.author || 'Quality Engineer';
  if (curDateSpan) curDateSpan.textContent = isCurFrozen ? `${curRev.date || '-'} (Frozen: ${curRev.freezeDate || '-'})` : (curRev.date || '-');
  if (curDescSpan) curDescSpan.textContent = curRev.changeDesc || 'Initial Release';
  if (checklistScoreSpan) {
    checklistScoreSpan.innerHTML = `<span style="color:${percentage === 100 ? '#34d399' : '#fbbf24'}; font-weight:700;">${percentage}% (${completedCount}/${totalCount})</span>`;
  }
  if (cpChecklistPctBadge) {
    cpChecklistPctBadge.textContent = isCurFrozen ? `100% — View Frozen Checksheet` : `${percentage}% (${completedCount}/${totalCount})`;
  }

  if (activeStatusTag) {
    activeStatusTag.textContent = isCurFrozen ? 'Frozen Baseline' : 'In Progress (Draft)';
    activeStatusTag.style.background = isCurFrozen ? 'rgba(16,185,129,0.2)' : 'rgba(245,158,11,0.2)';
    activeStatusTag.style.color = isCurFrozen ? '#34d399' : '#fbbf24';
    activeStatusTag.style.border = isCurFrozen ? '1px solid #059669' : '1px solid #d97706';
  }

  // Hide Freeze button when active revision is already Frozen, while keeping Checkpoints button visible to view frozen checksheet
  if (btnFreezeCp) {
    btnFreezeCp.style.display = isCurFrozen ? 'none' : 'inline-block';
  }
  const sortedRevs = [...revs].sort((a, b) => (parseInt(a.revNo || '0', 10) - parseInt(b.revNo || '0', 10)));
  const curRevIdx = sortedRevs.findIndex(r => r.revNo === curRev.revNo);
  if (btnPreviewCp) {
    btnPreviewCp.style.display = (!isCurFrozen && curRevIdx > 0) ? 'inline-block' : 'none';
  }

  // Hide Create Next Revision form whenever ANY in-progress Control Plan revision exists in the file
  if (inProgressCpRev) {
    if (cpCreateRevFormControls) cpCreateRevFormControls.style.display = 'none';
    if (cpCreateRevNotice) {
      cpCreateRevNotice.style.display = 'block';
      cpCreateRevNotice.innerHTML = `🔒 Control Plan Revision <strong>Rev ${escapeHtml(inProgressCpRev.revNo)}</strong> is currently In Progress. Complete verification &amp; freeze it before creating the next revision.`;
    }
  } else {
    if (cpCreateRevFormControls) cpCreateRevFormControls.style.display = 'block';
    if (cpCreateRevNotice) cpCreateRevNotice.style.display = 'none';
  }

  const maxRevNum = revs.reduce((max, r) => Math.max(max, parseInt(r.revNo || '1', 10) || 1), 1);
  const nextRevNo = (maxRevNum + 1).toString().padStart(2, '0');
  const newRevNoInput = document.getElementById('newCpRevNo');
  const newRevDateInput = document.getElementById('newCpRevDate');
  const newRevChangeInput = document.getElementById('newCpRevChange');

  if (newRevNoInput) newRevNoInput.value = nextRevNo;
  if (newRevDateInput) newRevDateInput.value = new Date().toISOString().split('T')[0];
  if (newRevChangeInput) newRevChangeInput.value = '';

  const listContainer = document.getElementById('cpRevisionHistoryList');
  if (listContainer) {
    let listHtml = `
      <table style="width:100%; border-collapse:collapse; font-size:11px; color:#f8fafc;">
        <thead>
          <tr style="background:#0f172a; border-bottom:1px solid #334155; color:#38bdf8;">
            <th style="padding:6px; text-align:center; width:45px;">Rev</th>
            <th style="padding:6px; width:75px;">Phase</th>
            <th style="padding:6px; width:80px;">Date</th>
            <th style="padding:6px;">Change Description</th>
            <th style="padding:6px; width:150px;">Upstream Lineage</th>
            <th style="padding:6px; width:110px; text-align:center;">Checklist</th>
            <th style="padding:6px; width:85px; text-align:center;">Status</th>
            <th style="padding:6px; width:160px; text-align:center;">Actions</th>
          </tr>
        </thead>
        <tbody>
    `;

    revs.forEach(r => {
      const isActive = r.revNo === fmeaData.currentControlPlanRevision;
      const isFrozen = r.status === 'Frozen' || r.status === 'Released';
      const chkStat = calculateControlPlanChecklistCompletion(r);
      const revNum = parseInt(r.revNo || '0', 10);

      let lineageHtml = '<span style="font-size:10px; color:#94a3b8;">Live PFMEA &amp; DFMEA</span>';
      if (r.upstreamLineage) {
        const pfStr = r.upstreamLineage.pfmea ? (r.upstreamLineage.pfmea.revNumber || 'PFMEA') : 'PFMEA';
        const dfStr = r.upstreamLineage.dfmea ? (r.upstreamLineage.dfmea.revNumber || 'DFMEA') : 'DFMEA';
        lineageHtml = `
          <div style="display:flex; flex-direction:column; gap:2px;">
            <span class="badge" style="background:rgba(2,132,199,0.15); color:#38bdf8; border:1px solid #0284c7; font-size:9.5px;" title="${escapeHtml(r.upstreamLineage.pfmea?.lineageLabel || '')}">🏭 PFMEA: ${escapeHtml(pfStr)}</span>
            <span class="badge" style="background:rgba(139,92,246,0.15); color:#c4b5fd; border:1px solid #8b5cf6; font-size:9.5px;" title="${escapeHtml(r.upstreamLineage.dfmea?.lineageLabel || '')}">🚗 DFMEA: ${escapeHtml(dfStr)}</span>
          </div>
        `;
      }

      listHtml += `
        <tr style="border-bottom:1px solid #334155; background:${isActive ? 'rgba(2,132,199,0.15)' : 'transparent'};">
          <td style="padding:6px; text-align:center; font-weight:700; color:${isActive ? '#38bdf8' : '#cbd5e1'};">${escapeHtml(r.revNo)}</td>
          <td style="padding:6px; color:#34d399;">${escapeHtml(r.phase)}</td>
          <td style="padding:6px; color:#94a3b8;">${escapeHtml(r.date)}</td>
          <td style="padding:6px; color:#f8fafc;">${escapeHtml(r.changeDesc)}</td>
          <td style="padding:6px;">${lineageHtml}</td>
          <td style="padding:6px; text-align:center;">
            <button type="button" class="btn btn-xs" onclick="openControlPlanChecklistModal('${r.revNo}')" style="background:transparent; border:1px solid ${chkStat.percentage === 100 ? '#059669' : '#d97706'}; color:${chkStat.percentage === 100 ? '#34d399' : '#fbbf24'}; font-size:9.5px; padding:1px 6px; border-radius:3px; cursor:pointer;" title="${isFrozen ? 'View Filled Output Checksheet (Frozen)' : 'Open Output Verification Checksheet'}">
              ${chkStat.percentage === 100 ? '✓ 100% (14/14)' : chkStat.percentage + '% (' + chkStat.completedCount + '/14)'}
            </button>
          </td>
          <td style="padding:6px; text-align:center;">
            <span style="font-size:10px; font-weight:700; padding:1px 6px; border-radius:3px; background:${isFrozen ? 'rgba(16,185,129,0.2)' : 'rgba(245,158,11,0.2)'}; color:${isFrozen ? '#34d399' : '#fbbf24'}; border:1px solid ${isFrozen ? '#059669' : '#d97706'};">
              ${escapeHtml(r.status)}
            </span>
          </td>
          <td style="padding:6px; text-align:center;">
            <div style="display:inline-flex; gap:4px; align-items:center; justify-content:center;">
              ${isActive ? '<span style="color:#38bdf8; font-size:10px; font-weight:700; margin-right:2px;">★ Active</span>' : `<button type="button" class="btn btn-xs" onclick="activateCpRevision('${r.revNo}')" style="background:#1e293b; border:1px solid #475569; color:#cbd5e1; font-size:10px; padding:1px 5px; border-radius:3px; cursor:pointer;" title="Switch to this revision">Switch</button>`}
              ${isFrozen ? `<button type="button" class="btn btn-xs" onclick="viewControlPlanRevisionSnapshot('${r.revNo}')" style="background:#0f172a; border:1px solid #d97706; color:#fbbf24; font-size:10px; padding:1px 5px; border-radius:3px; cursor:pointer;" title="View read-only historical snapshot">👁️ Snap</button>` : ''}
              ${revNum > 1 ? `
                <button type="button" class="btn btn-xs" onclick="activateControlPlanTableComparison('${r.revNo}')" style="background:#0f172a; border:1px solid #0284c7; color:#38bdf8; font-size:10px; padding:1px 5px; border-radius:3px; cursor:pointer;" title="Compare in Table vs previous baseline">🔍 Diff</button>
                <button type="button" class="btn btn-xs" onclick="openControlPlanChangeReportModal('${r.revNo}')" style="background:#0f172a; border:1px solid #8b5cf6; color:#a78bfa; font-size:10px; padding:1px 5px; border-radius:3px; cursor:pointer;" title="Open Change Report">📊 Report</button>
              ` : ''}
            </div>
          </td>
        </tr>
      `;
    });

    listHtml += `
        </tbody>
      </table>
    `;
    listContainer.innerHTML = listHtml;
  }
}
