function createControlPlanRevision() {
  initControlPlanDefaults();
  const revs = fmeaData.controlPlanRevisions || [];
  const inProgressCpRev = revs.find(r => r && r.status !== 'Frozen' && r.status !== 'Released');
  if (inProgressCpRev) {
    alert(`Control Plan Revision ${inProgressCpRev.revNo} is currently In Progress. Please complete its verification checklist and freeze it before creating a new revision.`);
    renderControlPlanRevisionUI();
    return;
  }

  const revNo = (document.getElementById('newCpRevNo')?.value || '').trim();
  const phase = document.getElementById('newCpRevPhase')?.value || 'Production';
  const date = (document.getElementById('newCpRevDate')?.value || '').trim() || new Date().toISOString().split('T')[0];
  const changeDesc = (document.getElementById('newCpRevChange')?.value || '').trim();

  if (!revNo) {
    alert('Please enter a revision number.');
    return;
  }
  if (!changeDesc) {
    alert('Please enter a reason or change description for the new revision.');
    return;
  }

  const newRev = {
    revNo,
    phase,
    date,
    changeDesc,
    status: 'In Progress',
    author: (fmeaData.headerInfo && fmeaData.headerInfo.preparedBy) || 'Quality Engineer',
    checklist: {}
  };
  OFFICIAL_CP_CHECKPOINTS.forEach(cp => {
    newRev.checklist[cp.key] = { checked: false, comment: '', verifiedBy: '', verifiedAt: '' };
  });

  fmeaData.controlPlanRevisions.unshift(newRev);
  fmeaData.currentControlPlanRevision = revNo;

  if (typeof markDataChanged === 'function') markDataChanged('New Control Plan Revision Created');
  if (typeof showToast === 'function') {
    showToast('Control Plan Rev ' + revNo + ' created successfully!', 'success');
  }

  renderControlPlanRevisionUI();
  updateControlPlanHeaderBadges();
  renderControlPlanTable();
}
window.createControlPlanRevision = createControlPlanRevision;

