function executeControlPlanPrint(format = 'PDF') {
  initControlPlanDefaults();
  const scopeRadio = document.querySelector('input[name="cpPrintScope"]:checked');
  const scopeVal = scopeRadio ? scopeRadio.value : 'ACTIVE_STEP';
  const variantVal = document.getElementById('cpPrintVariantSelect')?.value || 'ALL';

  const includeVariantMatrix = document.getElementById('chk_cpIncludeVariantMatrix') ? document.getElementById('chk_cpIncludeVariantMatrix').checked : true;
  const includeRevHistory = document.getElementById('chk_cpIncludeRevHistory') ? document.getElementById('chk_cpIncludeRevHistory').checked : true;
  const includePlanData = document.getElementById('chk_cpIncludePlanData') ? document.getElementById('chk_cpIncludePlanData').checked : true;

  let targetElementId = null;
  let targetOpId = null;

  if (scopeVal === 'ACTIVE_STEP') {
    targetElementId = window.selectedCharLinkageElementId || window.selectedStructureId || null;
    targetOpId = window.selectedCharLinkageOpId || window.selectedProcessStepId || null;
  } else if (scopeVal === 'SELECTED_ELEMENT') {
    targetElementId = window.selectedCharLinkageElementId || window.selectedStructureId || null;
    targetOpId = 'ALL';
  } else {
    targetElementId = 'ALL';
    targetOpId = 'ALL';
  }

  const groups = getEffectiveControlPlanRows(scopeVal, targetElementId, targetOpId, variantVal);
  const curRev = getActiveControlPlanRevision();

  // Resolve Header Info identical to PFMEA header specification
  const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: true };
  let h = {};
  if (ctx && ctx.headerInfo && Object.keys(ctx.headerInfo).length > 0) {
    h = ctx.headerInfo;
  } else if (ctx && ctx.pfmea && ctx.pfmea.headerInfo && Object.keys(ctx.pfmea.headerInfo).length > 0) {
    h = ctx.pfmea.headerInfo;
  } else if (fmeaData.pfmeas && fmeaData.pfmeas.length > 0 && fmeaData.pfmeas[0].headerInfo && Object.keys(fmeaData.pfmeas[0].headerInfo).length > 0) {
    h = fmeaData.pfmeas[0].headerInfo;
  } else {
    h = fmeaData.headerInfo || fmeaData.header || {};
  }

  const isCpMultiVariant = (variantVal === 'ALL');
  let targetActiveVar = null;
  if (!isCpMultiVariant && variantVal && variantVal !== 'ALL') {
    targetActiveVar = (fmeaData.variants || []).find(v => v.id === variantVal);
  }
  const cpH = (targetActiveVar && (targetActiveVar.cpHeader || targetActiveVar.pfmeaHeader)) || {};
  const cpLeadMember = targetActiveVar?.fiveT?.teamMembers?.find(m => m.isCpLead)?.name;
  const pfLeadMember = targetActiveVar?.fiveT?.teamMembers?.find(m => m.isPfmeaLead)?.name;
  const cpCftMembers = targetActiveVar?.fiveT?.teamMembers?.filter(m => !m.isDfmeaLead && !m.isPfmeaLead && !m.isCpLead) || [];

  const companyName = h.companyName || (fmeaData.headerInfo && fmeaData.headerInfo.companyName) || 'JOST Group';
  const plantLocation = isCpMultiVariant ? 'Multiple Plants (See Variant Matrix Table)' : ((targetActiveVar && (cpH.plantLoc || targetActiveVar.plantLoc)) || h.plantLoc || h.plantLocation || (fmeaData.headerInfo && (fmeaData.headerInfo.plantLoc || fmeaData.headerInfo.plantLocation)) || 'Manufacturing Plant');

  let customerName = (targetActiveVar && targetActiveVar.customer) || h.customerName || (fmeaData.headerInfo && fmeaData.headerInfo.customerName) || fmeaData.projectName || 'Acme Motors';
  let modelYear = (targetActiveVar && (targetActiveVar.model || targetActiveVar.vehicle)) || h.modelYear || (fmeaData.headerInfo && fmeaData.headerInfo.modelYear) || '';
  let subjectSystem = cpH.subject || (targetActiveVar && (targetActiveVar.subject || targetActiveVar.name)) || h.subjectSystem || (fmeaData.projectInfo && fmeaData.projectInfo.projectName) || (fmeaData.structure ? fmeaData.structure.name : 'Process Control Plan');
  let docNo = cpH.docNo || (h.fmeaDocNo ? 'CP-' + h.fmeaDocNo.replace(/^FMEA-|^DFMEA-|^PFMEA-|^CP-/i, '') : ('CP-' + (curRev.revNo ? curRev.revNo : Date.now().toString().slice(-6))));
  let designResp = cpH.resp || (targetActiveVar && targetActiveVar.designResp) || (cpLeadMember ? 'Quality / Process: ' + cpLeadMember : (pfLeadMember ? 'Process: ' + pfLeadMember : (h.designResp || (fmeaData.headerInfo && fmeaData.headerInfo.designResp) || 'Process / Quality Engineering')));
  let keyLead = cpH.keyLead || (targetActiveVar && targetActiveVar.keyLead) || cpLeadMember || h.keyLead || (fmeaData.headerInfo && fmeaData.headerInfo.keyLead) || curRev.author || 'Lead Quality Engineer';
  let crossTeam = (cpCftMembers.length > 0 ? cpCftMembers.map(m => `${m.name}${m.dept || m.role ? ' (' + (m.dept || m.role) + ')' : ''}`).join(', ') : (h.crossTeam || h.coreTeam || (fmeaData.headerInfo && (fmeaData.headerInfo.crossTeam || fmeaData.headerInfo.coreTeam)) || 'Core Engineering Team'));

  if (isCpMultiVariant) {
    subjectSystem = 'Multiple Variants (See Variant Matrix Table)';
    customerName = 'Multiple Customers (See Variant Matrix Table)';
    designResp = 'Multiple Leads (See Variant Matrix Table)';
    keyLead = 'Multiple Prepared By / Leads (See Variant Matrix Table)';
    crossTeam = 'Multiple Core Teams (See Variant Matrix Table)';
  }

  const confidentiality = cpH.confidentiality || h.confidentiality || (fmeaData.headerInfo && fmeaData.headerInfo.confidentiality) || 'Internal Confidential';
  const startDate = h.startDate || (fmeaData.headerInfo && fmeaData.headerInfo.startDate) || curRev.date || new Date().toISOString().slice(0, 10);
  const revDate = curRev.date || h.revDate || (fmeaData.headerInfo && fmeaData.headerInfo.revDate) || new Date().toISOString().slice(0, 10);

  const cpRawPhases = cpH.phases || targetActiveVar?.phases || [curRev.phase || 'Production'];
  const phase = isCpMultiVariant ? 'Multiple Phases' : cpRawPhases.join(' | ');
  const cpPhaseBadges = isCpMultiVariant ? '<span style="background:#fef3c7; color:#92400e; border:1px solid #f59e0b; padding:1px 5px; border-radius:3px; font-weight:bold; font-size:8px;">Multiple Phases (See Variant Matrix)</span>' : cpRawPhases.map(p => {
    if (p.toLowerCase().includes('proto')) return '<span style="background:#fef3c7; color:#92400e; border:1px solid #f59e0b; padding:1px 5px; border-radius:3px; font-weight:bold; font-size:8px; display:inline-block; margin-right:3px;">🧪 Prototype</span>';
    if (p.toLowerCase().includes('pre') || p.toLowerCase().includes('safe')) return '<span style="background:#e0f2fe; color:#0369a1; border:1px solid #0284c7; padding:1px 5px; border-radius:3px; font-weight:bold; font-size:8px; display:inline-block; margin-right:3px;">🚀 Pre-Launch</span>';
    return '<span style="background:#dcfce7; color:#166534; border:1px solid #16a34a; padding:1px 5px; border-radius:3px; font-weight:bold; font-size:8px; display:inline-block; margin-right:3px;">🏭 Production</span>';
  }).join(' ');
  const revNo = curRev.revNo || '01';
  const revStatus = curRev.status || 'In Progress';

  const selectedLogos = (h.selectedLogos && h.selectedLogos.length > 0) ? h.selectedLogos : (fmeaData.headerInfo?.selectedLogos || ['JOST']);
  const brandLogosHtml = typeof renderHeaderLogosHTML === 'function' ? renderHeaderLogosHTML(selectedLogos) : '';

  if (format === 'EXCEL') {
    // CSV Export with standard AIAG-VDA Header
    let csv = [];
    csv.push(['AIAG & VDA PROCESS CONTROL PLAN (' + phase.toUpperCase() + ' PHASE)']);
    csv.push(['Company Name:', companyName, 'Subject / Process:', subjectSystem, 'Control Plan Doc No:', docNo, 'Confidentiality:', confidentiality]);
    csv.push(['Process Plant Location:', plantLocation, 'Start Date:', startDate, 'Process Responsibility:', designResp, 'Revision Date:', revDate + ' (Rev ' + revNo + ' - ' + revStatus + ')']);
    csv.push(['Customer Name:', customerName + (modelYear ? ' (' + modelYear + ')' : ''), 'Core Team Members:', crossTeam, 'Key Lead / Prepared By:', keyLead, 'Phase:', phase]);
    if (variantVal !== 'ALL') {
      csv.push(['Variant Scope:', variantVal]);
    }
    csv.push([]);
    csv.push([
      'Op No', 'Process Name / Operation', 'Machine / Tooling', 'Char No',
      'Product Characteristic', 'Process Characteristic', 'Special Class',
      'Specification / Tolerance', 'Control Method (Prevention)', 'Evaluation Method (Detection)',
      'Sample Size', 'Sample Frequency', 'Evaluator / Responsible', 'Reaction & Escalation Plan'
    ]);

    groups.forEach(g => {
      g.rows.forEach(r => {
        const prevText = r.prevCtrl ? ((r.prevCtrl.isPokaYoke ? '[POKA-YOKE] ' : '') + (r.prevCtrl.isActionSync ? '[ACTION] ' : '') + r.prevCtrl.desc) : '-';
        const detText = r.detCtrl ? ((r.detCtrl.isPokaYoke ? '[POKA-YOKE] ' : '') + (r.detCtrl.isActionSync ? '[ACTION] ' : '') + r.detCtrl.desc) : '-';
        csv.push([
          g.opNo, g.opName, r.machineTooling, r.charNo,
          r.productChar, r.processChar, r.specialClass,
          r.spec, prevText, detText,
          r.sampleSize, r.sampleFreq, r.evaluator, r.reactionPlan
        ]);
      });
    });

    const csvContent = 'data:text/csv;charset=utf-8,\ufeff' + csv.map(e => e.map(cell => '"' + String(cell || '').replace(/"/g, '""') + '"').join(',')).join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `Control_Plan_${subjectSystem.replace(/\s+/g, '_')}_Rev${revNo}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    closeControlPlanPrintModal();
    return;
  }

  // Print Preview PDF HTML
  let printPagesHTML = '';

  // Page 1: Product & Variant Master Matrix Table
  if (includeVariantMatrix) {
    const matrixHTML = getVariantHeaderMatrixHTML('ControlPlan');
    if (matrixHTML && matrixHTML.trim()) {
      printPagesHTML += `
        <div class="scope-section print-page-cover" style="page-break-after:always; break-after:page; margin-bottom:15px;">
          ${matrixHTML}
        </div>
      `;
    }
  }

  // Page 2: Control Plan Revision History Table
  if (includeRevHistory) {
    const revHTML = getCompleteRevisionHistoryTableHTML('ControlPlan');
    if (revHTML && revHTML.trim()) {
      printPagesHTML += `
        <div class="scope-section print-page-revision" style="page-break-after:always; break-after:page; margin-bottom:15px;">
          ${revHTML}
        </div>
      `;
    }
  }

  // Page 3+: Control Plan Worksheet Table with Standard Header
  if (includePlanData) {
    printPagesHTML += `
      <div class="scope-section">
        <!-- AIAG-VDA Official Form Header (Exact match to PFMEA Header) -->
        <div class="fmea-project-header-box">
          <div style="background: #0f172a; color: #ffffff; display:flex; align-items:center; justify-content:space-between; padding: 5px 12px;">
            <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
              ${brandLogosHtml}
            </div>
            <div style="flex:1; text-align:center; font-weight:bold; font-size:13px; letter-spacing:0.5px; text-transform:uppercase; padding: 0 10px;">
              AIAG-VDA PROCESS CONTROL PLAN (${escapeHtml(phase.toUpperCase())} PHASE)
            </div>
            <div style="text-align:right; font-size:9px; color:#94a3b8; white-space:nowrap;">JOST World<br>Process Control Plan</div>
          </div>

          ${isCpMultiVariant ? `
            <div style="background:#fef3c7; border-bottom:1px solid #f59e0b; color:#92400e; padding:3px 8px; font-size:9px; font-weight:bold;">
              ℹ️ Multi-Variant Document: Covers all active product variants. Refer to the attached Variant Header Matrix Table for specific Part Numbers, Assemblies, Customers, Phase Applicability, and Core Teams.
            </div>
          ` : ''}
          <table style="width: 100%; border-collapse: collapse; border: none; font-size: 9.5px;">
            <tr style="background:#f8fafc;">
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Company Name:</strong> ${escapeHtml(companyName)}</td>
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Subject / Process:</strong> ${escapeHtml(subjectSystem)}</td>
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Control Plan Doc No:</strong> ${escapeHtml(docNo)}</td>
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Confidentiality Level:</strong> ${escapeHtml(confidentiality)}</td>
            </tr>
            <tr>
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Process Plant Location:</strong> ${escapeHtml(plantLocation)}</td>
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Control Plan Start Date:</strong> ${escapeHtml(startDate)}</td>
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Process Responsibility:</strong> ${escapeHtml(designResp)}</td>
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Revision Date:</strong> ${escapeHtml(revDate)} (Rev ${escapeHtml(revNo)} - ${escapeHtml(revStatus)})</td>
            </tr>
            <tr style="background:#f8fafc;">
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Customer Name:</strong> ${escapeHtml(customerName)} ${modelYear ? '(' + escapeHtml(modelYear) + ')' : ''}</td>
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px;" colspan="2"><strong>Core Team Members:</strong> ${escapeHtml(crossTeam)}</td>
              <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Key Lead / Prepared By:</strong> ${escapeHtml(keyLead)}</td>
            </tr>
            ${variantVal !== 'ALL' ? `
            <tr>
              <td colspan="4" style="border: 1px solid #cbd5e1; padding: 3px 8px; background:#f1f5f9; font-size:9px; color:#0369a1;">
                <strong>Variant Scope:</strong> ${escapeHtml(variantVal)}
              </td>
            </tr>` : ''}
          </table>
        </div>

        <table class="cp-main-table">
          <thead>
            <tr>
              <th style="width:30px; text-align:center;">Op No</th>
              <th style="width:110px;">Process Name / Operation</th>
              <th style="width:90px;">Machine / Tooling</th>
              <th style="width:30px; text-align:center;">Char #</th>
              <th style="width:100px;">Product Characteristic</th>
              <th style="width:100px;">Process Characteristic</th>
              <th style="width:40px; text-align:center;">Class</th>
              <th style="width:90px;">Specification / Tolerance</th>
              <th style="width:110px;">Control Method (Prevention)</th>
              <th style="width:110px;">Evaluation Method (Detection)</th>
              <th style="width:55px;">Size</th>
              <th style="width:55px;">Freq</th>
              <th style="width:75px;">Evaluator</th>
              <th style="width:125px;">Reaction &amp; Escalation Plan</th>
            </tr>
          </thead>
          <tbody>
            ${groups.map(g => {
      const totalOpRows = g.rows.length;
      return g.rows.map((r, rowIdx) => {
        const isFirstOpRow = rowIdx === 0;
        const isFirstCharRow = r.isFirstCharLine;
        const charRowSpan = r.charLinesCount;

        let prevText = '-';
        if (r.prevCtrl) {
          const pyBadge = r.prevCtrl.isPokaYoke ? '<span class="poka-badge">🛡️ POKA-YOKE</span>' : '';
          const actBadge = r.prevCtrl.isActionSync ? '<span class="action-badge">⚡ ACTION</span>' : '';
          prevText = `<div>${pyBadge}${actBadge}${escapeHtml(r.prevCtrl.desc)}</div>`;
        }

        let detText = '-';
        if (r.detCtrl) {
          const pyBadge = r.detCtrl.isPokaYoke ? '<span class="poka-badge">🛡️ POKA-YOKE</span>' : '';
          const actBadge = r.detCtrl.isActionSync ? '<span class="action-badge">⚡ ACTION</span>' : '';
          detText = `<div>${pyBadge}${actBadge}${escapeHtml(r.detCtrl.desc)}</div>`;
        }

        return `
                  <tr>
                    ${isFirstOpRow ? `
                      <td rowspan="${totalOpRows}" style="text-align:center; font-weight:bold; background:#f8fafc;">${escapeHtml(g.opNo)}</td>
                      <td rowspan="${totalOpRows}" style="font-weight:bold; background:#f8fafc;">
                        ${escapeHtml(g.opName)}
                        ${g.elementPartNo ? `<div style="font-size:8px; color:#64748b;">[${escapeHtml(g.elementPartNo)}]</div>` : ''}
                      </td>
                    ` : ''}

                    ${isFirstCharRow ? `
                      <td rowspan="${charRowSpan}">${escapeHtml(r.machineTooling)}</td>
                      <td rowspan="${charRowSpan}" style="text-align:center;">${escapeHtml(r.charNo)}</td>
                      <td rowspan="${charRowSpan}">${escapeHtml(r.productChar)}</td>
                      <td rowspan="${charRowSpan}">${escapeHtml(r.processChar)}</td>
                      <td rowspan="${charRowSpan}" style="text-align:center;">${r.specialClass !== '-' ? `<span class="class-badge">${escapeHtml(r.specialClass)}</span>` : '-'}</td>
                      <td rowspan="${charRowSpan}" style="font-family:monospace; font-size:9px;">${escapeHtml(r.spec)}</td>
                    ` : ''}

                    <td>${prevText}</td>
                    <td>${detText}</td>
                    <td>${escapeHtml(r.sampleSize)}</td>
                    <td>${escapeHtml(r.sampleFreq)}</td>
                    <td style="font-weight:600; color:#0369a1;">${escapeHtml(r.evaluator)}</td>
                    <td>${escapeHtml(r.reactionPlan)}</td>
                  </tr>
                `;
      }).join('');
    }).join('')}
          </tbody>
        </table>

        <div style="margin-top:20px; display:flex; justify-content:space-between; font-size:10px; border-top:1px solid #cbd5e1; padding-top:10px;">
          <div>Process Engineer: ______________________</div>
          <div>Quality Assurance: ______________________</div>
          <div>Plant Operations Manager: ______________________</div>
        </div>
      </div>
    `;
  }

  let printHtml = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <title>AIAG &amp; VDA Process Control Plan - ${escapeHtml(subjectSystem)}</title>
      <style>
        @page { size: landscape; margin: 8mm; }
        * { box-sizing: border-box; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; color: #111827; background: #fff; margin: 0; padding: 10px; }
        .scope-section { page-break-after: always; break-after: page; margin-bottom: 0px; }
        .scope-section:last-child { page-break-after: auto; break-after: auto; }
        .fmea-project-header-box { border: 2px solid #0f172a; margin-bottom: 10px; font-family: Arial, sans-serif; font-size: 10px; background: #ffffff; }
        table.cp-main-table { width: 100%; border-collapse: collapse; font-size: 9.5px; }
        table.cp-main-table th, table.cp-main-table td { border: 1px solid #475569; padding: 4px 5px; text-align: left; vertical-align: top; }
        table.cp-main-table th { background: #0f172a; color: #fff; font-weight: bold; font-size: 9.5px; }
        .poka-badge { display: inline-block; background: #d1fae5; color: #065f46; border: 1px solid #059669; padding: 1px 4px; font-size: 8px; font-weight: bold; border-radius: 2px; margin-right: 2px; }
        .action-badge { display: inline-block; background: #e0f2fe; color: #0369a1; border: 1px solid #0284c7; padding: 1px 3px; font-size: 8px; font-weight: bold; border-radius: 2px; margin-right: 2px; }
        .class-badge { display: inline-block; background: #ffe4e6; color: #e11d48; border: 1px solid #e11d48; padding: 1px 4px; font-size: 8px; font-weight: bold; border-radius: 2px; }
        .phase-badge { display: inline-block; padding: 2px 8px; font-size: 10px; font-weight: bold; border-radius: 4px; background: #0284c7; color: #fff; }
      </style>
    </head>
    <body>
      ${printPagesHTML}
      <script>
        window.onload = function() { window.print(); };
      </script>
    </body>
    </html>
  `;

  if (typeof window !== 'undefined' && typeof window.executeHtmlPrint === 'function') {
    window.executeHtmlPrint(printHtml);
  } else if (typeof executeHtmlPrint === 'function') {
    executeHtmlPrint(printHtml);
  } else {
    const printWin = window.open('', '_blank');
    if (printWin) {
      printWin.document.open();
      printWin.document.write(printHtml);
      printWin.document.close();
    }
  }

  closeControlPlanPrintModal();
}
window.executeControlPlanPrint = executeControlPlanPrint;

window.getEffectiveControlPlanRows = getEffectiveControlPlanRows;
window.initControlPlanDefaults = initControlPlanDefaults;
window.getActiveControlPlanRevision = getActiveControlPlanRevision;
window.getMasterPokaYokeItems = getMasterPokaYokeItems;
window.renderControlPlanTable = renderControlPlanTable;
window.getAiagVdaHeaderHTML = getAiagVdaHeaderHTML;
window.getCompleteRevisionHistoryTableHTML = getCompleteRevisionHistoryTableHTML;
window.getVariantHeaderMatrixHTML = getVariantHeaderMatrixHTML;
window.exportToPDF = exportToPDF;
window.executeExport = executeExport;
window.renderControlPlanRevisionUI = renderControlPlanRevisionUI;

